def utc_now():
    return datetime.now(timezone.utc)


def iso_now():
    return utc_now().replace(microsecond=0).isoformat()


def read_json(path, default):
    if not path.exists():
        return default
    try:
        return json.loads(path.read_text(encoding="utf-8-sig"))
    except Exception:
        return default


class LivePortfolioError(RuntimeError):
    pass


def read_json_strict(path):
    return json.loads(path.read_text(encoding="utf-8-sig"))


def validate_live_portfolio(portfolio, source="live_portfolio"):
    if not isinstance(portfolio, dict):
        raise LivePortfolioError(f"{source}_must_be_an_object")
    if not isinstance(portfolio.get("bets", []), list):
        raise LivePortfolioError(f"{source}_bets_must_be_a_list")
    return portfolio


def write_json(path, payload):
    if isinstance(payload, dict):
        flush_evidence_archives(path, payload)
    tmp = path.with_suffix(path.suffix + f".{os.getpid()}.{uuid.uuid4().hex}.tmp")
    tmp.write_text(json.dumps(payload, indent=2, sort_keys=True), encoding="utf-8")
    last_error = None
    for attempt in range(5):
        try:
            tmp.replace(path)
            return
        except PermissionError as exc:
            last_error = exc
            time.sleep(0.05 * (attempt + 1))
    try:
        tmp.unlink(missing_ok=True)
    except OSError:
        pass
    raise last_error


def load_settings():
    settings = dict(DEFAULT_SETTINGS)
    settings.update(read_json(SETTINGS_FILE, {}))
    try:
        settings.update(read_secure_settings(SECURE_SETTINGS_FILE, {}))
    except Exception as exc:
        # A configured encrypted store must never be silently ignored: doing so
        # can turn off paid data sources while making the scan look healthy.
        if SECURE_SETTINGS_FILE.exists():
            raise RuntimeError(f"crypto_secure_settings_unavailable:{type(exc).__name__}") from exc
    settings.update({
        k: v
        for k, v in os.environ.items()
        if k.startswith("CRYPTO_") or k.startswith("MULTI_MARKET_")
    })
    return {k: str(v) for k, v in settings.items()}


def bot_setting(name, default=""):
    value = os.getenv(name)
    if value not in (None, ""):
        return value
    settings = read_json(BOT_SETTINGS_FILE, {})
    value = settings.get(name, default)
    return default if value is None else str(value)


def setting_bool(settings, key):
    return str(settings.get(key, "")).lower() == "true"


def setting_float(settings, key):
    try:
        return float(settings.get(key, DEFAULT_SETTINGS.get(key, "0")) or 0)
    except (TypeError, ValueError):
        return float(DEFAULT_SETTINGS.get(key, "0") or 0)


def setting_int(settings, key):
    return int(float(settings.get(key, DEFAULT_SETTINGS.get(key, "0")) or 0))


def setting_list(settings, key):
    return [item.strip().upper() for item in settings.get(key, "").split(",") if item.strip()]


def setting_float_list(settings, key):
    values = []
    for item in str(settings.get(key, "")).split(","):
        try:
            values.append(float(item.strip()))
        except (TypeError, ValueError):
            continue
    return values


def effective_scan_bet_limit(settings, campaign_enabled=None):
    configured = max(0, setting_int(settings, "CRYPTO_MAX_BETS_PER_SCAN"))
    if campaign_enabled is None:
        campaign_enabled = setting_bool(settings, "CRYPTO_15M_CAMPAIGN_ENABLED")
    if not campaign_enabled:
        return configured
    bot_count = max(1, setting_int(settings, "CRYPTO_15M_CAMPAIGN_BOT_COUNT"))
    return min(configured, bot_count) if configured > 0 else bot_count


def rotate_append_file(path, incoming_bytes=0, max_bytes=0, backup_count=14):
    """Rotate append-only runtime files without reading them into memory."""
    try:
        from storage_maintenance import rotate_file
        return rotate_file(path, incoming_bytes=incoming_bytes, max_bytes=max_bytes)
    except ImportError:
        pass
    path = Path(path)
    max_bytes = max(0, int(max_bytes or 0))
    if max_bytes <= 0 or not path.exists():
        return None
    try:
        current_size = path.stat().st_size
    except OSError:
        return None
    if current_size + max(0, int(incoming_bytes or 0)) <= max_bytes:
        return None
    archive_dir = path.parent / "archives" / "crypto_log_rotation"
    archive_dir.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S_%fZ")
    rotated = archive_dir / f"{path.name}.{timestamp}"
    path.replace(rotated)
    backup_count = max(1, int(backup_count or 1))
    backups = sorted(
        archive_dir.glob(f"{path.name}.*"),
        key=lambda item: item.stat().st_mtime,
        reverse=True,
    )
    for stale in backups[backup_count:]:
        try:
            stale.unlink()
        except OSError:
            pass
    return rotated


def log_line(message):
    line = f"[{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}] {message}"
    encoded_bytes = len((line + "\n").encode("utf-8"))
    rotate_append_file(
        LOG_FILE,
        encoded_bytes,
        LOG_MAX_BYTES,
        LOG_ROTATION_BACKUPS,
    )
    with LOG_FILE.open("a", encoding="utf-8") as handle:
        handle.write(line + "\n")


def safe_error_message(exc):
    message = str(exc)
    message = re.sub(r"([?&](?:apiKey|auth_token|token|key)=)[^&\s)]+", r"\1[redacted]", message, flags=re.IGNORECASE)
    message = re.sub(r"(Authorization:\s*)(Bearer\s+)?[^\s,;)]+", r"\1[redacted]", message, flags=re.IGNORECASE)
    return message


def exception_diagnostics(exc, max_chain=3):
    """Return a sanitized, structured exception chain for durable execution logs."""
    chain = []
    current = exc
    seen = set()
    while current is not None and len(chain) < max(1, int(max_chain or 1)):
        identity = id(current)
        if identity in seen:
            break
        seen.add(identity)
        chain.append({
            "type": type(current).__name__,
            "message": safe_error_message(current)[:2000],
        })
        current = current.__cause__ or current.__context__
    primary = chain[0] if chain else {"type": "Exception", "message": ""}
    return {
        "exception_type": primary["type"],
        "exchange_error": primary["message"],
        "chain": chain,
    }


def compact_log_value(value, limit=1200):
    text = re.sub(r"\s+", " ", str(value or "")).strip()
    return text[: max(1, int(limit or 1))]


def event_line(payload):
    row = {"ts": iso_now(), **payload}
    encoded = (json.dumps(row, sort_keys=True) + "\n").encode("utf-8")
    rotate_append_file(
        EVENTS_FILE,
        len(encoded),
        EVENTS_MAX_BYTES,
        LOG_ROTATION_BACKUPS,
    )
    with EVENTS_FILE.open("a", encoding="utf-8") as handle:
        handle.write(encoded.decode("utf-8"))


def http_json(url, headers=None, timeout=20, retries=2):
    last_error = None
    for attempt in range(retries + 1):
        try:
            response = requests.get(url, headers=headers or {}, timeout=timeout)
            if response.status_code == 429 and attempt < retries:
                time.sleep(1.5 * (attempt + 1))
                continue
            response.raise_for_status()
            return response.json()
        except Exception as exc:
            last_error = exc
            if attempt < retries:
                time.sleep(0.75 * (attempt + 1))
    raise last_error


def parse_time(value):
    if not value:
        return None
    try:
        return datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    except ValueError:
        return None


def cents_from_market(value, dollars=False):
    if value in (None, ""):
        return None
    try:
        raw = float(value)
    except (TypeError, ValueError):
        return None
    if raw <= 0:
        return None
    return raw * 100.0 if dollars else raw


def market_price(market, *names):
    for name in names:
        if name in market:
            value = cents_from_market(market.get(name), dollars=name.endswith("_dollars"))
            if value is not None:
                return value
    return None


def load_portfolio(settings):
    live_mode = execution_mode(settings) == "live" and PORTFOLIO_FILE == LIVE_PORTFOLIO_FILE
    if live_mode and setting_bool(settings, "CRYPTO_LIVE_FAIL_CLOSED_PORTFOLIO"):
        try:
            portfolio = validate_live_portfolio(
                read_json_strict(PORTFOLIO_FILE),
                "live_portfolio",
            )
        except Exception as exc:
            try:
                backup = validate_live_portfolio(
                    read_json_strict(LIVE_PORTFOLIO_BACKUP_FILE),
                    "live_portfolio_backup",
                )
            except Exception as backup_exc:
                try:
                    # The compact ledger is updated immediately after every
                    # remote fill and settlement. It is the final fail-closed
                    # recovery source when a hard shutdown damages both large
                    # portfolio generations.
                    ledger = live_bot_ledger_rows()
                    if not ledger:
                        raise LivePortfolioError("live_bot_ledger_empty")
                    starting = setting_float(settings, "CRYPTO_STARTING_BALANCE")
                    portfolio = {
                        "created_at": min(
                            (
                                str(row.get("placed_at"))
                                for row in ledger.values()
                                if row.get("placed_at")
                            ),
                            default=iso_now(),
                        ),
                        "mode": "live",
                        "starting_balance": starting,
                        "balance": starting,
                        "bets": sorted(
                            (dict(row) for row in ledger.values()),
                            key=lambda row: str(row.get("placed_at") or row.get("settled_at") or ""),
                        ),
                        "live_ledger_disaster_recovery": {
                            "recovered_at": iso_now(),
                            "row_count": len(ledger),
                            "main_error": type(exc).__name__,
                            "backup_error": type(backup_exc).__name__,
                            "requires_account_reconciliation": True,
                        },
                    }
                    validate_live_portfolio(portfolio, "live_ledger_recovery")
                    write_json(LIVE_PORTFOLIO_BACKUP_FILE, portfolio)
                    write_json(LIVE_PORTFOLIO_FILE, portfolio)
                    log_line(
                        "CRYPTO LIVE DISASTER RECOVERY FROM DURABLE LEDGER: "
                        f"restored={len(ledger)} account_reconciliation_required=true"
                    )
                except Exception as ledger_exc:
                    raise LivePortfolioError(
                        f"live_portfolio_unreadable_and_no_valid_backup: {type(exc).__name__}; "
                        f"backup={type(backup_exc).__name__}; ledger={type(ledger_exc).__name__}"
                    ) from exc
            else:
                portfolio = backup
                write_json(LIVE_PORTFOLIO_FILE, portfolio)
                log_line(
                    f"CRYPTO LIVE PORTFOLIO RESTORED FROM BACKUP: "
                    f"bets={len(portfolio.get('bets') or [])} reason={type(exc).__name__}"
                )
    elif PORTFOLIO_FILE.exists():
        portfolio = read_json(PORTFOLIO_FILE, {})
    else:
        portfolio = {}
    starting = setting_float(settings, "CRYPTO_STARTING_BALANCE")
    portfolio.setdefault("created_at", iso_now())
    portfolio.setdefault("mode", "paper")
    portfolio.setdefault("starting_balance", starting)
    portfolio.setdefault("balance", starting)
    portfolio.setdefault("bets", [])
    if live_mode and setting_bool(settings, "CRYPTO_LIVE_LEDGER_RECOVERY_ENABLED"):
        recovered = recover_live_bot_rows_from_ledger(portfolio)
        if recovered:
            portfolio["live_ledger_recovery"] = {
                "recovered_at": iso_now(),
                "row_count": recovered,
            }
            log_line(
                f"CRYPTO LIVE LEDGER RECOVERY: restored={recovered} "
                f"portfolio_bets={len(portfolio.get('bets') or [])}"
            )
    return portfolio


def save_portfolio(portfolio):
    if PORTFOLIO_FILE == LIVE_PORTFOLIO_FILE:
        validate_live_portfolio(portfolio)
        if LIVE_PORTFOLIO_FILE.exists():
            current = validate_live_portfolio(
                read_json_strict(LIVE_PORTFOLIO_FILE),
                "existing_live_portfolio",
            )
            current_ids = {
                str(row.get("id"))
                for row in current.get("bets") or []
                if row.get("id")
            }
            new_ids = {
                str(row.get("id"))
                for row in portfolio.get("bets") or []
                if row.get("id")
            }
            missing_ids = current_ids - new_ids
            if missing_ids:
                raise LivePortfolioError(
                    f"live_portfolio_row_drop_blocked:{len(missing_ids)}"
                )
            write_json(LIVE_PORTFOLIO_BACKUP_FILE, current)
    write_json(PORTFOLIO_FILE, portfolio)


LIVE_LEDGER_OMIT_FIELDS = {
    "ai_review",
    "disagreement_guard",
    "directional_confirmation",
    "flow_review",
    "grok_review",
    "kalshi_microstructure",
    "learned_15m_model",
    "microstructure",
    "model",
    "probability",
    "shadow",
}


def compact_live_ledger_bet(row):
    return {
        key: value
        for key, value in (row or {}).items()
        if key not in LIVE_LEDGER_OMIT_FIELDS
    }


def live_bot_ledger_rows():
    if not LIVE_BOT_LEDGER_FILE.exists():
        return {}
    payload = read_json_strict(LIVE_BOT_LEDGER_FILE)
    rows = payload.get("bets") if isinstance(payload, dict) else None
    if not isinstance(rows, dict):
        raise LivePortfolioError("live_bot_ledger_invalid")
    return rows


def _prefer_live_ledger_row(current, incoming):
    current_status = str((current or {}).get("status") or "").lower()
    incoming_status = str((incoming or {}).get("status") or "").lower()
    if current_status == "settled" and incoming_status != "settled":
        return current
    if incoming_status == "settled" and current_status != "settled":
        return incoming
    return incoming


def _prefer_live_recovery_row(current, ledger_row):
    if not current:
        return ledger_row
    current_status = str(current.get("status") or "").lower()
    ledger_status = str((ledger_row or {}).get("status") or "").lower()
    if ledger_status == "settled" and current_status != "settled":
        return ledger_row
    return current


def update_live_bot_ledger(rows):
    ledger = live_bot_ledger_rows()
    changed = 0
    for row in rows or []:
        if (
            is_user_crypto_bet(row)
            or str(row.get("mode") or "").lower() != "live"
            or not row.get("id")
        ):
            continue
        row_id = str(row["id"])
        compact = compact_live_ledger_bet(row)
        preferred = _prefer_live_ledger_row(ledger.get(row_id), compact)
        if ledger.get(row_id) != preferred:
            ledger[row_id] = preferred
            changed += 1
    if changed:
        write_json(
            LIVE_BOT_LEDGER_FILE,
            {"updated_at": iso_now(), "bets": ledger},
        )
    return changed


def recover_live_bot_rows_from_ledger(portfolio):
    ledger = live_bot_ledger_rows()
    if not ledger:
        return 0
    bets = portfolio.setdefault("bets", [])
    by_id = {
        str(row.get("id")): index
        for index, row in enumerate(bets)
        if row.get("id")
    }
    recovered = 0
    for row_id, ledger_row in ledger.items():
        index = by_id.get(str(row_id))
        if index is None:
            bets.append(dict(ledger_row))
            by_id[str(row_id)] = len(bets) - 1
            recovered += 1
            continue
        preferred = _prefer_live_recovery_row(bets[index], ledger_row)
        if preferred != bets[index]:
            bets[index] = dict(preferred)
            recovered += 1
    return recovered


def rebuild_live_bot_ledger_from_events(events_path=None):
    events_path = Path(events_path or LIVE_EVENTS_FILE)
    ledger = {}
    for event in iter_jsonl(jsonl_sources(events_path)):
        if event.get("type") not in {"live_bet", "live_settled_bet"}:
            continue
        row = event.get("bet") or {}
        if is_user_crypto_bet(row) or not row.get("id"):
            continue
        row_id = str(row["id"])
        compact = compact_live_ledger_bet(row)
        ledger[row_id] = _prefer_live_ledger_row(ledger.get(row_id), compact)
    write_json(
        LIVE_BOT_LEDGER_FILE,
        {
            "rebuilt_at": iso_now(),
            "source": str(events_path),
            "bets": ledger,
        },
    )
    return {"recovered_rows": len(ledger), "source": str(events_path)}


def open_bets(portfolio):
    return [bet for bet in portfolio.get("bets", []) if bet.get("status") == "open"]


def is_user_crypto_bet(row):
    row = row or {}
    return (
        str(row.get("strategy_owner") or "") in {"user_bet", "manual_live_import"}
        or str(row.get("source") or "") in {"user_manual", "kalshi_user_order_import"}
        or bool(row.get("user_bet"))
        or bool(row.get("manual_bet"))
    )


def bot_open_bets(portfolio):
    return [bet for bet in open_bets(portfolio) if not is_user_crypto_bet(bet)]


def open_exposure(portfolio):
    return round(sum(float(bet.get("stake") or 0) for bet in open_bets(portfolio)), 2)


def execution_mode(settings):
    mode = str(settings.get("CRYPTO_EXECUTION_MODE", "paper")).strip().lower()
    return mode if mode in {"paper", "live"} else "paper"


def configure_runtime_files(settings):
    global LOG_FILE, EVENTS_FILE, PORTFOLIO_FILE, REPORT_FILE
    global LOG_MAX_BYTES, EVENTS_MAX_BYTES, LOG_ROTATION_BACKUPS
    if execution_mode(settings) == "live":
        LOG_FILE = LIVE_LOG_FILE
        EVENTS_FILE = LIVE_EVENTS_FILE
        PORTFOLIO_FILE = LIVE_PORTFOLIO_FILE
        REPORT_FILE = LIVE_REPORT_FILE
    else:
        LOG_FILE = PAPER_LOG_FILE
        EVENTS_FILE = PAPER_EVENTS_FILE
        PORTFOLIO_FILE = PAPER_PORTFOLIO_FILE
        REPORT_FILE = PAPER_REPORT_FILE
    LOG_MAX_BYTES = max(
        0,
        int(setting_float(settings, "CRYPTO_LOG_MAX_MB") * 1024 * 1024),
    )
    EVENTS_MAX_BYTES = max(
        0,
        int(setting_float(settings, "CRYPTO_EVENTS_MAX_MB") * 1024 * 1024),
    )
    LOG_ROTATION_BACKUPS = max(
        1,
        setting_int(settings, "CRYPTO_LOG_ROTATION_BACKUPS"),
    )


def kalshi_credentials(settings=None):
    settings = settings or {}
    return {
        "api_key_id": os.getenv("KALSHI_API_KEY") or settings.get("KALSHI_API_KEY") or bot_setting("KALSHI_API_KEY", ""),
        "private_key_path": os.getenv("KALSHI_PRIVATE_KEY_PATH") or settings.get("KALSHI_PRIVATE_KEY_PATH") or bot_setting("KALSHI_PRIVATE_KEY_PATH", ""),
        "private_key_pem": os.getenv("KALSHI_API_SECRET") or settings.get("KALSHI_API_SECRET") or bot_setting("KALSHI_API_SECRET", ""),
    }


def pyth_api_key(settings=None):
    settings = settings or {}
    return (
        os.getenv("PYTH_API_KEY")
        or settings.get("MULTI_MARKET_PYTH_API_KEY")
        or bot_setting("PYTH_API_KEY", "")
    )


def allow_live_trading():
    return bot_setting("ALLOW_LIVE_TRADING", "false").lower() == "true"


def crypto_15m_sprint_execution_freeze(settings):
    """Return the explicit sprint freeze before any bankroll or order action."""
    shadow_only = setting_bool(settings, "CRYPTO_15M_SPRINT_SHADOW_ONLY")
    return {
        "active": shadow_only,
        "reason": "crypto_15m_sprint_live_freeze" if shadow_only else None,
        "blocked_before_bankroll_reservation": shadow_only,
        "live_order_enabled": setting_bool(settings, "CRYPTO_LIVE_ORDER_ENABLED"),
        "dry_run": setting_bool(settings, "CRYPTO_LIVE_DRY_RUN"),
        "unit_staking_enabled": setting_bool(settings, "CRYPTO_15M_UNIT_STAKING_ENABLED"),
        "unit_recovery_enabled": setting_bool(settings, "CRYPTO_15M_UNIT_RECOVERY_ENABLED"),
        "pooled_recovery_enabled": setting_bool(settings, "CRYPTO_15M_POOLED_RECOVERY_ENABLED"),
        "partial_recovery_enabled": setting_bool(settings, "CRYPTO_15M_PARTIAL_RECOVERY_ENABLED"),
        "cross_bot_recovery_enabled": setting_bool(
            settings,
            "CRYPTO_15M_CROSS_BOT_CAP_RECOVERY_ENABLED",
        ),
        "dynamic_auto_promote_enabled": setting_bool(
            settings,
            "CRYPTO_DYNAMIC_AUTO_PROMOTE_ENABLED",
        ),
    }


def crypto_live_readiness(settings):
    creds = kalshi_credentials(settings)
    dry_run = setting_bool(settings, "CRYPTO_LIVE_DRY_RUN")
    sprint_freeze = crypto_15m_sprint_execution_freeze(settings)
    checks = {
        "mode_live": execution_mode(settings) == "live",
        "allow_live_trading": allow_live_trading(),
        "live_order_enabled": setting_bool(settings, "CRYPTO_LIVE_ORDER_ENABLED"),
        "sprint_shadow_only_disabled": not sprint_freeze.get("active"),
        "confirmation_disabled": not setting_bool(settings, "CRYPTO_LIVE_REQUIRE_CONFIRMATION"),
        "dry_run_disabled": not dry_run,
        "kalshi_client_available": bool(kalshi_private_request and kalshi_event_order_body),
        "kalshi_api_key_saved": bool(creds["api_key_id"]),
        "kalshi_private_key_saved": bool(creds["private_key_path"] or creds["private_key_pem"]),
        "shared_bankroll_available": bool(reserve_live_order and finalize_reservation) or not setting_bool(settings, "CRYPTO_LIVE_REQUIRE_SHARED_BANKROLL"),
    }
    blocking = [key for key, ok in checks.items() if not ok]
    dry_run_blocking = [
        key
        for key in (
            "mode_live",
            "allow_live_trading",
            "live_order_enabled",
            "sprint_shadow_only_disabled",
            "kalshi_client_available",
            "shared_bankroll_available",
        )
        if not checks.get(key)
    ]
    risk_warnings = []
    if setting_int(settings, "CRYPTO_MAX_OPEN_BETS") <= 0:
        risk_warnings.append("total_open_position_cap_unlimited")
    if setting_int(settings, "CRYPTO_MAX_OPEN_PER_EVENT") <= 0:
        risk_warnings.append("same_event_position_cap_unlimited")
    if setting_int(settings, "CRYPTO_MAX_OPEN_PER_ASSET") <= 0:
        risk_warnings.append("same_asset_position_cap_unlimited")
    if setting_float(settings, "CRYPTO_PHASE_TWO_MAX_STAKE_PCT") >= 1:
        risk_warnings.append("phase_two_stake_cap_allows_full_bankroll")
    multi_enabled = setting_bool(settings, "MULTI_MARKET_ENABLED")
    configured_lanes = {
        market_lane({"series_ticker": series})
        for series in setting_list(settings, "CRYPTO_SERIES")
    }
    crypto_hourly_enabled = "crypto_hourly" in configured_lanes
    commodity_hourly_enabled = "commodity_hourly" in configured_lanes
    commodity_15m_enabled = "commodity_15m" in configured_lanes
    pyth_key_saved = bool(pyth_api_key(settings))
    commodity_health = {
        asset: dict(COMMODITY_DATA_HEALTH.get(asset) or {})
        for asset in sorted(COMMODITY_ASSETS)
    }
    commodity_verified = bool(
        pyth_key_saved
        and all((commodity_health.get(asset) or {}).get("ok") for asset in COMMODITY_ASSETS)
    )
    commodity_blocking = []
    if not pyth_key_saved:
        commodity_blocking.append("pyth_api_key_missing")
    elif not commodity_verified:
        if any((row or {}).get("reason") == "pyth_not_entitled" for row in commodity_health.values()):
            commodity_blocking.append("pyth_indices_entitlement_required")
        else:
            commodity_blocking.append("pyth_commodity_feeds_unverified")
    multi_market = {
        "enabled": multi_enabled,
        "live_enabled": setting_bool(settings, "MULTI_MARKET_LIVE_ENABLED"),
        "commodity_live_enabled": setting_bool(
            settings,
            "MULTI_MARKET_COMMODITY_LIVE_ENABLED",
        ),
        "commodity_mode": (
            "live"
            if setting_bool(settings, "MULTI_MARKET_COMMODITY_LIVE_ENABLED")
            else "paper_shadow_only"
        ),
        "crypto_hourly_enabled": crypto_hourly_enabled,
        "crypto_hourly_ready": multi_enabled and crypto_hourly_enabled,
        "commodity_15m_enabled": commodity_15m_enabled,
        "commodity_hourly_enabled": commodity_hourly_enabled,
        "commodity_ready": multi_enabled and commodity_15m_enabled and commodity_verified,
        "pyth_api_key_saved": pyth_key_saved,
        "commodity_blocking": commodity_blocking,
        "commodity_feed_health": commodity_health,
        "max_bets_per_scan": setting_int(settings, "CRYPTO_MAX_BETS_PER_SCAN"),
        "effective_bets_per_scan": effective_scan_bet_limit(settings),
        "max_open_bets": setting_int(settings, "CRYPTO_MAX_OPEN_BETS"),
        "max_open_per_lane": setting_int(settings, "MULTI_MARKET_MAX_OPEN_PER_LANE"),
        "max_open_per_cluster": setting_int(settings, "MULTI_MARKET_MAX_OPEN_PER_CLUSTER"),
        "max_open_per_exposure_group": setting_int(settings, "MULTI_MARKET_MAX_OPEN_PER_EXPOSURE_GROUP"),
    }
    return {
        "ok": not blocking,
        "dry_run_ok": dry_run and not dry_run_blocking,
        "dry_run": dry_run,
        "checks": checks,
        "blocking": blocking,
        "dry_run_blocking": dry_run_blocking,
        "risk_warnings": risk_warnings,
        "time_in_force": settings.get("CRYPTO_LIVE_TIME_IN_FORCE", "immediate_or_cancel"),
        "live_max_stake": setting_float(settings, "CRYPTO_LIVE_MAX_STAKE"),
        "multi_market": multi_market,
    }


def crypto_spot_flow_live_pilot_readiness(settings, candidate=None):
    """Return the isolated live-pilot readiness without unfreezing legacy bots."""
    creds = kalshi_credentials(settings)
    review = (candidate or {}).get("spot_flow_live_pilot") or {}
    checks = {
        "mode_live": execution_mode(settings) == "live",
        "allow_live_trading": allow_live_trading(),
        "live_order_enabled": setting_bool(settings, "CRYPTO_LIVE_ORDER_ENABLED"),
        "pilot_enabled": setting_bool(settings, "CRYPTO_SPOT_FLOW_LIVE_PILOT_ENABLED"),
        "confirmation_disabled": not setting_bool(
            settings, "CRYPTO_LIVE_REQUIRE_CONFIRMATION"
        ),
        "dry_run_disabled": not setting_bool(settings, "CRYPTO_LIVE_DRY_RUN"),
        "kalshi_client_available": bool(kalshi_private_request and kalshi_event_order_body),
        "kalshi_api_key_saved": bool(creds["api_key_id"]),
        "kalshi_private_key_saved": bool(
            creds["private_key_path"] or creds["private_key_pem"]
        ),
        "shared_bankroll_available": bool(
            reserve_live_order and finalize_reservation
        )
        or not setting_bool(settings, "CRYPTO_LIVE_REQUIRE_SHARED_BANKROLL"),
        "candidate_qualified": bool(review.get("eligible")) if candidate else True,
        "recovery_disabled": not bool(
            (candidate or {}).get("recovery_context", {}).get("active")
        ),
    }
    blocking = [key for key, ok in checks.items() if not ok]
    return {
        "ok": not blocking,
        "checks": checks,
        "blocking": blocking,
        "legacy_sprint_freeze_preserved": crypto_15m_sprint_execution_freeze(
            settings
        ).get("active"),
        "time_in_force": "fill_or_kill",
        "owner": CRYPTO_SPOT_FLOW_LIVE_PILOT_OWNER,
    }


def crypto_patient_readiness(settings):
    """Explicitly enable only the patient lane; preserve legacy sprint freeze."""
    base = crypto_live_readiness(settings)
    checks = dict(base["checks"])
    checks.pop("sprint_shadow_only_disabled", None)
    checks.update(
        patient_enabled=patient_enabled(settings),
        shared_bankroll_required=setting_bool(settings, "CRYPTO_LIVE_REQUIRE_SHARED_BANKROLL"),
        reconciliation_required=setting_bool(settings, "CRYPTO_RECONCILE_LIVE_ON_SCAN"),
        fresh_depth_required=setting_bool(settings, "CRYPTO_LIVE_DEPTH_PREFLIGHT_ENABLED"),
    )
    return {"ok": all(checks.values()), "checks": checks,
            "blocking": [key for key, ok in checks.items() if not ok], "owner": PATIENT_OWNER}


def live_local_open_positions(portfolio):
    positions = {}
    for bet in portfolio.get("bets", []):
        if bet.get("mode") != "live" or bet.get("status") != "open":
            continue
        ticker = bet.get("kalshi_ticker") or bet.get("ticker")
        if not ticker:
            continue
        positions[ticker] = {
            "ticker": ticker,
            "side": str(bet.get("order_side") or bet.get("side") or "yes").lower(),
            "stake": round(float(bet.get("stake") or 0), 2),
            "contracts": float(bet.get("contracts") or (bet.get("live_order") or {}).get("contracts") or 0),
            "asset": bet.get("asset", ""),
            "placed_at": bet.get("placed_at", ""),
        }
    return positions


def cents_to_dollars(value):
    try:
        return round(float(value or 0) / 100.0, 2)
    except (TypeError, ValueError):
        return 0.0


def extract_kalshi_balance(data):
    for key in ("balance_dollars", "available_balance_dollars", "cash_balance_dollars", "portfolio_value_dollars"):
        if key in data and data[key] not in (None, ""):
            return round(float(data[key]), 2)
    for key in ("balance", "available_balance", "cash_balance", "portfolio_value"):
        if key in data and data[key] not in (None, ""):
            return cents_to_dollars(data[key])
    return None


def fetch_live_account_snapshot(settings):
    creds = kalshi_credentials(settings)
    if not (creds["api_key_id"] and (creds["private_key_path"] or creds["private_key_pem"])):
        return {"ok": False, "reason": "kalshi_credentials_missing"}
    if not kalshi_private_request:
        return {"ok": False, "reason": "kalshi_client_unavailable"}

    snapshot = {"ok": True, "fetched_at": iso_now(), "positions_complete": False, "orders_complete": False}
    try:
        data, _headers = kalshi_private_request("/portfolio/balance", **creds)
        snapshot["balance_raw"] = data
        snapshot["cash_balance"] = extract_kalshi_balance(data)
    except Exception as exc:
        snapshot["ok"] = False
        snapshot["balance_error"] = safe_error_message(exc)

    try:
        positions = complete_pages(
            lambda path: kalshi_private_request(path, **creds),
            "/portfolio/positions", "market_positions", params={"count_filter": "position", "limit": 1000},
        )
        snapshot["position_count"] = len(positions)
        snapshot["positions_sample"] = positions[:50]
        snapshot["positions"] = positions
        snapshot["positions_complete"] = True
    except Exception as exc:
        snapshot["ok"] = False
        snapshot["positions_error"] = safe_error_message(exc)
    try:
        snapshot["resting_orders"] = complete_pages(
            lambda path: kalshi_private_request(path, **creds),
            "/portfolio/orders", "orders", params={"status": "resting", "limit": 1000},
        )
        snapshot["orders_complete"] = True
    except Exception as exc:
        snapshot["ok"] = False
        snapshot["orders_error"] = safe_error_message(exc)
    return snapshot


def fetch_live_orders(settings, limit=100):
    creds = kalshi_credentials(settings)
    if not kalshi_private_request or not creds["api_key_id"]:
        return []
    try:
        return complete_pages(lambda path: kalshi_private_request(path, **creds),
                              "/portfolio/orders", "orders", params={"limit": int(limit)})
    except Exception as exc:
        log_line(f"CRYPTO LIVE ORDERS FETCH WARNING: {safe_error_message(exc)}")
        return []


def fetch_live_settlements(settings, limit=100):
    creds = kalshi_credentials(settings)
    if not kalshi_private_request or not creds["api_key_id"]:
        return []
    try:
        return complete_pages(lambda path: kalshi_private_request(path, **creds),
                              "/portfolio/settlements", "settlements", params={"limit": int(limit)})
    except Exception as exc:
        log_line(f"CRYPTO LIVE SETTLEMENTS FETCH WARNING: {safe_error_message(exc)}")
        return []


def order_fill_cost(order, outcome_side=None):
    for key in ("taker_fill_cost_dollars", "maker_fill_cost_dollars"):
        try:
            value = float(order.get(key) or 0)
        except (TypeError, ValueError):
            value = 0.0
        if value > 0:
            return round(value, 4)
    count = order_fill_count(order)
    if count <= 0:
        return None
    price = order_entry_price_cents(order, outcome_side=outcome_side)
    return round(count * price / 100.0, 4) if price > 0 else None


def order_fill_count(order):
    try:
        return float(order.get("fill_count_fp") or order.get("fill_count") or 0)
    except (TypeError, ValueError):
        return 0.0


def order_fill_fee(order):
    fee = 0.0
    direct_fee_present = False
    for key in ("taker_fees_dollars", "maker_fees_dollars"):
        direct_fee_present = direct_fee_present or key in order
        try:
            fee += float(order.get(key) or 0)
        except (TypeError, ValueError):
            continue
    if direct_fee_present:
        return round(fee, 4)
    try:
        average_fee = float(order.get("average_fee_paid") or 0)
    except (TypeError, ValueError):
        average_fee = 0.0
    return round(average_fee * order_fill_count(order), 4)


def order_entry_price_cents(order, outcome_side=None):
    side = str(outcome_side or order.get("outcome_side") or order.get("side") or "yes").lower()
    # Kalshi order requests use bid for YES and ask for NO in this bot.
    side = "no" if side in {"no", "ask"} else "yes"
    key = "no_price_dollars" if side == "no" else "yes_price_dollars"
    try:
        price = float(order.get(key) or 0)
    except (TypeError, ValueError):
        price = 0.0
    if price <= 0:
        opposite_key = "yes_price_dollars" if side == "no" else "no_price_dollars"
        try:
            opposite = float(order.get(opposite_key) or 0)
        except (TypeError, ValueError):
            opposite = 0.0
        if 0 < opposite < 1:
            price = 1.0 - opposite
    if price <= 0:
        try:
            average_yes_price = float(order.get("average_fill_price") or 0)
        except (TypeError, ValueError):
            average_yes_price = 0.0
        if 0 < average_yes_price < 1:
            price = 1.0 - average_yes_price if side == "no" else average_yes_price
    return round(price * 100.0, 4) if 0 < price < 1 else 0.0


def local_live_order_identifiers(portfolio):
    order_ids = set()
    client_ids = set()
    for bet in portfolio.get("bets", []):
        live_order = bet.get("live_order") or {}
        response = live_order.get("response") or {}
        request = live_order.get("request") or {}
        order_id = bet.get("kalshi_order_id") or response.get("order_id")
        client_id = bet.get("kalshi_client_order_id") or request.get("client_order_id")
        if order_id:
            order_ids.add(str(order_id))
        if client_id:
            client_ids.add(str(client_id))
    return order_ids, client_ids


def user_crypto_order_candidates(portfolio, settings, orders):
    known_order_ids, known_client_ids = local_live_order_identifiers(portfolio)
    crypto_series = tuple(setting_list(settings, "CRYPTO_SERIES"))
    candidates = []
    for order in orders or []:
        ticker = str(order.get("ticker") or order.get("market_ticker") or "")
        order_id = str(order.get("order_id") or "")
        client_id = str(order.get("client_order_id") or "")
        if (
            not ticker
            or not order_id
            or (crypto_series and not ticker.startswith(crypto_series))
            or str(order.get("action") or "buy").lower() != "buy"
            or order_fill_count(order) <= 0
            or order_id in known_order_ids
            or (client_id and client_id in known_client_ids)
            or client_id.lower().startswith("crypto-")
        ):
            continue
        candidates.append(order)
    return candidates


def import_user_crypto_orders(portfolio, settings, orders=None):
    orders = fetch_live_orders(settings) if orders is None else orders
    imported = []
    for order in user_crypto_order_candidates(portfolio, settings, orders):
        ticker = str(order.get("ticker") or order.get("market_ticker") or "")
        side = str(order.get("outcome_side") or order.get("side") or "yes").lower()
        asset = infer_asset({"ticker": ticker, "series_ticker": ticker.split("-", 1)[0]})
        contracts = order_fill_count(order)
        stake = order_fill_cost(order)
        entry_price = order_entry_price_cents(order)
        if not asset or contracts <= 0 or stake is None or entry_price <= 0:
            continue
        bet = {
            "id": str(uuid.uuid4()),
            "status": "open",
            "mode": "live",
            "placed_at": order.get("created_time") or iso_now(),
            "imported_at": iso_now(),
            "ticker": ticker,
            "kalshi_ticker": ticker,
            "event_ticker": ticker.rsplit("-", 1)[0],
            "series_ticker": ticker.split("-", 1)[0],
            "asset": asset,
            "title": f"User {asset} 15-minute Kalshi bet",
            "market_kind": "above",
            "is_15m_market": True,
            "side": side,
            "order_side": side,
            "entry_price": entry_price,
            "stake": stake,
            "contracts": contracts,
            "fee": order_fill_fee(order),
            "source": "kalshi_user_order_import",
            "strategy_owner": "user_bet",
            "user_bet": True,
            "excluded_from_bot_campaign": True,
            "excluded_from_bot_analytics": True,
            "kalshi_order_id": str(order.get("order_id") or ""),
            "kalshi_client_order_id": str(order.get("client_order_id") or ""),
            "kalshi_order_status": order.get("status"),
            "live_order": {
                "actual_stake": stake,
                "contracts": contracts,
                "price": entry_price,
                "response": {
                    "order_id": order.get("order_id"),
                    "client_order_id": order.get("client_order_id"),
                    "ticker": ticker,
                    "side": side,
                    "action": order.get("action"),
                    "status": order.get("status"),
                    "fill_count_fp": order.get("fill_count_fp"),
                    "created_time": order.get("created_time"),
                },
            },
        }
        portfolio.setdefault("bets", []).append(bet)
        imported.append(bet)
        log_line(
            f"CRYPTO USER BET IMPORTED: {side.upper()} {asset} {ticker} "
            f"stake=${stake:.4f} fee=${bet['fee']:.4f} contracts={contracts:.4f}"
        )
        event_line({"type": "crypto_user_bet_imported", "bet": bet})
    return imported


def sync_live_order_costs(portfolio, settings, orders=None):
    orders = fetch_live_orders(settings) if orders is None else orders
    by_order_id = {str(order.get("order_id") or ""): order for order in orders if order.get("order_id")}
    by_client_id = {str(order.get("client_order_id") or ""): order for order in orders if order.get("client_order_id")}
    changed = False
    for bet in portfolio.get("bets", []):
        if bet.get("mode") != "live" or bet.get("status") != "open":
            continue
        live_order = bet.get("live_order") or {}
        response = live_order.get("response") or {}
        request = live_order.get("request") or {}
        order = (
            by_order_id.get(str(bet.get("kalshi_order_id") or response.get("order_id") or ""))
            or by_client_id.get(str(bet.get("kalshi_client_order_id") or request.get("client_order_id") or ""))
        )
        if not order:
            continue
        cost = order_fill_cost(order, outcome_side=bet.get("side"))
        if cost is None:
            continue
        current_stake = round(float(bet.get("stake") or 0), 4)
        if abs(current_stake - cost) > 0.005:
            bet["original_recorded_stake"] = current_stake
            bet["stake"] = cost
            live_order["actual_stake"] = cost
            live_order["order_cost_source"] = "kalshi_order_fill_cost"
            bet["live_order"] = live_order
            changed = True
            log_line(f"CRYPTO LIVE COST SYNC: {bet.get('ticker')} stake ${current_stake:.4f} -> ${cost:.4f}")
        contracts = order_fill_count(order)
        if contracts > 0 and abs(float(bet.get("contracts") or 0) - contracts) > 0.00001:
            bet["contracts"] = contracts
            changed = True
        entry_price = order_entry_price_cents(order, outcome_side=bet.get("side"))
        if entry_price > 0 and abs(float(bet.get("entry_price") or 0) - entry_price) > 0.00001:
            bet.setdefault("quoted_entry_price", bet.get("entry_price"))
            bet["entry_price"] = entry_price
            live_order["executed_price"] = entry_price
            live_order["order_cost_source"] = "kalshi_order_fill_cost"
            bet["live_order"] = live_order
            changed = True
        fee = order_fill_fee(order)
        if abs(float(bet.get("fee") or 0) - fee) > 0.00001:
            bet["fee"] = fee
            changed = True
    return changed


def settlement_cost_for_side(settlement, side):
    side = "no" if str(side).lower() == "no" else "yes"
    key = "no_total_cost_dollars" if side == "no" else "yes_total_cost_dollars"
    try:
        return round(float(settlement.get(key) or 0), 2)
    except (TypeError, ValueError):
        return 0.0


def settlement_contracts_for_side(settlement, side):
    side = "no" if str(side).lower() == "no" else "yes"
    key = "no_count_fp" if side == "no" else "yes_count_fp"
    try:
        return float(settlement.get(key) or 0)
    except (TypeError, ValueError):
        return 0.0


def settle_live_bets_from_kalshi(portfolio, settings, settlements=None):
    settlements = fetch_live_settlements(settings) if settlements is None else settlements
    by_ticker = {str(row.get("ticker") or ""): row for row in settlements if row.get("ticker")}
    changed = False
    changed_rows = []
    for bet in list(portfolio.get("bets", [])):
        if bet.get("mode") != "live" or bet.get("status") != "open":
            continue
        ticker = bet.get("kalshi_ticker") or bet.get("ticker")
        settlement = by_ticker.get(str(ticker or ""))
        if not settlement:
            continue
        side = str(bet.get("order_side") or bet.get("side") or "yes").lower()
        contracts = float(bet.get("contracts") or 0) or settlement_contracts_for_side(settlement, side)
        cost = float(bet.get("stake") or 0) or settlement_cost_for_side(settlement, side)
        market_result = str(settlement.get("market_result") or "").lower()
        total_contracts = (
            settlement_contracts_for_side(settlement, "yes")
            + settlement_contracts_for_side(settlement, "no")
        )
        if bet.get("fee") is not None:
            fee = float(bet.get("fee") or 0)
        else:
            total_fee = float(settlement.get("fee_cost") or 0)
            fee = total_fee * contracts / total_contracts if total_contracts > 0 else total_fee
        payout = round(contracts if market_result == side else 0.0, 2)
        profit = round(payout - cost - fee, 2)
        result = "WIN" if market_result == side else "LOSS"
        bet.update({
            "status": "settled",
            "settled_at": settlement.get("settled_time") or iso_now(),
            "settlement_source": "kalshi_live_settlement",
            "market_result": market_result,
            "result": result,
            "contracts": contracts,
            "stake": round(cost, 4),
            "fee": round(fee, 4),
            "payout": payout,
            "profit": profit,
        })
        changed = True
        changed_rows.append(bet)
        log_line(
            f"CRYPTO LIVE SETTLED: {result} {ticker} side={side} "
            f"cost=${cost:.2f} fee=${fee:.4f} payout=${payout:.2f} profit=${profit:.2f} "
            f"low_edge_pilot={bool((bet.get('low_edge_pilot') or {}).get('active'))}"
        )
        event_line({"type": "live_settled_bet", "bet": bet})
    if (
        changed_rows
        and execution_mode(settings) == "live"
        and PORTFOLIO_FILE == LIVE_PORTFOLIO_FILE
    ):
        update_live_bot_ledger(changed_rows)
    return changed


def finalized_market_bet_fee(bet):
    if bet.get("fee") is not None:
        return round(float(bet.get("fee") or 0), 4)
    response = ((bet.get("live_order") or {}).get("response") or {})
    try:
        per_contract = float(response.get("average_fee_paid") or 0)
    except (TypeError, ValueError):
        per_contract = 0.0
    return round(per_contract * float(bet.get("contracts") or 0), 4)


def settle_stale_live_bets_from_markets(
    portfolio,
    settings,
    tickers,
    markets=None,
):
    tickers = {str(value) for value in tickers or [] if value}
    markets = dict(markets or {})
    changed_rows = []
    for bet in portfolio.get("bets") or []:
        if (
            bet.get("mode") != "live"
            or bet.get("status") != "open"
            or str(bet.get("kalshi_ticker") or bet.get("ticker") or "") not in tickers
        ):
            continue
        ticker = str(bet.get("kalshi_ticker") or bet.get("ticker") or "")
        market = markets.get(ticker)
        if market is None:
            try:
                payload = http_json(f"{KALSHI_BASE}/markets/{quote(ticker)}")
                market = (payload or {}).get("market") or {}
            except Exception as exc:
                log_line(
                    f"CRYPTO FINALIZED MARKET LOOKUP WARNING: {ticker} "
                    f"{type(exc).__name__}: {safe_error_message(exc)}"
                )
                continue
        market_result = str(market.get("result") or "").lower()
        if (
            str(market.get("status") or "").lower() != "finalized"
            or market_result not in {"yes", "no"}
        ):
            continue
        side = str(bet.get("order_side") or bet.get("side") or "yes").lower()
        contracts = float(bet.get("contracts") or 0)
        cost = float(bet.get("stake") or 0)
        fee = finalized_market_bet_fee(bet)
        payout = round(contracts if side == market_result else 0.0, 2)
        profit = round(payout - cost - fee, 2)
        result = "WIN" if side == market_result else "LOSS"
        bet.update({
            "status": "settled",
            "settled_at": market.get("settlement_ts") or iso_now(),
            "settlement_source": "kalshi_finalized_market_recovery",
            "market_result": market_result,
            "result": result,
            "fee": fee,
            "payout": payout,
            "profit": profit,
        })
        changed_rows.append(bet)
        log_line(
            f"CRYPTO FINALIZED MARKET RECOVERED: {result} {ticker} side={side} "
            f"cost=${cost:.2f} fee=${fee:.4f} payout=${payout:.2f} profit=${profit:.2f}"
        )
        event_line({"type": "live_settled_bet", "bet": bet})
    if changed_rows:
        update_live_bot_ledger(changed_rows)
    return len(changed_rows)


def reconciliation_remote_tickers(remote_positions, local_tickers, crypto_series):
    """Return nonzero remote crypto positions, retaining locally owned legacy series."""
    local_tickers = set(local_tickers or ())
    crypto_series = tuple(crypto_series or ())
    tickers = set()
    for pos in remote_positions or ():
        ticker = str(pos.get("ticker") or pos.get("market_ticker") or "")
        if not ticker:
            continue
        contracts = 0.0
        for key in ("position_fp", "position", "count"):
            try:
                contracts = abs(float(pos.get(key) or 0))
            except (TypeError, ValueError):
                continue
            if contracts:
                break
        if not contracts:
            continue
        if ticker in local_tickers or not crypto_series or ticker.startswith(crypto_series):
            tickers.add(ticker)
    return tickers


def delayed_live_settlement_alerts(
    portfolio,
    settings,
    remote_tickers,
    now=None,
):
    """Report long-closed remote positions without assuming their outcome."""
    now = now or utc_now()
    threshold_minutes = max(
        1.0,
        setting_float(
            settings,
            "CRYPTO_LIVE_DELAYED_SETTLEMENT_ALERT_MINUTES",
        ),
    )
    repeat_minutes = max(
        threshold_minutes,
        setting_float(
            settings,
            "CRYPTO_LIVE_DELAYED_SETTLEMENT_ALERT_REPEAT_MINUTES",
        ),
    )
    remote_tickers = set(remote_tickers or ())
    alerts = []
    for bet in portfolio.get("bets") or []:
        if (
            bet.get("mode") != "live"
            or bet.get("status") != "open"
            or bet.get("strategy_owner") != CRYPTO_15M_CAMPAIGN_OWNER
        ):
            continue
        ticker = str(bet.get("kalshi_ticker") or bet.get("ticker") or "")
        if not ticker or ticker not in remote_tickers:
            continue
        close_time = parse_time(bet.get("close_time"))
        if not close_time:
            continue
        if close_time.tzinfo is None:
            close_time = close_time.replace(tzinfo=timezone.utc)
        delay_minutes = (now - close_time.astimezone(timezone.utc)).total_seconds() / 60.0
        if delay_minutes < threshold_minutes:
            continue
        metadata = bet.setdefault("delayed_settlement_alert", {})
        metadata.setdefault("first_detected_at", iso_now())
        metadata.update({
            "active": True,
            "last_detected_at": iso_now(),
            "delay_minutes": round(delay_minutes, 2),
            "outcome_assumed": False,
        })
        alert = {
            "ticker": ticker,
            "asset": bet.get("asset"),
            "bot_number": crypto_campaign_bot_number(bet),
            "close_time": bet.get("close_time"),
            "delay_minutes": round(delay_minutes, 2),
            "remote_position_present": True,
            "outcome_assumed": False,
        }
        alerts.append(alert)
        last_logged_at = parse_time(metadata.get("last_logged_at"))
        should_log = (
            last_logged_at is None
            or (now - last_logged_at.astimezone(timezone.utc)).total_seconds()
            >= repeat_minutes * 60.0
        )
        if should_log:
            metadata["last_logged_at"] = iso_now()
            log_line(
                f"CRYPTO DELAYED SETTLEMENT ALERT: {ticker} "
                f"bot={alert['bot_number']} delay={alert['delay_minutes']:.1f}m "
                "remote_position_present=true outcome_assumed=false"
            )
            event_line({
                "type": "delayed_settlement_alert",
                **alert,
            })
    return alerts


def reconcile_live_account(portfolio, settings):
    orders = fetch_live_orders(settings)
    imported_user_bets = import_user_crypto_orders(portfolio, settings, orders=orders)
    sync_changed = sync_live_order_costs(portfolio, settings, orders=orders)
    settlements = fetch_live_settlements(settings)
    settle_changed = settle_live_bets_from_kalshi(
        portfolio,
        settings,
        settlements=settlements,
    )
    report = {
        "generated_at": iso_now(),
        "readiness": crypto_live_readiness(settings),
        "local_live_open": live_local_open_positions(portfolio),
        "sync_changed": sync_changed,
        "settle_changed": settle_changed,
        "user_bet_import": {
            "imported_count": len(imported_user_bets),
            "imported_order_ids": [bet.get("kalshi_order_id") for bet in imported_user_bets],
            "tracked_open_count": len([
                bet for bet in open_bets(portfolio) if is_user_crypto_bet(bet)
            ]),
        },
    }
    if not setting_bool(settings, "CRYPTO_RECONCILE_LIVE_ON_SCAN"):
        report["account"] = {"ok": False, "reason": "reconciliation_disabled"}
        write_json(LIVE_RECONCILIATION_FILE, report)
        return report

    account = fetch_live_account_snapshot(settings)
    report["account"] = account
    local_tickers = set(report["local_live_open"])
    remote_positions = account.get("positions") or []
    crypto_series = tuple(setting_list(settings, "CRYPTO_SERIES"))
    remote_tickers = reconciliation_remote_tickers(
        remote_positions,
        local_tickers,
        crypto_series,
    )
    delayed_alerts = delayed_live_settlement_alerts(
        portfolio,
        settings,
        remote_tickers,
    )
    report["delayed_settlement_alerts"] = delayed_alerts
    report["delayed_settlement_alert_count"] = len(delayed_alerts)
    stale_local_tickers = local_tickers - remote_tickers
    finalized_recovered = settle_stale_live_bets_from_markets(
        portfolio,
        settings,
        stale_local_tickers,
    )
    if finalized_recovered:
        report["finalized_market_recovered_count"] = finalized_recovered
        report["local_live_open"] = live_local_open_positions(portfolio)
        local_tickers = set(report["local_live_open"])
    if account.get("ok"):
        report["unmatched_local_tickers"] = sorted(local_tickers - remote_tickers)[:50]
        report["unmatched_remote_tickers"] = sorted(remote_tickers - local_tickers)[:50]
    else:
        report["unmatched_local_tickers"] = []
        report["unmatched_remote_tickers"] = []
    if account.get("cash_balance") is not None:
        portfolio["live_cash_balance"] = account.get("cash_balance")
        if execution_mode(settings) == "live":
            portfolio["balance"] = account.get("cash_balance")
    write_json(LIVE_RECONCILIATION_FILE, report)
    if account.get("ok"):
        log_line(f"CRYPTO LIVE RECONCILIATION OK: cash={account.get('cash_balance')} remote_positions={account.get('position_count', 0)} local_live_open={len(local_tickers)}")
    else:
        log_line(f"CRYPTO LIVE RECONCILIATION WARNING: {account.get('balance_error') or account.get('reason') or account.get('positions_error')}")
    return report


def live_bankroll_for_sizing(settings, portfolio):
    if build_shared_bankroll_state:
        try:
            cash = build_shared_bankroll_state(save=True).get("cash")
            if cash is not None:
                return max(0.0, float(cash))
        except Exception:
            pass
    live_cash = portfolio.get("live_cash_balance")
    if live_cash is not None:
        return max(0.0, float(live_cash))
    return max(0.0, float(portfolio.get("balance") or 0))


def infer_asset(market):
    expanded = infer_market_asset(market)
    if expanded:
        return expanded
    blob = " ".join(str(market.get(k) or "") for k in ("ticker", "event_ticker", "series_ticker", "title", "subtitle")).upper()
    for needle, asset in SERIES_ASSET_HINTS.items():
        if re.search(rf"\b{needle}\b", blob) or needle in str(market.get("series_ticker") or "").upper():
            return asset
    if "BITCOIN" in blob:
        return "BTC"
    if "ETHEREUM" in blob:
        return "ETH"
    if "SOLANA" in blob:
        return "SOL"
    if "DOGECOIN" in blob:
        return "DOGE"
    return ""


def market_series_ticker(market):
    explicit = str(market.get("series_ticker") or "").upper()
    if explicit:
        return explicit
    event_ticker = str(market.get("event_ticker") or "").upper()
    ticker = str(market.get("ticker") or "").upper()
    return event_ticker.split("-", 1)[0] or ticker.split("-", 1)[0]


def kalshi_series_fee_schedule(settings, series_ticker):
    """Return a cached, authoritative fee schedule for one Kalshi series."""
    series = str(series_ticker or "").strip().upper()
    if not series:
        return {
            "series_ticker": "",
            "fee_type": "unknown",
            "fee_multiplier": 1.0,
            "authoritative": False,
            "source": "missing_series_ticker",
        }
    now_ts = time.time()
    ttl = max(60.0, setting_float(settings, "CRYPTO_FEE_SCHEDULE_CACHE_MINUTES") * 60.0)
    cached = KALSHI_SERIES_FEE_CACHE.get(series) or {}
    if cached and now_ts - float(cached.get("_cached_unix") or 0) <= ttl:
        return {key: value for key, value in cached.items() if not key.startswith("_")}
    try:
        payload = http_json(
            f"{KALSHI_BASE}/series/{quote(series, safe='')}",
            timeout=max(1.0, setting_float(settings, "CRYPTO_HTTP_TIMEOUT_SECONDS")),
            retries=1,
        )
        row = payload.get("series") if isinstance(payload, dict) else {}
        row = row if isinstance(row, dict) else {}
        fee_type = str(row.get("fee_type") or "unknown").strip().lower()
        multiplier_value = row.get("fee_multiplier")
        multiplier = float(1.0 if multiplier_value in (None, "") else multiplier_value)
        schedule = {
            "series_ticker": series,
            "fee_type": fee_type,
            "fee_multiplier": multiplier,
            "authoritative": fee_type in {"quadratic", "quadratic_with_maker_fees"},
            "source": "kalshi_series_api",
            "fetched_at": iso_now(),
        }
        KALSHI_SERIES_FEE_CACHE[series] = {**schedule, "_cached_unix": now_ts}
        return schedule
    except Exception as exc:
        if cached:
            stale = {key: value for key, value in cached.items() if not key.startswith("_")}
            stale["source"] = "stale_kalshi_series_cache"
            stale["stale"] = True
            stale["refresh_error"] = safe_error_message(exc)
            return stale
        return {
            "series_ticker": series,
            "fee_type": "unknown",
            "fee_multiplier": 1.0,
            "authoritative": False,
            "source": "conservative_fallback",
            "error": safe_error_message(exc),
        }


def is_15m_target_market(market):
    return market_series_ticker(market).endswith("15M") and market_kind(market) == "above"


def market_minutes_to_close(market, now=None):
    now = now or utc_now()
    close_time = parse_time(
        market.get("close_time")
        or market.get("expected_expiration_time")
        or market.get("expiration_time")
    )
    if not close_time:
        return None
    return (close_time - now).total_seconds() / 60.0


def fetch_kalshi_markets(settings):
    global LAST_KALSHI_MARKET_FETCH_HEALTH, KALSHI_MARKET_SCAN_SEQUENCE
    series_list = setting_list(settings, "CRYPTO_SERIES")
    base_limit = setting_int(settings, "CRYPTO_KALSHI_MARKETS_PER_SERIES")
    hourly_limit = setting_int(settings, "MULTI_MARKET_HOURLY_MARKETS_PER_SERIES")
    all_markets = []
    successful_series = []
    failed_series = []
    cached_series = []
    cached_fallback_series = []
    KALSHI_MARKET_SCAN_SEQUENCE += 1
    scan_sequence = KALSHI_MARKET_SCAN_SEQUENCE
    hourly_series = [
        series for series in series_list
        if market_lane({"series_ticker": series}) in {"crypto_hourly", "commodity_hourly"}
    ]
    hourly_group = {series: index % 2 for index, series in enumerate(hourly_series)}
    stagger_hourly = setting_bool(settings, "MULTI_MARKET_HOURLY_DISCOVERY_STAGGER_ENABLED")
    cache_seconds = max(
        30.0,
        setting_float(settings, "MULTI_MARKET_HOURLY_DISCOVERY_CACHE_SECONDS"),
    )

    def fetch_series(series):
        lane = market_lane({"series_ticker": series})
        is_hourly = lane in {"crypto_hourly", "commodity_hourly"}
        cached = KALSHI_SERIES_MARKET_CACHE.get(series) or {}
        cache_age = max(0.0, time.monotonic() - float(cached.get("fetched_monotonic") or 0))
        scheduled_for_refresh = hourly_group.get(series, scan_sequence % 2) == scan_sequence % 2
        if (
            is_hourly
            and stagger_hourly
            and cached.get("markets") is not None
            and not scheduled_for_refresh
            and cache_age <= cache_seconds
        ):
            return series, list(cached["markets"]), "", "scheduled_cache"
        limit = hourly_limit if lane in {"crypto_hourly", "commodity_hourly"} else base_limit
        url = f"{KALSHI_BASE}/markets?series_ticker={quote(series)}&status=open&limit={limit}"
        try:
            payload = http_json(url, retries=2)
            markets = payload.get("markets", [])
            quote_fetched_at = iso_now()
            for market in markets:
                if isinstance(market, dict):
                    market["_quote_fetched_at"] = quote_fetched_at
            KALSHI_SERIES_MARKET_CACHE[series] = {
                "markets": list(markets),
                "fetched_monotonic": time.monotonic(),
                "fetched_at": quote_fetched_at,
            }
            return series, markets, "", "network"
        except Exception as exc:
            error = f"{type(exc).__name__}: {safe_error_message(exc)}"
            if is_hourly and cached.get("markets") is not None and cache_age <= cache_seconds:
                return series, list(cached["markets"]), error, "error_cache"
            return series, [], error, "error"

    workers = max(
        1,
        min(
            len(series_list) or 1,
            setting_int(settings, "CRYPTO_FETCH_MAX_WORKERS") or 1,
        ),
    )
    with ThreadPoolExecutor(max_workers=workers, thread_name_prefix="crypto-markets") as pool:
        futures = [pool.submit(fetch_series, series) for series in series_list]
        for future in as_completed(futures):
            series, markets, error, source = future.result()
            all_markets.extend(markets)
            if source == "error_cache":
                successful_series.append(series)
                cached_fallback_series.append(series)
                log_line(
                    f"Kalshi crypto markets CACHED_FALLBACK series={series} "
                    f"markets={len(markets)} error={error}"
                )
            elif error:
                failed_series.append({
                    "series": series,
                    "error": compact_log_value(error, 1000),
                })
                log_line(f"Kalshi crypto markets ERROR series={series} error={error}")
            else:
                successful_series.append(series)
                if source == "scheduled_cache":
                    cached_series.append(series)
                else:
                    log_line(f"Kalshi crypto markets OK series={series} markets={len(markets)}")
    deduped = {
        market.get("ticker"): market
        for market in all_markets
        if market.get("ticker")
        and market_lane(market) != "unsupported"
        and (
            market_lane(market) != "crypto_15m"
            or not setting_bool(settings, "CRYPTO_15M_CAMPAIGN_ENABLED")
            or is_15m_target_market(market)
        )
    }
    error_text = " ".join(row["error"] for row in failed_series).lower()
    LAST_KALSHI_MARKET_FETCH_HEALTH = {
        "fetched_at": iso_now(),
        "series_requested": len(series_list),
        "successful_series": len(successful_series),
        "failed_series": len(failed_series),
        "cached_series": len(cached_series),
        "cached_fallback_series": len(cached_fallback_series),
        "markets_loaded": len(deduped),
        "outage": bool(series_list and not successful_series and failed_series),
        "network_failure": bool(
            failed_series
            and any(
                token in error_text
                for token in (
                    "failed to resolve",
                    "getaddrinfo failed",
                    "nameresolutionerror",
                    "network is unreachable",
                    "socket operation",
                    "connection aborted",
                )
            )
        ),
        "errors": failed_series[:5],
    }
    return list(deduped.values())


def fetch_coinbase_snapshot(asset):
    product = ASSET_PRODUCTS.get(asset, {}).get("coinbase")
    if not product:
        raise ValueError(f"unsupported_asset_{asset}")
    ticker = http_json(f"https://api.exchange.coinbase.com/products/{product}/ticker", retries=1)
    spot = float(ticker.get("price"))
    granularity = 60 if str(product) else 300
    candles = http_json(f"https://api.exchange.coinbase.com/products/{product}/candles?granularity={granularity}", retries=1)
    candles = sorted(candles, key=lambda row: row[0])
    closes = [float(row[4]) for row in candles if len(row) >= 5]
    if len(closes) < 10:
        raise ValueError(f"coinbase_candles_short_{asset}")
    # A separate 15-minute series supplies enough non-overlapping history for
    # a genuine 24-hour forecast. The one-minute series remains untouched for
    # the 1h/4h models and 15-minute settlement work.
    closes_15m = []
    try:
        daily_candles = http_json(
            f"https://api.exchange.coinbase.com/products/{product}/candles?granularity=900",
            retries=1,
        )
        daily_candles = sorted(daily_candles, key=lambda row: row[0])
        closes_15m = [float(row[4]) for row in daily_candles if len(row) >= 5]
    except Exception:
        closes_15m = []
    return {
        "asset": asset,
        "source": "coinbase",
        "spot": spot,
        "closes": closes,
        "closes_15m": closes_15m,
        "volume_24h": float(ticker.get("volume") or 0),
        "fetched_at": iso_now(),
    }


def fetch_coingecko_price(asset):
    coin = ASSET_PRODUCTS.get(asset, {}).get("coingecko")
    if not coin:
        raise ValueError(f"unsupported_asset_{asset}")
    url = f"https://api.coingecko.com/api/v3/simple/price?ids={coin}&vs_currencies=usd&include_24hr_change=true"
    payload = http_json(url, retries=1)
    row = payload.get(coin) or {}
    return {
        "asset": asset,
        "source": "coingecko",
        "spot": float(row.get("usd")),
        "change_24h": float(row.get("usd_24h_change") or 0),
        "fetched_at": iso_now(),
    }


def get_coinbase_microstructure_stream(settings, assets):
    global COINBASE_MICROSTRUCTURE_STREAM
    if not setting_bool(settings, "CRYPTO_15M_MICROSTRUCTURE_ENABLED"):
        return None
    products = {
        asset: ASSET_PRODUCTS.get(asset, {}).get("coinbase")
        for asset in assets or []
        if ASSET_PRODUCTS.get(asset, {}).get("coinbase")
    }
    if not products:
        return None
    if (
        COINBASE_MICROSTRUCTURE_STREAM is None
        or COINBASE_MICROSTRUCTURE_STREAM.asset_products != products
    ):
        COINBASE_MICROSTRUCTURE_STREAM = CoinbaseMicrostructureStream(products)
        started = COINBASE_MICROSTRUCTURE_STREAM.start()
        log_line(
            f"Crypto Coinbase microstructure stream {'started' if started else 'REST fallback'} "
            f"products={len(products)}"
        )
    return COINBASE_MICROSTRUCTURE_STREAM


def get_kraken_microstructure_stream(settings, assets):
    global KRAKEN_MICROSTRUCTURE_STREAM
    if (
        not setting_bool(settings, "CRYPTO_15M_MICROSTRUCTURE_ENABLED")
        or not setting_bool(settings, "CRYPTO_KRAKEN_WS_ENABLED")
    ):
        return None
    selected = sorted({str(asset or "").upper() for asset in assets or [] if asset})
    if not selected:
        return None
    expected = {
        asset: value
        for asset, value in KrakenMicrostructureStream(selected).asset_symbols.items()
    }
    if (
        KRAKEN_MICROSTRUCTURE_STREAM is None
        or KRAKEN_MICROSTRUCTURE_STREAM.asset_symbols != expected
    ):
        KRAKEN_MICROSTRUCTURE_STREAM = KrakenMicrostructureStream(selected)
        started = KRAKEN_MICROSTRUCTURE_STREAM.start()
        log_line(
            f"Crypto Kraken v2 microstructure stream "
            f"{'started' if started else 'REST fallback'} products={len(expected)}"
        )
    return KRAKEN_MICROSTRUCTURE_STREAM


def get_kalshi_crypto_stream(settings, tickers):
    global KALSHI_CRYPTO_STREAM
    if (
        not setting_bool(settings, "CRYPTO_15M_MICROSTRUCTURE_ENABLED")
        or not setting_bool(settings, "CRYPTO_KALSHI_WS_ENABLED")
    ):
        return None
    selected = list(dict.fromkeys(str(value or "").strip() for value in tickers or [] if value))
    if not selected:
        return None
    credentials = kalshi_credentials(settings)
    identity = (
        str(credentials.get("api_key_id") or ""),
        str(credentials.get("private_key_path") or ""),
        bool(credentials.get("private_key_pem")),
    )
    current_identity = getattr(KALSHI_CRYPTO_STREAM, "_credential_identity", None)
    if KALSHI_CRYPTO_STREAM is None or current_identity != identity:
        KALSHI_CRYPTO_STREAM = KalshiCryptoStream(
            api_key_id=credentials.get("api_key_id"),
            private_key_path=credentials.get("private_key_path"),
            private_key_pem=credentials.get("private_key_pem"),
        )
        KALSHI_CRYPTO_STREAM._credential_identity = identity
        started = KALSHI_CRYPTO_STREAM.start()
        log_line(
            f"Crypto Kalshi market stream "
            f"{'started' if started else 'REST fallback'} tickers={len(selected)}"
        )
    KALSHI_CRYPTO_STREAM.replace_subscriptions(selected)
    KALSHI_CRYPTO_STREAM.start()
    return KALSHI_CRYPTO_STREAM


def align_asset_history_to_proxy(asset_row, proxy_spot):
    """Put Coinbase history on the same price basis as the live proxy.

    A constant rescale preserves all candle returns while preventing the
    Coinbase/Kraken basis from looking like short-horizon momentum.
    """
    original_spot = float(asset_row.get("spot") or 0)
    proxy_spot = float(proxy_spot or 0)
    if original_spot <= 0 or proxy_spot <= 0:
        return asset_row
    factor = proxy_spot / original_spot
    asset_row["coinbase_spot"] = original_spot
    asset_row["spot"] = proxy_spot
    asset_row["closes"] = [
        float(value) * factor
        for value in (asset_row.get("closes") or [])
    ]
    asset_row["closes_15m"] = [
        float(value) * factor
        for value in (asset_row.get("closes_15m") or [])
    ]
    asset_row["settlement_proxy_used"] = True
    asset_row["price_alignment_factor"] = factor
    return asset_row


def align_commodity_proxy_to_kalshi_anchor(settings, asset_row, anchor_market):
    """Transport an exact Kalshi/Pyth opening value with a liquid Core return."""
    if not asset_row.get("requires_kalshi_anchor"):
        return asset_row
    open_time = parse_time((anchor_market or {}).get("open_time"))
    floor, _ = market_strikes(anchor_market or {})
    if not open_time or floor is None or floor <= 0:
        raise ValueError("commodity_kalshi_anchor_missing")
    age_minutes = (utc_now() - open_time).total_seconds() / 60.0
    max_age = setting_float(settings, "MULTI_MARKET_PROXY_MAX_ANCHOR_AGE_MINUTES")
    if age_minutes < -0.25 or age_minutes > max_age:
        raise ValueError(f"commodity_kalshi_anchor_stale_{age_minutes:.1f}m")
    feed = asset_row.get("pyth_proxy") or {}
    anchor = fetch_pyth_price_at(
        feed,
        int(open_time.timestamp()),
        api_key=pyth_api_key(settings),
        timeout=setting_float(settings, "MULTI_MARKET_PYTH_TIMEOUT_SECONDS"),
    )
    proxy_open = float(anchor.get("price") or 0)
    proxy_now = float(asset_row.get("spot") or 0)
    if proxy_open <= 0 or proxy_now <= 0:
        raise ValueError("commodity_proxy_anchor_price_invalid")
    factor = float(floor) / proxy_open
    row = dict(asset_row)
    row["spot"] = proxy_now * factor
    row["closes"] = [float(value) * factor for value in (asset_row.get("closes") or [])]
    row["source"] = "kalshi_anchored_pyth_core"
    row["settlement_source"] = "Pyth"
    row["settlement_proxy_used"] = True
    row["requires_kalshi_anchor"] = False
    row["kalshi_anchor"] = {
        "ticker": anchor_market.get("ticker"),
        "open_time": open_time.isoformat(),
        "settlement_open": float(floor),
        "proxy_open": proxy_open,
        "proxy_now": proxy_now,
        "transported_spot": row["spot"],
        "age_minutes": round(age_minutes, 3),
        "proxy_publish_time": anchor.get("publish_time"),
    }
    microstructure = dict(asset_row.get("microstructure") or {})
    microstructure.update({
        "settlement_proxy_spot": row["spot"],
        "source": "kalshi_open_anchored_pyth_core_return",
    })
    row["microstructure"] = microstructure
    return row


def fetch_asset_data(
    settings,
    assets=None,
    coinbase_stream=None,
    kraken_stream=None,
):
    data = {}
    selected_assets = setting_list(settings, "CRYPTO_ASSETS") if assets is None else assets

    def fetch_asset(asset):
        if asset in COMMODITY_ASSETS:
            prior_health = COMMODITY_DATA_HEALTH.get(asset) or {}
            prior_checked = parse_time(prior_health.get("checked_at"))
            retry_minutes = max(
                1.0,
                setting_float(settings, "MULTI_MARKET_PYTH_ENTITLEMENT_RETRY_MINUTES"),
            )
            exact_feed_cooldown = (
                prior_health.get("reason") == "pyth_not_entitled"
                and prior_checked
                and utc_now() - prior_checked < timedelta(minutes=retry_minutes)
            )
            try:
                common = {
                    "api_key": pyth_api_key(settings),
                    "lookback_minutes": setting_int(settings, "MULTI_MARKET_PYTH_LOOKBACK_MINUTES"),
                    "max_age_seconds": setting_float(settings, "MULTI_MARKET_PYTH_MAX_AGE_SECONDS"),
                    "timeout": setting_float(settings, "MULTI_MARKET_PYTH_TIMEOUT_SECONDS"),
                    "channel": settings.get("MULTI_MARKET_PYTH_CHANNEL", "fixed_rate@1000ms"),
                }
                if exact_feed_cooldown:
                    raise PermissionError("exact_pyth_feed_entitlement_cooldown")
                row = fetch_commodity_snapshot(asset, **common)
                COMMODITY_DATA_HEALTH[asset] = {
                    "ok": True,
                    "reason": "ready",
                    "checked_at": iso_now(),
                    "symbol": (row.get("pyth") or {}).get("symbol"),
                }
                return asset, row, [
                    f"Commodity price data OK asset={asset} source=pyth "
                    f"spot={row['spot']:.5f} history={len(row.get('closes') or [])}"
                ]
            except Exception as exc:
                status_code = getattr(getattr(exc, "response", None), "status_code", None)
                if setting_bool(settings, "MULTI_MARKET_PROXY_ENABLED") and (
                    exact_feed_cooldown or status_code == 403 or isinstance(exc, PermissionError)
                ):
                    try:
                        row = fetch_commodity_proxy_snapshot(
                            asset,
                            twelve_api_key=settings.get("MULTI_MARKET_TWELVE_DATA_API_KEY", ""),
                            **common,
                        )
                        COMMODITY_DATA_HEALTH[asset] = {
                            "ok": True,
                            "reason": "pyth_not_entitled",
                            "proxy_ready": True,
                            "checked_at": iso_now(),
                            "symbol": (row.get("pyth_proxy") or {}).get("symbol"),
                            "exact_feed_entitled": False,
                        }
                        return asset, row, [
                            f"Commodity price data OK asset={asset} source=pyth_core_proxy "
                            f"spot={row['spot']:.5f} history={len(row.get('closes') or [])} "
                            "anchor=kalshi_open_required"
                        ]
                    except Exception as proxy_exc:
                        exc = proxy_exc
                        status_code = getattr(getattr(exc, "response", None), "status_code", None)
                COMMODITY_DATA_HEALTH[asset] = {
                    "ok": False,
                    "reason": "pyth_not_entitled" if status_code == 403 else "pyth_feed_error",
                    "status_code": status_code,
                    "error_type": type(exc).__name__,
                    "checked_at": iso_now(),
                }
                return asset, None, [
                    f"Commodity price data BLOCKED asset={asset} "
                    f"{type(exc).__name__}: {safe_error_message(exc)}"
                ]
        if asset not in ASSET_PRODUCTS:
            return asset, None, [f"unsupported_asset_{asset}"]
        messages = []
        try:
            row = fetch_coinbase_snapshot(asset)
            messages.append(
                f"Price data OK asset={asset} source=coinbase spot={row['spot']:.4f}"
            )
        except Exception as exc:
            try:
                row = fetch_coingecko_price(asset)
                row["closes"] = [row["spot"]]
                messages.append(
                    f"Price data fallback OK asset={asset} source=coingecko spot={row['spot']:.4f}"
                )
            except Exception as fallback_exc:
                messages.append(
                    f"Price data ERROR asset={asset} primary={type(exc).__name__}: "
                    f"{safe_error_message(exc)} fallback={type(fallback_exc).__name__}: "
                    f"{safe_error_message(fallback_exc)}"
                )
                return asset, None, messages
        if setting_bool(settings, "CRYPTO_15M_MICROSTRUCTURE_ENABLED"):
            try:
                microstructure = combined_asset_microstructure(
                    asset,
                    ASSET_PRODUCTS[asset]["coinbase"],
                    coinbase_stream=coinbase_stream,
                    kraken_stream=kraken_stream,
                    timeout=max(1.0, setting_float(settings, "CRYPTO_15M_MICROSTRUCTURE_TIMEOUT_SECONDS")),
                )
                row["microstructure"] = microstructure
                proxy_spot = float(microstructure.get("settlement_proxy_spot") or 0)
                dispersion = float(microstructure.get("cross_exchange_dispersion_bps") or 0)
                if (
                    proxy_spot > 0
                    and int(microstructure.get("settlement_proxy_source_count") or 0) >= 2
                    and dispersion <= setting_float(settings, "CRYPTO_15M_FLOW_CONFIRMATION_MAX_DISPERSION_BPS")
                ):
                    align_asset_history_to_proxy(row, proxy_spot)
                messages.append(
                    f"Crypto microstructure OK asset={asset} sources={microstructure.get('settlement_proxy_source_count')} "
                    f"proxy={proxy_spot:.6f} dispersion={dispersion:.2f}bps "
                    f"flow={float(microstructure.get('underlying_flow_score') or 0):+.3f}"
                )
            except Exception as exc:
                row["microstructure"] = {"errors": [safe_error_message(exc)]}
                messages.append(
                    f"Crypto microstructure WARNING asset={asset} "
                    f"{type(exc).__name__}: {safe_error_message(exc)}"
                )
        return asset, row, messages

    selected_assets = list(selected_assets or [])
    workers = max(
        1,
        min(
            len(selected_assets) or 1,
            setting_int(settings, "CRYPTO_FETCH_MAX_WORKERS") or 1,
        ),
    )
    with ThreadPoolExecutor(max_workers=workers, thread_name_prefix="crypto-assets") as pool:
        futures = [pool.submit(fetch_asset, asset) for asset in selected_assets]
        for future in as_completed(futures):
            asset, row, messages = future.result()
            for message in messages:
                log_line(message)
            if row is not None:
                data[asset] = row
    return data


def fetch_kalshi_microstructure(settings, markets):
    if not setting_bool(settings, "CRYPTO_15M_MICROSTRUCTURE_ENABLED"):
        return {}
    timeout = max(1.0, setting_float(settings, "CRYPTO_15M_MICROSTRUCTURE_TIMEOUT_SECONDS"))
    rows = {}
    selected = []
    for market in markets or []:
        ticker = market.get("ticker")
        minutes = market_minutes_to_close(market)
        if (
            not ticker
            or not is_15m_target_market(market)
            or minutes is None
            or minutes < 0
            or minutes > 15
        ):
            continue
        selected.append(ticker)
    selected = list(dict.fromkeys(selected))

    stream = get_kalshi_crypto_stream(settings, selected)
    max_age_seconds = max(0.25, setting_float(settings, "CRYPTO_KALSHI_WS_MAX_AGE_SECONDS"))
    if stream:
        stream.wait_for_fresh(
            selected,
            max_age_seconds=max_age_seconds,
            timeout_seconds=max(0.0, setting_float(settings, "CRYPTO_KALSHI_WS_WAIT_SECONDS")),
        )
        for ticker in selected:
            snapshot = stream.snapshot(ticker, max_age_seconds=max_age_seconds)
            if (
                snapshot.get("fresh")
                and snapshot.get("yes_levels")
                and snapshot.get("no_levels")
            ):
                snapshot["source"] = "kalshi_websocket"
                snapshot["orderbook_fetched_at"] = snapshot.get("received_at")
                rows[ticker] = snapshot

    fallback_tickers = [ticker for ticker in selected if ticker not in rows]

    def fetch_ticker(ticker):
        try:
            return ticker, kalshi_market_microstructure(
                KALSHI_BASE, ticker, timeout=timeout
            ), ""
        except Exception as exc:
            return ticker, {"error": safe_error_message(exc)}, (
                f"{type(exc).__name__}: {safe_error_message(exc)}"
            )

    workers = max(
        1,
        min(
            len(fallback_tickers) or 1,
            setting_int(settings, "CRYPTO_FETCH_MAX_WORKERS") or 1,
        ),
    )
    with ThreadPoolExecutor(max_workers=workers, thread_name_prefix="crypto-kalshi-micro") as pool:
        futures = [pool.submit(fetch_ticker, ticker) for ticker in fallback_tickers]
        for future in as_completed(futures):
            ticker, row, error = future.result()
            rows[ticker] = row
            if error:
                log_line(
                    f"Crypto Kalshi microstructure WARNING ticker={ticker} {error}"
                )
    return rows


def fetch_fear_greed():
    try:
        payload = http_json("https://api.alternative.me/fng/?limit=1&format=json", retries=1)
        row = (payload.get("data") or [{}])[0]
        return {
            "value": float(row.get("value") or 50),
            "classification": row.get("value_classification") or "Neutral",
            "source": "alternative.me",
        }
    except Exception as exc:
        log_line(f"Fear greed ERROR {type(exc).__name__}: {exc}")
        return {"value": 50.0, "classification": "Neutral", "source": "fallback"}


def score_text_sentiment(text):
    words = re.findall(r"[a-zA-Z]+", text.lower())
    if not words:
        return 0.0
    pos = sum(1 for word in words if word in POSITIVE_WORDS)
    neg = sum(1 for word in words if word in NEGATIVE_WORDS)
    return max(-1.0, min(1.0, (pos - neg) / max(3, pos + neg + 1)))


def dedupe_preserve_order(values):
    seen = set()
    deduped = []
    for value in values:
        clean = re.sub(r"\s+", " ", str(value or "")).strip()
        key = clean.lower()
        if not clean or key in seen:
            continue
        seen.add(key)
        deduped.append(clean)
    return deduped


def fetch_free_rss_headlines(settings, asset):
    if not setting_bool(settings, "CRYPTO_FREE_RSS_ENABLED"):
        return []
    terms = {
        "BTC": ["bitcoin", "btc"],
        "ETH": ["ethereum", "ether", "eth"],
        "SOL": ["solana", "sol"],
        "XRP": ["xrp", "ripple"],
        "DOGE": ["dogecoin", "doge"],
        "GOLD": ["gold", "bullion", "xau"],
        "SILVER": ["silver", "xag"],
        "WTI": ["wti", "crude oil", "oil", "opec", "petroleum"],
    }.get(asset, [asset.lower()])
    urls = [url.strip() for url in settings.get("CRYPTO_FREE_RSS_URLS", "").split(",") if url.strip()]
    headlines = []
    headers = {"User-Agent": f"polymaker-crypto-{execution_mode(settings)}/1.0"}
    for url in urls:
        try:
            response = requests.get(url, headers=headers, timeout=12)
            response.raise_for_status()
            root = ET.fromstring(response.content)
            for item in root.findall(".//item") + root.findall(".//{http://www.w3.org/2005/Atom}entry"):
                title_node = item.find("title")
                if title_node is None:
                    title_node = item.find("{http://www.w3.org/2005/Atom}title")
                title = "".join(title_node.itertext()).strip() if title_node is not None else ""
                if title and any(re.search(rf"\b{re.escape(term)}\b", title, re.IGNORECASE) for term in terms):
                    headlines.append(title)
        except Exception as exc:
            log_line(f"Free RSS ERROR asset={asset} url={url} {type(exc).__name__}: {exc}")
    return dedupe_preserve_order(headlines)


def fetch_news_sentiment(settings, asset):
    global NEWS_API_BACKOFF_UNTIL
    if not setting_bool(settings, "CRYPTO_NEWS_ENABLED"):
        return {"score": 0.0, "count": 0, "headlines": [], "source": "disabled"}
    cache_key = str(asset or "").upper()
    cached = NEWS_SENTIMENT_CACHE.get(cache_key) or {}
    cache_seconds = max(0.0, setting_float(settings, "CRYPTO_NEWS_CACHE_MINUTES") * 60.0)
    if cached and time.time() - float(cached.get("cached_at") or 0) <= cache_seconds:
        return dict(cached.get("value") or {})
    terms = {
        "BTC": "bitcoin OR BTC",
        "ETH": "ethereum OR ETH",
        "SOL": "solana OR SOL",
        "XRP": "XRP OR ripple",
        "DOGE": "dogecoin OR DOGE",
        "GOLD": "gold bullion federal reserve rates",
        "SILVER": "silver metal federal reserve rates",
        "WTI": "WTI crude oil OPEC EIA inventory",
    }.get(asset, asset)
    headlines = []
    sources = []
    api_key = settings.get("CRYPTO_NEWS_API_KEY", "")
    newsapi_backoff_active = bool(NEWS_API_BACKOFF_UNTIL and utc_now() < NEWS_API_BACKOFF_UNTIL)
    if api_key and not newsapi_backoff_active:
        since = (utc_now() - timedelta(hours=setting_float(settings, "CRYPTO_NEWS_LOOKBACK_HOURS"))).strftime("%Y-%m-%dT%H:%M:%SZ")
        url = f"https://newsapi.org/v2/everything?q={quote(terms)}&from={quote(since)}&sortBy=publishedAt&pageSize=20&language=en&apiKey={quote(api_key)}"
        try:
            payload = http_json(url, retries=1)
            newsapi_headlines = [item.get("title", "") for item in payload.get("articles", []) if item.get("title")]
            headlines.extend(newsapi_headlines)
            if newsapi_headlines:
                sources.append("newsapi")
        except Exception as exc:
            response = getattr(exc, "response", None)
            if getattr(response, "status_code", None) == 429:
                backoff_minutes = max(1.0, setting_float(settings, "CRYPTO_NEWS_API_BACKOFF_MINUTES"))
                NEWS_API_BACKOFF_UNTIL = utc_now() + timedelta(minutes=backoff_minutes)
                log_line(
                    f"NewsAPI RATE LIMITED asset={asset}; pausing NewsAPI for {backoff_minutes:g}m "
                    "and continuing with configured fallback news feeds"
                )
            else:
                log_line(f"NewsAPI ERROR asset={asset} {type(exc).__name__}: {safe_error_message(exc)}")
    cryptopanic_key = settings.get("CRYPTO_CRYPTOPANIC_API_KEY", "")
    if cryptopanic_key and str(asset).upper() in CRYPTO_ASSETS:
        url = f"https://cryptopanic.com/api/v1/posts/?auth_token={quote(cryptopanic_key)}&currencies={quote(asset)}&public=true"
        try:
            payload = http_json(url, retries=1)
            cryptopanic_headlines = [item.get("title", "") for item in payload.get("results", []) if item.get("title")]
            headlines.extend(cryptopanic_headlines)
            if cryptopanic_headlines:
                sources.append("cryptopanic")
        except Exception as exc:
            log_line(f"CryptoPanic ERROR asset={asset} {type(exc).__name__}: {safe_error_message(exc)}")
    rss_headlines = fetch_free_rss_headlines(settings, asset)
    if rss_headlines:
        headlines.extend(rss_headlines)
        sources.append("free_rss")
    headlines = dedupe_preserve_order(headlines)
    score = sum(score_text_sentiment(title) for title in headlines) / len(headlines) if headlines else 0.0
    result = {"score": round(score, 3), "count": len(headlines), "headlines": headlines[:8], "source": ",".join(sources) if sources else "none"}
    NEWS_SENTIMENT_CACHE[cache_key] = {"cached_at": time.time(), "value": result}
    return dict(result)


def fetch_market_regime_news(settings, prior_state=None):
    """Fetch one shared hourly news bundle instead of one request per asset."""
    global NEWS_API_BACKOFF_UNTIL
    prior = (((prior_state or {}).get("latest") or {}).get("news") or {})
    prior_global = prior.get("global") or {}
    fetched_at = parse_regime_time(prior_global.get("fetched_at"))
    max_age = max(60.0, setting_float(settings, "CRYPTO_MARKET_REGIME_NEWS_REFRESH_MINUTES") * 60.0)
    allowed_age = min(max_age, 300.0) if prior_global.get("status") == "no_headlines" else max_age
    if fetched_at and (utc_now() - fetched_at).total_seconds() <= allowed_age:
        return prior
    if not setting_bool(settings, "CRYPTO_NEWS_ENABLED"):
        return {"global": {"score": 0.0, "count": 0, "headlines": [], "sources": [], "risk_level": "normal", "fetched_at": iso_now(), "status": "disabled"}, "by_asset": {}}

    headlines = []
    sources = []
    api_key = str(settings.get("CRYPTO_NEWS_API_KEY") or "").strip()
    newsapi_backoff_active = bool(NEWS_API_BACKOFF_UNTIL and utc_now() < NEWS_API_BACKOFF_UNTIL)
    if api_key and not newsapi_backoff_active:
        since = (utc_now() - timedelta(hours=setting_float(settings, "CRYPTO_MARKET_REGIME_NEWS_LOOKBACK_HOURS"))).strftime("%Y-%m-%dT%H:%M:%SZ")
        try:
            response = requests.get(
                "https://newsapi.org/v2/everything",
                params={
                    "q": '(bitcoin OR ethereum OR solana OR XRP OR dogecoin OR "crypto market")',
                    "from": since,
                    "sortBy": "publishedAt",
                    "pageSize": 30,
                    "language": "en",
                    "apiKey": api_key,
                },
                headers={"User-Agent": f"polymaker-regime-{execution_mode(settings)}/1.0"},
                timeout=12,
            )
            response.raise_for_status()
            rows = response.json().get("articles") or []
            newsapi_headlines = [str(row.get("title") or "").strip() for row in rows if row.get("title")]
            headlines.extend(newsapi_headlines)
            if newsapi_headlines:
                sources.append("newsapi")
        except Exception as exc:
            status_code = getattr(getattr(exc, "response", None), "status_code", None)
            if status_code == 429:
                backoff_minutes = max(1.0, setting_float(settings, "CRYPTO_NEWS_API_BACKOFF_MINUTES"))
                NEWS_API_BACKOFF_UNTIL = utc_now() + timedelta(minutes=backoff_minutes)
            log_line(f"Market regime NewsAPI WARNING {type(exc).__name__}: {safe_error_message(exc)}")

    # RSS is optional and fetched once for the entire regime rather than once per asset.
    if setting_bool(settings, "CRYPTO_FREE_RSS_ENABLED"):
        urls = [url.strip() for url in str(settings.get("CRYPTO_FREE_RSS_URLS") or "").split(",") if url.strip()]
        for url in urls:
            try:
                response = requests.get(url, headers={"User-Agent": "polymaker-regime/1.0"}, timeout=12)
                response.raise_for_status()
                root = ET.fromstring(response.content)
                for item in root.findall(".//item") + root.findall(".//{http://www.w3.org/2005/Atom}entry"):
                    title_node = item.find("title")
                    if title_node is None:
                        title_node = item.find("{http://www.w3.org/2005/Atom}title")
                    title = "".join(title_node.itertext()).strip() if title_node is not None else ""
                    if title:
                        headlines.append(title)
                sources.append("free_rss")
            except Exception as exc:
                log_line(f"Market regime RSS WARNING {type(exc).__name__}: {safe_error_message(exc)}")

    headlines = dedupe_preserve_order(headlines)[:60]
    risk_terms = ("hack", "exploit", "liquidat", "crash", "emergency", "ban", "lawsuit", "war", "attack", "outage", "default")
    risk_count = sum(any(term in headline.lower() for term in risk_terms) for headline in headlines)
    global_score = sum(score_text_sentiment(headline) for headline in headlines) / max(1, len(headlines))
    asset_terms = {
        "BTC": ("bitcoin", "btc"), "ETH": ("ethereum", "ether", "eth"),
        "SOL": ("solana", "sol"), "XRP": ("xrp", "ripple"), "DOGE": ("dogecoin", "doge"),
    }
    by_asset = {}
    for asset, terms in asset_terms.items():
        selected = [headline for headline in headlines if any(re.search(rf"\b{re.escape(term)}\b", headline, re.IGNORECASE) for term in terms)]
        if selected:
            by_asset[asset] = {
                "score": round(sum(score_text_sentiment(headline) for headline in selected) / len(selected), 4),
                "count": len(selected),
                "headlines": selected[:5],
            }
    return {
        "global": {
            "score": round(global_score, 4),
            "count": len(headlines),
            "headlines": headlines[:12],
            "sources": dedupe_preserve_order(sources),
            "risk_level": "event" if risk_count >= 3 else "elevated" if risk_count >= 1 else "normal",
            "risk_headline_count": risk_count,
            "fetched_at": iso_now(),
            "status": "ok" if headlines else "no_headlines",
        },
        "by_asset": by_asset,
    }


def _request_market_regime_ai_shadow(settings, preliminary_snapshot):
    model = str(settings.get("CRYPTO_MARKET_REGIME_AI_MODEL") or "gemma3:4b")
    maximum_confidence = max(0.0, min(1.0, setting_float(settings, "CRYPTO_MARKET_REGIME_AI_MAX_CONFIDENCE")))
    compact_assets = {
        asset: {
            "direction": row.get("direction"), "regime": row.get("regime"),
            "score_1h": row.get("score_1h"), "score_4h": row.get("score_4h"),
            "score_24h": row.get("score_24h"),
            "reliability": row.get("reliability"),
            "rsi_1h": (row.get("features") or {}).get("rsi_1h"),
            "flow": (row.get("features") or {}).get("flow_score"),
        }
        for asset, row in (preliminary_snapshot.get("assets") or {}).items()
    }
    prompt = (
        "You are a shadow-only market-regime classifier. Do not recommend trades or sizes. "
        "Using only the supplied metrics and headlines, classify the next one, four, and twenty-four hours conservatively. "
        "Do not copy the input or repeat numeric metrics. Return exactly this JSON shape: "
        '{"global_forecast":{"direction_1h":"up|down|neutral","direction_4h":"up|down|neutral","direction_24h":"up|down|neutral",'
        '"confidence":0.00,"event_risk":"normal|elevated|event","reason":"short explanation"},'
        '"asset_forecasts":[{"asset":"BTC","direction_1h":"up|down|neutral",'
        '"direction_4h":"up|down|neutral","direction_24h":"up|down|neutral","confidence":0.00,"reason":"short explanation"}]}. '
        "Include one asset_forecasts row for every supplied asset. Confidence must be a decimal from 0 to "
        f"{maximum_confidence:.2f}; use a positive confidence when either direction is not neutral. "
        "Neutral is valid.\nINPUT METRICS:\n"
        + json.dumps({
            "global": preliminary_snapshot.get("global") or {},
            "assets": compact_assets,
            "news": (preliminary_snapshot.get("news") or {}).get("global") or {},
        }, separators=(",", ":"))
    )
    reviewed = {"enabled": True, "mode": "shadow_only", "affects_execution": False, "model": model, "reviewed_at": iso_now()}
    try:
        response = requests.post(
            str(settings.get("CRYPTO_MARKET_REGIME_AI_URL") or "http://127.0.0.1:11434").rstrip("/") + "/api/generate",
            json={
                "model": model,
                "prompt": prompt,
                "stream": False,
                "format": "json",
                "keep_alive": "2h",
                "options": {"temperature": 0.1, "num_predict": 1600},
            },
            timeout=max(3.0, setting_float(settings, "CRYPTO_MARKET_REGIME_AI_TIMEOUT_SECONDS")),
        )
        response.raise_for_status()
        parsed = json.loads(str(response.json().get("response") or "{}"))
        normalized = {}
        for scope in ("global", "assets"):
            source = (
                parsed.get("global_forecast") or parsed.get("global") or {}
                if scope == "global"
                else parsed.get("asset_forecasts") or parsed.get("assets") or {}
            )
            if scope == "assets" and isinstance(source, list):
                source = {
                    str(row.get("asset") or "").upper(): row
                    for row in source
                    if isinstance(row, dict) and row.get("asset")
                }
            if scope == "global":
                source = {"GLOBAL": source}
            clean = {}
            for asset, row in source.items():
                if not isinstance(row, dict):
                    continue
                direction_1h = str(row.get("direction_1h") or row.get("direction") or "neutral").lower()
                direction_4h = str(row.get("direction_4h") or row.get("direction") or "neutral").lower()
                direction_24h = str(row.get("direction_24h") or row.get("direction") or "neutral").lower()
                raw_confidence = float(row.get("confidence") or 0.0)
                if raw_confidence > 1.0:
                    raw_confidence /= 100.0
                clean[str(asset).upper()] = {
                    "direction_1h": direction_1h if direction_1h in {"up", "down", "neutral"} else "neutral",
                    "direction_4h": direction_4h if direction_4h in {"up", "down", "neutral"} else "neutral",
                    "direction_24h": direction_24h if direction_24h in {"up", "down", "neutral"} else "neutral",
                    "confidence": round(max(0.0, min(maximum_confidence, raw_confidence)), 4),
                    "reason": re.sub(r"\s+", " ", str(row.get("reason") or ""))[:240],
                }
                if scope == "global":
                    risk = str(row.get("event_risk") or "normal").lower()
                    clean[str(asset).upper()]["event_risk"] = risk if risk in {"normal", "elevated", "event"} else "normal"
            normalized[scope] = clean.get("GLOBAL", {}) if scope == "global" else clean
        all_forecasts = [normalized.get("global") or {}, *(normalized.get("assets") or {}).values()]
        if not any(float(row.get("confidence") or 0.0) > 0 for row in all_forecasts):
            raise ValueError("invalid_ai_schema_missing_confidence")
        expected_assets = set(compact_assets)
        returned_assets = set(normalized.get("assets") or {})
        missing_assets = sorted(expected_assets - returned_assets)
        if missing_assets:
            # Small local models sometimes stop after four asset objects. A
            # compact second batch completes coverage on the same background
            # thread and still never delays the trading scan.
            try:
                missing_prompt = (
                    "Return strict JSON only with key asset_forecasts. Include exactly these assets: "
                    + ",".join(missing_assets)
                    + ". For each include asset, direction_1h, direction_4h, direction_24h (up/down/neutral), "
                    f"confidence from 0 to {maximum_confidence:.2f}, and a reason under 20 words. "
                    "Do not copy input metrics. INPUT:\n"
                    + json.dumps({asset: compact_assets[asset] for asset in missing_assets}, separators=(",", ":"))
                )
                followup = requests.post(
                    str(settings.get("CRYPTO_MARKET_REGIME_AI_URL") or "http://127.0.0.1:11434").rstrip("/") + "/api/generate",
                    json={
                        "model": model,
                        "prompt": missing_prompt,
                        "stream": False,
                        "format": "json",
                        "keep_alive": "2h",
                        "options": {"temperature": 0.1, "num_predict": 900},
                    },
                    timeout=max(3.0, setting_float(settings, "CRYPTO_MARKET_REGIME_AI_TIMEOUT_SECONDS")),
                )
                followup.raise_for_status()
                followup_parsed = json.loads(str(followup.json().get("response") or "{}"))
                followup_rows = followup_parsed.get("asset_forecasts") or followup_parsed.get("assets") or {}
                if isinstance(followup_rows, list):
                    followup_rows = {
                        str(row.get("asset") or "").upper(): row
                        for row in followup_rows
                        if isinstance(row, dict) and row.get("asset")
                    }
                for asset, row in (followup_rows.items() if isinstance(followup_rows, dict) else []):
                    asset = str(asset).upper()
                    if asset not in expected_assets or not isinstance(row, dict):
                        continue
                    direction_1h = str(row.get("direction_1h") or row.get("direction") or "neutral").lower()
                    direction_4h = str(row.get("direction_4h") or row.get("direction") or "neutral").lower()
                    direction_24h = str(row.get("direction_24h") or row.get("direction") or "neutral").lower()
                    raw_confidence = float(row.get("confidence") or 0.0)
                    if raw_confidence > 1.0:
                        raw_confidence /= 100.0
                    normalized["assets"][asset] = {
                        "direction_1h": direction_1h if direction_1h in {"up", "down", "neutral"} else "neutral",
                        "direction_4h": direction_4h if direction_4h in {"up", "down", "neutral"} else "neutral",
                        "direction_24h": direction_24h if direction_24h in {"up", "down", "neutral"} else "neutral",
                        "confidence": round(max(0.0, min(maximum_confidence, raw_confidence)), 4),
                        "reason": re.sub(r"\s+", " ", str(row.get("reason") or ""))[:240],
                    }
                returned_assets = set(normalized.get("assets") or {})
                missing_assets = sorted(expected_assets - returned_assets)
            except Exception as followup_exc:
                log_line(
                    "Market regime local AI follow-up WARNING "
                    f"{type(followup_exc).__name__}: {safe_error_message(followup_exc)}"
                )
        reviewed.update({
            "status": "ok" if not missing_assets else "partial",
            "asset_coverage": {
                "returned": len(expected_assets & returned_assets),
                "expected": len(expected_assets),
                "missing": missing_assets,
            },
            **normalized,
        })
    except Exception as exc:
        reviewed.update({"status": "error", "error": safe_error_message(exc), "global": {}, "assets": {}})
        log_line(f"Market regime local AI WARNING {type(exc).__name__}: {safe_error_message(exc)}")
    return reviewed


def _market_regime_ai_worker(settings, preliminary_snapshot):
    global MARKET_REGIME_AI_JOB, MARKET_REGIME_AI_RESULT
    result = _request_market_regime_ai_shadow(settings, preliminary_snapshot)
    with MARKET_REGIME_AI_LOCK:
        MARKET_REGIME_AI_RESULT = result
        MARKET_REGIME_AI_JOB = None


def run_market_regime_ai_shadow(settings, preliminary_snapshot, prior_state=None):
    """Return cached AI context immediately and refresh it off the scan thread."""
    global MARKET_REGIME_AI_JOB
    if not setting_bool(settings, "CRYPTO_MARKET_REGIME_AI_ENABLED"):
        return {"enabled": False, "status": "disabled"}
    previous = (((prior_state or {}).get("latest") or {}).get("ai_shadow") or {})
    max_age = max(60.0, setting_float(settings, "CRYPTO_MARKET_REGIME_AI_REFRESH_MINUTES") * 60.0)
    with MARKET_REGIME_AI_LOCK:
        completed = MARKET_REGIME_AI_RESULT or {}
        completed_at = parse_regime_time(completed.get("reviewed_at"))
        if completed_at and (utc_now() - completed_at).total_seconds() <= max_age:
            return completed
    reviewed_at = parse_regime_time(previous.get("reviewed_at"))
    previous_forecasts = [previous.get("global") or {}, *((previous.get("assets") or {}).values())]
    previous_has_confidence = any(float(row.get("confidence") or 0.0) > 0 for row in previous_forecasts)
    if previous.get("status") in {"error", "pending"} or not previous_has_confidence:
        allowed_age = min(max_age, 60.0)
    elif previous.get("status") == "partial":
        allowed_age = min(max_age, 60.0)
    else:
        allowed_age = max_age
    if reviewed_at and (utc_now() - reviewed_at).total_seconds() <= allowed_age:
        return previous
    with MARKET_REGIME_AI_LOCK:
        if MARKET_REGIME_AI_JOB is None or not MARKET_REGIME_AI_JOB.is_alive():
            MARKET_REGIME_AI_JOB = threading.Thread(
                target=_market_regime_ai_worker,
                args=(dict(settings), dict(preliminary_snapshot)),
                name="market-regime-ai-shadow",
                daemon=True,
            )
            MARKET_REGIME_AI_JOB.start()
    if previous:
        return {**previous, "refresh_pending": True}
    return {
        "enabled": True,
        "mode": "shadow_only",
        "affects_execution": False,
        "status": "pending",
        "model": str(settings.get("CRYPTO_MARKET_REGIME_AI_MODEL") or "gemma3:4b"),
        "reviewed_at": iso_now(),
        "global": {},
        "assets": {},
    }


def build_market_regime_scan_context(settings, asset_data, perps_report, candidates):
    if not setting_bool(settings, "CRYPTO_MARKET_REGIME_ENABLED"):
        return {"mode": "disabled", "affects_execution": False, "annotated_candidates": 0}
    state = read_market_regime_json(CRYPTO_MARKET_REGIME_FILE, {"history": []})
    latest = state.get("latest") or {}
    generated_at = parse_regime_time(latest.get("generated_at"))
    refresh_seconds = max(60.0, setting_float(settings, "CRYPTO_MARKET_REGIME_REFRESH_MINUTES") * 60.0)
    refreshed = not generated_at or (utc_now() - generated_at).total_seconds() > refresh_seconds
    ai_updated = False
    news_updated = False
    forecast_records = list(state.get("forecast_records") or [])
    forecast_evaluation = state.get("forecast_evaluation") or {}
    if refreshed:
        news = fetch_market_regime_news(settings, state)
        preliminary = build_regime_snapshot(
            asset_data,
            perps_report=perps_report,
            news_context=news,
            calibration=forecast_evaluation,
        )
        ai_shadow = run_market_regime_ai_shadow(settings, preliminary, state)
        snapshot = build_regime_snapshot(
            asset_data,
            perps_report=perps_report,
            news_context=news,
            ai_shadow=ai_shadow,
            calibration=forecast_evaluation,
        )
        forecast_records, forecast_evaluation = update_market_regime_forecasts(
            forecast_records,
            snapshot,
        )
        evaluation = summarize_market_regime_dataset(CRYPTO_15M_TRAINING_DATASET_FILE)
        state = persist_market_regime_snapshot(
            CRYPTO_MARKET_REGIME_FILE,
            snapshot,
            maximum_history=setting_int(settings, "CRYPTO_MARKET_REGIME_HISTORY_MAX"),
            evaluation=evaluation,
            forecast_records=forecast_records,
            forecast_evaluation=forecast_evaluation,
        )
        event_line({"type": "market_regime_refreshed", "snapshot": snapshot, "evaluation": evaluation})
    else:
        snapshot = latest
        evaluation = state.get("evaluation") or summarize_market_regime_dataset(CRYPTO_15M_TRAINING_DATASET_FILE)
        news = fetch_market_regime_news(settings, state)
        if news != (snapshot.get("news") or {}):
            snapshot = {**snapshot, "news": news}
            news_updated = True
        ai_shadow = run_market_regime_ai_shadow(settings, snapshot, state)
        if ai_shadow != (snapshot.get("ai_shadow") or {}):
            snapshot = {**snapshot, "ai_shadow": ai_shadow}
            ai_updated = True
        if ai_updated or news_updated:
            state = persist_market_regime_snapshot(
                CRYPTO_MARKET_REGIME_FILE,
                snapshot,
                maximum_history=setting_int(settings, "CRYPTO_MARKET_REGIME_HISTORY_MAX"),
                evaluation=evaluation,
                forecast_records=forecast_records,
                forecast_evaluation=forecast_evaluation,
            )
    live_requested = bool(
        setting_bool(settings, "CRYPTO_MARKET_REGIME_AFFECTS_EXECUTION")
        and execution_mode(settings) == "live"
    )
    forecast_live_qualified = bool(
        evaluation.get("qualified_for_live")
        and (forecast_evaluation.get("horizons") or {}).get("1h", {}).get("qualified_for_live")
        and (forecast_evaluation.get("horizons") or {}).get("4h", {}).get("qualified_for_live")
    )
    live_enabled = bool(live_requested and forecast_live_qualified)
    annotated = annotate_market_regime_candidates(
        candidates,
        snapshot,
        maximum_adjustment_pp=setting_float(settings, "CRYPTO_MARKET_REGIME_MAX_ADJUSTMENT_PP"),
        execution_enabled=live_enabled,
        live_maximum_adjustment_pp=setting_float(
            settings,
            "CRYPTO_MARKET_REGIME_LIVE_MAX_ADJUSTMENT_PP",
        ),
        live_maximum_age_minutes=setting_float(
            settings,
            "CRYPTO_MARKET_REGIME_LIVE_MAX_AGE_MINUTES",
        ),
        live_minimum_reliability=setting_float(
            settings,
            "CRYPTO_MARKET_REGIME_LIVE_MIN_RELIABILITY",
        ),
    )
    live_adjusted = sum(
        1
        for candidate in candidates or []
        if (candidate.get("market_regime_live") or {}).get("applied")
    )
    return {
        "mode": "live_bounded" if live_enabled else "shadow_only",
        "affects_execution": live_enabled,
        "execution_requested": live_requested,
        "execution_validation_qualified": forecast_live_qualified,
        "refreshed_this_scan": refreshed,
        "ai_updated_this_scan": ai_updated,
        "news_updated_this_scan": news_updated,
        "annotated_candidates": annotated,
        "live_adjusted_candidates": live_adjusted,
        "maximum_adjustment_pp": setting_float(settings, "CRYPTO_MARKET_REGIME_MAX_ADJUSTMENT_PP"),
        "maximum_live_adjustment_pp": setting_float(
            settings,
            "CRYPTO_MARKET_REGIME_LIVE_MAX_ADJUSTMENT_PP",
        ),
        "live_maximum_age_minutes": setting_float(
            settings,
            "CRYPTO_MARKET_REGIME_LIVE_MAX_AGE_MINUTES",
        ),
        "live_minimum_reliability": setting_float(
            settings,
            "CRYPTO_MARKET_REGIME_LIVE_MIN_RELIABILITY",
        ),
        "refresh_minutes": setting_float(settings, "CRYPTO_MARKET_REGIME_REFRESH_MINUTES"),
        "news_refresh_minutes": setting_float(settings, "CRYPTO_MARKET_REGIME_NEWS_REFRESH_MINUTES"),
        "latest": snapshot,
        "evaluation": evaluation,
        "forecast_validation": forecast_evaluation,
    }


def extract_xai_response_text(payload):
    if payload.get("output_text"):
        return str(payload["output_text"])
    chunks = []
    for item in payload.get("output", []) or []:
        for content in item.get("content", []) or []:
            if isinstance(content, dict):
                if content.get("text"):
                    chunks.append(str(content["text"]))
                elif content.get("type") in ("output_text", "text") and content.get("content"):
                    chunks.append(str(content["content"]))
    return "\n".join(chunks)


def parse_grok_review(content):
    raw = str(content or "").strip()
    review = {"enabled": True, "ok": True, "raw": raw[:2000]}
    if not raw:
        review.update({"ok": False, "reason": "empty_grok_response"})
        return review
    match = re.search(r"\{.*\}", raw, re.DOTALL)
    if not match:
        return review
    try:
        parsed = json.loads(match.group(0))
    except json.JSONDecodeError:
        return review
    review["parsed"] = parsed
    if isinstance(parsed, dict):
        review["risk_level"] = str(parsed.get("risk_level", "")).lower()
        veto_value = parsed.get("veto")
        if isinstance(veto_value, str):
            review["veto"] = veto_value.strip().lower() in {"1", "true", "yes", "y", "on"}
        else:
            review["veto"] = bool(veto_value)
        reasons = parsed.get("reasons")
        if isinstance(reasons, list):
            review["reasons"] = [str(item)[:240] for item in reasons[:6]]
    return review


def grok_usage_day():
    return utc_now().date().isoformat()


def grok_candidate_cache_key(candidate):
    return "|".join([
        str(candidate.get("event_ticker") or ""),
        str(candidate.get("ticker") or candidate.get("title") or ""),
        str(candidate.get("side") or "").lower(),
    ])


def grok_candidate_fingerprint(candidate):
    model = candidate.get("model") or {}
    probability = candidate.get("probability") or {}
    news = model.get("news") or {}
    payload = {
        "entry_price_bucket": int(round(float(candidate.get("entry_price") or 0) / 5.0) * 5),
        "model_probability_bucket": int(round(float(candidate.get("model_prob_yes") or 0) / 5.0) * 5),
        "market_gap_bucket": int(round(float(probability.get("market_gap") or 0) / 5.0) * 5),
        "news_score": round(float(news.get("score") or 0), 1),
        "news_headlines": [str(item).strip().lower()[:240] for item in (news.get("headlines") or [])[:8]],
    }
    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()[:20]


def load_grok_usage_state(settings):
    state = read_json(GROK_USAGE_STATE_FILE, {})
    today = grok_usage_day()
    if state.get("date") != today:
        state = {
            "date": today,
            "daily_calls": 0,
            "daily_cost_usd": 0.0,
            "daily_unpriced_reserve_usd": 0.0,
            "cache": state.get("cache") or {},
        }
    state.setdefault("daily_calls", 0)
    state.setdefault("daily_cost_usd", 0.0)
    state.setdefault("daily_unpriced_reserve_usd", 0.0)
    state.setdefault("cache", {})

    cache_cutoff = utc_now() - timedelta(minutes=max(1, setting_int(settings, "CRYPTO_GROK_CACHE_MINUTES")))
    state["cache"] = {
        key: entry
        for key, entry in state["cache"].items()
        if parse_time(entry.get("reviewed_at")) and parse_time(entry.get("reviewed_at")) >= cache_cutoff
    }
    return state


def grok_accounted_cost(state):
    return round(
        float(state.get("daily_cost_usd") or 0) + float(state.get("daily_unpriced_reserve_usd") or 0),
        8,
    )


def cached_grok_review(settings, candidate, state):
    entry = (state.get("cache") or {}).get(grok_candidate_cache_key(candidate))
    if not entry or entry.get("fingerprint") != grok_candidate_fingerprint(candidate):
        return None
    reviewed_at = parse_time(entry.get("reviewed_at"))
    if not reviewed_at or reviewed_at < utc_now() - timedelta(minutes=max(1, setting_int(settings, "CRYPTO_GROK_CACHE_MINUTES"))):
        return None
    review = dict(entry.get("review") or {})
    review.update({
        "enabled": True,
        "source": "cache",
        "cached": True,
        "reviewed_at": entry.get("reviewed_at"),
        "cost_usd": 0.0,
        "daily_accounted_cost_usd": grok_accounted_cost(state),
    })
    return review


def grok_search_needed(settings, candidate):
    if not setting_bool(settings, "CRYPTO_GROK_WEB_SEARCH_ENABLED"):
        return False
    if candidate.get("_ai_needs_live_search"):
        return True
    model = candidate.get("model") or {}
    probability = candidate.get("probability") or {}
    news = model.get("news") or {}
    headlines = " ".join(str(item).lower() for item in (news.get("headlines") or []))
    risk_terms = (
        "hack", "exploit", "breach", "outage", "halt", "liquidat", "regulat", "lawsuit",
        "sanction", "delist", "fraud", "rumor", "etf approval", "etf denial", "emergency",
    )
    return any(term in headlines for term in risk_terms) or (
        abs(float(news.get("score") or 0)) >= setting_float(settings, "CRYPTO_GROK_SEARCH_MIN_NEWS_SCORE")
        or float(model.get("fakeout_risk") or 0) >= setting_float(settings, "CRYPTO_GROK_SEARCH_MIN_FAKEOUT_RISK")
        or abs(float(probability.get("market_gap") or 0)) >= setting_float(settings, "CRYPTO_GROK_SEARCH_MIN_MARKET_GAP")
    )


def xai_usage_summary(payload):
    usage = (payload or {}).get("usage") or {}
    ticks = usage.get("cost_in_usd_ticks")
    cost_usd = None
    try:
        if ticks is not None:
            cost_usd = float(ticks) / 10_000_000_000
    except (TypeError, ValueError):
        ticks = None
    summary = {
        "input_tokens": usage.get("input_tokens", usage.get("prompt_tokens")),
        "output_tokens": usage.get("output_tokens", usage.get("completion_tokens")),
        "total_tokens": usage.get("total_tokens"),
        "cached_input_tokens": usage.get("cached_input_tokens"),
        "server_side_tool_usage": usage.get("server_side_tool_usage") or {},
        "cost_in_usd_ticks": ticks,
        "cost_usd": round(cost_usd, 8) if cost_usd is not None else None,
    }
    return {key: value for key, value in summary.items() if value not in (None, {}, [])}


def record_grok_usage(settings, state, payload):
    usage = xai_usage_summary(payload)
    state["daily_calls"] = int(state.get("daily_calls") or 0) + 1
    if usage.get("cost_usd") is None:
        state["daily_unpriced_reserve_usd"] = round(
            float(state.get("daily_unpriced_reserve_usd") or 0)
            + max(0.01, setting_float(settings, "CRYPTO_GROK_CALL_BUDGET_RESERVE_USD")),
            8,
        )
    else:
        state["daily_cost_usd"] = round(
            float(state.get("daily_cost_usd") or 0) + float(usage["cost_usd"]),
            8,
        )
    state["updated_at"] = iso_now()
    usage["daily_calls"] = state["daily_calls"]
    usage["daily_cost_usd"] = state["daily_cost_usd"]
    usage["daily_unpriced_reserve_usd"] = state["daily_unpriced_reserve_usd"]
    usage["daily_accounted_cost_usd"] = grok_accounted_cost(state)
    return usage


def maybe_grok_review(settings, candidate, scan_context=None):
    if not setting_bool(settings, "CRYPTO_GROK_ENABLED"):
        return {"enabled": False}
    api_key = settings.get("CRYPTO_GROK_API_KEY", "")
    if not api_key:
        return {"enabled": True, "ok": False, "reason": "missing_crypto_grok_api_key"}
    if candidate.get("edge", 0) < setting_float(settings, "CRYPTO_GROK_MIN_EDGE"):
        return {"enabled": True, "ok": False, "reason": "edge_below_grok_min"}
    if candidate.get("confidence", 0) < setting_float(settings, "CRYPTO_GROK_MIN_CONFIDENCE"):
        return {"enabled": True, "ok": False, "reason": "confidence_below_grok_min"}

    state = load_grok_usage_state(settings)
    cached = cached_grok_review(settings, candidate, state)
    if cached:
        return cached

    scan_context = scan_context if scan_context is not None else {}
    scan_calls = int(scan_context.get("api_calls") or 0)
    if scan_calls >= max(0, setting_int(settings, "CRYPTO_GROK_MAX_CALLS_PER_SCAN")):
        return {
            "enabled": True,
            "ok": False,
            "source": "skipped",
            "reason": "scan_call_limit",
            "daily_accounted_cost_usd": grok_accounted_cost(state),
        }

    daily_budget = max(0.0, setting_float(settings, "CRYPTO_GROK_DAILY_BUDGET_USD"))
    call_reserve = max(0.01, setting_float(settings, "CRYPTO_GROK_CALL_BUDGET_RESERVE_USD"))
    if daily_budget <= 0 or grok_accounted_cost(state) + call_reserve > daily_budget + 1e-9:
        return {
            "enabled": True,
            "ok": False,
            "source": "skipped",
            "reason": "daily_budget_exhausted",
            "daily_budget_usd": daily_budget,
            "daily_accounted_cost_usd": grok_accounted_cost(state),
        }

    scan_context["api_calls"] = scan_calls + 1
    use_web_search = grok_search_needed(settings, candidate)
    use_x_search = use_web_search and setting_bool(settings, "CRYPTO_GROK_X_SEARCH_ENABLED")
    search_instruction = (
        "Use live web search only to resolve the material breaking-news ambiguity. "
        if use_web_search
        else "Use only the candidate's embedded market, model, and RSS/news context. "
    )
    prompt = (
        f"You are reviewing a {execution_mode(settings)} Kalshi crypto candidate. "
        f"{search_instruction}Check breaking news, rumor risk, ETF/regulatory headlines, exchange outages, and buy-the-rumor/sell-the-news setups. "
        "Return compact JSON with risk_level low|medium|high, veto boolean, and reasons array. "
        f"Candidate: {json.dumps(candidate, sort_keys=True)[:5000]}"
    )
    response_payload = {}
    try:
        model = settings.get("CRYPTO_GROK_MODEL", DEFAULT_SETTINGS["CRYPTO_GROK_MODEL"])
        max_output_tokens = max(50, setting_int(settings, "CRYPTO_GROK_MAX_OUTPUT_TOKENS"))
        if use_web_search:
            tools = [{"type": "web_search"}]
            if use_x_search:
                tools.append({"type": "x_search"})
            body = {
                "model": model,
                "input": [{"role": "user", "content": prompt}],
                "tools": tools,
                "temperature": 0.1,
                "max_output_tokens": max_output_tokens,
            }
            response = requests.post(
                "https://api.x.ai/v1/responses",
                headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
                json=body,
                timeout=30,
            )
            try:
                response_payload = response.json()
            except ValueError:
                response_payload = {}
            response.raise_for_status()
            content = extract_xai_response_text(response_payload)
        else:
            response = requests.post(
                "https://api.x.ai/v1/chat/completions",
                headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
                json={
                    "model": model,
                    "messages": [{"role": "user", "content": prompt}],
                    "temperature": 0.1,
                    "max_tokens": max_output_tokens,
                },
                timeout=30,
            )
            try:
                response_payload = response.json()
            except ValueError:
                response_payload = {}
            response.raise_for_status()
            content = response_payload["choices"][0]["message"]["content"]
        review = parse_grok_review(content)
        usage = record_grok_usage(settings, state, response_payload)
        review.update({
            "source": "api",
            "cached": False,
            "reviewed_at": iso_now(),
            "web_search": use_web_search,
            "x_search": use_x_search,
            "usage": usage,
            "cost_usd": usage.get("cost_usd"),
            "daily_accounted_cost_usd": usage.get("daily_accounted_cost_usd"),
        })
        state["cache"][grok_candidate_cache_key(candidate)] = {
            "reviewed_at": review["reviewed_at"],
            "fingerprint": grok_candidate_fingerprint(candidate),
            "review": {
                key: review.get(key)
                for key in ("ok", "parsed", "risk_level", "veto", "reasons", "web_search", "x_search")
                if key in review
            },
        }
        write_json(GROK_USAGE_STATE_FILE, state)
        log_line(
            "CRYPTO GROK USAGE: "
            f"ticker={candidate.get('ticker')} cost=${float(usage.get('cost_usd') or 0):.6f} "
            f"daily_accounted=${float(usage.get('daily_accounted_cost_usd') or 0):.6f} "
            f"web={use_web_search} x={use_x_search} tools={json.dumps(usage.get('server_side_tool_usage') or {}, sort_keys=True)}"
        )
        event_line({
            "type": "crypto_grok_usage",
            "ticker": candidate.get("ticker"),
            "event_ticker": candidate.get("event_ticker"),
            "web_search": use_web_search,
            "x_search": use_x_search,
            "usage": usage,
            "veto": bool(review.get("veto")),
            "risk_level": review.get("risk_level"),
        })
        return review
    except Exception as exc:
        usage = record_grok_usage(settings, state, response_payload)
        write_json(GROK_USAGE_STATE_FILE, state)
        reason = f"{type(exc).__name__}: {safe_error_message(exc)}"
        log_line(
            "CRYPTO GROK ERROR: "
            f"ticker={candidate.get('ticker')} daily_accounted=${float(usage.get('daily_accounted_cost_usd') or 0):.6f} "
            f"reason={reason}"
        )
        event_line({
            "type": "crypto_grok_usage",
            "ticker": candidate.get("ticker"),
            "event_ticker": candidate.get("event_ticker"),
            "web_search": use_web_search,
            "x_search": use_x_search,
            "usage": usage,
            "error": reason,
        })
        return {
            "enabled": True,
            "ok": False,
            "source": "api",
            "reason": reason,
            "usage": usage,
            "daily_accounted_cost_usd": usage.get("daily_accounted_cost_usd"),
        }


def maybe_ai_review(settings, candidate, scan_context=None):
    """Run the low-cost voter cascade; local results are shadow-only by default."""
    if not setting_bool(settings, "CRYPTO_AI_VOTING_ENABLED"):
        return {"enabled": False, "effective_veto": False}
    if candidate.get("edge", 0) < setting_float(settings, "CRYPTO_OPENAI_MIN_EDGE"):
        return {"enabled": True, "ok": False, "reason": "edge_below_ai_min", "effective_veto": False}
    if candidate.get("confidence", 0) < setting_float(settings, "CRYPTO_OPENAI_MIN_CONFIDENCE"):
        return {"enabled": True, "ok": False, "reason": "confidence_below_ai_min", "effective_veto": False}

    scan_context = scan_context if scan_context is not None else {}
    result = {
        "enabled": True,
        "policy": "deterministic_rules_then_local_shadow_then_openai_nano_then_grok_search_fallback",
        "effective_veto": False,
    }
    context = f"{execution_mode(settings)} Kalshi crypto candidate with embedded market/model/RSS context"
    local_vote = {"enabled": False}
    if setting_bool(settings, "CRYPTO_LOCAL_AI_ENABLED") and int(scan_context.get("local_calls") or 0) < 1:
        scan_context["local_calls"] = int(scan_context.get("local_calls") or 0) + 1
        local_vote = ollama_vote(
            settings.get("CRYPTO_LOCAL_AI_URL", DEFAULT_SETTINGS["CRYPTO_LOCAL_AI_URL"]),
            settings.get("CRYPTO_LOCAL_AI_MODEL", DEFAULT_SETTINGS["CRYPTO_LOCAL_AI_MODEL"]),
            candidate,
            context,
            max_output_tokens=setting_int(settings, "CRYPTO_OPENAI_MAX_OUTPUT_TOKENS"),
        )
    result["local_vote"] = local_vote

    openai_vote_result = {"enabled": False}
    openai_calls = int(scan_context.get("openai_calls") or 0)
    if setting_bool(settings, "CRYPTO_OPENAI_ENABLED") and openai_calls < max(0, setting_int(settings, "CRYPTO_OPENAI_MAX_CALLS_PER_SCAN")):
        scan_context["openai_calls"] = openai_calls + 1
        openai_vote_result = openai_vote(
            settings.get("CRYPTO_OPENAI_API_KEY", ""),
            settings.get("CRYPTO_OPENAI_MODEL", DEFAULT_SETTINGS["CRYPTO_OPENAI_MODEL"]),
            candidate,
            context,
            max_output_tokens=setting_int(settings, "CRYPTO_OPENAI_MAX_OUTPUT_TOKENS"),
        )
    elif setting_bool(settings, "CRYPTO_OPENAI_ENABLED"):
        openai_vote_result = {"enabled": True, "ok": False, "provider": "openai", "error": "scan_call_limit"}
    result["openai_vote"] = openai_vote_result

    grok_needed = (
        bool(openai_vote_result.get("needs_live_search"))
        or grok_search_needed(settings, candidate)
        or (
            openai_vote_result.get("enabled")
            and not openai_vote_result.get("ok")
            and openai_vote_result.get("error") != "scan_call_limit"
        )
        or votes_disagree(local_vote, openai_vote_result)
    )
    grok_vote = {"enabled": False, "reason": "not_needed"}
    if grok_needed and setting_bool(settings, "CRYPTO_GROK_FALLBACK_ENABLED"):
        candidate["_ai_needs_live_search"] = bool(openai_vote_result.get("needs_live_search"))
        grok_vote = maybe_grok_review(settings, candidate, scan_context.setdefault("grok_context", {"api_calls": 0}))
        candidate.pop("_ai_needs_live_search", None)
    result["grok_vote"] = grok_vote
    result["grok_escalated"] = grok_needed

    cloud_veto = bool(openai_vote_result.get("ok") and openai_vote_result.get("veto"))
    grok_veto = bool(grok_vote.get("ok") and grok_vote.get("veto"))
    local_enforced = str(settings.get("CRYPTO_LOCAL_AI_ENFORCEMENT", "shadow")).lower() == "active"
    local_veto = bool(local_enforced and local_vote.get("ok") and local_vote.get("veto"))
    result["effective_veto"] = cloud_veto or grok_veto or local_veto
    result["effective_provider"] = "grok" if grok_veto else ("openai" if cloud_veto else ("ollama" if local_veto else "none"))
    result["ok"] = bool(openai_vote_result.get("ok") or grok_vote.get("ok") or local_vote.get("ok"))
    log_line(
        "CRYPTO AI VOTE: "
        f"ticker={candidate.get('ticker')} local={local_vote.get('risk_level', local_vote.get('error', 'off'))} "
        f"openai={openai_vote_result.get('risk_level', openai_vote_result.get('error', 'off'))} "
        f"grok_escalated={grok_needed} veto={result['effective_veto']}"
    )
    return result


def returns_from_closes(closes):
    returns = []
    for prev, cur in zip(closes, closes[1:]):
        if prev > 0 and cur > 0:
            returns.append(math.log(cur / prev))
    return returns


def clamp(value, low, high):
    return max(low, min(high, value))


def stdev(values):
    if len(values) < 2:
        return 0.0
    mean = sum(values) / len(values)
    return math.sqrt(sum((value - mean) ** 2 for value in values) / (len(values) - 1))


def ema(values, period):
    if not values:
        return None
    alpha = 2.0 / (period + 1.0)
    current = float(values[0])
    for value in values[1:]:
        current = alpha * float(value) + (1.0 - alpha) * current
    return current


def window_sum(values, count):
    if not values:
        return 0.0
    return sum(values[-count:]) if len(values) >= count else sum(values)


def norm_cdf(x):
    return 0.5 * (1.0 + math.erf(x / math.sqrt(2.0)))


def estimate_15m_asset_model(asset_row, settings=None):
    settings = settings or DEFAULT_SETTINGS
    spot = float(asset_row["spot"])
    closes = [float(value) for value in (asset_row.get("closes") or [spot])]
    returns = returns_from_closes(closes)
    momentum_1m = window_sum(returns, 1)
    momentum_5m = window_sum(returns, 5)
    momentum_15m = window_sum(returns, 15)
    momentum_60m = window_sum(returns, 60)
    minute_vol_15 = stdev(returns[-15:]) if len(returns) >= 8 else 0.0005
    minute_vol_60 = stdev(returns[-60:]) if len(returns) >= 20 else minute_vol_15
    minute_vol = max(0.00015, 0.60 * minute_vol_15 + 0.40 * minute_vol_60)
    ema_fast = ema(closes[-30:], 5) or spot
    ema_slow = ema(closes[-90:], 20) or spot
    ema_gap = math.log(max(0.0000001, ema_fast) / max(0.0000001, ema_slow))
    microstructure = asset_row.get("microstructure") or {}
    underlying_flow_score = clamp(
        float(microstructure.get("underlying_flow_score") or 0),
        -1.0,
        1.0,
    )
    trend_drift_per_minute = clamp(
        0.12 * momentum_1m
        + 0.08 * (momentum_5m / 5.0)
        + 0.06 * (momentum_15m / 15.0)
        + 0.04 * ema_gap,
        -3.0 * minute_vol,
        3.0 * minute_vol,
    )
    reversion_drift_per_minute = clamp(
        -0.05 * math.log(spot / max(0.0000001, ema_slow)),
        -2.0 * minute_vol,
        2.0 * minute_vol,
    )
    flow_drift_per_minute = clamp(
        setting_float(settings, "CRYPTO_15M_FLOW_DRIFT_WEIGHT")
        * minute_vol
        * underlying_flow_score,
        -0.5 * minute_vol,
        0.5 * minute_vol,
    )
    drift_per_minute = clamp(
        0.65 * trend_drift_per_minute
        + 0.23 * reversion_drift_per_minute
        + flow_drift_per_minute,
        -2.5 * minute_vol,
        2.5 * minute_vol,
    )
    fakeout_risk = 0.0
    if momentum_1m * momentum_5m < 0:
        fakeout_risk += 0.08
    if momentum_5m * momentum_15m < 0:
        fakeout_risk += 0.08
    if abs(momentum_1m) > max(0.001, 2.5 * minute_vol):
        fakeout_risk += 0.08
    return {
        "model_horizon": "15m",
        "spot": spot,
        "momentum_1m": round(momentum_1m, 6),
        "momentum_5m": round(momentum_5m, 6),
        "momentum_15m": round(momentum_15m, 6),
        "momentum_60m": round(momentum_60m, 6),
        "minute_vol": round(minute_vol, 7),
        "hourly_vol": round(minute_vol * math.sqrt(60.0), 6),
        "ema_fast": round(ema_fast, 8),
        "ema_slow": round(ema_slow, 8),
        "trend_drift_per_minute": round(trend_drift_per_minute, 7),
        "reversion_drift_per_minute": round(reversion_drift_per_minute, 7),
        "flow_drift_per_minute": round(flow_drift_per_minute, 7),
        "drift_per_minute": round(drift_per_minute, 7),
        "trend_bias": round(ema_gap / max(minute_vol * math.sqrt(15.0), 0.0001), 4),
        "distance_from_slow": round(math.log(spot / max(0.0000001, ema_slow)) / max(minute_vol * math.sqrt(15.0), 0.0001), 4),
        "fakeout_risk": round(min(0.35, fakeout_risk), 3),
        "underlying_flow_score": round(underlying_flow_score, 4),
        "cross_exchange_dispersion_bps": round(float(microstructure.get("cross_exchange_dispersion_bps") or 0), 4),
        "settlement_proxy_source_count": int(microstructure.get("settlement_proxy_source_count") or 0),
        "settlement_proxy_used": bool(asset_row.get("settlement_proxy_used")),
        "settlement_source": asset_row.get("settlement_source") or (
            "Pyth"
            if str(asset_row.get("source") or "").lower() == "pyth"
            else "CF Benchmarks"
        ),
        "data_source": asset_row.get("source"),
        "coinbase_spot": asset_row.get("coinbase_spot"),
        "news": {"enabled": False, "count": 0, "score": 0.0, "source": "disabled_for_15m"},
    }


def estimate_intraday_asset_model(asset_row, settings=None, horizon="hourly", news=None):
    """Use minute observations for hourly threshold contracts.

    The legacy generic model was built around longer horizons.  Hourly Kalshi
    contracts need minute-scaled volatility and drift, just like 15-minute
    direction markets, while still supporting multiple above/range strikes.
    """
    model = estimate_15m_asset_model(asset_row, settings=settings)
    model["model_horizon"] = str(horizon)
    model["settlement_source"] = asset_row.get("settlement_source") or (
        "Pyth" if str(asset_row.get("source") or "").lower() == "pyth" else "CF Benchmarks"
    )
    model["data_source"] = asset_row.get("source")
    model["history_points"] = len(asset_row.get("closes") or [])
    model["kalshi_anchor"] = asset_row.get("kalshi_anchor")
    model["proxy_ready"] = bool(
        not asset_row.get("requires_kalshi_anchor")
        and (
            str(asset_row.get("source") or "").lower() == "pyth"
            or bool(asset_row.get("kalshi_anchor"))
        )
    )
    model["proxy_symbol"] = (asset_row.get("pyth_proxy") or {}).get("symbol")
    model["news"] = news or {
        "enabled": False,
        "count": 0,
        "score": 0.0,
        "source": "not_loaded",
    }
    # News is deliberately a small hourly tilt.  It cannot manufacture a
    # trade: price, fees, confidence, and execution gates still apply.
    news_tilt = clamp(float(model["news"].get("score") or 0), -1.0, 1.0)
    minute_vol = max(0.00005, float(model.get("minute_vol") or 0.0005))
    model["drift_per_minute"] = round(
        clamp(
            float(model.get("drift_per_minute") or 0) + 0.04 * minute_vol * news_tilt,
            -2.5 * minute_vol,
            2.5 * minute_vol,
        ),
        7,
    )
    return model


def market_kind(market):
    floor, cap = market_strikes(market)
    if floor is not None and cap is not None:
        return "range"
    if floor is not None:
        return "above"
    if cap is not None:
        return "below"
    return "unknown"


def market_strikes(market):
    """Return numeric strikes from either standard or Kalshi custom fields."""
    market = market or {}
    custom = market.get("custom_strike") or {}
    floor = market.get("floor_strike")
    cap = market.get("cap_strike")
    if floor in (None, ""):
        floor = custom.get("floor_strike")
    if cap in (None, ""):
        cap = custom.get("cap_strike")

    def numeric(value):
        if value in (None, ""):
            return None
        try:
            return float(value)
        except (TypeError, ValueError):
            return None

    return numeric(floor), numeric(cap)


def market_implied_yes_probability(market):
    yes_ask = market_price(market, "yes_ask", "yes_ask_dollars")
    yes_bid = market_price(market, "yes_bid", "yes_bid_dollars")
    no_ask = market_price(market, "no_ask", "no_ask_dollars")
    no_bid = market_price(market, "no_bid", "no_bid_dollars")
    # YES and complemented NO quotes describe the same executable interval;
    # averaging both double-counted one book. Build the tight no-arbitrage
    # interval once, then tilt its midpoint with a fresh quantity microprice.
    lower_candidates = [value for value in (yes_bid, 100.0 - no_ask if no_ask is not None else None) if value is not None]
    upper_candidates = [value for value in (yes_ask, 100.0 - no_bid if no_bid is not None else None) if value is not None]
    lower = max(lower_candidates) if lower_candidates else None
    upper = min(upper_candidates) if upper_candidates else None
    midpoint = (
        (lower + upper) / 2.0
        if lower is not None and upper is not None and upper >= lower
        else lower if lower is not None else upper
    )
    microprice = market.get("microprice_yes_cents")
    quote_age = market.get("orderbook_age_seconds")
    if quote_age is None:
        quote_age = market.get("age_seconds")
    microprice_fresh = (
        microprice is not None
        and (quote_age is None or float(quote_age) <= 3.0)
        and 0.0 < float(microprice) < 100.0
    )
    if midpoint is not None and microprice_fresh:
        return clamp(0.35 * midpoint + 0.65 * float(microprice), 0.01, 99.99)
    if midpoint is not None:
        return clamp(midpoint, 0.01, 99.99)
    # Last trade is a fallback only when there is no valid executable book.
    last_price = market_price(market, "last_price", "last_price_dollars")
    return clamp(last_price, 0.01, 99.99) if last_price is not None else None


def probability_for_market(market, model, settings=None, now=None):
    now = now or utc_now()
    settings = settings or DEFAULT_SETTINGS
    if model.get("model_horizon") == "15m" or is_15m_target_market(market):
        return probability_for_15m_market(market, model, settings=settings, now=now)
    if model.get("model_horizon") == "hourly":
        return probability_for_intraday_threshold_market(
            market,
            model,
            settings=settings,
            now=now,
        )
    close_time = parse_time(market.get("close_time") or market.get("expected_expiration_time") or market.get("expiration_time"))
    if not close_time:
        return None
    hours = max(0.05, (close_time - now).total_seconds() / 3600.0)
    spot = float(model["spot"])
    sigma = max(0.002, float(model["hourly_vol"]) * math.sqrt(hours))
    horizon_weight = min(1.0, hours / 24.0)

    def cdf_price(price, mu):
        if price is None or float(price) <= 0:
            return None
        return norm_cdf((math.log(float(price)) - mu) / sigma)

    def raw_probability(drift):
        mu = math.log(spot) + float(drift) * horizon_weight
        kind = market_kind(market)
        floor, cap = market_strikes(market)
        if kind == "above":
            floor_cdf = cdf_price(floor, mu)
            return 1.0 - floor_cdf if floor_cdf is not None else None
        if kind == "below":
            return cdf_price(cap, mu)
        if kind == "range":
            lo = cdf_price(floor, mu)
            hi = cdf_price(cap, mu)
            return (hi - lo) if lo is not None and hi is not None else None
        return None

    neutral_prob = raw_probability(0.0)
    trend_prob = raw_probability(model.get("trend_drift", model.get("drift", 0.0)))
    reversion_prob = raw_probability(model.get("reversion_drift", 0.0))
    ensemble_prob = raw_probability(model.get("drift", 0.0))
    if ensemble_prob is None:
        return None
    if setting_bool(settings, "CRYPTO_PROBABILITY_ENSEMBLE_ENABLED"):
        components = [value for value in (ensemble_prob, neutral_prob, trend_prob, reversion_prob) if value is not None]
        if components:
            ensemble_prob = (
                0.48 * ensemble_prob
                + 0.20 * (trend_prob if trend_prob is not None else ensemble_prob)
                + 0.17 * (reversion_prob if reversion_prob is not None else ensemble_prob)
                + 0.15 * (neutral_prob if neutral_prob is not None else ensemble_prob)
            )
    market_yes = market_implied_yes_probability(market)
    market_anchor_weight = clamp(setting_float(settings, "CRYPTO_MARKET_ANCHOR_WEIGHT"), 0.0, 0.45)
    if market_yes is not None and setting_bool(settings, "CRYPTO_PROBABILITY_ENSEMBLE_ENABLED"):
        ensemble_prob = (1.0 - market_anchor_weight) * ensemble_prob + market_anchor_weight * (market_yes / 100.0)
    fakeout = float(model.get("fakeout_risk") or 0)
    shrink = clamp(setting_float(settings, "CRYPTO_EXTREME_PROB_SHRINK"), 0.0, 0.4)
    if hours > 48:
        shrink += 0.04
    prob = 0.5 + (clamp(ensemble_prob, 0.0, 1.0) - 0.5) * (1.0 - fakeout) * (1.0 - shrink)
    component_values = [value * 100.0 for value in (neutral_prob, trend_prob, reversion_prob, ensemble_prob) if value is not None]
    disagreement = max(component_values) - min(component_values) if component_values else 0.0
    market_gap = abs(prob * 100.0 - market_yes) if market_yes is not None else None
    return {
        "prob": round(prob * 100, 2),
        "neutral_prob": round(neutral_prob * 100, 2) if neutral_prob is not None else None,
        "trend_prob": round(trend_prob * 100, 2) if trend_prob is not None else None,
        "reversion_prob": round(reversion_prob * 100, 2) if reversion_prob is not None else None,
        "ensemble_prob": round(ensemble_prob * 100, 2),
        "market_implied_yes": round(market_yes, 2) if market_yes is not None else None,
        "model_disagreement": round(disagreement, 2),
        "market_gap": round(market_gap, 2) if market_gap is not None else None,
        "hours_to_close": round(hours, 2),
        "sigma": round(sigma, 5),
        "kind": market_kind(market),
    }


def probability_for_intraday_threshold_market(market, model, settings=None, now=None):
    settings = settings or DEFAULT_SETTINGS
    now = now or utc_now()
    minutes = market_minutes_to_close(market, now=now)
    if minutes is None or minutes <= 0:
        return None
    spot = float(model.get("spot") or 0)
    if spot <= 0:
        return None
    minute_vol = max(0.00005, float(model.get("minute_vol") or 0.0005))
    basis_bps = 2.0 if str(model.get("settlement_source") or "") == "Pyth" else setting_float(
        settings,
        "CRYPTO_15M_SETTLEMENT_BASIS_BUFFER_BPS",
    )
    sigma = max(
        0.0001,
        math.sqrt((minute_vol ** 2) * (minutes + 0.5) + (basis_bps / 10000.0) ** 2),
    )

    def cdf_price(price, drift_per_minute):
        if price is None or float(price) <= 0:
            return None
        mean_log = math.log(spot) + float(drift_per_minute or 0) * minutes
        return norm_cdf((math.log(float(price)) - mean_log) / sigma)

    def raw_probability(drift_per_minute):
        kind = market_kind(market)
        floor, cap = market_strikes(market)
        if kind == "above":
            value = cdf_price(floor, drift_per_minute)
            return 1.0 - value if value is not None else None
        if kind == "below":
            return cdf_price(cap, drift_per_minute)
        if kind == "range":
            lo = cdf_price(floor, drift_per_minute)
            hi = cdf_price(cap, drift_per_minute)
            return hi - lo if lo is not None and hi is not None else None
        return None

    neutral = raw_probability(0.0)
    trend = raw_probability(model.get("trend_drift_per_minute", 0.0))
    reversion = raw_probability(model.get("reversion_drift_per_minute", 0.0))
    ensemble = raw_probability(model.get("drift_per_minute", 0.0))
    if ensemble is None:
        return None
    ensemble = (
        0.50 * ensemble
        + 0.20 * (neutral if neutral is not None else ensemble)
        + 0.20 * (trend if trend is not None else ensemble)
        + 0.10 * (reversion if reversion is not None else ensemble)
    )
    pre_anchor = ensemble
    market_yes = market_implied_yes_probability(market)
    anchor_weight = min(0.35, max(0.0, setting_float(settings, "CRYPTO_MARKET_ANCHOR_WEIGHT")))
    if market_yes is not None:
        ensemble = (1.0 - anchor_weight) * ensemble + anchor_weight * market_yes / 100.0
    fakeout = float(model.get("fakeout_risk") or 0)
    prob = 0.5 + (clamp(ensemble, 0.0, 1.0) - 0.5) * (1.0 - fakeout)
    components = [
        value * 100.0
        for value in (neutral, trend, reversion, ensemble)
        if value is not None
    ]
    return {
        "prob": round(prob * 100.0, 2),
        "pre_anchor_prob": round(pre_anchor * 100.0, 2),
        "neutral_prob": round(neutral * 100.0, 2) if neutral is not None else None,
        "trend_prob": round(trend * 100.0, 2) if trend is not None else None,
        "reversion_prob": round(reversion * 100.0, 2) if reversion is not None else None,
        "ensemble_prob": round(ensemble * 100.0, 2),
        "market_implied_yes": round(market_yes, 2) if market_yes is not None else None,
        "model_disagreement": round(max(components) - min(components), 2) if components else 0.0,
        "market_gap": round(abs(prob * 100.0 - market_yes), 2) if market_yes is not None else None,
        "raw_market_gap": round(abs(pre_anchor * 100.0 - market_yes), 2) if market_yes is not None else None,
        "hours_to_close": round(minutes / 60.0, 4),
        "minutes_to_close": round(minutes, 2),
        "sigma": round(sigma, 7),
        "basis_buffer_bps": round(basis_bps, 3),
        "settlement_price_source": model.get("settlement_source"),
        "kind": market_kind(market),
    }


def probability_for_15m_market(market, model, settings=None, now=None):
    settings = settings or DEFAULT_SETTINGS
    now = now or utc_now()
    minutes = market_minutes_to_close(market, now=now)
    target, _cap = market_strikes(market)
    if minutes is None or minutes <= 0 or target is None or float(target) <= 0:
        return None
    spot = float(model["spot"])
    minute_vol = max(0.00005, float(model.get("minute_vol") or 0.0005))
    horizons = settlement_window_horizons(
        minutes,
        setting_float(settings, "CRYPTO_15M_SETTLEMENT_WINDOW_SECONDS"),
    )
    drift_minutes = float(horizons["drift_minutes"])
    variance_minutes = float(horizons["variance_minutes"])
    is_pyth = str(model.get("settlement_source") or "").lower() == "pyth"
    learned_basis = model.get("settlement_basis_model") or {}
    basis_samples = int(learned_basis.get("samples") or 0)
    use_learned_basis = basis_samples >= max(
        1,
        setting_int(settings, "CRYPTO_15M_SETTLEMENT_BASIS_MIN_SAMPLES"),
    )
    learned_basis_mean_bps = float(learned_basis.get("mean_bps") or 0) if use_learned_basis else 0.0
    learned_basis_std_bps = max(0.0, float(learned_basis.get("std_bps") or 0)) if use_learned_basis else 0.0
    basis_buffer = (
        0.0002
        if is_pyth
        else max(0.0, setting_float(settings, "CRYPTO_15M_SETTLEMENT_BASIS_BUFFER_BPS")) / 10000.0
    )
    if not is_pyth and setting_bool(settings, "CRYPTO_15M_DYNAMIC_BASIS_BUFFER_ENABLED"):
        dispersion_buffer_bps = min(
            max(0.0, setting_float(settings, "CRYPTO_15M_MAX_SETTLEMENT_BASIS_BUFFER_BPS")),
            max(0.0, float(model.get("cross_exchange_dispersion_bps") or 0)) / 2.0,
        )
        basis_buffer = max(basis_buffer, dispersion_buffer_bps / 10000.0)
    learned_basis_sigma = learned_basis_std_bps / 10000.0
    sigma = max(
        0.0001,
        math.sqrt(
            (minute_vol ** 2) * variance_minutes
            + basis_buffer ** 2
            + learned_basis_sigma ** 2
        ),
    )
    effective_target = float(target)
    partial = model.get("settlement_partial_window") or {}
    partial_active = False
    partial_average = float(partial.get("average") or 0)
    source_count = max(1, int(partial.get("source_count") or 1))
    observations_per_source = float(partial.get("observations") or 0) / source_count
    window_minutes = float(horizons["window_seconds"]) / 60.0
    elapsed_window_minutes = max(0.0, window_minutes - minutes)
    if (
        minutes < window_minutes
        and partial_average > 0
        and elapsed_window_minutes > 0
        and observations_per_source >= elapsed_window_minutes * 60.0 * 0.5
    ):
        basis_factor = 1.0 + learned_basis_mean_bps / 10000.0
        known_official_average = partial_average * basis_factor
        effective_target = (
            float(target) * window_minutes
            - known_official_average * elapsed_window_minutes
        ) / max(1.0 / 60.0, minutes)
        effective_target = max(spot * 0.01, effective_target)
        partial_active = True
    target_log = math.log(effective_target)

    def above_probability(drift_per_minute):
        mean_log = (
            math.log(spot)
            + math.log1p(max(-0.99, learned_basis_mean_bps / 10000.0))
            + float(drift_per_minute or 0) * drift_minutes
        )
        return 1.0 - norm_cdf((target_log - mean_log) / sigma)

    neutral_prob = above_probability(0.0)
    trend_prob = above_probability(model.get("trend_drift_per_minute", 0.0))
    reversion_prob = above_probability(model.get("reversion_drift_per_minute", 0.0))
    ensemble_prob = above_probability(model.get("drift_per_minute", 0.0))
    ensemble_prob = 0.50 * ensemble_prob + 0.20 * neutral_prob + 0.20 * trend_prob + 0.10 * reversion_prob
    pre_anchor_prob = ensemble_prob
    market_yes = market_implied_yes_probability(market)
    anchor_weight = clamp(setting_float(settings, "CRYPTO_15M_MARKET_ANCHOR_WEIGHT"), 0.0, 0.45)
    if market_yes is not None:
        ensemble_prob = (1.0 - anchor_weight) * ensemble_prob + anchor_weight * market_yes / 100.0
    fakeout = float(model.get("fakeout_risk") or 0)
    shrink = clamp(setting_float(settings, "CRYPTO_EXTREME_PROB_SHRINK"), 0.0, 0.4)
    prob = 0.5 + (clamp(ensemble_prob, 0.0, 1.0) - 0.5) * (1.0 - fakeout) * (1.0 - shrink)
    components = [neutral_prob * 100.0, trend_prob * 100.0, reversion_prob * 100.0, ensemble_prob * 100.0]
    disagreement = max(components) - min(components)
    market_gap = abs(prob * 100.0 - market_yes) if market_yes is not None else None
    raw_market_gap = abs(pre_anchor_prob * 100.0 - market_yes) if market_yes is not None else None
    target_distance_sigma = math.log(spot / effective_target) / sigma
    return {
        "prob": round(prob * 100.0, 2),
        "pre_anchor_prob": round(pre_anchor_prob * 100.0, 2),
        "neutral_prob": round(neutral_prob * 100.0, 2),
        "trend_prob": round(trend_prob * 100.0, 2),
        "reversion_prob": round(reversion_prob * 100.0, 2),
        "ensemble_prob": round(ensemble_prob * 100.0, 2),
        "market_implied_yes": round(market_yes, 2) if market_yes is not None else None,
        "model_disagreement": round(disagreement, 2),
        "market_gap": round(market_gap, 2) if market_gap is not None else None,
        "raw_market_gap": round(raw_market_gap, 2) if raw_market_gap is not None else None,
        "market_anchor_weight": round(anchor_weight, 4),
        "hours_to_close": round(minutes / 60.0, 4),
        "minutes_to_close": round(minutes, 2),
        "sigma": round(sigma, 7),
        "basis_buffer_bps": round(basis_buffer * 10000.0, 4),
        "settlement_window_seconds": horizons["window_seconds"],
        "settlement_drift_minutes": round(drift_minutes, 4),
        "settlement_variance_minutes": round(variance_minutes, 4),
        "learned_settlement_basis_bps": round(learned_basis_mean_bps, 4),
        "learned_settlement_basis_std_bps": round(learned_basis_std_bps, 4),
        "learned_settlement_basis_samples": basis_samples,
        "learned_settlement_basis_active": use_learned_basis,
        "partial_settlement_window_active": partial_active,
        "partial_settlement_proxy_average": round(partial_average, 8) if partial_average > 0 else None,
        "partial_settlement_observations_per_source": round(observations_per_source, 2),
        "effective_target": round(effective_target, 8),
        "effective_remaining_window_target": round(effective_target, 8),
        "target_distance_sigma": round(target_distance_sigma, 3),
        "settlement_source": model.get("settlement_source") or "CF Benchmarks",
        "settlement_price_source": (
            "Pyth settlement proxy"
            if is_pyth
            else "CF Benchmarks RTI settlement; Coinbase + Kraken live proxy with basis buffer"
        ),
        "kind": "above",
    }


def confidence_for_candidate(market, model, probability):
    if model.get("model_horizon") == "15m":
        conf = 62.0
        conf += min(12.0, abs(float(probability["prob"]) - 50.0) * 0.35)
        conf += min(5.0, abs(float(probability.get("target_distance_sigma") or 0)) * 2.0)
        conf += min(4.0, math.log10(max(1.0, float(market.get("volume") or market.get("volume_fp") or 0) + 1)))
        disagreement = float(probability.get("model_disagreement") or 0)
        conf += 4.0 if disagreement <= 8 else 1.0 if disagreement <= 15 else -5.0
        market_gap = probability.get("market_gap")
        if market_gap is not None and float(market_gap) < 8:
            conf += 2.0
        flow_score = float(model.get("underlying_flow_score") or 0)
        probability_direction = 1.0 if float(probability.get("prob") or 50) >= 50 else -1.0
        if abs(flow_score) >= 0.15:
            conf += 4.0 * abs(flow_score) if flow_score * probability_direction > 0 else -6.0 * abs(flow_score)
        dispersion = float(model.get("cross_exchange_dispersion_bps") or 0)
        if dispersion > 10:
            conf -= min(6.0, (dispersion - 10.0) * 0.25)
        conf -= float(model.get("fakeout_risk") or 0) * 25.0
        return round(max(0.0, min(100.0, conf)), 1)
    conf = 55.0
    conf += min(15.0, abs(probability["prob"] - 50.0) * 0.35)
    conf += min(8.0, math.log10(max(1.0, float(market.get("volume") or market.get("volume_fp") or 0) + 1)))
    conf += 8.0 if probability["hours_to_close"] <= 30 else 2.0
    disagreement = float(probability.get("model_disagreement") or 0)
    market_gap = float(probability.get("market_gap") or 0)
    conf -= min(12.0, disagreement * 0.35)
    if market_gap > 30:
        conf -= min(10.0, (market_gap - 30.0) * 0.25)
    elif market_gap and market_gap < 12:
        conf += 2.0
    if abs(float(model.get("trend_bias") or 0)) > 0.5 and model.get("trend_drift", 0) * model.get("drift", 0) > 0:
        conf += 2.0
    if abs(float(model.get("distance_from_slow") or 0)) > 2.5:
        conf -= 3.0
    conf -= float(model.get("fakeout_risk") or 0) * 30.0
    if model.get("news", {}).get("count", 0) == 0:
        conf -= 3.0
    elif model.get("news", {}).get("count", 0) >= 3:
        conf += 2.0
    return round(max(0.0, min(100.0, conf)), 1)


def crypto_15m_disagreement_review(settings, candidate):
    if not setting_bool(settings, "CRYPTO_15M_DISAGREEMENT_GUARD_ENABLED"):
        return {"enabled": False, "ok": True, "reason": "disabled"}
    probability = candidate.get("probability") or {}
    flow = candidate.get("flow_review") or {}
    gap = float(
        probability.get("raw_market_gap")
        if probability.get("raw_market_gap") is not None
        else probability.get("market_gap")
        or 0
    )
    side = str(candidate.get("side") or "").lower()
    flow_direction = str(flow.get("direction") or "neutral").lower()
    strength = float(flow.get("strength") or 0)
    source_count = int(flow.get("source_count") or 0)
    confirming_source_count = int(flow.get("confirming_source_count") or 0)
    if flow_direction != side:
        confirming_source_count = int(
            flow.get(f"{side}_source_count") or 0
        )
    dispersion = float(flow.get("cross_exchange_dispersion_bps") or 0)
    large_disagreement = gap > setting_float(settings, "CRYPTO_15M_MAX_UNCONFIRMED_MARKET_GAP")
    flow_confirmed = (
        flow_direction == side
        and strength >= setting_float(settings, "CRYPTO_15M_FLOW_CONFIRMATION_MIN_STRENGTH")
        and confirming_source_count >= setting_int(settings, "CRYPTO_15M_FLOW_CONFIRMATION_MIN_SOURCES")
        and dispersion <= setting_float(settings, "CRYPTO_15M_FLOW_CONFIRMATION_MAX_DISPERSION_BPS")
    )
    flow_override_enabled = setting_bool(
        settings,
        "CRYPTO_15M_FLOW_CAN_OVERRIDE_MARKET_GAP",
    )
    ok = not large_disagreement or (flow_confirmed and flow_override_enabled)
    return {
        "enabled": True,
        "ok": ok,
        "reason": "confirmed_by_live_flow" if large_disagreement and flow_confirmed and flow_override_enabled else (
            "model_market_disagreement_unconfirmed" if large_disagreement else "within_market_gap"
        ),
        "raw_market_gap": round(gap, 2),
        "maximum_unconfirmed_gap": setting_float(settings, "CRYPTO_15M_MAX_UNCONFIRMED_MARKET_GAP"),
        "selected_side": side,
        "flow_direction": flow_direction,
        "flow_strength": round(strength, 4),
        "minimum_flow_strength": setting_float(settings, "CRYPTO_15M_FLOW_CONFIRMATION_MIN_STRENGTH"),
        "source_count": source_count,
        "confirming_source_count": confirming_source_count,
        "minimum_sources": setting_int(settings, "CRYPTO_15M_FLOW_CONFIRMATION_MIN_SOURCES"),
        "cross_exchange_dispersion_bps": round(dispersion, 4),
        "maximum_dispersion_bps": setting_float(settings, "CRYPTO_15M_FLOW_CONFIRMATION_MAX_DISPERSION_BPS"),
        "flow_confirmed": flow_confirmed,
        "flow_override_enabled": flow_override_enabled,
    }


def crypto_15m_directional_confirmation_review(settings, candidate):
    if not setting_bool(
        settings,
        "CRYPTO_15M_DIRECTIONAL_CONFIRMATION_REQUIRED",
    ):
        return {
            "enabled": False,
            "ok": True,
            "reason": "disabled",
        }
    flow = candidate.get("flow_review") or {}
    selected_side = str(candidate.get("side") or "").lower()
    minimum_sources = max(
        1,
        setting_int(
            settings,
            "CRYPTO_15M_DIRECTIONAL_CONFIRMATION_MIN_SOURCES",
        ),
    )
    selected_side_source_count = (
        int(flow.get(f"{selected_side}_source_count") or 0)
        if selected_side in {"yes", "no"}
        else 0
    )
    flow_direction = str(flow.get("direction") or "neutral").lower()
    flow_strength = float(flow.get("strength") or 0)
    minimum_strength = max(
        0.0,
        setting_float(
            settings,
            "CRYPTO_15M_DIRECTIONAL_CONFIRMATION_MIN_STRENGTH",
        ),
    )
    opposing_side = "no" if selected_side == "yes" else "yes"
    opposing_source_count = int(flow.get(f"{opposing_side}_source_count") or 0)
    source_count = int(flow.get("source_count") or 0)
    healthy_source_count = int(flow.get("healthy_source_count") or source_count)
    quality = candidate.get("data_quality") or {}
    all_feeds_fresh = (
        float(quality.get("source_freshness") or 0) >= 0.8
        and float(quality.get("kalshi_freshness") or 0) >= 0.8
    )
    strong_opposition = (
        selected_side in {"yes", "no"}
        and flow_direction == opposing_side
        and flow_strength >= minimum_strength
    ) or opposing_source_count >= 2
    ok = (
        selected_side in {"yes", "no"}
        and selected_side_source_count >= minimum_sources
        and flow_direction == selected_side
        and flow_strength >= minimum_strength
        and not strong_opposition
    )
    one_source_shadow = (
        setting_bool(settings, "CRYPTO_15M_ONE_SOURCE_SHADOW_ENABLED")
        and not ok
        and selected_side_source_count == 1
        and opposing_source_count <= setting_int(
            settings,
            "CRYPTO_15M_ONE_SOURCE_SHADOW_MAX_OPPOSING_SOURCES",
        )
        and flow_direction == selected_side
        and flow_strength >= setting_float(
            settings,
            "CRYPTO_15M_ONE_SOURCE_SHADOW_MIN_STRENGTH",
        )
        and all_feeds_fresh
    )
    if ok:
        reason = "confirmed_by_directional_sources"
    elif healthy_source_count <= 0 or source_count <= 0:
        reason = "directional_data_unavailable"
    elif strong_opposition:
        reason = "directional_opposition"
    elif flow_direction == "neutral" or flow_strength < minimum_strength:
        reason = "directional_flow_too_weak"
    else:
        reason = "directional_insufficient_consensus"
    return {
        "enabled": True,
        "ok": ok,
        "reason": reason,
        "selected_side": selected_side,
        "selected_side_source_count": selected_side_source_count,
        "minimum_sources": minimum_sources,
        "flow_direction": flow_direction,
        "flow_direction_matches": flow_direction == selected_side,
        "flow_strength": round(flow_strength, 4),
        "minimum_flow_strength": minimum_strength,
        "flow_strength_passes": flow_strength >= minimum_strength,
        "source_count": source_count,
        "healthy_source_count": healthy_source_count,
        "yes_source_count": int(flow.get("yes_source_count") or 0),
        "no_source_count": int(flow.get("no_source_count") or 0),
        "opposing_source_count": opposing_source_count,
        "strong_opposition": strong_opposition,
        "all_feeds_fresh": all_feeds_fresh,
        "one_source_shadow_eligible": one_source_shadow,
        "lane": "one_source_shadow" if one_source_shadow else "live" if ok else "rejected",
    }


def crypto_15m_learning_influence(settings, learned):
    """Bound model influence by independent walk-forward evidence.

    A learned probability is a correction to the executable market probability,
    not a second unconstrained fair-value estimate.  An unqualified model may be
    observed in shadow, but cannot receive the live-model weight.
    """
    learned = learned or {}
    maximum_weight = clamp(
        setting_float(settings, "CRYPTO_15M_UNIT_WIN_PROB_MODEL_WEIGHT"),
        0.0,
        1.0,
    )
    shadow_maximum = min(
        maximum_weight,
        clamp(
            setting_float(settings, "CRYPTO_15M_UNIT_WIN_PROB_SHADOW_MAX_WEIGHT"),
            0.0,
            1.0,
        ),
    )
    evaluation = learned.get("evaluation") or {}

    def metric(section, key, fallback=None):
        value = (evaluation.get(section) or {}).get(key)
        try:
            value = float(value)
            return value if math.isfinite(value) else fallback
        except (TypeError, ValueError):
            return fallback

    test_markets = int(max(0.0, metric("", "test_markets", 0.0) or 0.0))
    if not test_markets:
        try:
            test_markets = int(max(0, evaluation.get("test_markets") or 0))
        except (TypeError, ValueError):
            test_markets = 0
    market_brier = metric("market_weighted_market_baseline", "brier")
    model_brier = metric("market_weighted_calibrated_ensemble", "brier")
    policy_roi = metric("after_fee_policy", "roi")
    brier_improvement = (
        market_brier - model_brier
        if market_brier is not None and model_brier is not None
        else None
    )
    positive_walk_forward = bool(
        brier_improvement is not None
        and brier_improvement > 0
        and policy_roi is not None
        and policy_roi > 0
    )
    interval_qualified = bool(learned.get("interval_qualified"))
    activation_qualified = bool(
        learned.get("active")
        and learned.get("qualified_for_activation", learned.get("active"))
        and positive_walk_forward
        and interval_qualified
    )
    evidence_fraction = clamp(test_markets / 200.0, 0.0, 1.0)
    if activation_qualified:
        # Even an activated model earns the full configured influence gradually.
        effective_weight = maximum_weight * (0.50 + 0.50 * evidence_fraction)
        source = "qualified_market_residual_model"
        status = "active_evidence_weighted"
    elif learned.get("available") and positive_walk_forward:
        effective_weight = shadow_maximum * max(0.10, evidence_fraction)
        source = "shadow_market_residual_model"
        status = "shadow_positive_walk_forward"
    else:
        # Preserve a small version of the existing heuristic while the learned
        # residual is unqualified.  This is also market-anchored and can only
        # reach the explicitly small shadow cap.
        effective_weight = shadow_maximum
        source = "guardrailed_heuristic_residual"
        status = "learned_model_not_qualified"
    return {
        "effective_weight": round(clamp(effective_weight, 0.0, maximum_weight), 6),
        "learned_model_weight": round(
            0.0
            if source == "guardrailed_heuristic_residual"
            else clamp(effective_weight, 0.0, maximum_weight),
            6,
        ),
        "maximum_weight": round(maximum_weight, 6),
        "shadow_maximum_weight": round(shadow_maximum, 6),
        "source": source,
        "status": status,
        "test_markets": test_markets,
        "market_weighted_brier_improvement": (
            round(brier_improvement, 6) if brier_improvement is not None else None
        ),
        "after_fee_policy_roi": (
            round(policy_roi, 6) if policy_roi is not None else None
        ),
        "positive_walk_forward": positive_walk_forward,
        "interval_qualified": interval_qualified,
        "activation_qualified": activation_qualified,
    }


def apply_15m_learning_prediction(settings, candidate, probability, learned_state):
    if not setting_bool(settings, "CRYPTO_15M_LEARNING_ENABLED"):
        learned = {
            "available": False,
            "active": False,
            "status": "disabled",
        }
    else:
        learned = predict_15m_candidate(candidate, learned_state or {})
    influence = crypto_15m_learning_influence(settings, learned)
    if not setting_bool(settings, "CRYPTO_15M_LEARNING_ACTIVE_ENABLED"):
        learned = {**learned, "active": False, "activation_status": "operator_shadow_freeze"}
        influence = {**crypto_15m_learning_influence(settings, {}),
                     "manual_activation_required": True, "status": "operator_shadow_freeze"}
    candidate["learned_15m_model"] = {
        **learned,
        "influence": influence,
        # The model is a market-residual model. Keep the exact market anchor
        # used for this prediction so a later live quote refresh can preserve
        # the learned residual instead of comparing a stale probability with a
        # fresh book and manufacturing a false edge.
        "prediction_market_probability_yes": probability.get(
            "market_implied_yes"
        ),
        "prediction_target_distance_sigma": probability.get(
            "target_distance_sigma"
        ),
        "prediction_captured_at": iso_now(),
    }
    heuristic_probability = float(probability.get("prob") or 0)
    market_yes = probability.get("market_implied_yes")
    if market_yes is None:
        probability["adaptive_model_weight"] = 0.0
        probability["adaptive_probability_status"] = "market_probability_unavailable"
        return probability
    market_yes = float(market_yes)
    use_learned = bool(
        influence.get("source") != "guardrailed_heuristic_residual"
        and learned.get("prob_yes") is not None
    )
    source_probability = (
        float(learned.get("prob_yes")) if use_learned else heuristic_probability
    )
    source_low = learned.get("prob_yes_low") if use_learned else None
    source_high = learned.get("prob_yes_high") if use_learned else None
    weight = float(influence.get("effective_weight") or 0)
    final_probability = market_yes + weight * (source_probability - market_yes)
    probability["heuristic_prob_before_ml"] = round(heuristic_probability, 2)
    probability["heuristic_raw_market_gap"] = probability.get("raw_market_gap")
    probability["learned_pre_anchor_prob"] = learned.get("prob_yes")
    probability["learned_blend_weight"] = round(weight, 6)
    probability["adaptive_model_weight"] = influence.get("learned_model_weight", 0.0)
    probability["adaptive_residual_weight"] = round(weight, 6)
    probability["adaptive_probability_source"] = influence.get("source")
    probability["adaptive_probability_status"] = influence.get("status")
    probability["adaptive_source_probability_yes"] = round(source_probability, 4)
    probability["adaptive_source_probability_low"] = source_low
    probability["adaptive_source_probability_high"] = source_high
    probability["raw_market_gap"] = round(abs(source_probability - market_yes), 2)
    probability["prob"] = round(clamp(final_probability, 0.01, 99.99), 2)
    probability["market_gap"] = round(abs(probability["prob"] - market_yes), 2)
    if source_low is not None and source_high is not None:
        adaptive_low = market_yes + weight * (float(source_low) - market_yes)
        adaptive_high = market_yes + weight * (float(source_high) - market_yes)
        probability["adaptive_probability_interval"] = {
            "available": True,
            "p_yes": round(probability["prob"], 4),
            "p_low": round(clamp(min(adaptive_low, probability["prob"]), 0.01, 99.99), 4),
            "p_high": round(clamp(max(adaptive_high, probability["prob"]), 0.01, 99.99), 4),
            "interval_level": float(
                (learned.get("empirical_interval") or {}).get("interval_level") or 0.90
            ),
            "qualified": bool(learned.get("interval_qualified")),
            "scope": (learned.get("empirical_interval") or {}).get("scope"),
            "markets": (learned.get("empirical_interval") or {}).get("markets"),
        }
    return probability


def candidate_probability_interval(settings, probability, data_quality):
    estimated = probability_interval(
        probability.get("prob"),
        model_disagreement_pp=probability.get("model_disagreement") or 0,
        data_quality=(data_quality or {}).get("score") or 0,
        basis_std_bps=probability.get("learned_settlement_basis_std_bps") or 0,
        base_sigma_pp=setting_float(
            settings,
            "CRYPTO_15M_PROBABILITY_INTERVAL_BASE_SIGMA_PP",
        ),
    )
    empirical = probability.get("adaptive_probability_interval") or {}
    if not empirical.get("available"):
        estimated["interval_status"] = "input_quality_interval_only"
        return estimated
    probability_yes = float(estimated.get("p_yes") or probability.get("prob") or 0)
    low = min(float(estimated.get("p_low") or probability_yes), float(empirical.get("p_low") or probability_yes))
    high = max(float(estimated.get("p_high") or probability_yes), float(empirical.get("p_high") or probability_yes))
    sigma = max(
        float(estimated.get("probability_sigma_pp") or 0),
        (probability_yes - low) / 1.6448536269514722,
        (high - probability_yes) / 1.6448536269514722,
    )
    return {
        **estimated,
        "p_low": round(max(0.01, low), 3),
        "p_high": round(min(99.99, high), 3),
        "probability_sigma_pp": round(max(0.25, sigma), 4),
        "interval_level": min(
            float(estimated.get("interval_level") or 0.90),
            float(empirical.get("interval_level") or 0.90),
        ),
        "method": "empirical_market_residual_plus_input_quality",
        "interval_status": (
            "empirical_coverage_qualified"
            if empirical.get("qualified")
            else "empirical_interval_not_coverage_qualified"
        ),
        "empirical_interval": empirical,
    }


def expected_execution_slippage_cents(settings, kalshi_micro, side):
    base = max(0.0, setting_float(settings, "CRYPTO_15M_EXPECTED_SLIPPAGE_CENTS"))
    row = kalshi_micro or {}
    age = max(0.0, float(row.get("age_seconds") or row.get("orderbook_age_seconds") or 0))
    bid = row.get(f"best_{side}_bid_cents")
    ask = row.get(f"best_{side}_entry_price_cents")
    spread = max(0.0, float(ask) - float(bid)) if ask is not None and bid is not None else 0.0
    return round(base + min(2.0, 0.20 * age) + min(1.5, 0.15 * spread), 4)


def price_candidate_side(
    settings,
    probability,
    side,
    entry_price,
    fee_schedule,
    kalshi_micro,
    interval,
):
    fee = kalshi_order_fee(
        entry_price,
        1.0,
        schedule=fee_schedule,
        liquidity_role="taker",
        fallback_rate=setting_float(settings, "CRYPTO_SHADOW_FEE_RATE"),
    )
    metrics = conservative_edge_metrics(
        probability.get("prob"),
        side,
        entry_price,
        fee_per_contract_dollars=fee.get("fee_per_contract_dollars"),
        expected_slippage_cents=expected_execution_slippage_cents(settings, kalshi_micro, side),
        interval=interval,
    )
    raw_edge = (
        float(probability.get("prob") or 0)
        if side == "yes"
        else 100.0 - float(probability.get("prob") or 0)
    ) - float(entry_price)
    return {
        "side": side,
        "entry_price": float(entry_price),
        "raw_edge": round(raw_edge, 3),
        "fee": fee,
        **metrics,
    }


def apply_candidate_pricing(settings, candidate):
    """Recompute auditable edge/confidence after any quote/probability refresh."""
    probability = candidate.get("probability") or {
        "prob": float(candidate.get("model_prob_yes") or 50.0),
        "model_disagreement": 0.0,
    }
    candidate["probability"] = probability
    quality = candidate.get("data_quality") or {"score": 1.0}
    interval = candidate_probability_interval(
        settings,
        probability,
        quality,
    )
    probability.update(interval)
    result = price_candidate_side(
        settings,
        probability,
        str(candidate.get("side") or "yes"),
        float(candidate.get("entry_price") or 0),
        candidate.get("fee_schedule") or {},
        candidate.get("kalshi_microstructure") or {},
        interval,
    )
    fee = result["fee"]
    candidate.update({
        "raw_edge": result["raw_edge"],
        "estimated_fee_edge_pp": result["exact_fee_cents"],
        "exact_fee_cents": result["exact_fee_cents"],
        "expected_slippage_cents": result["expected_slippage_cents"],
        "expected_edge": result["expected_edge"],
        "edge_low": result["edge_low"],
        "probability_net_edge_positive": result["probability_net_edge_positive"],
        "selected_side_probability": result["selected_side_probability"],
        "selected_side_probability_low": result["selected_side_probability_low"],
        "selected_side_probability_high": result["selected_side_probability_high"],
        "net_edge": result["expected_edge"],
        "edge": result["expected_edge"],
        "confidence": result["probability_net_edge_positive"],
        "fee_detail": fee,
        "fee_schedule_exact": bool(fee.get("exact")),
    })
    return result


def build_candidates(
    settings,
    markets,
    asset_data,
    fear_greed,
    kalshi_microstructure_by_ticker=None,
    learned_state=None,
):
    allow_range = setting_bool(settings, "CRYPTO_ALLOW_RANGE_MARKETS")
    allow_ab = setting_bool(settings, "CRYPTO_ALLOW_ABOVE_BELOW_MARKETS")
    candidates = []
    asset_news_cache = {}
    asset_model_cache = {}
    active_strategy_identity = build_strategy_identity(settings, learned_state)
    commodity_anchor_markets = {}
    for possible_anchor in markets:
        if market_lane(possible_anchor) != "commodity_15m":
            continue
        anchor_asset = infer_asset(possible_anchor)
        anchor_open = parse_time(possible_anchor.get("open_time"))
        anchor_floor, _ = market_strikes(possible_anchor)
        if not anchor_asset or not anchor_open or anchor_floor is None or anchor_open > utc_now():
            continue
        prior = commodity_anchor_markets.get(anchor_asset)
        if not prior or anchor_open > parse_time(prior.get("open_time")):
            commodity_anchor_markets[anchor_asset] = possible_anchor
    for market in markets:
        lane = market_lane(market)
        if lane == "unsupported":
            continue
        if lane != "crypto_15m" and not setting_bool(settings, "MULTI_MARKET_ENABLED"):
            continue
        if lane != "crypto_15m":
            minutes_remaining = market_minutes_to_close(market)
            maximum_minutes = setting_float(
                settings,
                (
                    "MULTI_MARKET_15M_MAX_MINUTES_REMAINING"
                    if lane.endswith("15m")
                    else "MULTI_MARKET_HOURLY_MAX_MINUTES_REMAINING"
                ),
            )
            minimum_minutes = setting_float(
                settings,
                (
                    "MULTI_MARKET_15M_MIN_MINUTES_REMAINING"
                    if lane.endswith("15m")
                    else "MULTI_MARKET_HOURLY_MIN_MINUTES_REMAINING"
                ),
            )
            if (
                minutes_remaining is None
                or minutes_remaining < minimum_minutes
                or minutes_remaining > maximum_minutes
            ):
                continue
        is_15m = lane in {"crypto_15m", "commodity_15m"}
        asset = infer_asset(market)
        if asset not in asset_data:
            continue
        kind = market_kind(market)
        if kind == "range" and not allow_range:
            continue
        if kind in {"above", "below"} and not allow_ab:
            continue
        if kind == "unknown":
            continue
        news_key = (asset, lane)
        if news_key not in asset_news_cache:
            news_disabled = is_15m or (
                asset in COMMODITY_ASSETS
                and not setting_bool(settings, "MULTI_MARKET_COMMODITY_NEWS_ENABLED")
            )
            asset_news_cache[news_key] = (
                {"enabled": False, "count": 0, "score": 0.0, "source": "disabled_for_short_horizon"}
                if news_disabled
                else fetch_news_sentiment(settings, asset)
            )
        model_asset_row = asset_data[asset]
        anchor_market = None
        if asset in COMMODITY_ASSETS and model_asset_row.get("requires_kalshi_anchor"):
            anchor_market = market if lane == "commodity_15m" else commodity_anchor_markets.get(asset)
            if not anchor_market:
                continue
            try:
                model_asset_row = align_commodity_proxy_to_kalshi_anchor(
                    settings, model_asset_row, anchor_market
                )
            except Exception as exc:
                log_line(
                    f"Commodity candidate BLOCKED asset={asset} ticker={market.get('ticker')} "
                    f"reason={type(exc).__name__}:{safe_error_message(exc)}"
                )
                continue
        model_key = (asset, lane, (anchor_market or {}).get("ticker"))
        if model_key not in asset_model_cache:
            asset_model_cache[model_key] = (
                estimate_15m_asset_model(model_asset_row, settings=settings)
                if lane == "crypto_15m"
                else estimate_intraday_asset_model(
                    model_asset_row,
                    settings=settings,
                    horizon="15m" if lane == "commodity_15m" else "hourly",
                    news=asset_news_cache[news_key],
                )
            )
        kalshi_micro = (kalshi_microstructure_by_ticker or {}).get(market.get("ticker")) or {}
        microstructure = model_asset_row.get("microstructure") or {}
        model = dict(asset_model_cache[model_key])
        if lane == "crypto_15m":
            basis_by_asset = (learned_state or {}).get("settlement_basis_by_asset") or {}
            model["settlement_basis_model"] = basis_by_asset.get(asset) or {}
            close_time = parse_time(market.get("close_time"))
            if close_time:
                remaining = max(0.0, (close_time - utc_now()).total_seconds())
                if remaining < setting_float(settings, "CRYPTO_15M_SETTLEMENT_WINDOW_SECONDS"):
                    model["settlement_partial_window"] = settlement_proxy_window(
                        settings,
                        asset,
                        close_time,
                    )
        pricing_market = dict(market)
        quote_mapping = {
            "yes_bid": "best_yes_bid_cents",
            "yes_ask": "best_yes_entry_price_cents",
            "no_bid": "best_no_bid_cents",
            "no_ask": "best_no_entry_price_cents",
            "microprice_yes_cents": "microprice_yes_cents",
            "orderbook_age_seconds": "age_seconds",
        }
        for market_key, micro_key in quote_mapping.items():
            value = kalshi_micro.get(micro_key)
            if value is not None:
                pricing_market[market_key] = value
        probability = probability_for_market(pricing_market, model, settings)
        if not probability:
            continue
        flow_review = combined_flow_review(
            microstructure,
            kalshi_micro,
            include_kalshi_book_vote=setting_bool(
                settings,
                "CRYPTO_15M_DIRECTIONAL_INCLUDE_KALSHI_BOOK_VOTE",
            ),
        )
        preliminary = {
            "asset": asset,
            "ticker": market.get("ticker"),
            "exchange_index": market.get("exchange_index"),
            "event_ticker": market.get("event_ticker"),
            "series_ticker": market_series_ticker(market),
            "market_kind": kind,
            "market_lane": lane,
            "exposure_group": exposure_group(asset),
            "is_15m_market": is_15m,
            "minutes_to_close": probability.get("minutes_to_close"),
            "close_time": market.get("close_time"),
            "model_prob_yes": probability["prob"],
            "model": model,
            "probability": probability,
            "microstructure": microstructure,
            "kalshi_microstructure": kalshi_micro,
            "flow_review": flow_review,
        }
        if lane == "crypto_15m":
            probability = apply_15m_learning_prediction(
                settings,
                preliminary,
                probability,
                learned_state,
            )
        quality = data_quality_metrics(
            microstructure,
            kalshi_micro,
            maximum_age_seconds=setting_float(
                settings,
                "CRYPTO_15M_DATA_QUALITY_MAX_AGE_SECONDS",
            ),
        )
        if not is_15m:
            quality = {**quality, "score": max(0.8, float(quality.get("score") or 0))}
        interval = candidate_probability_interval(settings, probability, quality)
        probability.update(interval)
        fee_schedule = kalshi_series_fee_schedule(settings, market_series_ticker(market))
        market_yes_ask = market_price(market, "yes_ask", "yes_ask_dollars")
        market_no_ask = market_price(market, "no_ask", "no_ask_dollars")
        executable_yes_ask = kalshi_micro.get("best_yes_entry_price_cents")
        executable_no_ask = kalshi_micro.get("best_no_entry_price_cents")
        has_executable_yes_ask = (
            executable_yes_ask is not None
            and 0 < float(executable_yes_ask) < 100
        )
        has_executable_no_ask = (
            executable_no_ask is not None
            and 0 < float(executable_no_ask) < 100
        )
        yes_ask = (
            float(executable_yes_ask)
            if has_executable_yes_ask
            else market_yes_ask
        )
        no_ask = (
            float(executable_no_ask)
            if has_executable_no_ask
            else market_no_ask
        )
        yes_bid = market_price(market, "yes_bid", "yes_bid_dollars")
        last_price = market_price(market, "last_price", "last_price_dollars")
        choices = []
        if yes_ask is not None and yes_ask > 0:
            choices.append(price_candidate_side(
                settings, probability, "yes", yes_ask, fee_schedule, kalshi_micro, interval
            ))
        if no_ask is not None and no_ask > 0:
            choices.append(price_candidate_side(
                settings, probability, "no", no_ask, fee_schedule, kalshi_micro, interval
            ))
        if not choices and last_price is not None:
            choices.append(price_candidate_side(
                settings, probability, "yes", last_price, fee_schedule, kalshi_micro, interval
            ))
        if not choices:
            continue
        selected = max(choices, key=lambda row: (row["edge_low"], row["expected_edge"]))
        side = selected["side"]
        entry_price = selected["entry_price"]
        raw_edge = selected["raw_edge"]
        edge = selected["expected_edge"]
        fee_drag = selected["exact_fee_cents"]
        selected_orderbook_price = (
            has_executable_yes_ask
            if side == "yes"
            else has_executable_no_ask
            if side == "no"
            else False
        )
        initial_price_source = (
            "kalshi_executable_orderbook"
            if selected_orderbook_price
            else "kalshi_market_quote"
        )
        confidence = selected["probability_net_edge_positive"]
        candidate = {
            "asset": asset,
            "ticker": market.get("ticker"),
            "exchange_index": market.get("exchange_index"),
            "event_ticker": market.get("event_ticker"),
            "series_ticker": market_series_ticker(market),
            "title": market.get("title"),
            "market_kind": kind,
            "market_lane": lane,
            "exposure_group": exposure_group(asset),
            "position_cluster": position_cluster_key({
                "asset": asset,
                "close_time": market.get("close_time"),
            }),
            "side": side,
            "entry_price": round(entry_price, 2),
            "yes_bid": yes_bid,
            "yes_ask": yes_ask,
            "no_ask": no_ask,
            "market_yes_ask": market_yes_ask,
            "market_no_ask": market_no_ask,
            "initial_price_source": initial_price_source,
            "market_quote_fetched_at": (
                kalshi_micro.get("orderbook_fetched_at")
                if initial_price_source == "kalshi_executable_orderbook"
                else market.get("_quote_fetched_at")
            ),
            "model_prob_yes": probability["prob"],
            "raw_edge": round(raw_edge, 2),
            "estimated_fee_edge_pp": round(fee_drag, 3),
            "net_edge": round(edge, 2),
            "edge": round(edge, 2),
            "confidence": confidence,
            "expected_edge": selected["expected_edge"],
            "edge_low": selected["edge_low"],
            "probability_net_edge_positive": selected["probability_net_edge_positive"],
            "selected_side_probability_low": selected["selected_side_probability_low"],
            "selected_side_probability_high": selected["selected_side_probability_high"],
            "exact_fee_cents": selected["exact_fee_cents"],
            "expected_slippage_cents": selected["expected_slippage_cents"],
            "fee_schedule": fee_schedule,
            "fee_detail": selected["fee"],
            "fee_schedule_exact": bool(selected["fee"].get("exact")),
            "data_quality": quality,
            "close_time": market.get("close_time"),
            "open_time": market.get("open_time"),
            "is_15m_market": is_15m,
            "minutes_to_close": probability.get("minutes_to_close"),
            "floor_strike": market_strikes(market)[0],
            "cap_strike": market_strikes(market)[1],
            "volume": float(market.get("volume") or market.get("volume_fp") or 0),
            "liquidity": float(market.get("liquidity") or market.get("liquidity_dollars") or 0),
            "open_interest": float(
                market.get("open_interest")
                or market.get("open_interest_fp")
                or kalshi_micro.get("open_interest")
                or 0
            ),
            "probability": probability,
            "model": model,
            "microstructure": microstructure,
            "kalshi_microstructure": kalshi_micro,
            "flow_review": flow_review,
            "learned_15m_model": preliminary.get("learned_15m_model"),
            "strategy_identity": active_strategy_identity,
            "strategy_version": active_strategy_identity.get("strategy_version"),
            "strategy_config_hash": active_strategy_identity.get("config_hash"),
            "feature_schema_version": active_strategy_identity.get("feature_schema_version"),
            "skip_reasons": [],
        }
        candidate["disagreement_guard"] = (
            crypto_15m_disagreement_review(settings, candidate)
            if lane in {"crypto_15m", "commodity_15m"}
            else {"enabled": False, "ok": True, "reason": "lane_specific_model"}
        )
        candidates.append(candidate)
    return candidates


def kelly_stake(
    prob_pct,
    price_cents,
    balance,
    settings,
    *,
    probability_low_pct=None,
    fee_cents=0.0,
    slippage_cents=0.0,
):
    total_cost_cents = float(price_cents) + max(0.0, float(fee_cents or 0)) + max(0.0, float(slippage_cents or 0))
    if total_cost_cents <= 0 or total_cost_cents >= 100:
        return 0.0
    conservative_probability = prob_pct if probability_low_pct is None else probability_low_pct
    p = max(0.0, min(1.0, float(conservative_probability) / 100.0))
    b = (100.0 / total_cost_cents) - 1.0
    if b <= 0 or p <= 1.0 / (b + 1.0):
        return 0.0
    kelly = (p * b - (1.0 - p)) / b
    cap = balance * setting_float(settings, "CRYPTO_MAX_STAKE_PCT")
    stake = min(balance * kelly * setting_float(settings, "CRYPTO_KELLY_FRACTION"), cap, setting_float(settings, "CRYPTO_MAX_STAKE"))
    return round(max(0.0, stake), 2)


def candidate_side_probability(candidate):
    yes_prob = float(candidate.get("model_prob_yes") or 0)
    return yes_prob if candidate.get("side") == "yes" else 100.0 - yes_prob


def crypto_candidate_sort_key(settings, candidate):
    priority_asset = str(settings.get("CRYPTO_15M_PRIORITY_ASSET") or "").strip().upper()
    asset = str(candidate.get("asset") or "").strip().upper()
    return (
        1 if priority_asset and asset == priority_asset else 0,
        float(candidate.get("edge") or -999),
        float(candidate.get("confidence") or 0),
    )


def apply_crypto_shadow_analysis(settings, portfolio, candidates):
    if not setting_bool(settings, "CRYPTO_SHADOW_PRICING_ENABLED"):
        return {
            "version": "fee-correlation-v1",
            "mode": "disabled",
            "affects_execution": False,
            "candidate_count": 0,
            "top_opportunities": [],
            "reason_counts": [],
        }
    balance = live_bankroll_for_sizing(settings, portfolio) if execution_mode(settings) == "live" else float(portfolio.get("balance") or 0)
    capital_base = max(balance + open_exposure(portfolio), float(portfolio.get("starting_balance") or 0))
    open_rows = bot_open_bets(portfolio)
    for candidate in candidates:
        candidate["shadow"] = analyze_shadow_candidate(
            probability_pct=candidate_side_probability(candidate),
            price_cents=candidate.get("entry_price"),
            bankroll=balance,
            capital_base=capital_base,
            open_positions=open_rows,
            event_key=candidate.get("event_ticker"),
            group_key=candidate.get("asset"),
            event_field="event_ticker",
            group_field="asset",
            min_net_edge_pp=setting_float(settings, "CRYPTO_MIN_EDGE"),
            kelly_fraction=setting_float(settings, "CRYPTO_KELLY_FRACTION"),
            max_stake_pct=setting_float(settings, "CRYPTO_MAX_STAKE_PCT"),
            max_stake_amount=setting_float(settings, "CRYPTO_MAX_STAKE"),
            min_stake=setting_float(settings, "CRYPTO_MIN_STAKE"),
            fee_rate=setting_float(settings, "CRYPTO_SHADOW_FEE_RATE"),
            fee_schedule=candidate.get("fee_schedule") or {},
            probability_low_pct=candidate.get("selected_side_probability_low"),
            event_exposure_pct=setting_float(settings, "CRYPTO_SHADOW_EVENT_EXPOSURE_PCT"),
            group_exposure_pct=setting_float(settings, "CRYPTO_SHADOW_ASSET_EXPOSURE_PCT"),
            max_event_positions=setting_int(settings, "CRYPTO_SHADOW_MAX_EVENT_POSITIONS"),
            current_filter_reasons=candidate.get("skip_reasons") or [],
        )
    summary = summarize_shadow_candidates(candidates)
    summary["outcomes"] = summarize_shadow_outcomes([
        bet for bet in portfolio.get("bets", []) if crypto_analytics_included(bet, settings)
    ])
    summary["configuration"] = {
        "fee_rate": setting_float(settings, "CRYPTO_SHADOW_FEE_RATE"),
        "min_net_edge_pp": setting_float(settings, "CRYPTO_MIN_EDGE"),
        "event_exposure_pct": setting_float(settings, "CRYPTO_SHADOW_EVENT_EXPOSURE_PCT"),
        "asset_exposure_pct": setting_float(settings, "CRYPTO_SHADOW_ASSET_EXPOSURE_PCT"),
        "max_event_positions": setting_int(settings, "CRYPTO_SHADOW_MAX_EVENT_POSITIONS"),
        "bankroll": round(balance, 2),
        "capital_base": round(capital_base, 2),
    }
    return summary


def low_edge_shadow_quality_review(settings, candidate):
    reasons = []
    edge = float(candidate.get("edge") or 0)
    if not (
        setting_float(settings, "CRYPTO_LOW_EDGE_SHADOW_MIN_EDGE")
        <= edge
        < setting_float(settings, "CRYPTO_LOW_EDGE_SHADOW_MAX_EDGE")
    ):
        reasons.append("outside_low_edge_cohorts")
    if float(candidate.get("confidence") or 0) < setting_float(
        settings,
        "CRYPTO_LOW_EDGE_SHADOW_MIN_CONFIDENCE",
    ):
        reasons.append("confidence_below_65")
    disagreement = candidate.get("disagreement_guard") or {}
    if disagreement.get("enabled") and not disagreement.get("ok"):
        reasons.append(
            disagreement.get("reason")
            or "model_market_disagreement_unconfirmed"
        )
    directional = crypto_15m_directional_confirmation_review(settings, candidate)
    if directional.get("enabled") and not directional.get("ok"):
        reasons.append(
            directional.get("reason")
            or "campaign_directional_confirmation"
        )
    return {
        "ok": not reasons,
        "reasons": reasons,
        "disagreement_guard": disagreement,
        "directional_confirmation": directional,
        "uses_live_position_limits": False,
        "uses_campaign_recovery": False,
        "affects_execution": False,
    }


def fetch_low_edge_shadow_market(ticker):
    payload = http_json(f"{KALSHI_BASE}/markets/{quote(str(ticker or ''))}")
    return (payload or {}).get("market") or {}


def run_low_edge_shadow(settings, candidates):
    ledger = normalize_low_edge_shadow_ledger(
        read_json(CRYPTO_LOW_EDGE_SHADOW_FILE, empty_low_edge_shadow_ledger())
    )
    if not setting_bool(settings, "CRYPTO_LOW_EDGE_SHADOW_ENABLED"):
        summary = summarize_low_edge_shadow(ledger)
        summary.update({
            "mode": "frozen_history",
            "capture_enabled": False,
            "captured_this_scan": 0,
            "settled_this_scan": 0,
            "freeze_reason": "negative_after_fee_forward_evidence",
            "affects_execution": False,
        })
        return summary
    settled = settle_low_edge_shadow_records(
        ledger,
        fetch_low_edge_shadow_market,
        fee_per_contract=lambda price: estimated_taker_fee_per_contract(
            price,
            setting_float(settings, "CRYPTO_SHADOW_FEE_RATE"),
        ),
        grace_minutes=setting_float(
            settings,
            "CRYPTO_LOW_EDGE_SHADOW_SETTLEMENT_GRACE_MINUTES",
        ),
        retry_minutes=setting_float(
            settings,
            "CRYPTO_LOW_EDGE_SHADOW_SETTLEMENT_RETRY_MINUTES",
        ),
        max_checks=setting_int(
            settings,
            "CRYPTO_LOW_EDGE_SHADOW_MAX_SETTLEMENT_CHECKS_PER_SCAN",
        ),
    )
    for candidate in candidates:
        review = low_edge_shadow_quality_review(settings, candidate)
        candidate["low_edge_shadow_quality_ok"] = review["ok"]
        candidate["low_edge_shadow_quality_controls"] = review
    shadow_min_edge = setting_float(
        settings,
        "CRYPTO_LOW_EDGE_SHADOW_MIN_EDGE",
    )
    shadow_max_edge = setting_float(
        settings,
        "CRYPTO_LOW_EDGE_SHADOW_MAX_EDGE",
    )
    shadow_min_confidence = setting_float(
        settings,
        "CRYPTO_LOW_EDGE_SHADOW_MIN_CONFIDENCE",
    )
    shadow_min_price = setting_float(
        settings,
        "CRYPTO_15M_MIN_ENTRY_PRICE_CENTS",
    )
    shadow_max_price = setting_float(
        settings,
        "CRYPTO_15M_MAX_ENTRY_PRICE_CENTS",
    )
    shadow_min_minutes = setting_float(
        settings,
        "CRYPTO_15M_MIN_MINUTES_REMAINING",
    )
    shadow_max_minutes = setting_float(
        settings,
        "CRYPTO_15M_MAX_MINUTES_REMAINING",
    )
    targeted_candidates = [
        candidate
        for candidate in candidates
        if (
            candidate.get("is_15m_market")
            and shadow_min_edge
            <= float(candidate.get("edge") or 0)
            < shadow_max_edge
            and float(candidate.get("confidence") or 0)
            >= shadow_min_confidence
            and shadow_min_price
            <= float(candidate.get("entry_price") or 0)
            <= shadow_max_price
            and shadow_min_minutes
            <= float(candidate.get("minutes_to_close") or 0)
            <= shadow_max_minutes
        )
    ]
    shadow_reason_counts = {}
    for candidate in targeted_candidates:
        for reason in (
            (candidate.get("low_edge_shadow_quality_controls") or {}).get(
                "reasons",
            )
            or []
        ):
            shadow_reason_counts[reason] = shadow_reason_counts.get(reason, 0) + 1
    added = capture_low_edge_shadow_candidates(
        ledger,
        candidates,
        min_confidence=shadow_min_confidence,
        min_price=shadow_min_price,
        max_price=shadow_max_price,
        min_minutes=shadow_min_minutes,
        max_minutes=shadow_max_minutes,
        virtual_stake=setting_float(
            settings,
            "CRYPTO_LOW_EDGE_SHADOW_VIRTUAL_STAKE",
        ),
        max_records=setting_int(
            settings,
            "CRYPTO_LOW_EDGE_SHADOW_MAX_RECORDS",
        ),
    )
    write_json(CRYPTO_LOW_EDGE_SHADOW_FILE, ledger)
    for row in added:
        log_line(
            f"CRYPTO LOW EDGE SHADOW CAPTURED: {row.get('cohort')} "
            f"{str(row.get('side') or '').upper()} {row.get('asset')} "
            f"{row.get('ticker')} edge={row.get('net_edge')}% "
            f"conf={row.get('confidence')} entry={row.get('entry_price')}c"
        )
        event_line({"type": "crypto_low_edge_shadow_captured", "shadow": row})
    for row in settled:
        log_line(
            f"CRYPTO LOW EDGE SHADOW SETTLED: {row.get('result')} "
            f"{row.get('cohort')} {row.get('ticker')} "
            f"profit=${float(row.get('virtual_profit') or 0):.4f}"
        )
        event_line({"type": "crypto_low_edge_shadow_settled", "shadow": row})
    summary = summarize_low_edge_shadow(ledger)
    summary["captured_this_scan"] = len(added)
    summary["settled_this_scan"] = len(settled)
    summary["candidate_funnel"] = {
        "targeted_this_scan": len(targeted_candidates),
        "quality_approved_this_scan": sum(
            1
            for candidate in targeted_candidates
            if candidate.get("low_edge_shadow_quality_ok")
        ),
        "captured_this_scan": len(added),
        "quality_rejection_reasons": [
            {"label": label, "count": count}
            for label, count in sorted(
                shadow_reason_counts.items(),
                key=lambda item: (-item[1], item[0]),
            )
        ],
    }
    summary["configuration"] = {
        "edge_cohorts": ["1-2%", "2-3%", "3-4%"],
        "minimum_confidence": shadow_min_confidence,
        "minimum_price_cents": shadow_min_price,
        "maximum_price_cents": shadow_max_price,
        "minimum_minutes_remaining": shadow_min_minutes,
        "maximum_minutes_remaining": shadow_max_minutes,
        "virtual_stake": setting_float(
            settings,
            "CRYPTO_LOW_EDGE_SHADOW_VIRTUAL_STAKE",
        ),
        "requires_disagreement_guard": True,
        "requires_directional_confirmation": setting_bool(
            settings,
            "CRYPTO_15M_DIRECTIONAL_CONFIRMATION_REQUIRED",
        ),
    }
    return summary


def run_rejection_shadow(settings, candidates):
    if not setting_bool(settings, "CRYPTO_REJECTION_SHADOW_ENABLED"):
        return {
            "version": "crypto-rejection-shadow-v3",
            "mode": "disabled",
            "affects_execution": False,
            "tracked": 0,
            "open": 0,
            "settled": 0,
            "cohorts": [],
        }
    ledger = normalize_rejection_shadow_ledger(
        read_json(CRYPTO_REJECTION_SHADOW_FILE, empty_rejection_shadow_ledger())
    )
    settled = settle_rejection_shadow_records(
        ledger,
        fetch_low_edge_shadow_market,
        fee_per_contract=lambda price: estimated_taker_fee_per_contract(
            price,
            setting_float(settings, "CRYPTO_SHADOW_FEE_RATE"),
        ),
        grace_minutes=setting_float(
            settings,
            "CRYPTO_REJECTION_SHADOW_SETTLEMENT_GRACE_MINUTES",
        ),
        retry_minutes=setting_float(
            settings,
            "CRYPTO_REJECTION_SHADOW_SETTLEMENT_RETRY_MINUTES",
        ),
        max_checks=setting_int(
            settings,
            "CRYPTO_REJECTION_SHADOW_MAX_SETTLEMENT_CHECKS_PER_SCAN",
        ),
    )
    added = capture_rejection_shadow_candidates(
        ledger,
        candidates,
        virtual_stake=setting_float(
            settings,
            "CRYPTO_REJECTION_SHADOW_VIRTUAL_STAKE",
        ),
        max_records=setting_int(
            settings,
            "CRYPTO_REJECTION_SHADOW_MAX_RECORDS",
        ),
    )
    write_json(CRYPTO_REJECTION_SHADOW_FILE, ledger)
    for row in added:
        log_line(
            f"CRYPTO REJECTION SHADOW CAPTURED: {row.get('cohort')} "
            f"{str(row.get('side') or '').upper()} {row.get('asset')} "
            f"{row.get('ticker')} edge={row.get('edge')}% "
            f"conf={row.get('confidence')} entry={row.get('entry_price')}c"
        )
        event_line({"type": "crypto_rejection_shadow_captured", "shadow": row})
    for row in settled:
        log_line(
            f"CRYPTO REJECTION SHADOW SETTLED: {row.get('result')} "
            f"{row.get('cohort')} {row.get('ticker')} "
            f"profit=${float(row.get('virtual_profit') or 0):.4f}"
        )
        event_line({"type": "crypto_rejection_shadow_settled", "shadow": row})
    summary = summarize_rejection_shadow(ledger)
    summary["captured_this_scan"] = len(added)
    summary["settled_this_scan"] = len(settled)
    summary["configuration"] = {
        "cohorts": [
            "directional_confirmation",
            "directional_opposition",
            "directional_flow_too_weak",
            "directional_insufficient_consensus",
            "directional_data_unavailable",
            "one_source_shadow",
            "mid_price_6_9_edge",
            "commodity_live_shadow",
        ],
        "virtual_stake": setting_float(
            settings,
            "CRYPTO_REJECTION_SHADOW_VIRTUAL_STAKE",
        ),
    }
    one_source = next(
        (row for row in summary.get("cohorts") or [] if row.get("cohort") == "one_source_shadow"),
        {},
    )
    required_markets = setting_int(settings, "CRYPTO_15M_ONE_SOURCE_PROMOTION_MIN_MARKETS")
    minimum_roi = setting_float(settings, "CRYPTO_15M_ONE_SOURCE_PROMOTION_MIN_ROI_PCT")
    summary["one_source_promotion_review"] = {
        "automatic_promotion": False,
        "eligible_for_manual_review": (
            int(one_source.get("independent_settled_markets") or 0) >= required_markets
            and float(one_source.get("market_weighted_roi") or 0) > minimum_roi
        ),
        "independent_settled_markets": int(one_source.get("independent_settled_markets") or 0),
        "required_independent_settled_markets": required_markets,
        "market_weighted_roi": float(one_source.get("market_weighted_roi") or 0),
        "minimum_market_weighted_roi": minimum_roi,
    }
    return summary


def run_directional_opposition_v2(settings, candidates):
    if not setting_bool(settings, "CRYPTO_DIRECTIONAL_OPPOSITION_V2_ENABLED"):
        return {
            "version": DIRECTIONAL_OPPOSITION_V2_VERSION,
            "mode": "disabled",
            "affects_execution": False,
            "automatic_promotion": False,
            "tracked": 0,
            "open": 0,
            "settled": 0,
            "lanes": [],
        }
    ledger = normalize_directional_opposition_v2_ledger(
        read_json(
            CRYPTO_DIRECTIONAL_OPPOSITION_V2_FILE,
            empty_directional_opposition_v2_ledger(settings),
        ),
        settings,
    )
    settled = settle_directional_opposition_v2_records(
        ledger,
        fetch_low_edge_shadow_market,
        settings,
    )
    directional_research_candidates = []
    for candidate in candidates or []:
        research_candidate = dict(candidate)
        research_candidate["directional_shadow_review"] = (
            crypto_15m_directional_confirmation_review(settings, research_candidate)
        )
        directional_research_candidates.append(research_candidate)
    added = capture_directional_opposition_v2_candidates(
        ledger,
        directional_research_candidates,
        settings,
    )
    paired_records = {
        str(row.get("id") or ""): row
        for row in ((ledger.get("paired_experiment") or {}).get("records") or [])
    }
    paired_added = [
        paired_records[record_id]
        for record_id in (ledger.get("last_paired_capture_ids") or [])
        if record_id in paired_records
    ]
    paired_settled = [
        paired_records[record_id]
        for record_id in (ledger.get("last_paired_settled_ids") or [])
        if record_id in paired_records
    ]
    replication_records = {
        str(row.get("id") or ""): row
        for row in (
            (ledger.get("asset_replication_experiment") or {}).get("records")
            or []
        )
    }
    replication_added = [
        replication_records[record_id]
        for record_id in (ledger.get("last_replication_capture_ids") or [])
        if record_id in replication_records
    ]
    replication_settled = [
        replication_records[record_id]
        for record_id in (ledger.get("last_replication_settled_ids") or [])
        if record_id in replication_records
    ]
    summary = summarize_directional_opposition_v2(ledger, settings)
    summary["captured_this_scan"] = len(added)
    summary["settled_this_scan"] = len(settled)
    summary.setdefault("paired_forward", {})["captured_this_scan"] = len(paired_added)
    summary["paired_forward"]["settled_this_scan"] = len(paired_settled)
    summary.setdefault("asset_replications", {})["captured_this_scan"] = len(
        replication_added
    )
    summary["asset_replications"]["settled_this_scan"] = len(
        replication_settled
    )
    write_json(CRYPTO_DIRECTIONAL_OPPOSITION_V2_FILE, ledger)
    for row in added:
        log_line(
            "CRYPTO DIRECTIONAL OPPOSITION V2 CAPTURED: "
            f"lane={row.get('lane')} {str(row.get('side') or '').upper()} "
            f"{row.get('asset')} {row.get('ticker')} "
            f"entry={float(row.get('entry_price_cents') or 0):.1f}c "
            f"version={row.get('strategy_version')}"
        )
        event_line({
            "type": "crypto_directional_opposition_v2_captured",
            "shadow": row,
        })
    for row in settled:
        log_line(
            "CRYPTO DIRECTIONAL OPPOSITION V2 SETTLED: "
            f"{row.get('result')} lane={row.get('lane')} "
            f"{row.get('asset')} {row.get('ticker')} "
            f"profit=${float(row.get('virtual_profit') or 0):.4f}"
        )
        event_line({
            "type": "crypto_directional_opposition_v2_settled",
            "shadow": row,
        })
    for row in paired_added:
        log_line(
            "CRYPTO DIRECTIONAL PAIRED FORWARD CAPTURED: "
            f"{row.get('asset')} {row.get('ticker')} "
            f"fade={str((row.get('fade') or {}).get('side') or '').upper()}@"
            f"{float((row.get('fade') or {}).get('entry_price_cents') or 0):.1f}c "
            f"follow={str((row.get('follow') or {}).get('side') or '').upper()}@"
            f"{float((row.get('follow') or {}).get('entry_price_cents') or 0):.1f}c"
        )
        event_line({
            "type": "crypto_directional_paired_forward_captured",
            "shadow": row,
        })
    for row in paired_settled:
        log_line(
            "CRYPTO DIRECTIONAL PAIRED FORWARD SETTLED: "
            f"{row.get('asset')} {row.get('ticker')} "
            f"result={str(row.get('market_result') or '').upper()} "
            f"fade=${float((row.get('fade') or {}).get('virtual_profit') or 0):.4f} "
            f"follow=${float((row.get('follow') or {}).get('virtual_profit') or 0):.4f} "
            f"delta=${float(row.get('profit_delta') or 0):.4f}"
        )
        event_line({
            "type": "crypto_directional_paired_forward_settled",
            "shadow": row,
        })
    for row in replication_added:
        log_line(
            "CRYPTO DIRECTIONAL ASSET REPLICATION CAPTURED: "
            f"hypothesis={row.get('hypothesis')} {row.get('asset')} "
            f"{row.get('ticker')} primary={row.get('primary_arm_name')}"
        )
        event_line({
            "type": "crypto_directional_asset_replication_captured",
            "shadow": row,
        })
    for row in replication_settled:
        log_line(
            "CRYPTO DIRECTIONAL ASSET REPLICATION SETTLED: "
            f"hypothesis={row.get('hypothesis')} {row.get('asset')} "
            f"{row.get('ticker')} result={str(row.get('market_result') or '').upper()} "
            f"primary=${float(row.get('primary_profit') or 0):.4f} "
            f"delta=${float(row.get('profit_delta') or 0):.4f}"
        )
        event_line({
            "type": "crypto_directional_asset_replication_settled",
            "shadow": row,
        })
    return summary


def run_btc_15m_sprint(settings, candidates):
    if not setting_bool(settings, "CRYPTO_15M_SPRINT_ENABLED"):
        return {
            "version": BTC_15M_SPRINT_VERSION,
            "policy_name": "btc_15m_flow_veto_override",
            "mode": "disabled",
            "status": "DISABLED",
            "affects_execution": False,
            "automatic_promotion": False,
            "execution_freeze": crypto_15m_sprint_execution_freeze(settings),
            "lanes": [],
            "controls_by_asset": [],
            "recent_records": [],
        }
    state = read_json(
        CRYPTO_BTC_15M_SPRINT_FILE,
        empty_btc_15m_sprint_state(settings),
    )
    rejection_ledger = normalize_rejection_shadow_ledger(
        read_json(CRYPTO_REJECTION_SHADOW_FILE, empty_rejection_shadow_ledger())
    )
    state, summary, added, settled = run_btc_15m_sprint_scan(
        state,
        candidates,
        fetch_low_edge_shadow_market,
        settings=settings,
        rejection_records=rejection_ledger.get("records") or [],
    )
    write_json(CRYPTO_BTC_15M_SPRINT_FILE, state)
    for row in added:
        log_line(
            f"BTC 15M SPRINT CAPTURED: lane={row.get('lane')} "
            f"{str(row.get('side') or '').upper()} {row.get('asset')} "
            f"{row.get('ticker')} entry={float(row.get('entry_price_cents') or 0):.1f}c "
            f"reserved_edge={float(row.get('reserved_edge_cents') or 0):.2f}c"
        )
        event_line({"type": "crypto_btc_15m_sprint_captured", "shadow": row})
    for row in settled:
        log_line(
            f"BTC 15M SPRINT SETTLED: lane={row.get('lane')} "
            f"{row.get('result')} {row.get('ticker')} "
            f"reserved_profit=${float(row.get('reserved_profit') or 0):.4f}"
        )
        event_line({"type": "crypto_btc_15m_sprint_settled", "shadow": row})
    freeze = crypto_15m_sprint_execution_freeze(settings)
    isolated_pilot_armed = bool(
        setting_bool(settings, "CRYPTO_SPOT_FLOW_LIVE_PILOT_ENABLED")
        and freeze.get("live_order_enabled")
        and not freeze.get("dry_run")
    )
    isolated_patient_armed = bool(
        patient_enabled(settings) and freeze.get("live_order_enabled") and not freeze.get("dry_run")
    )
    freeze["healthy_intentional_state"] = bool(
        freeze.get("active")
        and (
            (
                not freeze.get("live_order_enabled")
                and freeze.get("dry_run")
            )
            or isolated_pilot_armed
            or isolated_patient_armed
        )
        and not freeze.get("unit_staking_enabled")
        and not freeze.get("unit_recovery_enabled")
        and not freeze.get("pooled_recovery_enabled")
        and not freeze.get("partial_recovery_enabled")
        and not freeze.get("cross_bot_recovery_enabled")
        and not freeze.get("dynamic_auto_promote_enabled")
    )
    freeze["isolated_spot_flow_live_pilot_armed"] = isolated_pilot_armed
    freeze["isolated_eth_patient_armed"] = isolated_patient_armed
    summary["execution_freeze"] = freeze
    return summary


def run_signal_tournament_shadow(settings, candidates):
    if not setting_bool(settings, "CRYPTO_SIGNAL_TOURNAMENT_ENABLED"):
        return {
            "version": SIGNAL_TOURNAMENT_VERSION,
            "mode": "disabled",
            "affects_execution": False,
            "automatic_promotion": False,
            "lanes": [],
        }
    ledger = normalize_signal_tournament_ledger(
        read_json(
            CRYPTO_SIGNAL_TOURNAMENT_FILE,
            empty_signal_tournament_ledger(settings),
        ),
        settings,
    )
    settled = settle_signal_tournament_records(
        ledger,
        fetch_low_edge_shadow_market,
        settings,
    )
    added = capture_signal_tournament_candidates(ledger, candidates, settings)
    parity_book_cache = {}

    def refresh_execution_parity_quote(ticker, side, required_contracts):
        if ticker not in parity_book_cache:
            payload, fetched_at = fetch_fresh_kalshi_orderbook(settings, ticker)
            parity_book_cache[ticker] = (payload, fetched_at)
        payload, fetched_at = parity_book_cache[ticker]
        return {
            **kalshi_orderbook_depth_summary(
                payload,
                side,
                required_contracts=required_contracts,
            ),
            "fetched_at": fetched_at,
        }

    parity_updates = attach_signal_execution_parity(
        ledger,
        added,
        refresh_execution_parity_quote,
        settings,
    )
    write_json(CRYPTO_SIGNAL_TOURNAMENT_FILE, ledger)
    for row in added:
        log_line(
            "CRYPTO SIGNAL TOURNAMENT CAPTURED: "
            f"lane={row.get('lane')} {str((row.get('primary') or {}).get('side') or '').upper()} "
            f"{row.get('asset')} {row.get('ticker')} "
            f"entry={float((row.get('primary') or {}).get('entry_price_cents') or 0):.1f}c "
            f"strength={float(row.get('signal_strength') or 0):.3f}"
        )
        event_line({"type": "crypto_signal_tournament_captured", "shadow": row})
    for row in parity_updates:
        parity = row.get("execution_parity") or {}
        log_line(
            "CRYPTO SIGNAL EXECUTION PARITY: "
            f"lane={row.get('lane')} {row.get('asset')} {row.get('ticker')} "
            f"initial={float(parity.get('initial_entry_price_cents') or 0):.1f}c "
            f"fresh={float(parity.get('refreshed_entry_price_cents') or 0):.1f}c "
            f"status={parity.get('status')} reason={parity.get('reason')}"
        )
        event_line({"type": "crypto_signal_execution_parity", "shadow": row})
    for row in settled:
        settled_arm = (
            ((row.get("execution_parity") or {}).get("arm"))
            or row.get("primary")
            or {}
        )
        log_line(
            "CRYPTO SIGNAL TOURNAMENT SETTLED: "
            f"lane={row.get('lane') or 'live_pipeline_exact'} {row.get('asset')} {row.get('ticker')} "
            f"result={str(row.get('market_result') or '').upper()} "
            f"primary=${float(settled_arm.get('virtual_profit') or 0):.4f} "
            f"delta=${float(row.get('profit_delta') or 0):.4f}"
        )
        event_line({"type": "crypto_signal_tournament_settled", "shadow": row})
    summary = summarize_signal_tournament(ledger, settings)
    summary["captured_this_scan"] = len(added)
    summary["execution_parity_this_scan"] = len(parity_updates)
    summary["settled_this_scan"] = len(settled)
    validation = spot_flow_live_pilot_validation_review(summary, ledger, settings)
    write_json(
        CRYPTO_SPOT_FLOW_VALIDATION_CACHE_FILE,
        {
            "version": "crypto-spot-flow-validation-cache-v1",
            "generated_at": iso_now(),
            "signal_policy_hash": (summary.get("configuration") or {}).get(
                "policy_hash"
            ),
            "validation": validation,
        },
    )
    return summary


def build_execution_shadow_runtime(settings, independent=False):
    """Share one fresh decision/confirmation snapshot across paired shadow labs."""
    snapshot_cache = {}
    confirmation_cache = {}

    def fresh_snapshot(candidate):
        ticker = str(candidate.get("ticker") or "")
        if not independent and ticker in snapshot_cache:
            return deepcopy(snapshot_cache[ticker])
        fresh = deepcopy(candidate)
        asset = str(fresh.get("asset") or "").upper()
        try:
            payload, fetched_at = fetch_fresh_kalshi_orderbook(settings, ticker)
        except Exception as exc:
            return {
                "error": "production_shadow_quote_unavailable",
                "message": safe_error_message(exc),
            }
        try:
            coinbase = (
                COINBASE_MICROSTRUCTURE_STREAM.snapshot(asset)
                if COINBASE_MICROSTRUCTURE_STREAM
                else {}
            )
            kraken = (
                KRAKEN_MICROSTRUCTURE_STREAM.snapshot(asset)
                if KRAKEN_MICROSTRUCTURE_STREAM
                else {}
            )
        except Exception as exc:
            return {
                "error": "production_shadow_source_unavailable",
                "message": safe_error_message(exc),
            }
        max_age = max(
            0.25,
            setting_float(settings, "CRYPTO_EXECUTION_LAB_MAX_QUOTE_AGE_SECONDS"),
        )
        stream_snapshot = (
            KALSHI_CRYPTO_STREAM.snapshot(ticker, max_age_seconds=max_age)
            if KALSHI_CRYPTO_STREAM
            else {}
        )
        kalshi = {
            **(fresh.get("kalshi_microstructure") or {}),
            **stream_snapshot,
        }
        contract_sizes = {
            1,
            3,
            5,
            max(1, setting_int(settings, "CRYPTO_EXECUTION_LAB_DEFAULT_CONTRACTS")),
            max(1, setting_int(settings, "CRYPTO_EXECUTION_LAB_CONFIRMED_CONTRACTS")),
        }
        depths = {"yes": {}, "no": {}}
        for side in ("yes", "no"):
            for contracts in contract_sizes:
                depths[side][str(contracts)] = kalshi_orderbook_depth_summary(
                    payload,
                    side,
                    required_contracts=contracts,
                )
        yes_depth = depths["yes"]["1"]
        no_depth = depths["no"]["1"]
        yes_entry = yes_depth.get("best_entry_price_cents")
        no_entry = no_depth.get("best_entry_price_cents")
        spread = (
            float(yes_entry) + float(no_entry) - 100.0
            if yes_entry is not None and no_entry is not None
            else 999.0
        )
        kalshi.update({
            "source": (stream_snapshot.get("source") or payload.get("source") or "production_fresh_book"),
            "fresh": True,
            "sequence_valid": bool(payload.get("sequence_valid", True)),
            "book_consistent": bool(
                yes_entry is not None
                and no_entry is not None
                and float(yes_entry) + float(no_entry) >= 100.0 - 1e-9
            ),
            "age_seconds": float(payload.get("age_seconds") or 0),
            "spread_yes_cents": round(spread, 4),
            "best_yes_entry_price_cents": yes_entry,
            "best_no_entry_price_cents": no_entry,
            "orderbook_fetched_at": fetched_at,
        })
        fresh["microstructure"] = {
            **(fresh.get("microstructure") or {}),
            "coinbase": coinbase,
            "kraken": kraken,
            "live_refreshed_at": iso_now(),
        }
        fresh["kalshi_microstructure"] = kalshi
        fresh["production_shadow_depth"] = depths
        fresh["yes_ask"] = yes_entry
        fresh["no_ask"] = no_entry
        fresh["market_quote_fetched_at"] = fetched_at
        close_time = parse_time(fresh.get("close_time"))
        if close_time:
            fresh["minutes_to_close"] = round(
                max(0.0, (close_time - utc_now()).total_seconds() / 60.0),
                4,
            )
        fresh["data_quality"] = data_quality_metrics(
            fresh["microstructure"],
            kalshi,
            maximum_age_seconds=setting_float(
                settings,
                "CRYPTO_15M_DATA_QUALITY_MAX_AGE_SECONDS",
            ),
        )
        if independent:
            refresh_result = refresh_live_underlying_probability(settings, fresh, payload)
            if not refresh_result.get("ok"):
                fresh["probability_interval"] = {"interval_status": "fresh_probability_unavailable"}
            else:
                fresh["probability_interval"] = candidate_probability_interval(
                    settings, fresh.get("probability") or {}, fresh["data_quality"])
        snapshot_cache[ticker] = fresh
        return deepcopy(fresh)

    def confirm_fill(ticker, side, required_contracts):
        key = (str(ticker or ""), str(side or ""), int(required_contracts or 0))
        if key not in confirmation_cache or confirmation_reasons(confirmation_cache[key], maximum_age=0.5):
            try:
                if independent:
                    payload, fetched_at = fetch_fresh_kalshi_orderbook(settings, ticker, force_rest=True)
                else:
                    payload, fetched_at = fetch_fresh_kalshi_orderbook(settings, ticker)
                confirmation_cache[key] = {
                    **kalshi_orderbook_depth_summary(
                        payload,
                        side,
                        required_contracts=required_contracts,
                    ),
                    "fetched_at": fetched_at,
                    "book_revision": payload.get("book_revision"),
                    "sequence_valid": payload.get("sequence_valid", True),
                    "source": payload.get("source") or "kalshi_rest_orderbook",
                }
            except Exception as exc:
                confirmation_cache[key] = {
                    "ok": False,
                    "error": "production_shadow_confirmation_unavailable",
                    "message": safe_error_message(exc),
                    "fetched_at": iso_now(),
                }
        return {**confirmation_cache[key], "checked_at": utc_now().isoformat()}

    return {
        "fresh_snapshot": fresh_snapshot,
        "confirm_fill": confirm_fill,
    }


def prospective_research_store():
    global PROSPECTIVE_RESEARCH_STORE
    if PROSPECTIVE_RESEARCH_STORE is None:
        PROSPECTIVE_RESEARCH_STORE = ResearchStore("crypto_prospective_shadow.json")
    return PROSPECTIVE_RESEARCH_STORE


def run_prospective_research(settings, candidates):
    if not setting_bool(settings, "CRYPTO_PROSPECTIVE_SHADOW_ENABLED"):
        return {"mode": "disabled", "automatic_promotion": False}
    research_settings = {**settings, "CRYPTO_KALSHI_WS_MAX_AGE_SECONDS": "1",
                         "CRYPTO_EXECUTION_LAB_MAX_QUOTE_AGE_SECONDS": "1",
                         "CRYPTO_LIVE_UNDERLYING_REFRESH_ENABLED": "true",
                         "CRYPTO_LIVE_UNDERLYING_REQUIRE_FRESH": "true",
                         "CRYPTO_LIVE_UNDERLYING_MAX_AGE_SECONDS": "2"}
    runtime = build_execution_shadow_runtime(research_settings, independent=True)
    return prospective_research_store().scan(candidates, runtime["fresh_snapshot"],
        runtime["confirm_fill"], fetch_low_edge_shadow_market)


def prospective_brti_sink(settings, market, review, cf, book, history):
    if setting_bool(settings, "CRYPTO_PROSPECTIVE_SHADOW_ENABLED"):
        runtime = build_execution_shadow_runtime(settings, independent=True)
        prospective_research_store().brti_tick(market, review, cf, book, history, runtime["confirm_fill"])


def run_execution_lab_shadow(settings, candidates, runtime=None):
    """Run prospective strategies against the production quote/depth pipeline."""
    if not setting_bool(settings, "CRYPTO_EXECUTION_LAB_SHADOW_ENABLED"):
        return {
            "version": EXECUTION_LAB_SHADOW_VERSION,
            "mode": "disabled",
            "affects_execution": False,
            "automatic_promotion": False,
            "lanes": [],
        }
    ledger = normalize_execution_lab_ledger(
        read_json(
            CRYPTO_EXECUTION_LAB_SHADOW_FILE,
            empty_execution_lab_ledger(settings),
        ),
        settings,
    )
    settled = settle_execution_lab_records(
        ledger,
        fetch_low_edge_shadow_market,
        settings,
    )
    runtime = runtime or build_execution_shadow_runtime(settings)
    fresh_snapshot = runtime["fresh_snapshot"]
    confirm_fill = runtime["confirm_fill"]

    added, attempts = capture_execution_lab_candidates(
        ledger,
        candidates,
        fresh_snapshot,
        confirm_fill,
        settings,
    )
    write_json(CRYPTO_EXECUTION_LAB_SHADOW_FILE, ledger)
    for row in attempts:
        log_line(
            "CRYPTO EXECUTION LAB ATTEMPT: "
            f"lane={row.get('lane')} {str(row.get('side') or '').upper()} "
            f"{row.get('asset')} {row.get('ticker')} "
            f"signal={float(row.get('signal_entry_price_cents') or 0):.1f}c "
            f"confirmed={float(row.get('confirmed_entry_price_cents') or 0):.1f}c "
            f"status={row.get('status')} reason={row.get('reason')}"
        )
        event_line({"type": "crypto_execution_lab_attempt", "shadow": row})
    for row in settled:
        arm = row.get("arm") or {}
        log_line(
            "CRYPTO EXECUTION LAB SETTLED: "
            f"lane={row.get('lane')} {row.get('asset')} {row.get('ticker')} "
            f"result={arm.get('result')} profit=${float(arm.get('virtual_profit') or 0):.4f}"
        )
        event_line({"type": "crypto_execution_lab_settled", "shadow": row})
    summary = summarize_execution_lab(ledger, settings)
    summary["captured_this_scan"] = len(added)
    summary["attempts_this_scan"] = len(attempts)
    summary["settled_this_scan"] = len(settled)
    return summary


