def persist_signal_live_pipeline_parity(
    settings,
    candidate,
    quote_refresh,
    live_order=None,
):
    """Stamp the matching shadow row with the exact promoted live decision."""
    if not is_spot_flow_live_pilot_candidate(candidate):
        return None
    ledger = normalize_signal_tournament_ledger(
        read_json(
            CRYPTO_SIGNAL_TOURNAMENT_FILE,
            empty_signal_tournament_ledger(settings),
        ),
        settings,
    )
    updated = apply_signal_live_pipeline_parity(
        ledger,
        candidate,
        quote_refresh,
        live_order=live_order,
        settings=settings,
    )
    if updated is not None:
        write_json(CRYPTO_SIGNAL_TOURNAMENT_FILE, ledger)
    return updated


