def run_crypto_cycle_shadow(settings, candidates):
    state = read_json(
        CRYPTO_CYCLE_SHADOW_FILE,
        empty_cycle_shadow_state(settings),
    )
    prior_discovery_status = {
        str(row.get("id") or ""): str(row.get("status") or "")
        for row in state.get("edge_discovery_records") or []
    }
    state, summary, added, settled, cycles = run_cycle_shadow_scan(
        state,
        candidates,
        fetch_low_edge_shadow_market,
        settings=settings,
    )
    write_json(CRYPTO_CYCLE_SHADOW_FILE, state)
    for row in added:
        log_line(
            f"CRYPTO V6 SHADOW CAPTURED: Bot {row.get('bot_number')} "
            f"episode={row.get('cycle_number')} attempt={row.get('attempt')} "
            f"lane={row.get('lane')} type={row.get('attempt_type')} {str(row.get('side') or '').upper()} "
            f"{row.get('asset')} {row.get('ticker')} cost=${float(row.get('total_cost_dollars') or 0):.2f}"
        )
        event_line({"type": "crypto_cycle_shadow_captured", "shadow": row})
    for row in settled:
        log_line(
            f"CRYPTO V6 SHADOW SETTLED: Bot {row.get('bot_number')} "
            f"episode={row.get('cycle_number')} attempt={row.get('attempt')} "
            f"{row.get('result')} {row.get('ticker')} "
            f"profit=${float(row.get('virtual_profit') or 0):.2f}"
        )
        event_line({"type": "crypto_cycle_shadow_settled", "shadow": row})
    for row in cycles:
        log_line(
            f"CRYPTO V6 SHADOW EPISODE: Bot {row.get('bot_number')} "
            f"episode={row.get('cycle_number')} outcome={row.get('outcome')} "
            f"attempts={row.get('attempts')} profit=${float(row.get('profit') or 0):.2f}"
        )
        event_line({"type": "crypto_cycle_shadow_cycle_resolved", "shadow": row})
    for row in state.get("edge_discovery_records") or []:
        record_id = str(row.get("id") or "")
        prior_status = prior_discovery_status.get(record_id)
        if prior_status is None:
            decomposition = row.get("edge_decomposition") or {}
            log_line(
                f"CRYPTO POSITIVE EDGE SHADOW CAPTURED: {str(row.get('side') or '').upper()} "
                f"{row.get('asset')} {row.get('ticker')} entry={float(row.get('entry_price_cents') or 0):.1f}c "
                f"raw_edge={float(decomposition.get('raw_model_edge_cents') or 0):.2f}c "
                f"edge_low={float(decomposition.get('raw_model_edge_low_cents') or 0):.2f}c "
                f"anchored_edge={float(decomposition.get('market_anchored_edge_cents') or 0):.2f}c"
            )
            event_line({"type": "crypto_positive_edge_shadow_captured", "shadow": row})
        elif prior_status == "open" and row.get("status") == "settled":
            log_line(
                f"CRYPTO POSITIVE EDGE SHADOW SETTLED: {row.get('result')} {row.get('ticker')} "
                f"raw_taker_profit=${float(row.get('raw_model_taker_profit') or 0):.2f}"
            )
            event_line({"type": "crypto_positive_edge_shadow_settled", "shadow": row})
    return summary


def configure_settlement_lag_shadow(settings, markets):
    """Start/update the read-only BRTI worker without touching live decisions."""
    global SETTLEMENT_LAG_SHADOW_WORKER
    enabled = setting_bool(settings, "CRYPTO_SETTLEMENT_LAG_SHADOW_ENABLED")
    if not enabled:
        return {
            "version": "btc-settlement-lag-shadow-v1",
            "mode": "disabled",
            "affects_execution": False,
            "automatic_promotion": False,
        }
    stream = KALSHI_CRYPTO_STREAM
    if stream is None:
        return {
            "version": "btc-settlement-lag-shadow-v1",
            "mode": "paper_shadow_only",
            "affects_execution": False,
            "health": {"status": "waiting_for_kalshi_stream"},
        }
    selected = []
    for market in markets or []:
        if infer_asset(market) != "BTC" or market_lane(market) != "crypto_15m":
            continue
        kind = market_kind(market)
        target, _cap = market_strikes(market)
        close_time = parse_time(market.get("close_time"))
        if kind not in {"above", "below"} or target is None or not close_time:
            continue
        selected.append({
            "ticker": market.get("ticker"),
            "close_time": close_time.isoformat(),
            "target": float(target),
            "market_kind": kind,
            "series_ticker": market_series_ticker(market),
            "fee_schedule": kalshi_series_fee_schedule(
                settings,
                market_series_ticker(market),
            ),
        })
    if SETTLEMENT_LAG_SHADOW_WORKER is None:
        if setting_bool(settings, "CRYPTO_PROSPECTIVE_SHADOW_ENABLED"):
            prospective_research_store()
        SETTLEMENT_LAG_SHADOW_WORKER = SettlementLagShadowWorker(
            CRYPTO_SETTLEMENT_LAG_SHADOW_FILE,
            fetch_market=fetch_low_edge_shadow_market,
            logger=log_line,
            event_logger=event_line,
            research_sink=lambda market, review, cf, book, history: prospective_brti_sink(
                settings, market, review, cf, book, history),
        )
    stream.replace_cfbenchmark_snapshot_tickers(
        [market.get("ticker") for market in selected]
    )
    SETTLEMENT_LAG_SHADOW_WORKER.configure(
        stream=stream,
        markets=selected,
        settings=settings,
    )
    SETTLEMENT_LAG_SHADOW_WORKER.start()
    payload = read_json(CRYPTO_SETTLEMENT_LAG_SHADOW_FILE, {})
    summary = dict(payload.get("summary") or {})
    if not summary:
        summary = {
            "version": "btc-settlement-lag-shadow-v1",
            "mode": "paper_shadow_only",
            "affects_execution": False,
            "automatic_promotion": False,
            "health": {
                "status": "starting",
                **SETTLEMENT_LAG_SHADOW_WORKER.status(),
            },
        }
    return summary


