def profit_per_staked_dollar(price_cents):
    try:
        price = float(price_cents or 0)
    except (TypeError, ValueError):
        return 0.0
    return (100.0 / price) - 1.0 if 0 < price < 100 else 0.0


def local_date_key(value=None):
    parsed = parse_time(value) if value else datetime.now().astimezone()
    if not parsed:
        return datetime.now().astimezone().date().isoformat()
    if parsed.tzinfo:
        parsed = parsed.astimezone()
    return parsed.date().isoformat()


def active_daily_reset_cutoff():
    reset = read_json(DAILY_RESET_FILE, {})
    if reset.get("local_date") != local_date_key():
        return None
    strategies = {
        str(value).strip().lower()
        for value in (reset.get("strategies") or [])
        if str(value).strip()
    }
    if strategies and "crypto" not in strategies:
        return None
    return parse_time(reset.get("reset_at"))


def is_after_daily_reset(value):
    cutoff = active_daily_reset_cutoff()
    if not cutoff or not value:
        return True
    parsed = parse_time(value)
    # A reset is scoped to its local calendar day.  It must not hide earlier
    # days from historical accounting or deterministic replay tests.
    if parsed and local_date_key(parsed) != local_date_key(cutoff):
        return True
    return not parsed or parsed > cutoff


def crypto_15m_bot_capacity_reset_cutoff(portfolio, bot_number):
    """Return the latest manual daily-capacity reset for one campaign lane."""
    resets = (portfolio or {}).get("crypto_15m_daily_capacity_resets") or {}
    entry = resets.get(str(crypto_campaign_bot_number({"bot_number": bot_number})))
    if isinstance(entry, dict):
        entry = entry.get("reset_at")
    return parse_time(entry)


def crypto_15m_daily_capacity_includes(portfolio, bot_number, value):
    """Apply both the global daily reset and an optional per-bot reset."""
    if not is_after_daily_reset(value):
        return False
    cutoff = crypto_15m_bot_capacity_reset_cutoff(portfolio, bot_number)
    if not cutoff or not value:
        return True
    parsed = parse_time(value)
    if not parsed:
        return True
    if cutoff.tzinfo is None:
        cutoff = cutoff.replace(tzinfo=timezone.utc)
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed > cutoff


def crypto_analytics_included(bet, settings=None):
    if is_user_crypto_bet(bet):
        return False
    settings = settings or load_settings()
    minimum = setting_float(settings, "CRYPTO_ANALYTICS_MIN_ENTRY_PRICE_CENTS")
    try:
        return float(bet.get("entry_price") or 0) >= minimum
    except (TypeError, ValueError):
        return False


def money(value):
    try:
        return round(float(value or 0), 2)
    except (TypeError, ValueError):
        return 0.0


def load_crypto_phase_two_state():
    return read_json(PHASE_TWO_STATE_FILE, {})


def save_crypto_phase_two_state(state):
    write_json(PHASE_TWO_STATE_FILE, state)


def is_crypto_phase_two_bet(bet, settings=None):
    if not crypto_analytics_included(bet, settings=settings):
        return False
    phase = bet.get("phase_two") or {}
    return bool(phase.get("active") or phase.get("attempt_id") or bet.get("phase_two_attempt_id"))


def crypto_phase_two_daily_rows(portfolio, date_key=None, include_open=True):
    date_key = date_key or local_date_key()
    sources = list(portfolio.get("bets", []))
    sources.extend(portfolio.get("history", []))
    rows = []
    seen = set()
    reset_cutoff = active_daily_reset_cutoff()
    for bet in sources:
        bet_id = bet.get("id") or f"{bet.get('ticker')}:{bet.get('placed_at')}:{bet.get('stake')}"
        if bet_id in seen or not is_crypto_phase_two_bet(bet):
            continue
        seen.add(bet_id)
        if not include_open and bet.get("status") == "open":
            continue
        stamp = (bet.get("settled_at") or bet.get("closed_at")) if bet.get("status") == "settled" else bet.get("placed_at")
        if local_date_key(stamp) != date_key:
            continue
        parsed = parse_time(stamp)
        if bet.get("status") == "settled" and reset_cutoff and parsed and parsed <= reset_cutoff:
            continue
        rows.append(bet)
    return rows


def crypto_phase_two_cycle_target(base_target, cycle_number, settings):
    decay = setting_float(settings, "CRYPTO_PHASE_TWO_CYCLE_DECAY") or 0.5
    min_target = setting_float(settings, "CRYPTO_PHASE_TWO_MIN_CYCLE_TARGET")
    target = float(base_target or 0) * (decay ** max(0, int(cycle_number or 1) - 1))
    return money(max(min_target, target))


def crypto_phase_two_cycle_summary(rows, base_target, settings):
    max_cycles = max(1, setting_int(settings, "CRYPTO_PHASE_TWO_MAX_CYCLES"))
    cycles = []
    current_cycle = 1
    completed_cycles = 0
    for cycle_number in range(1, max_cycles + 1):
        cycle_rows = [
            row for row in rows
            if int((row.get("phase_two") or {}).get("cycle") or row.get("phase_two_cycle") or 1) == cycle_number
        ]
        open_count = sum(1 for row in cycle_rows if row.get("status") == "open")
        settled = [row for row in cycle_rows if row.get("status") == "settled"]
        wins = sum(1 for row in settled if row.get("result") == "WIN")
        losses = sum(1 for row in settled if row.get("result") == "LOSS")
        profit = money(sum(money(row.get("profit")) for row in settled))
        target = crypto_phase_two_cycle_target(base_target, cycle_number, settings)
        target_hit = target > 0 and profit >= target
        complete = open_count == 0 and bool(target_hit or wins > 0)
        cycles.append({
            "cycle": cycle_number,
            "target": target,
            "target_remaining": money(max(0.0, target - profit)),
            "attempts": len(cycle_rows),
            "open": open_count,
            "wins": wins,
            "losses": losses,
            "profit": profit,
            "target_hit": target_hit,
            "complete": complete,
        })
        if complete:
            completed_cycles = cycle_number
            current_cycle = min(max_cycles + 1, cycle_number + 1)
        else:
            current_cycle = cycle_number
            break
    return cycles, current_cycle, completed_cycles


def open_crypto_phase_two_bet(portfolio):
    for bet in open_bets(portfolio):
        if is_crypto_phase_two_bet(bet):
            return bet
    return None


def crypto_phase_two_context(settings, portfolio):
    enabled = setting_bool(settings, "CRYPTO_PHASE_TWO_ENABLED")
    date_key = local_date_key()
    state = load_crypto_phase_two_state()
    if state.get("date") != date_key:
        state = {"date": date_key, "events": []}

    bankroll_base = live_bankroll_for_sizing(settings, portfolio) if execution_mode(settings) == "live" else float(portfolio.get("balance") or 0)
    base_target = max(setting_float(settings, "CRYPTO_PHASE_TWO_DAILY_TARGET_MIN"), bankroll_base * setting_float(settings, "CRYPTO_PHASE_TWO_DAILY_TARGET_PCT"))
    max_target = setting_float(settings, "CRYPTO_PHASE_TWO_DAILY_TARGET_MAX")
    if max_target > 0:
        base_target = min(base_target, max_target)
    base_target = money(base_target)

    rows = crypto_phase_two_daily_rows(portfolio, date_key=date_key)
    cycles, current_cycle, completed_cycles = crypto_phase_two_cycle_summary(rows, base_target, settings)
    max_cycles = max(1, setting_int(settings, "CRYPTO_PHASE_TWO_MAX_CYCLES"))
    current_summary = cycles[min(current_cycle, max_cycles) - 1] if cycles else {}
    open_bet = open_crypto_phase_two_bet(portfolio)
    cycle_attempts = int(current_summary.get("attempts") or 0)
    max_attempts = max(1, setting_int(settings, "CRYPTO_PHASE_TWO_MAX_ATTEMPTS"))
    target_remaining = money(current_summary.get("target_remaining"))

    shared_state = build_shared_bankroll_state(save=True) if build_shared_bankroll_state and execution_mode(settings) == "live" else {}
    shared_cycle = (shared_state.get("cycle_coordination") or {}) if shared_state else {}
    shared_cycle_active = bool(shared_cycle.get("enabled"))
    shared_cycle_owner = shared_cycle.get("owner")
    if shared_cycle_active:
        current_cycle = int(shared_cycle.get("current_cycle") or current_cycle)
        completed_cycles = int(shared_cycle.get("completed_cycles") or 0)
        current_summary = {
            "target": money(shared_cycle.get("target")),
            "target_remaining": money(shared_cycle.get("target_remaining")),
            "profit": money(shared_cycle.get("positive_profit")),
        }
        cycle_rows = [
            row for row in rows
            if int((row.get("phase_two") or {}).get("cycle") or row.get("phase_two_cycle") or 1) == current_cycle
        ]
        cycle_attempts = len(cycle_rows)
        target_remaining = money(shared_cycle.get("target_remaining"))

    status = "active"
    reason = "ready"
    if not enabled:
        status = "disabled"
        reason = "crypto_phase_two_disabled"
    elif shared_cycle_active and shared_cycle.get("status") == "complete":
        status = "complete"
        reason = "shared_cycle_plan_complete"
    elif shared_cycle_active and shared_cycle_owner and shared_cycle_owner != "crypto":
        status = "pending"
        reason = f"shared_phase_two_owned_by_{shared_cycle_owner}"
    elif current_cycle > max_cycles:
        status = "complete"
        reason = "crypto_phase_two_cycles_complete"
    elif open_bet and setting_bool(settings, "CRYPTO_PHASE_TWO_WAIT_FOR_SETTLEMENT"):
        status = "pending"
        reason = "crypto_phase_two_open_bet_pending"
    elif cycle_attempts >= max_attempts and target_remaining > 0:
        status = "limited"
        reason = "crypto_phase_two_max_attempts_hit"

    context = {
        "date": date_key,
        "enabled": enabled,
        "status": status,
        "reason": reason,
        "bankroll_base": money(bankroll_base),
        "base_target": base_target,
        "current_cycle": current_cycle,
        "max_cycles": max_cycles,
        "completed_cycles": completed_cycles,
        "target": money(current_summary.get("target")),
        "target_remaining": target_remaining,
        "realized_profit": money(sum(money(row.get("profit")) for row in rows if row.get("status") == "settled")),
        "current_cycle_profit": money(current_summary.get("profit")),
        "attempts": len(rows),
        "cycle_attempts": cycle_attempts,
        "max_attempts": max_attempts,
        "cycles": cycles,
        "open_bet": {
            "id": open_bet.get("id"),
            "ticker": open_bet.get("ticker"),
            "stake": open_bet.get("stake"),
            "placed_at": open_bet.get("placed_at"),
        } if open_bet else None,
        "shared_cycle_coordination": shared_cycle,
    }
    state.update({key: context[key] for key in ("date", "status", "reason", "current_cycle", "completed_cycles", "target", "target_remaining", "realized_profit")})
    state.setdefault("events", [])
    save_crypto_phase_two_state(state)
    return context


def crypto_phase_two_skip_reason(settings, candidate, context):
    if not context or not context.get("enabled"):
        return "crypto_phase_two_disabled"
    if context.get("status") != "active":
        return context.get("reason") or "crypto_phase_two_not_active"
    edge = float(candidate.get("edge") or 0)
    confidence = float(candidate.get("confidence") or 0)
    if edge < setting_float(settings, "CRYPTO_PHASE_TWO_MIN_EDGE"):
        return "crypto_phase_two_edge_filter"
    if confidence < setting_float(settings, "CRYPTO_PHASE_TWO_MIN_CONFIDENCE"):
        return "crypto_phase_two_confidence_filter"
    if profit_per_staked_dollar(candidate.get("entry_price")) <= 0:
        return "crypto_phase_two_bad_entry_price"
    return ""


def apply_crypto_phase_two_staking(settings, portfolio, candidate, stake, balance, context):
    reason = crypto_phase_two_skip_reason(settings, candidate, context)
    if reason:
        candidate["phase_two_skip_reason"] = reason
        return stake
    profit_per_dollar = profit_per_staked_dollar(candidate.get("entry_price"))
    target_stake = money(float(context.get("target_remaining") or 0) / profit_per_dollar)
    base_stake = max(stake, balance * setting_float(settings, "CRYPTO_PHASE_TWO_BASE_STAKE_PCT"), setting_float(settings, "CRYPTO_PHASE_TWO_BASE_STAKE_MIN"))
    max_stake = min(
        balance * setting_float(settings, "CRYPTO_PHASE_TWO_MAX_STAKE_PCT"),
        setting_float(settings, "CRYPTO_PHASE_TWO_MAX_STAKE_CAP"),
        setting_float(settings, "CRYPTO_LIVE_MAX_STAKE") or setting_float(settings, "CRYPTO_MAX_STAKE"),
    )
    adjusted = money(min(max(base_stake, target_stake), max_stake, balance))
    if adjusted <= 0:
        candidate["phase_two_skip_reason"] = "crypto_phase_two_no_stake_available"
        return stake
    attempt_id = str(uuid.uuid4())
    phase = {
        "active": True,
        "attempt_id": attempt_id,
        "date": context.get("date"),
        "cycle": context.get("current_cycle"),
        "max_cycles": context.get("max_cycles"),
        "cycle_attempt": int(context.get("cycle_attempts") or 0) + 1,
        "max_attempts": context.get("max_attempts"),
        "target": context.get("target"),
        "target_remaining": context.get("target_remaining"),
        "base_stake": money(stake),
        "target_stake_raw": target_stake,
        "applied_stake": adjusted,
        "profit_per_staked_dollar": round(profit_per_dollar, 4),
    }
    candidate["phase_two"] = phase
    candidate["phase_two_attempt_id"] = attempt_id
    candidate["phase_two_cycle"] = phase["cycle"]
    candidate["strategy_owner"] = "phase_two_cycle"
    return adjusted


def crypto_strategy_owner(row):
    if is_patient_candidate(row):
        return PATIENT_OWNER
    if is_spot_flow_live_pilot_candidate(row):
        return CRYPTO_SPOT_FLOW_LIVE_PILOT_OWNER
    if (row.get("multi_market") or {}).get("active"):
        return str((row.get("multi_market") or {}).get("owner") or "multi_market")
    if (row.get("crypto_live_campaign") or {}).get("enabled") or row.get("strategy_owner") == CRYPTO_15M_CAMPAIGN_OWNER:
        return CRYPTO_15M_CAMPAIGN_OWNER
    if (row.get("live_core") or {}).get("active"):
        return "live_core"
    if (row.get("phase_two") or {}).get("active") or row.get("phase_two_attempt_id"):
        return "phase_two_cycle"
    if (row.get("small_edge") or {}).get("active"):
        return "small_edge"
    if (row.get("shared_recovery") or {}).get("active"):
        return "shared_recovery"
    if (row.get("selective_edge") or {}).get("active"):
        return "selective_edge"
    return row.get("strategy_owner") or "edge_scanner"


def open_exposure_by_owner(portfolio, owner):
    return money(sum(money(bet.get("stake")) for bet in open_bets(portfolio) if crypto_strategy_owner(bet) == owner))


def apply_crypto_small_edge_staking(settings, portfolio, candidate, stake, balance, phase_two_context):
    if not setting_bool(settings, "CRYPTO_SMALL_EDGE_DURING_PHASE_TWO_ENABLED"):
        return stake
    if (candidate.get("phase_two") or {}).get("active"):
        return stake
    if not phase_two_context or not phase_two_context.get("enabled") or phase_two_context.get("status") not in {"active", "pending", "limited"}:
        return stake
    cap_pct = setting_float(settings, "CRYPTO_SMALL_EDGE_PHASE_TWO_EXPOSURE_PCT")
    exposure_cap = money(balance * cap_pct) if cap_pct > 0 else 0.0
    open_small_edge = open_exposure_by_owner(portfolio, "small_edge")
    remaining = money(max(0.0, exposure_cap - open_small_edge)) if exposure_cap > 0 else balance
    selective_tier = str((candidate.get("selective_edge") or {}).get("tier") or "normal")
    if selective_tier == "elite_edge":
        support_cap = setting_float(settings, "CRYPTO_PHASE_TWO_SUPPORT_ELITE_MAX_STAKE")
    elif selective_tier == "strong_edge":
        support_cap = setting_float(settings, "CRYPTO_PHASE_TWO_SUPPORT_STRONG_MAX_STAKE")
    else:
        support_cap = setting_float(settings, "CRYPTO_PHASE_TWO_SUPPORT_NORMAL_MAX_STAKE")
    max_stake = min(support_cap, remaining, balance)
    adjusted = money(min(stake, max_stake))
    if adjusted < setting_float(settings, "CRYPTO_MIN_STAKE"):
        candidate["small_edge"] = {
            "active": False,
            "reason": "crypto_small_edge_phase_cap",
            "open_exposure": open_small_edge,
            "exposure_cap": exposure_cap,
            "remaining": remaining,
        }
        return 0.0
    candidate["small_edge"] = {
        "active": True,
        "reason": "phase_two_small_edge",
        "base_stake": money((candidate.get("selective_edge") or {}).get("base_stake") or stake),
        "applied_stake": adjusted,
        "support_tier": selective_tier,
        "support_cap": money(support_cap),
        "open_exposure": open_small_edge,
        "exposure_cap": exposure_cap,
        "remaining_before": remaining,
        "phase_two_status": phase_two_context.get("status"),
        "phase_two_cycle": phase_two_context.get("current_cycle"),
    }
    candidate["strategy_owner"] = "small_edge"
    return adjusted


def record_crypto_phase_two_placement(bet):
    if not is_crypto_phase_two_bet(bet):
        return
    state = load_crypto_phase_two_state()
    state.setdefault("date", local_date_key())
    events = state.setdefault("events", [])
    events.append({
        "type": "phase_two_placement",
        "ts": iso_now(),
        "bet_id": bet.get("id"),
        "ticker": bet.get("ticker"),
        "mode": bet.get("mode"),
        "stake": bet.get("stake"),
        "cycle": (bet.get("phase_two") or {}).get("cycle"),
        "attempt_id": bet.get("phase_two_attempt_id") or (bet.get("phase_two") or {}).get("attempt_id"),
    })
    state["events"] = events[-200:]
    save_crypto_phase_two_state(state)


def _execution_number(value, default=None):
    try:
        return float(value)
    except (TypeError, ValueError):
        return default


def build_execution_quality_record(candidate, outcome, live_order=None, reason="", settings=None):
    """Normalize quote-to-fill quality without changing execution decisions."""
    candidate = candidate or {}
    live_order = live_order or {}
    origin = candidate.get("execution_quote_origin") or {}
    refresh = candidate.get("live_quote_refresh") or {}
    underlying_refresh = candidate.get("live_underlying_refresh") or {}
    depth = live_order.get("liquidity_preflight") or refresh or {}
    initial_price = _execution_number(
        origin.get("price_cents"),
        _execution_number(refresh.get("original_price_cents"), _execution_number(candidate.get("entry_price"))),
    )
    refreshed_price = _execution_number(
        refresh.get("refreshed_price_cents"),
        _execution_number(live_order.get("price"), _execution_number(candidate.get("entry_price"))),
    )
    fill_price = _execution_number(
        live_order.get("accounting_fill_price_cents"),
        _execution_number(live_order.get("executed_price")),
    )
    if fill_price is None and live_order.get("response"):
        parsed_fill = order_entry_price_cents(
            live_order.get("response") or {},
            outcome_side=candidate.get("side"),
        )
        fill_price = parsed_fill if parsed_fill > 0 else None
    contracts = _execution_number(live_order.get("contracts"), 0.0) or 0.0
    actual_fee = order_fill_fee(live_order.get("response") or {}) if live_order.get("response") else 0.0
    settings = settings or DEFAULT_SETTINGS
    actual_fee_drag = (
        actual_fee / contracts * 100.0
        if actual_fee > 0 and contracts > 0
        else (
            estimated_taker_fee_per_contract(
                fill_price,
                setting_float(settings, "CRYPTO_SHADOW_FEE_RATE"),
            ) * 100.0
            if fill_price is not None
            else None
        )
    )
    side_probability = _execution_number(candidate_side_probability(candidate))
    post_fill_edge = (
        side_probability - fill_price - actual_fee_drag
        if side_probability is not None and fill_price is not None and actual_fee_drag is not None
        else None
    )
    original_edge = _execution_number(origin.get("net_edge"), _execution_number(refresh.get("original_net_edge")))
    refreshed_edge = _execution_number(refresh.get("refreshed_net_edge"), _execution_number(candidate.get("edge")))
    initial_to_refresh = (
        refreshed_price - initial_price
        if refreshed_price is not None and initial_price is not None
        else None
    )
    refresh_to_fill = (
        fill_price - refreshed_price
        if fill_price is not None and refreshed_price is not None
        else None
    )
    total_slippage = (
        fill_price - initial_price
        if fill_price is not None and initial_price is not None
        else None
    )
    available = _execution_number(depth.get("available_contracts"))
    required = _execution_number(depth.get("required_contracts"))
    shortfall = _execution_number(depth.get("depth_shortfall_contracts"))
    if shortfall is None and available is not None and required is not None:
        shortfall = max(0.0, required - available)
    unit_downshift = (
        live_order.get("unit_depth_downshift")
        or candidate.get("live_unit_depth_downshift")
        or refresh.get("unit_depth_downshift")
        or {}
    )
    unit_accounting = (
        live_order.get("unit_accounting")
        or candidate.get("live_unit_accounting")
        or {}
    )
    model_selected_units = _execution_number(
        unit_accounting.get("model_selected_units"),
        _execution_number(unit_downshift.get("original_units")),
    )
    executed_units = _execution_number(
        unit_accounting.get("executed_units"),
        _execution_number(unit_downshift.get("applied_units")),
    )
    unit_execution_downshifted = bool(
        unit_downshift.get("active")
        or unit_accounting.get("downshifted_after_sizing")
    )
    record = {
        "id": str(uuid.uuid4()),
        "captured_at": iso_now(),
        "outcome": str(outcome or "unknown"),
        "reason": str(reason or live_order.get("error") or refresh.get("error") or ""),
        "asset": candidate.get("asset"),
        "ticker": candidate.get("ticker"),
        "market_lane": candidate.get("market_lane"),
        "side": candidate.get("side"),
        "bot_number": (candidate.get("crypto_live_campaign") or {}).get("bot_number") or candidate.get("bot_number"),
        "minutes_to_close": _execution_number(candidate.get("minutes_to_close")),
        "initial_quote_cents": round(initial_price, 4) if initial_price is not None else None,
        "refreshed_quote_cents": round(refreshed_price, 4) if refreshed_price is not None else None,
        "fill_price_cents": round(fill_price, 4) if fill_price is not None else None,
        "initial_to_refresh_slippage_cents": round(initial_to_refresh, 4) if initial_to_refresh is not None else None,
        "refresh_to_fill_slippage_cents": round(refresh_to_fill, 4) if refresh_to_fill is not None else None,
        "total_slippage_cents": round(total_slippage, 4) if total_slippage is not None else None,
        "price_improvement_cents": (
            round(refreshed_price - fill_price, 4)
            if fill_price is not None and refreshed_price is not None
            else None
        ),
        "quote_age_seconds": _execution_number(refresh.get("quote_age_seconds")),
        "refresh_age_at_attempt_seconds": live_quote_refresh_age_seconds(refresh),
        "underlying_book_age_seconds": _execution_number(
            underlying_refresh.get("book_age_seconds")
        ),
        "underlying_move_bps": _execution_number(
            underlying_refresh.get("underlying_move_bps")
        ),
        "underlying_probability_move_pp": (
            round(
                float(underlying_refresh.get("fresh_model_prob_yes"))
                - float(underlying_refresh.get("old_model_prob_yes")),
                4,
            )
            if underlying_refresh.get("fresh_model_prob_yes") is not None
            and underlying_refresh.get("old_model_prob_yes") is not None
            else None
        ),
        "required_contracts": required,
        "available_contracts": available,
        "depth_shortfall_contracts": round(shortfall, 4) if shortfall is not None else None,
        "best_entry_price_cents": _execution_number(depth.get("best_entry_price_cents")),
        "full_size_entry_price_cents": _execution_number(depth.get("full_size_entry_price_cents")),
        "requested_stake": _execution_number(live_order.get("requested_stake")),
        "actual_stake": _execution_number(live_order.get("actual_stake")),
        "contracts": contracts,
        "unit_depth_downshifted": bool(unit_downshift.get("active")),
        "unit_execution_downshifted": unit_execution_downshifted,
        "model_selected_units": model_selected_units,
        "executed_units": executed_units,
        "unit_downshift_trigger": (
            unit_downshift.get("trigger")
            or ("post_sizing_cap_or_fill" if unit_accounting.get("downshifted_after_sizing") else None)
        ),
        "fill_ratio": (
            round(contracts / required, 4)
            if required and required > 0
            else None
        ),
        "model_side_probability": round(side_probability, 4) if side_probability is not None else None,
        "original_net_edge": round(original_edge, 4) if original_edge is not None else None,
        "refreshed_net_edge": round(refreshed_edge, 4) if refreshed_edge is not None else None,
        "actual_fee_edge_pp": round(actual_fee_drag, 4) if actual_fee_drag is not None else None,
        "post_fill_net_edge": round(post_fill_edge, 4) if post_fill_edge is not None else None,
        "edge_retained_pp": (
            round(post_fill_edge - original_edge, 4)
            if post_fill_edge is not None and original_edge is not None
            else None
        ),
        "fok_retry_attempted": bool((live_order.get("fok_retry") or {}).get("attempted")),
    }
    return record


def persist_execution_quality_record(settings, record):
    state = read_json(
        CRYPTO_EXECUTION_QUALITY_FILE,
        {"version": "crypto-execution-quality-v1", "records": []},
    )
    records = list(state.get("records") or [])
    records.append(dict(record or {}))
    retention_days = max(1, setting_int(settings, "CRYPTO_EXECUTION_QUALITY_RETENTION_DAYS"))
    cutoff = utc_now() - timedelta(days=retention_days)
    records = [
        row for row in records
        if not parse_time(row.get("captured_at")) or parse_time(row.get("captured_at")) >= cutoff
    ]
    maximum = max(100, setting_int(settings, "CRYPTO_EXECUTION_QUALITY_MAX_RECORDS"))
    state.update({
        "version": "crypto-execution-quality-v1",
        "updated_at": iso_now(),
        "records": records[-maximum:],
    })
    write_json(CRYPTO_EXECUTION_QUALITY_FILE, state)


def _execution_average(rows, key):
    values = [_execution_number(row.get(key)) for row in rows]
    values = [value for value in values if value is not None]
    return round(sum(values) / len(values), 3) if values else None


def _execution_summary(rows):
    rows = list(rows or [])
    filled = [row for row in rows if row.get("outcome") == "filled"]
    quote_blocks = [row for row in rows if row.get("outcome") == "quote_rejected"]
    order_failures = [row for row in rows if row.get("outcome") == "order_failed"]
    return {
        "attempts": len(rows),
        "filled": len(filled),
        "quote_rejected": len(quote_blocks),
        "order_failed": len(order_failures),
        "fill_rate": round(len(filled) / len(rows) * 100.0, 1) if rows else 0.0,
        "price_improved_fills": sum(1 for row in filled if (_execution_number(row.get("price_improvement_cents"), 0.0) or 0.0) > 0),
        "depth_blocks": sum(1 for row in rows if "depth" in str(row.get("reason") or "")),
        "slippage_blocks": sum(1 for row in rows if "slippage" in str(row.get("reason") or "")),
        "average_quote_age_seconds": _execution_average(rows, "quote_age_seconds"),
        "average_initial_to_refresh_slippage_cents": _execution_average(rows, "initial_to_refresh_slippage_cents"),
        "average_refresh_to_fill_slippage_cents": _execution_average(filled, "refresh_to_fill_slippage_cents"),
        "average_total_slippage_cents": _execution_average(filled, "total_slippage_cents"),
        "average_price_improvement_cents": _execution_average(filled, "price_improvement_cents"),
        "average_post_fill_net_edge": _execution_average(filled, "post_fill_net_edge"),
        "average_edge_retained_pp": _execution_average(filled, "edge_retained_pp"),
    }


def execution_quality_analytics(records=None, now=None):
    if records is None:
        records = (read_json(CRYPTO_EXECUTION_QUALITY_FILE, {}) or {}).get("records") or []
    rows = list(records or [])
    now = now or utc_now()
    rows.sort(key=lambda row: str(row.get("captured_at") or ""), reverse=True)
    last_24h = [row for row in rows if parse_time(row.get("captured_at")) and parse_time(row.get("captured_at")) >= now - timedelta(hours=24)]
    last_7d = [row for row in rows if parse_time(row.get("captured_at")) and parse_time(row.get("captured_at")) >= now - timedelta(days=7)]

    def grouped(label_fn):
        groups = {}
        for row in rows:
            groups.setdefault(label_fn(row) or "unknown", []).append(row)
        result = []
        for label, group in groups.items():
            summary = _execution_summary(group)
            result.append({"label": label, **summary})
        return sorted(result, key=lambda row: (-row["attempts"], row["label"]))

    reason_counts = {}
    for row in rows:
        if row.get("outcome") == "filled":
            continue
        reason = str(row.get("reason") or "unknown")
        reason_counts[reason] = reason_counts.get(reason, 0) + 1
    return {
        "version": "crypto-execution-quality-v1",
        "summary": _execution_summary(rows),
        "last_24h": _execution_summary(last_24h),
        "last_7d": _execution_summary(last_7d),
        "by_asset": grouped(lambda row: row.get("asset") or "unknown"),
        "by_price_band": grouped(lambda row: price_band(row.get("initial_quote_cents"))),
        "failure_reasons": [
            {"label": label, "count": count}
            for label, count in sorted(reason_counts.items(), key=lambda item: (-item[1], item[0]))
        ],
        "recent": rows[:100],
    }


def price_band(value):
    return aligned_price_band(value)


def analytics_entry_price(row):
    live_order = row.get("live_order") or {}
    try:
        executed_price = float(live_order.get("executed_price") or 0)
    except (TypeError, ValueError):
        executed_price = 0.0
    if executed_price <= 0:
        executed_price = order_entry_price_cents(
            live_order.get("response") or {},
            outcome_side=row.get("side"),
        )
    return executed_price if executed_price > 0 else row.get("entry_price")


def edge_band(value):
    try:
        edge = float(value or 0)
    except (TypeError, ValueError):
        return "no_edge"
    if edge < 0:
        return "negative"
    if edge < 6:
        return "0-5%"
    if edge < 10:
        return "6-9%"
    if edge < 15:
        return "10-14%"
    if edge < 20:
        return "15-19%"
    return "20%+"


def confidence_band(value):
    try:
        confidence = float(value or 0)
    except (TypeError, ValueError):
        return "no_confidence"
    if confidence < 60:
        return "<60"
    if confidence < 70:
        return "60-69"
    if confidence < 80:
        return "70-79"
    if confidence < 90:
        return "80-89"
    return "90+"


def hours_to_close_band(row):
    hours = None
    probability = row.get("probability") or {}
    if probability.get("hours_to_close") is not None:
        try:
            hours = float(probability.get("hours_to_close"))
        except (TypeError, ValueError):
            hours = None
    if hours is None:
        close_time = parse_time(row.get("close_time"))
        if close_time:
            entry_time = parse_time(row.get("placed_at") or row.get("created_at")) or utc_now()
            if entry_time.tzinfo is None:
                entry_time = entry_time.replace(tzinfo=timezone.utc)
            if close_time.tzinfo is None:
                close_time = close_time.replace(tzinfo=timezone.utc)
            hours = (close_time - entry_time).total_seconds() / 3600.0
    if hours is None:
        return "unknown"
    if hours < 0:
        return "closed"
    if hours < 1:
        return "<1h"
    if hours < 4:
        return "1-4h"
    if hours < 12:
        return "4-12h"
    if hours < 24:
        return "12-24h"
    return "24h+"


def count_rows(rows, label_fn):
    counts = {}
    for row in rows:
        label = label_fn(row) or "unknown"
        counts[label] = counts.get(label, 0) + 1
    return [{"label": label, "count": count} for label, count in sorted(counts.items(), key=lambda item: (-item[1], item[0]))]


def candidate_group_rows(candidates, label_fn):
    groups = {}
    for row in candidates:
        label = label_fn(row) or "unknown"
        item = groups.setdefault(label, {"label": label, "count": 0, "eligible": 0, "skipped": 0, "placed": 0, "edge_sum": 0.0, "confidence_sum": 0.0})
        item["count"] += 1
        if row.get("decision") in {"placed", "placed_live"}:
            item["placed"] += 1
        elif row.get("skip_reasons"):
            item["skipped"] += 1
        else:
            item["eligible"] += 1
        item["edge_sum"] += float(row.get("edge") or 0)
        item["confidence_sum"] += float(row.get("confidence") or 0)
    result = []
    for item in groups.values():
        count = max(1, item["count"])
        result.append({
            "label": item["label"],
            "count": item["count"],
            "eligible": item["eligible"],
            "skipped": item["skipped"],
            "placed": item["placed"],
            "avg_edge": round(item["edge_sum"] / count, 2),
            "avg_confidence": round(item["confidence_sum"] / count, 1),
        })
    return sorted(result, key=lambda row: (-row["count"], row["label"]))


def bet_group_rows(bets, label_fn):
    groups = {}
    for bet in bets:
        label = label_fn(bet) or "unknown"
        item = groups.setdefault(label, {"label": label, "wins": 0, "losses": 0, "stake": 0.0, "profit": 0.0})
        item["wins"] += 1 if bet.get("result") == "WIN" else 0
        item["losses"] += 1 if bet.get("result") == "LOSS" else 0
        item["stake"] += float(bet.get("stake") or 0)
        item["profit"] += float(bet.get("profit") or 0)
    result = []
    for item in groups.values():
        settled = item["wins"] + item["losses"]
        stake = item["stake"]
        result.append({
            "label": item["label"],
            "wins": item["wins"],
            "losses": item["losses"],
            "settled": settled,
            "win_rate": round((item["wins"] / settled) * 100, 1) if settled else 0.0,
            "stake": round(stake, 2),
            "profit": round(item["profit"], 2),
            "roi": round((item["profit"] / stake) * 100, 1) if stake else 0.0,
        })
    return sorted(result, key=lambda row: (-row["settled"], row["profit"]))


def stake_band(row):
    stake = float(row.get("stake") or 0)
    if stake <= 0:
        return "$0"
    if stake < 2:
        return "<$2"
    if stake < 5:
        return "$2-$4"
    if stake < 10:
        return "$5-$9"
    if stake < 20:
        return "$10-$19"
    return "$20+"


def selective_tier(row):
    selective = row.get("selective_edge") or {}
    if selective.get("active"):
        return selective.get("tier") or "selective_edge"
    return "normal"


def recovery_tier(row):
    campaign = row.get("crypto_live_campaign") or {}
    if campaign:
        if campaign.get("role") == "support":
            return "campaign_support"
        try:
            prior_losses = int(campaign.get("consecutive_primary_losses") or 0)
        except (TypeError, ValueError):
            prior_losses = 0
        if prior_losses > 0:
            loss_label = "loss" if prior_losses == 1 else "losses"
            count_label = "3+" if prior_losses > 3 else str(prior_losses)
            return f"campaign_recovery_after_{count_label}_{loss_label}"
        return "campaign_base"
    recovery = row.get("shared_recovery") or {}
    if recovery.get("active"):
        return "shared_recovery"
    reason = recovery.get("reason")
    return reason or "normal"


def strategy_owner_label(row):
    return crypto_strategy_owner(row)


def campaign_bot_label(row):
    if row.get("strategy_owner") != CRYPTO_15M_CAMPAIGN_OWNER:
        return "Other"
    return f"Bot {crypto_campaign_bot_number(row)}"


def news_source_label(row):
    model = row.get("model") or {}
    news = model.get("news") or {}
    return news.get("source") or "none"


def market_lane_label(row):
    return str((row or {}).get("market_lane") or market_lane(row) or "unsupported")


def correlated_campaign_window_analytics(settled):
    campaign_rows = [
        row for row in settled
        if row.get("strategy_owner") == CRYPTO_15M_CAMPAIGN_OWNER
        and row.get("close_time")
    ]
    grouped = {}
    for row in campaign_rows:
        campaign = row.get("crypto_live_campaign") or {}
        key = (
            str(campaign.get("campaign_date") or local_date_key(row.get("placed_at"))),
            str(row.get("close_time") or ""),
        )
        grouped.setdefault(key, []).append(row)

    overlap_keys = {
        key for key, rows in grouped.items()
        if len({crypto_campaign_bot_number(row) for row in rows}) >= 2
    }
    overlap_rows = [row for key in overlap_keys for row in grouped[key]]
    windows = []
    for key in overlap_keys:
        rows = grouped[key]
        sides = {str(row.get("side") or "").lower() for row in rows}
        tickers = {}
        for row in rows:
            tickers.setdefault(str(row.get("ticker") or ""), set()).add(crypto_campaign_bot_number(row))
        stake = round(sum(float(row.get("stake") or 0) for row in rows), 2)
        profit = round(sum(float(row.get("profit") or 0) for row in rows), 2)
        wins = sum(1 for row in rows if row.get("result") == "WIN")
        losses = sum(1 for row in rows if row.get("result") == "LOSS")
        windows.append({
            "campaign_date": key[0],
            "close_time": key[1],
            "bot_numbers": sorted({crypto_campaign_bot_number(row) for row in rows}),
            "assets": sorted({str(row.get("asset") or "") for row in rows if row.get("asset")}),
            "sides": sorted(side for side in sides if side),
            "direction_type": "same_direction" if len(sides) == 1 else "mixed_direction",
            "exact_contract_overlap": any(len(bots) >= 2 for bots in tickers.values()),
            "bets": len(rows),
            "wins": wins,
            "losses": losses,
            "stake": stake,
            "profit": profit,
            "roi": round(profit / max(0.01, stake) * 100, 2),
        })
    windows.sort(key=lambda row: (row["campaign_date"], row["close_time"]), reverse=True)
    overlap_stake = round(sum(float(row.get("stake") or 0) for row in overlap_rows), 2)
    overlap_profit = round(sum(float(row.get("profit") or 0) for row in overlap_rows), 2)
    return {
        "summary": {
            "total_windows": len(grouped),
            "overlap_windows": len(overlap_keys),
            "isolated_windows": max(0, len(grouped) - len(overlap_keys)),
            "overlap_bets": len(overlap_rows),
            "overlap_wins": sum(1 for row in overlap_rows if row.get("result") == "WIN"),
            "overlap_losses": sum(1 for row in overlap_rows if row.get("result") == "LOSS"),
            "overlap_stake": overlap_stake,
            "overlap_profit": overlap_profit,
            "overlap_roi": round(overlap_profit / max(0.01, overlap_stake) * 100, 2),
            "same_direction_windows": sum(1 for row in windows if row["direction_type"] == "same_direction"),
            "mixed_direction_windows": sum(1 for row in windows if row["direction_type"] == "mixed_direction"),
            "exact_contract_overlap_windows": sum(1 for row in windows if row["exact_contract_overlap"]),
        },
        "overlap_window_keys": [
            {"campaign_date": row["campaign_date"], "close_time": row["close_time"]}
            for row in windows
        ],
        "recent_windows": windows[:50],
    }


def _recovery_number(value, default=0.0):
    try:
        number = float(value)
    except (TypeError, ValueError):
        return float(default)
    return number if math.isfinite(number) else float(default)


def _recovery_row_id(row):
    return str(
        row.get("id")
        or (
            f"{row.get('ticker')}|{row.get('placed_at')}|{row.get('settled_at')}|"
            f"{row.get('stake')}|{row.get('bot_number')}"
        )
    )


def _bounded_recovery_metadata(row):
    units = row.get("crypto_units") if isinstance(row.get("crypto_units"), dict) else {}
    campaign = (
        row.get("crypto_live_campaign")
        if isinstance(row.get("crypto_live_campaign"), dict)
        else {}
    )
    bounded = (
        units.get("bounded_recovery")
        or campaign.get("bounded_unit_recovery")
        or row.get("bounded_unit_recovery")
        or {}
    )
    if not isinstance(bounded, dict):
        bounded = {}
    base_units = _recovery_number(
        bounded.get("base_units", units.get("base_units")),
    )
    bonus_units = _recovery_number(
        bounded.get("bonus_units", units.get("recovery_bonus_units")),
    )
    total_units = _recovery_number(
        bounded.get("total_units", units.get("applied_total_units")),
        base_units + bonus_units,
    )
    return {
        **bounded,
        "base_units": max(0.0, base_units),
        "bonus_units": max(0.0, bonus_units),
        "total_units": max(0.0, total_units),
    }


def _recovery_counterfactual_row(row):
    """Replay a recovery-sized settlement as though only its base units traded."""
    bounded = _bounded_recovery_metadata(row)
    bonus_units = _recovery_number(bounded.get("bonus_units"))
    base_units = _recovery_number(bounded.get("base_units"))
    total_units = _recovery_number(bounded.get("total_units"))
    actual_contracts = max(0.0, _recovery_number(row.get("contracts")))
    if bonus_units <= 0.0001 or base_units <= 0 or total_units <= 0 or actual_contracts <= 0:
        return None

    saved_base_contracts = _recovery_number(
        bounded.get("applied_base_contracts"),
        default=-1.0,
    )
    if saved_base_contracts >= 0:
        base_contracts = saved_base_contracts
    else:
        base_ratio = max(0.0, min(1.0, base_units / total_units))
        proportional_contracts = actual_contracts * base_ratio
        if str(row.get("mode") or "").lower() == "live" or abs(actual_contracts - round(actual_contracts)) < 1e-8:
            base_contracts = float(math.floor(proportional_contracts + 1e-9))
        else:
            base_contracts = proportional_contracts
    base_contracts = max(0.0, min(actual_contracts, base_contracts))
    contract_ratio = base_contracts / actual_contracts if actual_contracts > 0 else 0.0

    actual_stake = max(0.0, _recovery_number(row.get("stake")))
    actual_fee = max(0.0, _recovery_number(row.get("fee")))
    actual_profit = _recovery_number(row.get("profit"))
    base_stake = actual_stake * contract_ratio
    fee_method = "pro_rata_actual_fee"
    fee_schedule = row.get("fee_schedule") or {}
    if base_contracts > 0 and isinstance(fee_schedule, dict) and fee_schedule.get("authoritative"):
        base_fee = _recovery_number(
            kalshi_order_fee(
                analytics_entry_price(row),
                base_contracts,
                schedule=fee_schedule,
                liquidity_role="taker",
            ).get("fee_dollars")
        )
        fee_method = "saved_exact_fee_schedule"
    else:
        base_fee = actual_fee * contract_ratio
    base_payout = base_contracts if str(row.get("result") or "").upper() == "WIN" else 0.0
    base_profit = base_payout - base_stake - base_fee
    bonus_risk = max(0.0, (actual_stake + actual_fee) - (base_stake + base_fee))
    incremental_profit = actual_profit - base_profit
    settled_at = parse_time(row.get("settled_at") or row.get("closed_at"))
    return {
        "row_id": _recovery_row_id(row),
        "settled_at": settled_at.isoformat() if settled_at else row.get("settled_at"),
        "placed_at": row.get("placed_at"),
        "bot_number": crypto_campaign_bot_number(row),
        "asset": row.get("asset"),
        "ticker": row.get("ticker"),
        "side": str(row.get("side") or "").upper(),
        "result": str(row.get("result") or "").upper(),
        "base_units": round(base_units, 4),
        "bonus_units": round(bonus_units, 4),
        "total_units": round(total_units, 4),
        "actual_contracts": round(actual_contracts, 4),
        "counterfactual_base_contracts": round(base_contracts, 4),
        "actual_stake": round(actual_stake, 4),
        "actual_fee": round(actual_fee, 4),
        "actual_profit": round(actual_profit, 4),
        "counterfactual_base_stake": round(base_stake, 4),
        "counterfactual_base_fee": round(base_fee, 4),
        "counterfactual_base_profit": round(base_profit, 4),
        "bonus_risk": round(bonus_risk, 4),
        "incremental_profit": round(incremental_profit, 4),
        "fee_method": fee_method,
    }


def _recovery_profit_trajectory(
    rows,
    *,
    baseline_drawdown=0.0,
    cutoff=None,
    profit_overrides=None,
    reference_time=None,
):
    profit_overrides = profit_overrides or {}
    reference_time = reference_time or utc_now()
    if reference_time.tzinfo is None:
        reference_time = reference_time.replace(tzinfo=timezone.utc)
    running_profit = -max(0.0, _recovery_number(baseline_drawdown))
    high_water = 0.0
    maximum_drawdown = max(0.0, high_water - running_profit)
    recovery_started_at = cutoff if maximum_drawdown > 0.009 else None
    if recovery_started_at and recovery_started_at.tzinfo is None:
        recovery_started_at = recovery_started_at.replace(tzinfo=timezone.utc)
    recovery_hours = []
    settled_count = 0
    for settled_at, row_id, row in rows:
        if cutoff and settled_at <= cutoff:
            continue
        old_high_water = high_water
        profit = profit_overrides.get(row_id, _recovery_number(row.get("profit")))
        running_profit += profit
        settled_count += 1
        if recovery_started_at is None and running_profit < old_high_water - 0.009:
            recovery_started_at = settled_at
        if recovery_started_at is not None and running_profit >= old_high_water - 0.009:
            recovery_hours.append(
                max(0.0, (settled_at - recovery_started_at).total_seconds() / 3600.0)
            )
            recovery_started_at = None
        high_water = max(high_water, running_profit)
        maximum_drawdown = max(maximum_drawdown, high_water - running_profit)
    current_drawdown = max(0.0, high_water - running_profit)
    open_drawdown_hours = None
    if recovery_started_at is not None:
        open_drawdown_hours = max(
            0.0,
            (reference_time - recovery_started_at).total_seconds() / 3600.0,
        )
    return {
        "settled": settled_count,
        "current_profit": round(running_profit, 2),
        "high_water_profit": round(high_water, 2),
        "current_drawdown": round(current_drawdown, 2),
        "maximum_drawdown": round(maximum_drawdown, 2),
        "completed_recoveries": len(recovery_hours),
        "recovery_hours_total": round(sum(recovery_hours), 4),
        "average_recovery_hours": (
            round(sum(recovery_hours) / len(recovery_hours), 2)
            if recovery_hours
            else None
        ),
        "open_drawdown_hours": (
            round(open_drawdown_hours, 2)
            if open_drawdown_hours is not None
            else None
        ),
    }


def recovery_counterfactual_analytics(portfolio, reference_time=None):
    """Measure recovery add-ons against the exact same bets at base size only."""
    reference_time = reference_time or utc_now()
    if reference_time.tzinfo is None:
        reference_time = reference_time.replace(tzinfo=timezone.utc)
    unique = {}
    for row in [*(portfolio.get("history") or []), *(portfolio.get("bets") or [])]:
        if row.get("strategy_owner") != CRYPTO_15M_CAMPAIGN_OWNER:
            continue
        if str(row.get("status") or "").lower() != "settled":
            continue
        if str(row.get("result") or "").upper() not in {"WIN", "LOSS"}:
            continue
        settled_at = parse_time(row.get("settled_at") or row.get("closed_at"))
        if not settled_at:
            continue
        if settled_at.tzinfo is None:
            settled_at = settled_at.replace(tzinfo=timezone.utc)
        if settled_at > reference_time:
            continue
        unique[_recovery_row_id(row)] = (settled_at, row)

    all_rows = sorted(
        [(settled_at, row_id, row) for row_id, (settled_at, row) in unique.items()],
        key=lambda item: (item[0], item[1]),
    )
    counterfactual_rows = []
    for _settled_at, _row_id, row in all_rows:
        comparison = _recovery_counterfactual_row(row)
        if comparison:
            counterfactual_rows.append(comparison)
    comparison_by_id = {row["row_id"]: row for row in counterfactual_rows}
    base_profit_overrides = {
        row_id: row["counterfactual_base_profit"]
        for row_id, row in comparison_by_id.items()
    }

    ledgers = portfolio.get("crypto_15m_high_water_ledgers") or {}
    bot_numbers = {
        crypto_campaign_bot_number(row)
        for _settled_at, _row_id, row in all_rows
    }
    for key in ledgers:
        try:
            bot_numbers.add(max(1, min(5, int(key))))
        except (TypeError, ValueError):
            continue
    bot_rows = []
    for bot_number in sorted(bot_numbers):
        ledger = ledgers.get(str(bot_number)) or {}
        cutoff = parse_time(ledger.get("migration_cutoff"))
        if cutoff and cutoff.tzinfo is None:
            cutoff = cutoff.replace(tzinfo=timezone.utc)
        baseline = max(0.0, _recovery_number(ledger.get("baseline_drawdown")))
        rows = [
            item for item in all_rows
            if crypto_campaign_bot_number(item[2]) == bot_number
        ]
        actual = _recovery_profit_trajectory(
            rows,
            baseline_drawdown=baseline,
            cutoff=cutoff,
            reference_time=reference_time,
        )
        base_only = _recovery_profit_trajectory(
            rows,
            baseline_drawdown=baseline,
            cutoff=cutoff,
            profit_overrides=base_profit_overrides,
            reference_time=reference_time,
        )
        overlay_count = sum(
            1 for _settled_at, row_id, _row in rows
            if row_id in comparison_by_id and (not cutoff or _settled_at > cutoff)
        )
        bot_rows.append({
            "bot_number": bot_number,
            "overlay_bets": overlay_count,
            "actual": actual,
            "counterfactual_base_only": base_only,
            "drawdown_difference": round(
                actual["current_drawdown"] - base_only["current_drawdown"],
                2,
            ),
        })

    pooled_ledger = portfolio.get("crypto_15m_pooled_high_water_ledger") or {}
    pooled_cutoff = parse_time(pooled_ledger.get("migration_cutoff"))
    if pooled_cutoff and pooled_cutoff.tzinfo is None:
        pooled_cutoff = pooled_cutoff.replace(tzinfo=timezone.utc)
    pooled = None
    if pooled_cutoff:
        pooled_baseline = max(
            0.0,
            _recovery_number(pooled_ledger.get("baseline_drawdown")),
        )
        pooled_actual = _recovery_profit_trajectory(
            all_rows,
            baseline_drawdown=pooled_baseline,
            cutoff=pooled_cutoff,
            reference_time=reference_time,
        )
        pooled_base_only = _recovery_profit_trajectory(
            all_rows,
            baseline_drawdown=pooled_baseline,
            cutoff=pooled_cutoff,
            profit_overrides=base_profit_overrides,
            reference_time=reference_time,
        )
        pooled = {
            "actual": pooled_actual,
            "counterfactual_base_only": pooled_base_only,
            "drawdown_difference": round(
                pooled_actual["current_drawdown"]
                - pooled_base_only["current_drawdown"],
                2,
            ),
        }

    wins = sum(1 for row in counterfactual_rows if row["result"] == "WIN")
    losses = sum(1 for row in counterfactual_rows if row["result"] == "LOSS")
    actual_stake = sum(row["actual_stake"] for row in counterfactual_rows)
    actual_fee = sum(row["actual_fee"] for row in counterfactual_rows)
    actual_profit = sum(row["actual_profit"] for row in counterfactual_rows)
    base_stake = sum(row["counterfactual_base_stake"] for row in counterfactual_rows)
    base_fee = sum(row["counterfactual_base_fee"] for row in counterfactual_rows)
    base_profit = sum(row["counterfactual_base_profit"] for row in counterfactual_rows)
    bonus_risk = sum(row["bonus_risk"] for row in counterfactual_rows)
    incremental_profit = actual_profit - base_profit
    incremental_running = 0.0
    incremental_high_water = 0.0
    incremental_max_drawdown = 0.0
    current_loss_streak = 0
    maximum_loss_streak = 0
    for row in counterfactual_rows:
        incremental = row["incremental_profit"]
        incremental_running += incremental
        incremental_high_water = max(incremental_high_water, incremental_running)
        incremental_max_drawdown = max(
            incremental_max_drawdown,
            incremental_high_water - incremental_running,
        )
        if incremental < -0.0001:
            current_loss_streak += 1
            maximum_loss_streak = max(maximum_loss_streak, current_loss_streak)
        else:
            current_loss_streak = 0

    actual_recoveries = (
        pooled["actual"]["completed_recoveries"]
        if pooled
        else sum(row["actual"]["completed_recoveries"] for row in bot_rows)
    )
    base_recoveries = (
        pooled["counterfactual_base_only"]["completed_recoveries"]
        if pooled
        else sum(
            row["counterfactual_base_only"]["completed_recoveries"]
            for row in bot_rows
        )
    )
    actual_recovery_hours = (
        pooled["actual"]["recovery_hours_total"]
        if pooled
        else sum(row["actual"]["recovery_hours_total"] for row in bot_rows)
    )
    base_recovery_hours = (
        pooled["counterfactual_base_only"]["recovery_hours_total"]
        if pooled
        else sum(
            row["counterfactual_base_only"]["recovery_hours_total"]
            for row in bot_rows
        )
    )
    recovery_reservations = crypto_15m_open_recovery_reservations(portfolio)
    settled_count = wins + losses
    summary = {
        "status": "active" if settled_count else "collecting",
        "settled": settled_count,
        "wins": wins,
        "losses": losses,
        "win_rate": round(wins / settled_count * 100, 2) if settled_count else 0.0,
        "actual_stake": round(actual_stake, 2),
        "actual_fee": round(actual_fee, 4),
        "actual_profit": round(actual_profit, 2),
        "counterfactual_base_stake": round(base_stake, 2),
        "counterfactual_base_fee": round(base_fee, 4),
        "counterfactual_base_profit": round(base_profit, 2),
        "bonus_risk": round(bonus_risk, 2),
        "incremental_profit": round(incremental_profit, 2),
        "incremental_roi": (
            round(incremental_profit / bonus_risk * 100, 2)
            if bonus_risk > 0.0001
            else 0.0
        ),
        "maximum_incremental_loss_streak": maximum_loss_streak,
        "incremental_max_drawdown": round(incremental_max_drawdown, 2),
        "actual_max_drawdown": round(
            pooled["actual"]["maximum_drawdown"]
            if pooled
            else max(
                (row["actual"]["maximum_drawdown"] for row in bot_rows),
                default=0.0,
            ),
            2,
        ),
        "counterfactual_base_max_drawdown": round(
            pooled["counterfactual_base_only"]["maximum_drawdown"]
            if pooled
            else max(
                (
                    row["counterfactual_base_only"]["maximum_drawdown"]
                    for row in bot_rows
                ),
                default=0.0,
            ),
            2,
        ),
        "pooled_recovery": bool(pooled),
        "open_recovery_overlays": int(
            recovery_reservations.get("open_overlay_count") or 0
        ),
        "reserved_recovery_profit": round(
            float(recovery_reservations.get("reserved_recovery_profit") or 0),
            2,
        ),
        "actual_completed_recoveries": actual_recoveries,
        "counterfactual_base_completed_recoveries": base_recoveries,
        "actual_average_recovery_hours": (
            round(actual_recovery_hours / actual_recoveries, 2)
            if actual_recoveries
            else None
        ),
        "counterfactual_base_average_recovery_hours": (
            round(base_recovery_hours / base_recoveries, 2)
            if base_recoveries
            else None
        ),
    }
    return {
        "version": "bounded-recovery-counterfactual-v2",
        "generated_at": reference_time.replace(microsecond=0).isoformat(),
        "summary": summary,
        "pooled": pooled,
        "by_bot": bot_rows,
        "recent": list(reversed(counterfactual_rows[-50:])),
        "method": {
            "comparison": "same settled wagers replayed at base units only",
            "fills": "base contracts scaled from each actual fill; whole live fills remain whole contracts",
            "fees": "saved exact fee schedule when available, otherwise pro-rata allocation of the actual charged fee",
            "scope": "pooled crypto 15-minute campaign drawdown with per-bot attribution",
            "open_reservations": "open recovery win-profit allocations are subtracted before another bonus is sized",
        },
    }


def scan_analytics(portfolio, candidates, placed, settings=None):
    settings = settings or load_settings()
    settled = [
        bet for bet in portfolio.get("bets", [])
        if bet.get("status") == "settled" and crypto_analytics_included(bet, settings)
    ]
    open_rows = bot_open_bets(portfolio)
    placed_ids = {bet.get("id") for bet in placed}
    skip_counts = {}
    for row in candidates:
        for reason in row.get("skip_reasons") or []:
            skip_counts[reason] = skip_counts.get(reason, 0) + 1
    eligible = [row for row in candidates if not row.get("skip_reasons") or row.get("decision") == "placed"]
    strong = [
        row for row in candidates
        if float(row.get("edge") or 0) >= 10 and float(row.get("confidence") or 0) >= 74
    ]
    elite = [
        row for row in candidates
        if float(row.get("edge") or 0) >= 15 and float(row.get("confidence") or 0) >= 80
    ]
    preferred = [row for row in candidates if price_band(row.get("entry_price")) == "35-44c"]
    low_edge_pilot_candidates = [
        row
        for row in candidates
        if (row.get("low_edge_pilot") or {}).get("candidate_match")
    ]
    low_edge_pilot_rows = [
        row
        for row in settled
        if (row.get("low_edge_pilot") or {}).get("active")
    ]
    correlated_windows = correlated_campaign_window_analytics(settled)
    overlap_keys = {
        (row.get("campaign_date"), row.get("close_time"))
        for row in correlated_windows.get("overlap_window_keys") or []
    }
    return {
        "candidate_summary": {
            "total": len(candidates),
            "eligible": len(eligible),
            "skipped": len(candidates) - len(eligible),
            "placed": len(placed),
            "open": len(open_rows),
            "settled": len(settled),
            "preferred_band": len(preferred),
            "strong_edge": len(strong),
            "elite_edge": len(elite),
            "low_edge_pilot_candidates": len(low_edge_pilot_candidates),
            "low_edge_pilot_eligible": sum(
                1
                for row in low_edge_pilot_candidates
                if (row.get("low_edge_pilot") or {}).get("eligible")
            ),
        },
        "candidate_by_skip_reason": [{"label": label, "count": count} for label, count in sorted(skip_counts.items(), key=lambda item: (-item[1], item[0]))],
        "candidate_by_price_band": candidate_group_rows(candidates, lambda row: price_band(row.get("entry_price"))),
        "candidate_by_asset": candidate_group_rows(candidates, lambda row: row.get("asset") or "unknown"),
        "candidate_by_lane": candidate_group_rows(candidates, market_lane_label),
        "candidate_by_market_kind": candidate_group_rows(candidates, lambda row: row.get("market_kind") or "unknown"),
        "candidate_by_edge": candidate_group_rows(candidates, lambda row: edge_band(row.get("edge"))),
        "candidate_by_confidence": candidate_group_rows(candidates, lambda row: confidence_band(row.get("confidence"))),
        "candidate_by_time_to_close": candidate_group_rows(candidates, hours_to_close_band),
        "candidate_by_news_source": candidate_group_rows(candidates, news_source_label),
        "settled_by_asset": bet_group_rows(settled, lambda row: row.get("asset") or "unknown"),
        "settled_by_lane": bet_group_rows(settled, market_lane_label),
        "settled_by_market_kind": bet_group_rows(settled, lambda row: row.get("market_kind") or "unknown"),
        "settled_by_price_band": bet_group_rows(settled, lambda row: price_band(analytics_entry_price(row))),
        "settled_by_edge": bet_group_rows(settled, lambda row: edge_band(row.get("edge"))),
        "settled_by_confidence": bet_group_rows(settled, lambda row: confidence_band(row.get("confidence"))),
        "settled_by_side": bet_group_rows(settled, lambda row: str(row.get("side") or "unknown").upper()),
        "settled_by_stake": bet_group_rows(settled, stake_band),
        "settled_by_selective_tier": bet_group_rows(settled, selective_tier),
        "settled_by_recovery": bet_group_rows(settled, recovery_tier),
        "settled_low_edge_pilot": bet_group_rows(
            low_edge_pilot_rows,
            lambda row: price_band(row.get("entry_price")),
        ),
        "settled_by_strategy_owner": bet_group_rows(settled, strategy_owner_label),
        "settled_by_campaign_bot": bet_group_rows(
            [row for row in settled if row.get("strategy_owner") == CRYPTO_15M_CAMPAIGN_OWNER],
            campaign_bot_label,
        ),
        "settled_by_window_correlation": bet_group_rows(
            [row for row in settled if row.get("strategy_owner") == CRYPTO_15M_CAMPAIGN_OWNER],
            lambda row: (
                "Correlated window"
                if (
                    str((row.get("crypto_live_campaign") or {}).get("campaign_date") or local_date_key(row.get("placed_at"))),
                    str(row.get("close_time") or ""),
                ) in overlap_keys
                else "Isolated window"
            ),
        ),
        "correlated_windows": correlated_windows,
        "recovery_counterfactual": recovery_counterfactual_analytics(portfolio),
        "execution_quality": execution_quality_analytics(),
        "open_by_asset": count_rows(open_rows, lambda row: row.get("asset") or "unknown"),
        "open_by_lane": count_rows(open_rows, market_lane_label),
        "open_by_strategy_owner": count_rows(open_rows, strategy_owner_label),
        "open_by_campaign_bot": count_rows(
            [row for row in open_rows if row.get("strategy_owner") == CRYPTO_15M_CAMPAIGN_OWNER],
            campaign_bot_label,
        ),
        "placed_ids": [bet_id for bet_id in placed_ids if bet_id],
    }


def apply_crypto_selective_edge_scaling(settings, candidate, stake, balance):
    if not setting_bool(settings, "CRYPTO_SELECTIVE_EDGE_SCALING_ENABLED"):
        return stake
    edge = float(candidate.get("edge") or 0)
    confidence = float(candidate.get("confidence") or 0)
    tier = None
    multiplier = 1.0
    max_stake = setting_float(settings, "CRYPTO_MAX_STAKE")
    if edge >= setting_float(settings, "CRYPTO_ELITE_EDGE_MIN_EDGE") and confidence >= setting_float(settings, "CRYPTO_ELITE_EDGE_MIN_CONFIDENCE"):
        tier = "elite_edge"
        multiplier = max(1.0, setting_float(settings, "CRYPTO_ELITE_EDGE_STAKE_MULTIPLIER"))
        max_stake = max(max_stake, setting_float(settings, "CRYPTO_ELITE_EDGE_MAX_STAKE"))
    elif edge >= setting_float(settings, "CRYPTO_STRONG_EDGE_MIN_EDGE") and confidence >= setting_float(settings, "CRYPTO_STRONG_EDGE_MIN_CONFIDENCE"):
        tier = "strong_edge"
        multiplier = max(1.0, setting_float(settings, "CRYPTO_STRONG_EDGE_STAKE_MULTIPLIER"))
        max_stake = max(max_stake, setting_float(settings, "CRYPTO_STRONG_EDGE_MAX_STAKE"))
    if not tier:
        return min(stake, setting_float(settings, "CRYPTO_MAX_STAKE"))
    adjusted = round(min(max(stake, stake * multiplier), max_stake, balance), 2)
    candidate["selective_edge"] = {
        "active": adjusted > stake,
        "tier": tier,
        "base_stake": round(stake, 2),
        "applied_stake": adjusted,
        "multiplier": multiplier,
        "max_stake": max_stake,
        "edge": edge,
        "confidence": confidence,
    }
    return adjusted


def apply_crypto_shared_recovery_staking(settings, candidate, stake, balance):
    if not setting_bool(settings, "CRYPTO_SHARED_RECOVERY_ENABLED") or not shared_recovery_context:
        return stake
    if (candidate.get("phase_two") or {}).get("active"):
        return stake
    cluster = f"crypto:{str(candidate.get('event_ticker') or candidate.get('ticker') or '').strip().lower()}"
    context = shared_recovery_context("crypto", cluster_key=cluster)
    compact_context = {
        "enabled": context.get("enabled"),
        "strategy": context.get("strategy"),
        "active": context.get("active"),
        "reason": context.get("reason"),
        "cash": context.get("cash"),
        "realized_profit_basis": context.get("realized_profit_basis"),
        "drawdown": context.get("drawdown"),
        "effective_min_drawdown": context.get("effective_min_drawdown"),
        "target_profit": context.get("target_profit"),
        "slice_target_profit": context.get("slice_target_profit"),
        "campaign_target_profit": context.get("campaign_target_profit"),
        "campaign_slots_remaining": context.get("slots_remaining"),
        "cluster": cluster,
        "max_recovery_stake": context.get("max_recovery_stake"),
    }
    if not context.get("active"):
        candidate["shared_recovery"] = compact_context
        return stake
    edge = float(candidate.get("edge") or 0)
    confidence = float(candidate.get("confidence") or 0)
    if edge < setting_float(settings, "CRYPTO_SHARED_RECOVERY_MIN_EDGE"):
        candidate["shared_recovery"] = {**compact_context, "active": False, "reason": "crypto_recovery_edge_filter"}
        return stake
    if confidence < setting_float(settings, "CRYPTO_SHARED_RECOVERY_MIN_CONFIDENCE"):
        candidate["shared_recovery"] = {**compact_context, "active": False, "reason": "crypto_recovery_confidence_filter"}
        return stake
    profit_per_dollar = profit_per_staked_dollar(candidate.get("entry_price"))
    if profit_per_dollar <= 0:
        candidate["shared_recovery"] = {**compact_context, "active": False, "reason": "crypto_recovery_bad_entry_price"}
        return stake
    allocation = recovery_quality_allocation("crypto", candidate, context, settings=settings) if recovery_quality_allocation else {"target_profit": context.get("slice_target_profit")}
    target_profit = float(allocation.get("target_profit") or 0)
    target_stake = round(target_profit / profit_per_dollar, 2)
    max_recovery_stake = min(
        float(context.get("max_recovery_stake") or 0),
        setting_float(settings, "CRYPTO_SHARED_RECOVERY_MAX_STAKE"),
    )
    adjusted = round(min(max(stake, target_stake), max_recovery_stake, balance), 2)
    base_expected_profit = round(float(stake or 0) * profit_per_dollar, 2)
    if adjusted <= stake:
        if target_profit <= 0 or base_expected_profit + 0.01 < target_profit:
            candidate["shared_recovery"] = {**compact_context, "active": False, "reason": "crypto_recovery_no_size_increase"}
            return stake
        adjusted = round(float(stake or 0), 2)
    candidate["shared_recovery"] = {
        **compact_context,
        "active": True,
        "base_stake": round(stake, 2),
        "target_stake_raw": target_stake,
        "applied_stake": adjusted,
        "profit_per_staked_dollar": round(profit_per_dollar, 4),
        "expected_profit": round(adjusted * profit_per_dollar, 2),
        "covered_by_base_stake": adjusted <= round(float(stake or 0), 2),
        "quality_tier": allocation.get("tier"),
        "quality_score": allocation.get("quality_score"),
        "quality_components": allocation.get("quality_components"),
        "allocation_fraction": allocation.get("allocation_fraction"),
        "allocated_target_profit": round(target_profit, 2),
        "edge": edge,
        "confidence": confidence,
    }
    return adjusted


def duplicate_open(portfolio, ticker, side):
    return any(
        bet.get("status") == "open"
        and not is_user_crypto_bet(bet)
        and bet.get("ticker") == ticker
        and bet.get("side") == side
        for bet in portfolio.get("bets", [])
    )


def live_depth_retry_cooldown_remaining(settings, candidate, now=None):
    ticker = str(candidate.get("ticker") or "")
    if not ticker:
        return 0.0
    current = float(time.time() if now is None else now)
    expires = float(LIVE_DEPTH_RETRY_UNTIL.get(ticker) or 0)
    if expires <= current:
        LIVE_DEPTH_RETRY_UNTIL.pop(ticker, None)
        return 0.0
    remaining = round(expires - current, 3)
    candidate["live_depth_retry_cooldown"] = {
        "active": True,
        "ticker": ticker,
        "seconds_remaining": remaining,
    }
    return remaining


def start_live_depth_retry_cooldown(settings, candidate, now=None):
    seconds = max(0.0, setting_float(settings, "CRYPTO_LIVE_DEPTH_RETRY_COOLDOWN_SECONDS"))
    ticker = str(candidate.get("ticker") or "")
    if not ticker or seconds <= 0:
        return 0.0
    current = float(time.time() if now is None else now)
    LIVE_DEPTH_RETRY_UNTIL[ticker] = current + seconds
    candidate["live_depth_retry_cooldown"] = {
        "active": True,
        "ticker": ticker,
        "seconds_remaining": round(seconds, 3),
    }
    return seconds


def live_slippage_reconfirmation_key(candidate):
    ticker = str(candidate.get("ticker") or "").strip()
    side = str(candidate.get("side") or "").strip().lower()
    return f"{ticker}|{side}" if ticker and side else ""


def clear_live_slippage_reconfirmation(candidate):
    key = live_slippage_reconfirmation_key(candidate)
    if not key:
        return False
    with LIVE_SLIPPAGE_RECONFIRMATION_LOCK:
        return LIVE_SLIPPAGE_RECONFIRMATIONS.pop(key, None) is not None


def live_slippage_reconfirmation_review(settings, candidate, now=None):
    """Return the pending/ready second-quote state for an oversized move."""
    enabled = setting_bool(settings, "CRYPTO_LIVE_SLIPPAGE_RECONFIRM_ENABLED")
    key = live_slippage_reconfirmation_key(candidate)
    if not enabled or not key:
        if key and not enabled:
            clear_live_slippage_reconfirmation(candidate)
        return {"enabled": enabled, "active": False, "status": "inactive"}

    current = float(time.time() if now is None else now)
    with LIVE_SLIPPAGE_RECONFIRMATION_LOCK:
        state = dict(LIVE_SLIPPAGE_RECONFIRMATIONS.get(key) or {})
        if state and (
            str(state.get("close_time") or "")
            != str(candidate.get("close_time") or "")
            or float(state.get("expires_at_epoch") or 0) <= current
        ):
            LIVE_SLIPPAGE_RECONFIRMATIONS.pop(key, None)
            state = {}
    if not state:
        return {"enabled": True, "active": False, "status": "inactive"}

    ready_at = float(state.get("ready_at_epoch") or 0)
    ready = current + 1e-9 >= ready_at
    public_state = {
        key: value
        for key, value in state.items()
        if not key.endswith("_epoch")
    }
    public_state.update({
        "enabled": True,
        "active": True,
        "ready": ready,
        "status": "ready" if ready else "waiting",
        "seconds_remaining": round(max(0.0, ready_at - current), 3),
        "base_units_only": True,
    })
    candidate["live_slippage_reconfirmation"] = public_state
    return public_state


def start_live_slippage_reconfirmation(
    settings,
    candidate,
    quote_refresh,
    now=None,
    force_restart=False,
):
    """Start a short, idempotent wait before accepting a second stable quote."""
    if not setting_bool(settings, "CRYPTO_LIVE_SLIPPAGE_RECONFIRM_ENABLED"):
        return {"enabled": False, "active": False, "status": "disabled"}
    key = live_slippage_reconfirmation_key(candidate)
    reference_price = (quote_refresh or {}).get("refreshed_price_cents")
    if not key or reference_price is None:
        return {"enabled": True, "active": False, "status": "unavailable"}

    current = float(time.time() if now is None else now)
    wait_seconds = max(
        0.0,
        setting_float(settings, "CRYPTO_LIVE_SLIPPAGE_RECONFIRM_SECONDS"),
    )
    lifetime_seconds = max(60.0, wait_seconds * 4.0)
    with LIVE_SLIPPAGE_RECONFIRMATION_LOCK:
        existing = dict(LIVE_SLIPPAGE_RECONFIRMATIONS.get(key) or {})
        same_reference = bool(
            existing
            and abs(
                float(existing.get("reference_price_cents") or 0)
                - float(reference_price)
            )
            <= 1e-9
        )
        if existing and same_reference and not force_restart:
            state = existing
        else:
            started_at = datetime.fromtimestamp(current, timezone.utc).isoformat()
            state = {
                "ticker": str(candidate.get("ticker") or ""),
                "side": str(candidate.get("side") or "").lower(),
                "close_time": str(candidate.get("close_time") or ""),
                "reference_price_cents": round(float(reference_price), 4),
                "original_price_cents": (quote_refresh or {}).get(
                    "original_price_cents"
                ),
                "first_adverse_move_cents": (quote_refresh or {}).get(
                    "adverse_move_cents"
                ),
                "trigger_error": (quote_refresh or {}).get("error"),
                "started_at": started_at,
                "ready_at": datetime.fromtimestamp(
                    current + wait_seconds,
                    timezone.utc,
                ).isoformat(),
                "ready_at_epoch": current + wait_seconds,
                "expires_at_epoch": current + lifetime_seconds,
                "maximum_confirmation_move_cents": max(
                    0.0,
                    setting_float(
                        settings,
                        "CRYPTO_LIVE_SLIPPAGE_RECONFIRM_MAX_MOVE_CENTS",
                    ),
                ),
            }
            LIVE_SLIPPAGE_RECONFIRMATIONS[key] = state

    return live_slippage_reconfirmation_review(settings, candidate, now=current)


def handle_live_quote_refresh_failure(settings, candidate, quote_refresh, now=None):
    """Route slippage to reconfirmation and true depth failures to cooldown."""
    error = str((quote_refresh or {}).get("error") or "")
    if error in {
        "live_quote_slippage_limit",
        "live_quote_slippage_reconfirm_unstable",
    }:
        return start_live_slippage_reconfirmation(
            settings,
            candidate,
            quote_refresh,
            now=now,
            force_restart=error == "live_quote_slippage_reconfirm_unstable",
        )
    if error == "live_quote_slippage_reconfirm_wait":
        return live_slippage_reconfirmation_review(settings, candidate, now=now)
    seconds = start_live_depth_retry_cooldown(settings, candidate, now=now)
    return {
        "enabled": True,
        "active": seconds > 0,
        "status": "depth_retry_cooldown",
        "seconds_remaining": seconds,
    }


def mark_correlated_campaign_window(portfolio, bet):
    if bet.get("strategy_owner") != CRYPTO_15M_CAMPAIGN_OWNER:
        return
    close_time = str(bet.get("close_time") or "")
    if not close_time:
        return
    rows = [
        row for row in portfolio.get("bets", [])
        if row.get("strategy_owner") == CRYPTO_15M_CAMPAIGN_OWNER
        and str(row.get("close_time") or "") == close_time
        and str((row.get("crypto_live_campaign") or {}).get("campaign_date") or "")
        == str((bet.get("crypto_live_campaign") or {}).get("campaign_date") or "")
    ]
    bot_numbers = sorted({crypto_campaign_bot_number(row) for row in rows})
    if len(bot_numbers) < 2:
        return
    assets = sorted({str(row.get("asset") or "") for row in rows if row.get("asset")})
    sides = sorted({str(row.get("side") or "").lower() for row in rows if row.get("side")})
    metadata = {
        "active": True,
        "close_time": close_time,
        "bot_numbers": bot_numbers,
        "assets": assets,
        "sides": sides,
        "direction_type": "same_direction" if len(sides) == 1 else "mixed_direction",
    }
    for row in rows:
        row["correlated_window"] = dict(metadata)


def open_count_for(portfolio, key, value):
    return sum(1 for bet in bot_open_bets(portfolio) if bet.get(key) == value)


def crypto_position_yes_wins(row, spot):
    kind = str(row.get("market_kind") or "").lower()
    try:
        floor = float(row.get("floor_strike")) if row.get("floor_strike") is not None else None
        cap = float(row.get("cap_strike")) if row.get("cap_strike") is not None else None
    except (TypeError, ValueError):
        return None
    if kind == "above" and floor is not None:
        return spot > floor
    if kind == "below" and cap is not None:
        return spot < cap
    if kind == "range" and floor is not None and cap is not None:
        return floor <= spot <= cap
    return None


def crypto_position_profit_at_spot(row, spot, stake_override=None):
    yes_wins = crypto_position_yes_wins(row, spot)
    if yes_wins is None:
        return None
    stake = money(stake_override if stake_override is not None else row.get("stake"))
    price = float(row.get("entry_price") or 0)
    if stake <= 0 or price <= 0 or price >= 100:
        return None
    side_wins = yes_wins if str(row.get("side") or "").lower() == "yes" else not yes_wins
    return stake * ((100.0 / price) - 1.0) if side_wins else -stake


def crypto_event_coverage_review(open_event_rows, candidate, proposed_stake):
    boundaries = []
    for row in [*open_event_rows, candidate]:
        for key in ("floor_strike", "cap_strike"):
            try:
                if row.get(key) is not None:
                    boundaries.append(float(row.get(key)))
            except (TypeError, ValueError):
                pass
    boundaries = sorted(set(boundaries))
    if not boundaries or any(crypto_position_yes_wins(row, boundaries[0]) is None for row in open_event_rows):
        return {"reviewable": False, "improves": False, "reason": "event_payoff_shape_unavailable"}
    scale = max(1.0, max(abs(value) for value in boundaries))
    epsilon = scale * 0.000001
    scenarios = [boundaries[0] - max(1.0, epsilon), boundaries[-1] + max(1.0, epsilon)]
    for index, boundary in enumerate(boundaries):
        scenarios.extend([boundary - epsilon, boundary, boundary + epsilon])
        if index + 1 < len(boundaries):
            scenarios.append((boundary + boundaries[index + 1]) / 2.0)
    baseline_values = []
    candidate_values = []
    for spot in scenarios:
        existing_parts = [crypto_position_profit_at_spot(row, spot) for row in open_event_rows]
        candidate_part = crypto_position_profit_at_spot(candidate, spot, proposed_stake)
        if any(value is None for value in existing_parts) or candidate_part is None:
            return {"reviewable": False, "improves": False, "reason": "event_payoff_shape_unavailable"}
        baseline = sum(existing_parts)
        baseline_values.append(baseline)
        candidate_values.append(baseline + candidate_part)
    baseline_worst = min(baseline_values)
    proposed_worst = min(candidate_values)
    improvement = proposed_worst - baseline_worst
    return {
        "reviewable": True,
        "improves": improvement > 0,
        "reason": "event_worst_case_improved" if improvement > 0 else "event_worst_case_not_improved",
        "baseline_worst_profit": money(baseline_worst),
        "proposed_worst_profit": money(proposed_worst),
        "worst_case_improvement": money(improvement),
        "scenario_count": len(scenarios),
    }


def apply_crypto_event_diminishing(settings, portfolio, candidate, stake):
    if not setting_bool(settings, "CRYPTO_EVENT_DIMINISHING_ENABLED"):
        return stake
    if (candidate.get("phase_two") or {}).get("active") or (candidate.get("shared_recovery") or {}).get("active"):
        return stake
    event_ticker = candidate.get("event_ticker")
    if not event_ticker:
        return stake
    event_rows = [row for row in bot_open_bets(portfolio) if row.get("event_ticker") == event_ticker]
    open_count = len(event_rows)
    max_open = max(1, setting_int(settings, "CRYPTO_EVENT_MAX_OPEN_POSITIONS") or 3)
    review = {
        "active": open_count > 0,
        "event_ticker": event_ticker,
        "open_count_before": open_count,
        "max_open_positions": max_open,
        "original_stake": money(stake),
    }
    if open_count == 0:
        candidate["event_diversification"] = {**review, "tier": "first_full", "multiplier": 1.0, "applied_stake": money(stake)}
        return stake
    if open_count >= max_open:
        candidate["event_diversification"] = {**review, "allowed": False, "reason": "crypto_event_cluster_full", "applied_stake": 0.0}
        candidate.setdefault("skip_reasons", []).append("crypto_event_cluster_full")
        return 0.0
    if open_count == 1:
        multiplier = max(0.0, setting_float(settings, "CRYPTO_EVENT_SECOND_STAKE_MULTIPLIER"))
        adjusted = money(stake * multiplier)
        candidate["event_diversification"] = {
            **review,
            "allowed": adjusted > 0,
            "tier": "second_half",
            "reason": "crypto_event_second_diminished",
            "multiplier": multiplier,
            "applied_stake": adjusted,
        }
        return adjusted

    multiplier = max(0.0, setting_float(settings, "CRYPTO_EVENT_THIRD_STAKE_MULTIPLIER"))
    adjusted = money(stake * multiplier)
    coverage = crypto_event_coverage_review(event_rows, candidate, adjusted)
    minimum_improvement = setting_float(settings, "CRYPTO_EVENT_COVERAGE_MIN_IMPROVEMENT")
    coverage_ok = coverage.get("reviewable") and float(coverage.get("worst_case_improvement") or 0) >= minimum_improvement
    elite = (
        str((candidate.get("selective_edge") or {}).get("tier") or "") == "elite_edge"
        or (
            float(candidate.get("edge") or 0) >= setting_float(settings, "CRYPTO_ELITE_EDGE_MIN_EDGE")
            and float(candidate.get("confidence") or 0) >= setting_float(settings, "CRYPTO_ELITE_EDGE_MIN_CONFIDENCE")
        )
    )
    allowed = adjusted > 0 and (coverage_ok or elite)
    candidate["event_diversification"] = {
        **review,
        "allowed": allowed,
        "tier": "third_quarter",
        "reason": "crypto_event_third_coverage" if coverage_ok else "crypto_event_third_elite" if elite else "crypto_event_third_not_justified",
        "multiplier": multiplier,
        "applied_stake": adjusted if allowed else 0.0,
        "elite": elite,
        "coverage": coverage,
        "coverage_min_improvement": minimum_improvement,
    }
    if not allowed:
        candidate.setdefault("skip_reasons", []).append("crypto_event_third_not_justified")
        return 0.0
    return adjusted


def crypto_live_core_review(settings, candidate, balance):
    return quality_core_review(
        bankroll=balance,
        metrics={
            "edge": candidate.get("edge"),
            "confidence": candidate.get("confidence"),
        },
        minimums={
            "edge": setting_float(settings, "CRYPTO_LIVE_CORE_MIN_EDGE"),
            "confidence": setting_float(settings, "CRYPTO_LIVE_CORE_MIN_CONFIDENCE"),
        },
        elite_minimums={
            "edge": setting_float(settings, "CRYPTO_LIVE_CORE_ELITE_MIN_EDGE"),
            "confidence": setting_float(settings, "CRYPTO_LIVE_CORE_ELITE_MIN_CONFIDENCE"),
        },
        base_stake_pct=setting_float(settings, "CRYPTO_LIVE_CORE_BASE_STAKE_PCT"),
        base_stake_cap=setting_float(settings, "CRYPTO_LIVE_CORE_BASE_STAKE_CAP"),
        elite_multiplier=setting_float(settings, "CRYPTO_LIVE_CORE_ELITE_MULTIPLIER"),
        elite_stake_pct=setting_float(settings, "CRYPTO_LIVE_CORE_ELITE_STAKE_PCT"),
        elite_stake_cap=setting_float(settings, "CRYPTO_LIVE_CORE_ELITE_STAKE_CAP"),
        min_stake=setting_float(settings, "CRYPTO_MIN_STAKE"),
    )


def _crypto_15m_campaign_schedule_key(date_key, campaign_id, bot_number):
    return f"{date_key}|{campaign_id or 'default'}|bot{bot_number}"


def _crypto_15m_campaign_lane_has_rows(portfolio, date_key, campaign_id, bot_number):
    for row in [*(portfolio.get("history") or []), *(portfolio.get("bets") or [])]:
        if row.get("strategy_owner") != CRYPTO_15M_CAMPAIGN_OWNER:
            continue
        if crypto_campaign_bot_number(row) != bot_number:
            continue
        campaign = row.get("crypto_live_campaign") or {}
        row_date = str(campaign.get("campaign_date") or local_date_key(
            row.get("placed_at") or row.get("created_at")
        ))
        row_campaign_id = str(campaign.get("campaign_id") or "")
        if row_date == date_key and row_campaign_id == campaign_id:
            return True
    return False


def crypto_15m_campaign_strategy(settings, date_key=None, bot_number=1, portfolio=None):
    date_key = date_key or local_date_key()
    bot_number = max(1, min(5, crypto_campaign_bot_number({"bot_number": bot_number})))
    effective_date = str(
        settings.get("CRYPTO_15M_HYBRID_EFFECTIVE_DATE") or ""
    ).strip()
    hybrid_active = not effective_date or date_key >= effective_date
    goal_key = (
        "CRYPTO_15M_CYCLE_GOALS"
        if hybrid_active
        else "CRYPTO_15M_LEGACY_CYCLE_GOALS"
    )
    goals = setting_float_list(settings, goal_key)
    if not goals:
        goals = [2.0] * 5 if hybrid_active else [5.0, 2.5, 1.25]
    override_date = str(
        settings.get("CRYPTO_15M_CYCLE_GOALS_OVERRIDE_DATE") or ""
    ).strip()
    override_goals = setting_float_list(
        settings,
        "CRYPTO_15M_CYCLE_GOALS_OVERRIDE",
    )
    override_active = bool(
        hybrid_active
        and override_date
        and date_key == override_date
        and override_goals
    )
    if override_active:
        goals = override_goals
    base_goals = list(goals)
    base_source = "dated_override" if override_active else goal_key
    campaign_id = str(
        settings.get(f"CRYPTO_15M_BOT_{bot_number}_CAMPAIGN_ID")
        or settings.get("CRYPTO_15M_CAMPAIGN_ID")
        or ""
    ).strip()
    profit_key = f"CRYPTO_15M_BOT_{bot_number}_CYCLE_PROFIT"
    count_key = f"CRYPTO_15M_BOT_{bot_number}_CYCLE_COUNT"
    configured_cycle_profit = setting_float(settings, profit_key)
    if configured_cycle_profit <= 0:
        configured_cycle_profit = float(base_goals[0] if base_goals else 2.0)
    configured_cycle_count = setting_int(settings, count_key)
    if configured_cycle_count <= 0:
        configured_cycle_count = max(1, len(base_goals))
    configured_cycle_count = max(1, min(100, configured_cycle_count))
    configured_goals = [round(configured_cycle_profit, 2)] * configured_cycle_count
    schedule_locked = False
    schedule_key = _crypto_15m_campaign_schedule_key(date_key, campaign_id, bot_number)
    if portfolio is not None:
        schedules = portfolio.setdefault("crypto_15m_campaign_schedules", {})
        stored = schedules.get(schedule_key) or {}
        lane_has_rows = _crypto_15m_campaign_lane_has_rows(
            portfolio,
            date_key,
            campaign_id,
            bot_number,
        )
        stored_goals = [
            round(float(value), 2)
            for value in (stored.get("goals") or [])
            if float(value) > 0
        ]
        if lane_has_rows and stored_goals:
            goals = stored_goals
            goal_schedule_source = str(stored.get("source") or profit_key)
        elif lane_has_rows:
            # Grandfather an already-started legacy lane so a configuration
            # edit cannot reinterpret completed cycles or reopen its campaign.
            goals = base_goals
            goal_schedule_source = base_source
        else:
            goals = configured_goals
            goal_schedule_source = profit_key
        schedule_locked = lane_has_rows
        schedules[schedule_key] = {
            "campaign_date": date_key,
            "campaign_id": campaign_id,
            "bot_number": bot_number,
            "goals": list(goals),
            "source": goal_schedule_source,
            "configured_cycle_profit": round(configured_cycle_profit, 2),
            "configured_cycle_count": configured_cycle_count,
            "locked": schedule_locked,
        }
    else:
        goal_schedule_source = base_source
    return {
        "goals": goals,
        "goal_schedule_source": goal_schedule_source,
        "goal_schedule_override_date": override_date if override_active else "",
        "goal_schedule_key": schedule_key,
        "goal_schedule_locked": schedule_locked,
        "bot_number": bot_number,
        "configured_cycle_profit": round(configured_cycle_profit, 2),
        "configured_cycle_profit_key": profit_key,
        "configured_cycle_count": configured_cycle_count,
        "configured_cycle_count_key": count_key,
        "effective_cycle_count": len(goals),
        "hybrid_active": hybrid_active,
        "effective_date": effective_date,
        "campaign_id": campaign_id,
        "partial_recovery_enabled": (
            hybrid_active
            and setting_bool(settings, "CRYPTO_15M_PARTIAL_RECOVERY_ENABLED")
        ),
        "full_recovery_losses": setting_int(
            settings,
            "CRYPTO_15M_FULL_RECOVERY_LOSSES",
        ) or 3,
        "partial_recovery_fraction": setting_float(
            settings,
            "CRYPTO_15M_PARTIAL_RECOVERY_FRACTION",
        ),
    }


def configured_crypto_15m_campaign_bot_count(settings):
    """Return the lane count from settings, clamped to a practical limit."""
    try:
        return max(1, min(5, setting_int(settings, "CRYPTO_15M_CAMPAIGN_BOT_COUNT")))
    except (TypeError, ValueError):
        return 1


def crypto_15m_campaign_bot_order(settings, portfolio):
    """Rotate first choice so Bot 1 does not always receive the top candidate."""
    count = configured_crypto_15m_campaign_bot_count(settings)
    try:
        stored_first = portfolio.get("crypto_15m_campaign_next_bot")
        if stored_first is None:
            campaign_rows = [
                row for row in portfolio.get("bets", [])
                if row.get("strategy_owner") == CRYPTO_15M_CAMPAIGN_OWNER
                and crypto_campaign_bot_number(row) <= count
            ]
            last_row = max(
                campaign_rows,
                key=lambda row: str(row.get("placed_at") or ""),
                default=None,
            )
            first = (crypto_campaign_bot_number(last_row) % count) + 1 if last_row else 1
        else:
            first = int(stored_first or 1)
    except (TypeError, ValueError):
        first = 1
    if first < 1 or first > count:
        first = 1
    return list(range(first, count + 1)) + list(range(1, first))


def advance_crypto_15m_campaign_bot_order(portfolio, bot_number, configured_count):
    try:
        count = max(1, min(5, int(configured_count or 1)))
        current = max(1, min(count, int(bot_number or 1)))
    except (TypeError, ValueError):
        count, current = 1, 1
    portfolio["crypto_15m_campaign_next_bot"] = (current % count) + 1


def ensure_crypto_15m_campaign_bot_numbers(portfolio):
    """Persist Bot 1 on legacy campaign rows while preserving their ownership."""
    changed = False
    for row in [*(portfolio.get("history") or []), *(portfolio.get("bets") or [])]:
        if row.get("strategy_owner") != CRYPTO_15M_CAMPAIGN_OWNER:
            continue
        number = crypto_campaign_bot_number(row)
        campaign = dict(row.get("crypto_live_campaign") or {})
        if row.get("bot_number") != number:
            row["bot_number"] = number
            changed = True
        if campaign.get("bot_number") != number:
            campaign["bot_number"] = number
            row["crypto_live_campaign"] = campaign
            changed = True
    return changed


def crypto_15m_campaign_internal_goals(settings, strategy):
    """Keep the recovery ledger continuous when ordinary entries use units."""
    configured_goals = [float(value) for value in (strategy.get("goals") or [])]
    if not configured_goals:
        configured_goals = [max(0.01, float(strategy.get("configured_cycle_profit") or 1.0))]
    if not setting_bool(settings, "CRYPTO_15M_UNIT_STAKING_ENABLED"):
        return configured_goals
    return [
        *configured_goals,
        *([configured_goals[-1]] * max(0, 500 - len(configured_goals))),
    ]


def crypto_15m_continuous_opportunity_enabled(settings):
    """Return whether unit staking uses the cycle-free opportunity workflow."""
    return bool(
        setting_bool(settings, "CRYPTO_15M_UNIT_STAKING_ENABLED")
        and setting_bool(settings, "CRYPTO_15M_CONTINUOUS_OPPORTUNITY_MODE")
    )


def _crypto_15m_legacy_drawdown_for_migration(settings, portfolio, bot_number):
    """Capture the active legacy drawdown once without creating a new schedule."""
    profit_key = f"CRYPTO_15M_BOT_{bot_number}_CYCLE_PROFIT"
    count_key = f"CRYPTO_15M_BOT_{bot_number}_CYCLE_COUNT"
    cycle_profit = setting_float(settings, profit_key)
    if cycle_profit <= 0:
        cycle_profit = 2.0
    cycle_count = max(1, min(100, setting_int(settings, count_key) or 10))
    goals = [round(cycle_profit, 2)] * cycle_count
    goals.extend([goals[-1]] * max(0, 500 - len(goals)))
    campaign_id = str(
        settings.get(f"CRYPTO_15M_BOT_{bot_number}_CAMPAIGN_ID")
        or settings.get("CRYPTO_15M_CAMPAIGN_ID")
        or ""
    ).strip()
    legacy = build_crypto_15m_campaign_context(
        portfolio,
        local_date_key(),
        local_date_key,
        cycle_goals=goals,
        max_open=setting_int(settings, "CRYPTO_15M_MAX_OPEN") or 1,
        daily_loss_cap=setting_float(settings, "CRYPTO_15M_DAILY_LOSS_CAP"),
        daily_loss_cap_pct=setting_float(settings, "CRYPTO_15M_DAILY_LOSS_PCT"),
        fee_rate=setting_float(settings, "CRYPTO_SHADOW_FEE_RATE"),
        goal_tolerance=setting_float(settings, "CRYPTO_15M_GOAL_TOLERANCE"),
        campaign_id=campaign_id,
        bot_number=bot_number,
        include_daily_settled=lambda value: crypto_15m_daily_capacity_includes(
            portfolio,
            bot_number,
            value,
        ),
    )
    return round(max(0.0, -float(legacy.get("cycle_realized_profit") or 0)), 2)


def crypto_15m_high_water_drawdown_ledger(
    portfolio,
    bot_number,
    *,
    initial_drawdown=0.0,
    reference_time=None,
):
    """Maintain a durable per-bot high-water drawdown from settled unit bets."""
    reference_time = reference_time or utc_now()
    if reference_time.tzinfo is None:
        reference_time = reference_time.replace(tzinfo=timezone.utc)
    bot_number = max(1, min(5, crypto_campaign_bot_number({"bot_number": bot_number})))
    ledgers = portfolio.setdefault("crypto_15m_high_water_ledgers", {})
    key = str(bot_number)
    existing = dict(ledgers.get(key) or {})
    cutoff = parse_time(existing.get("migration_cutoff"))
    if not cutoff:
        cutoff = reference_time
        baseline_drawdown = round(max(0.0, float(initial_drawdown or 0)), 2)
        existing = {
            "version": 1,
            "mode": "continuous_high_water_drawdown",
            "bot_number": bot_number,
            "migration_cutoff": cutoff.replace(microsecond=0).isoformat(),
            "migrated_at": cutoff.replace(microsecond=0).isoformat(),
            "baseline_drawdown": baseline_drawdown,
            "migration_source": "legacy_active_cycle_drawdown",
        }
    elif cutoff.tzinfo is None:
        cutoff = cutoff.replace(tzinfo=timezone.utc)
    baseline_drawdown = round(
        max(0.0, float(existing.get("baseline_drawdown") or 0)),
        2,
    )

    rows = []
    seen = set()
    for row in [*(portfolio.get("history") or []), *(portfolio.get("bets") or [])]:
        if row.get("strategy_owner") != CRYPTO_15M_CAMPAIGN_OWNER:
            continue
        if crypto_campaign_bot_number(row) != bot_number:
            continue
        if str(row.get("status") or "").lower() != "settled":
            continue
        if str(row.get("result") or "").upper() not in {"WIN", "LOSS"}:
            continue
        settled_at = parse_time(row.get("settled_at") or row.get("closed_at"))
        if not settled_at:
            continue
        if settled_at.tzinfo is None:
            settled_at = settled_at.replace(tzinfo=timezone.utc)
        if settled_at <= cutoff or settled_at > reference_time:
            continue
        row_id = str(
            row.get("id")
            or f"{row.get('ticker')}|{row.get('placed_at')}|{row.get('stake')}|{settled_at.isoformat()}"
        )
        if row_id in seen:
            continue
        seen.add(row_id)
        rows.append((settled_at, row_id, float(row.get("profit") or 0), row))
    rows.sort(key=lambda item: (item[0], item[1]))

    running_profit = -baseline_drawdown
    high_water_profit = 0.0
    wins = 0
    losses = 0
    for _settled_at, _row_id, profit, row in rows:
        running_profit += profit
        high_water_profit = max(high_water_profit, running_profit)
        if str(row.get("result") or "").upper() == "WIN":
            wins += 1
        else:
            losses += 1
    outstanding_drawdown = max(0.0, high_water_profit - running_profit)
    rounded_current_profit = round(running_profit, 2)
    if abs(rounded_current_profit) < 0.005:
        rounded_current_profit = 0.0
    snapshot = {
        **existing,
        "version": 1,
        "mode": "continuous_high_water_drawdown",
        "bot_number": bot_number,
        "baseline_drawdown": baseline_drawdown,
        "current_profit": rounded_current_profit,
        "high_water_profit": round(high_water_profit, 2),
        "outstanding_drawdown": round(outstanding_drawdown, 2),
        "settled_since_migration": len(rows),
        "wins_since_migration": wins,
        "losses_since_migration": losses,
        "last_settled_at": rows[-1][0].replace(microsecond=0).isoformat() if rows else None,
        "updated_at": reference_time.replace(microsecond=0).isoformat(),
    }
    ledgers[key] = snapshot
    return dict(snapshot)


def crypto_15m_pooled_high_water_drawdown_ledger(
    portfolio,
    *,
    initial_drawdown=0.0,
    reference_time=None,
):
    """Maintain one durable high-water drawdown across all campaign bot lanes."""
    reference_time = reference_time or utc_now()
    if reference_time.tzinfo is None:
        reference_time = reference_time.replace(tzinfo=timezone.utc)
    existing = dict(portfolio.get("crypto_15m_pooled_high_water_ledger") or {})
    cutoff = parse_time(existing.get("migration_cutoff"))
    if not cutoff:
        cutoff = reference_time
        baseline_drawdown = round(max(0.0, float(initial_drawdown or 0)), 2)
        existing = {
            "version": 1,
            "mode": "pooled_continuous_high_water_drawdown",
            "migration_cutoff": cutoff.replace(microsecond=0).isoformat(),
            "migrated_at": cutoff.replace(microsecond=0).isoformat(),
            "baseline_drawdown": baseline_drawdown,
            "migration_source": "sum_of_active_per_bot_high_water_drawdowns",
        }
    elif cutoff.tzinfo is None:
        cutoff = cutoff.replace(tzinfo=timezone.utc)
    baseline_drawdown = round(
        max(0.0, float(existing.get("baseline_drawdown") or 0)),
        2,
    )

    rows = []
    seen = set()
    for row in [*(portfolio.get("history") or []), *(portfolio.get("bets") or [])]:
        if row.get("strategy_owner") != CRYPTO_15M_CAMPAIGN_OWNER:
            continue
        if str(row.get("status") or "").lower() != "settled":
            continue
        if str(row.get("result") or "").upper() not in {"WIN", "LOSS"}:
            continue
        settled_at = parse_time(row.get("settled_at") or row.get("closed_at"))
        if not settled_at:
            continue
        if settled_at.tzinfo is None:
            settled_at = settled_at.replace(tzinfo=timezone.utc)
        if settled_at <= cutoff or settled_at > reference_time:
            continue
        row_id = str(
            row.get("id")
            or f"{row.get('ticker')}|{row.get('placed_at')}|{row.get('stake')}|{settled_at.isoformat()}"
        )
        if row_id in seen:
            continue
        seen.add(row_id)
        rows.append((settled_at, row_id, float(row.get("profit") or 0), row))
    rows.sort(key=lambda item: (item[0], item[1]))

    running_profit = -baseline_drawdown
    high_water_profit = 0.0
    wins = 0
    losses = 0
    bot_numbers = set()
    for _settled_at, _row_id, profit, row in rows:
        running_profit += profit
        high_water_profit = max(high_water_profit, running_profit)
        bot_numbers.add(crypto_campaign_bot_number(row))
        if str(row.get("result") or "").upper() == "WIN":
            wins += 1
        else:
            losses += 1
    outstanding_drawdown = max(0.0, high_water_profit - running_profit)
    rounded_current_profit = round(running_profit, 2)
    if abs(rounded_current_profit) < 0.005:
        rounded_current_profit = 0.0
    snapshot = {
        **existing,
        "version": 1,
        "mode": "pooled_continuous_high_water_drawdown",
        "baseline_drawdown": baseline_drawdown,
        "current_profit": rounded_current_profit,
        "high_water_profit": round(high_water_profit, 2),
        "outstanding_drawdown": round(outstanding_drawdown, 2),
        "settled_since_migration": len(rows),
        "wins_since_migration": wins,
        "losses_since_migration": losses,
        "contributing_bot_numbers": sorted(bot_numbers),
        "last_settled_at": rows[-1][0].replace(microsecond=0).isoformat() if rows else None,
        "updated_at": reference_time.replace(microsecond=0).isoformat(),
    }
    portfolio["crypto_15m_pooled_high_water_ledger"] = snapshot
    return dict(snapshot)


def _crypto_15m_pooled_drawdown_for_migration(settings, portfolio, reference_time):
    """Snapshot current lane drawdowns once when the pooled ledger is introduced."""
    total = 0.0
    for bot_number in range(1, configured_crypto_15m_campaign_bot_count(settings) + 1):
        ledgers = portfolio.get("crypto_15m_high_water_ledgers") or {}
        initial_drawdown = 0.0
        if not (ledgers.get(str(bot_number)) or {}).get("migration_cutoff"):
            initial_drawdown = _crypto_15m_legacy_drawdown_for_migration(
                settings,
                portfolio,
                bot_number,
            )
        snapshot = crypto_15m_high_water_drawdown_ledger(
            portfolio,
            bot_number,
            initial_drawdown=initial_drawdown,
            reference_time=reference_time,
        )
        total += max(0.0, float(snapshot.get("outstanding_drawdown") or 0))
    return round(total, 2)


def crypto_15m_recovery_expiry_key(row):
    close_time = parse_time((row or {}).get("close_time"))
    if close_time:
        if close_time.tzinfo is None:
            close_time = close_time.replace(tzinfo=timezone.utc)
        return close_time.astimezone(timezone.utc).replace(microsecond=0).isoformat()
    return str(
        (row or {}).get("close_time")
        or (row or {}).get("event_ticker")
        or (row or {}).get("ticker")
        or "unknown"
    )


def crypto_15m_open_recovery_reservations(portfolio):
    """Reserve open recovery profit so parallel bots cannot target it twice."""
    rows = []
    by_expiry = {}
    for row in portfolio.get("bets") or []:
        if row.get("strategy_owner") != CRYPTO_15M_CAMPAIGN_OWNER:
            continue
        if str(row.get("status") or "").lower() != "open":
            continue
        bounded = _bounded_recovery_metadata(row)
        bonus_units = max(0.0, _recovery_number(bounded.get("bonus_units")))
        if bonus_units <= 0.0001:
            continue
        reserved_profit = max(
            0.0,
            _recovery_number(bounded.get("allocated_recovery_profit")),
        )
        if reserved_profit <= 0:
            reserved_profit = bonus_units * max(
                0.0,
                _recovery_number(bounded.get("estimated_profit_per_unit_after_fee")),
            )
        if reserved_profit <= 0:
            total_units = max(
                bonus_units,
                _recovery_number(bounded.get("total_units")),
            )
            ratio = min(1.0, bonus_units / total_units) if total_units > 0 else 0.0
            contracts = max(0.0, _recovery_number(row.get("contracts"))) * ratio
            price_fraction = max(0.0, _recovery_number(row.get("entry_price"))) / 100.0
            fee = max(0.0, _recovery_number(row.get("fee"))) * ratio
            reserved_profit = max(0.0, contracts * (1.0 - price_fraction) - fee)
        expiry_key = crypto_15m_recovery_expiry_key(row)
        item = {
            "bet_id": row.get("id"),
            "ticker": row.get("ticker"),
            "asset": row.get("asset"),
            "bot_number": crypto_campaign_bot_number(row),
            "close_time": row.get("close_time"),
            "expiry_key": expiry_key,
            "bonus_units": round(bonus_units, 4),
            "reserved_recovery_profit": round(reserved_profit, 2),
        }
        rows.append(item)
        expiry = by_expiry.setdefault(
            expiry_key,
            {"count": 0, "reserved_recovery_profit": 0.0},
        )
        expiry["count"] += 1
        expiry["reserved_recovery_profit"] += reserved_profit
    for value in by_expiry.values():
        value["reserved_recovery_profit"] = round(
            value["reserved_recovery_profit"],
            2,
        )
    return {
        "open_overlay_count": len(rows),
        "reserved_recovery_profit": round(
            sum(row["reserved_recovery_profit"] for row in rows),
            2,
        ),
        "by_expiry": by_expiry,
        "rows": rows,
    }


def crypto_15m_cross_bot_cap_recovery(settings, portfolio, date_key=None):
    """Allocate profitable lanes' daily gains once across losing bot lanes."""
    enabled = setting_bool(
        settings,
        "CRYPTO_15M_CROSS_BOT_CAP_RECOVERY_ENABLED",
    )
    bot_count = configured_crypto_15m_campaign_bot_count(settings)
    date_key = date_key or local_date_key()
    profits = {number: 0.0 for number in range(1, bot_count + 1)}
    seen = set()
    for row in [*(portfolio.get("history") or []), *(portfolio.get("bets") or [])]:
        if row.get("strategy_owner") != CRYPTO_15M_CAMPAIGN_OWNER:
            continue
        if str(row.get("status") or "").lower() != "settled":
            continue
        stamp = row.get("settled_at") or row.get("placed_at") or row.get("created_at")
        number = crypto_campaign_bot_number(row)
        if (
            local_date_key(stamp) != date_key
            or not crypto_15m_daily_capacity_includes(
                portfolio,
                number,
                stamp,
            )
        ):
            continue
        row_id = str(
            row.get("id")
            or f"{row.get('ticker')}|{stamp}|{row.get('profit')}|{row.get('bot_number')}"
        )
        if row_id in seen:
            continue
        seen.add(row_id)
        if number not in profits:
            continue
        profits[number] = round(
            profits[number] + float(row.get("profit") or 0),
            2,
        )

    positive_pool = round(sum(max(0.0, value) for value in profits.values()), 2)
    losses = {
        number: max(0.0, -value)
        for number, value in profits.items()
    }
    total_loss = sum(losses.values())
    allocations = {number: 0.0 for number in profits}
    distributable = min(positive_pool, total_loss)
    if enabled and distributable > 0.0 and total_loss > 0.0:
        for number, loss in losses.items():
            if loss <= 0:
                continue
            allocations[number] = round(
                min(loss, distributable * loss / total_loss),
                2,
            )
    return {
        "enabled": enabled,
        "mode": "positive_lane_profit_pro_rata_to_losing_lanes",
        "date": date_key,
        "bot_realized_profit": {
            str(number): round(value, 2)
            for number, value in profits.items()
        },
        "positive_profit_pool": positive_pool,
        "total_losing_lane_drawdown": round(total_loss, 2),
        "distributable_recovery_credit": round(distributable if enabled else 0.0, 2),
        "allocations": {
            str(number): round(value, 2)
            for number, value in allocations.items()
        },
    }


def crypto_15m_campaign_lane_context(settings, portfolio, bot_number):
    if crypto_15m_continuous_opportunity_enabled(settings):
        reference_time = utc_now()
        ledgers = portfolio.get("crypto_15m_high_water_ledgers") or {}
        initial_drawdown = 0.0
        if not (ledgers.get(str(bot_number)) or {}).get("migration_cutoff"):
            initial_drawdown = _crypto_15m_legacy_drawdown_for_migration(
                settings,
                portfolio,
                bot_number,
            )
        ledger = crypto_15m_high_water_drawdown_ledger(
            portfolio,
            bot_number,
            initial_drawdown=initial_drawdown,
            reference_time=reference_time,
        )
        pooled_enabled = setting_bool(
            settings,
            "CRYPTO_15M_POOLED_RECOVERY_ENABLED",
        )
        pooled_existing = portfolio.get("crypto_15m_pooled_high_water_ledger") or {}
        pooled_initial_drawdown = 0.0
        if pooled_enabled and not pooled_existing.get("migration_cutoff"):
            pooled_initial_drawdown = _crypto_15m_pooled_drawdown_for_migration(
                settings,
                portfolio,
                reference_time,
            )
        pooled_ledger = (
            crypto_15m_pooled_high_water_drawdown_ledger(
                portfolio,
                initial_drawdown=pooled_initial_drawdown,
                reference_time=reference_time,
            )
            if pooled_enabled
            else {}
        )
        recovery_reservations = (
            crypto_15m_open_recovery_reservations(portfolio)
            if pooled_enabled
            else {}
        )
        context = build_crypto_15m_campaign_context(
            portfolio,
            local_date_key(),
            local_date_key,
            cycle_goals=(),
            max_open=setting_int(settings, "CRYPTO_15M_MAX_OPEN") or 1,
            daily_loss_cap=setting_float(settings, "CRYPTO_15M_DAILY_LOSS_CAP"),
            daily_loss_cap_pct=setting_float(settings, "CRYPTO_15M_DAILY_LOSS_PCT"),
            fee_rate=setting_float(settings, "CRYPTO_SHADOW_FEE_RATE"),
            campaign_id="",
            bot_number=bot_number,
            include_daily_settled=lambda value: crypto_15m_daily_capacity_includes(
                portfolio,
                bot_number,
                value,
            ),
        )
        cross_bot_cap_recovery = crypto_15m_cross_bot_cap_recovery(
            settings,
            portfolio,
        )
        cross_bot_recovery_credit = float(
            (cross_bot_cap_recovery.get("allocations") or {}).get(
                str(bot_number),
                0.0,
            )
        )
        effective_bot_daily_profit = round(
            float(context.get("bot_daily_realized_profit") or 0)
            + cross_bot_recovery_credit,
            2,
        )
        daily_loss_remaining = round(
            max(
                0.0,
                float(context.get("daily_loss_cap") or 0)
                + effective_bot_daily_profit
                - float(context.get("bot_daily_open_risk") or 0),
            ),
            2,
        )
        daily_loss_cap_hit = bool(
            float(context.get("daily_loss_cap") or 0) > 0
            and daily_loss_remaining <= 0
        )
        unit_snapshot = crypto_15m_unit_bankroll_base(portfolio)
        unit_size = round(
            float(unit_snapshot.get("balance") or 0)
            * max(0.0, setting_float(settings, "CRYPTO_15M_UNIT_SIZE_PCT"))
            / 100.0,
            2,
        )
        unit_capacity_limited = bool(
            float(context.get("daily_loss_cap") or 0) > 0
            and (unit_size <= 0 or daily_loss_remaining + 1e-9 < unit_size)
        )
        context.update({
            "cross_bot_cap_recovery": cross_bot_cap_recovery,
            "cross_bot_recovery_credit": round(cross_bot_recovery_credit, 2),
            "effective_bot_daily_realized_profit": effective_bot_daily_profit,
            "daily_loss_remaining": daily_loss_remaining,
            "daily_loss_cap_hit": daily_loss_cap_hit,
            "minimum_unit_capacity": unit_size,
            "unit_capacity_available": not unit_capacity_limited,
            "unit_capacity_limited": unit_capacity_limited,
        })
        context.update({
            "active": not daily_loss_cap_hit and not unit_capacity_limited,
            "status": (
                "daily_loss_cap"
                if daily_loss_cap_hit
                else "unit_capacity"
                if unit_capacity_limited
                else "active"
            ),
            "complete": False,
            "campaign_id": "",
            "cycle_goals": [],
            "cycle_targets": [],
            "cycle_index": 0,
            "cycle_number": 0,
            "cycle_goal": 0.0,
            "cycle_target": 0.0,
            "cycle_start_profit": 0.0,
            "cycle_realized_profit": 0.0,
            "cycle_loss_count": 0,
            "cycle_win_count": 0,
            "target_remaining": 0.0,
            "progression_mode": "continuous_opportunity_units",
            "continuous_opportunity_mode": True,
            "cycle_workflow_enabled": False,
            "cycle_tracking_only": False,
            "cycle_completion_blocks": False,
            "continuous_recovery_ledger": True,
            "high_water_drawdown": ledger,
            "outstanding_drawdown": ledger["outstanding_drawdown"],
            "realized_drawdown": ledger["outstanding_drawdown"],
            "pooled_recovery_enabled": pooled_enabled,
            "pooled_high_water_drawdown": pooled_ledger,
            "pooled_outstanding_drawdown": float(
                pooled_ledger.get("outstanding_drawdown") or 0
            ),
            "recovery_reservations": recovery_reservations,
            "partial_recovery_enabled": False,
            "partial_recovery_active": False,
            "configured_cycle_profit": 0.0,
            "configured_cycle_count": 0,
            "effective_cycle_count": 0,
        })
        return context

    strategy = crypto_15m_campaign_strategy(
        settings,
        bot_number=bot_number,
        portfolio=portfolio,
    )
    context = build_crypto_15m_campaign_context(
        portfolio,
        local_date_key(),
        local_date_key,
        cycle_goals=crypto_15m_campaign_internal_goals(settings, strategy),
        max_open=setting_int(settings, "CRYPTO_15M_MAX_OPEN") or 1,
        daily_loss_cap=setting_float(settings, "CRYPTO_15M_DAILY_LOSS_CAP"),
        daily_loss_cap_pct=setting_float(settings, "CRYPTO_15M_DAILY_LOSS_PCT"),
        fee_rate=setting_float(settings, "CRYPTO_SHADOW_FEE_RATE"),
        goal_tolerance=setting_float(settings, "CRYPTO_15M_GOAL_TOLERANCE"),
        partial_recovery_enabled=strategy["partial_recovery_enabled"],
        full_recovery_losses=strategy["full_recovery_losses"],
        partial_recovery_fraction=strategy["partial_recovery_fraction"],
        campaign_id=strategy["campaign_id"],
        bot_number=bot_number,
        include_daily_settled=lambda value: crypto_15m_daily_capacity_includes(
            portfolio,
            bot_number,
            value,
        ),
    )
    context["hybrid_strategy_active"] = strategy["hybrid_active"]
    context["hybrid_effective_date"] = strategy["effective_date"]
    context["goal_schedule_source"] = strategy["goal_schedule_source"]
    context["goal_schedule_override_date"] = strategy["goal_schedule_override_date"]
    context["goal_schedule_key"] = strategy["goal_schedule_key"]
    context["goal_schedule_locked"] = strategy["goal_schedule_locked"]
    context["configured_cycle_profit"] = strategy["configured_cycle_profit"]
    context["configured_cycle_profit_key"] = strategy["configured_cycle_profit_key"]
    context["configured_cycle_count"] = strategy["configured_cycle_count"]
    context["configured_cycle_count_key"] = strategy["configured_cycle_count_key"]
    context["effective_cycle_count"] = strategy["effective_cycle_count"]
    if setting_bool(settings, "CRYPTO_15M_UNIT_STAKING_ENABLED"):
        context["cycle_goals"] = list(strategy["goals"])
        context["cycle_targets"] = []
        context["cycle_tracking_only"] = True
        context["cycle_completion_blocks"] = False
        context["continuous_recovery_ledger"] = True
    return context


def crypto_15m_campaign_context(settings, portfolio, bot_number=None):
    if bot_number is not None:
        return crypto_15m_campaign_lane_context(settings, portfolio, bot_number)

    configured_count = configured_crypto_15m_campaign_bot_count(settings)
    bots = [
        crypto_15m_campaign_lane_context(settings, portfolio, number)
        for number in range(1, configured_count + 1)
    ]
    known_numbers = {
        crypto_campaign_bot_number(row)
        for row in [*(portfolio.get("history") or []), *(portfolio.get("bets") or [])]
        if row.get("strategy_owner") == CRYPTO_15M_CAMPAIGN_OWNER
    }
    disabled_numbers = sorted(number for number in known_numbers if number > configured_count)
    disabled_bots = [
        {
            **crypto_15m_campaign_lane_context(settings, portfolio, number),
            "configured": False,
        }
        for number in disabled_numbers
    ]
    visible_bots = [*bots, *disabled_bots]
    max_open_per_bot = setting_int(settings, "CRYPTO_15M_MAX_OPEN") or 1
    unit_staking_enabled = setting_bool(settings, "CRYPTO_15M_UNIT_STAKING_ENABLED")
    continuous_mode = crypto_15m_continuous_opportunity_enabled(settings)
    disabled_open_count = sum(
        int(row.get("bot_live_open_count") or 0)
        for row in disabled_bots
    )
    available_numbers = [
        row["bot_number"]
        for row in bots
        if (continuous_mode or unit_staking_enabled or not row.get("complete"))
        and not row.get("daily_loss_cap_hit")
        and row.get("unit_capacity_available", True)
        and int(row.get("bot_live_open_count") or 0) < max_open_per_bot
    ]
    primary = dict(bots[0])
    all_complete = bool(
        not continuous_mode
        and not unit_staking_enabled
        and bots
        and all(row.get("complete") for row in bots)
    )
    all_stopped = bool(bots) and all(
        (
            (not continuous_mode and not unit_staking_enabled and row.get("complete"))
            or row.get("daily_loss_cap_hit")
            or row.get("unit_capacity_limited")
        )
        for row in bots
    )
    unit_snapshot = (
        crypto_15m_unit_bankroll_base(portfolio)
        if unit_staking_enabled
        else {}
    )
    unit_size_pct = max(0.0, setting_float(settings, "CRYPTO_15M_UNIT_SIZE_PCT"))
    pooled_recovery_enabled = bool(
        continuous_mode
        and setting_bool(settings, "CRYPTO_15M_POOLED_RECOVERY_ENABLED")
    )
    pooled_high_water_drawdown = dict(
        next(
            (
                row.get("pooled_high_water_drawdown")
                for row in bots
                if row.get("pooled_high_water_drawdown")
            ),
            {},
        )
        or {}
    )
    recovery_reservations = dict(
        next(
            (
                row.get("recovery_reservations")
                for row in bots
                if row.get("recovery_reservations")
            ),
            {},
        )
        or {}
    )
    per_bot_outstanding_drawdown = round(
        sum(float(row.get("outstanding_drawdown") or 0) for row in bots),
        2,
    )
    primary.update({
        "aggregate": True,
        "configured_bot_count": configured_count,
        "enabled_bot_count": configured_count,
        "bots": bots,
        "disabled_bots": disabled_bots,
        "available_bot_numbers": available_numbers,
        "available_bot_count": len(available_numbers),
        "complete_bot_count": sum(1 for row in bots if row.get("complete")),
        "status": "complete" if all_complete else "daily_loss_cap" if all_stopped else "active",
        "complete": all_complete,
        "realized_profit": round(sum(float(row.get("realized_profit") or 0) for row in bots), 2),
        "settled_count": sum(int(row.get("settled_count") or 0) for row in bots),
        "primary_wins": sum(int(row.get("primary_wins") or 0) for row in bots),
        "primary_losses": sum(
            max(
                0,
                int(row.get("settled_count") or 0)
                - int(row.get("primary_wins") or 0),
            )
            for row in bots
        ),
        "realized_drawdown": (
            round(float(pooled_high_water_drawdown.get("outstanding_drawdown") or 0), 2)
            if pooled_recovery_enabled
            else round(sum(float(row.get("realized_drawdown") or 0) for row in bots), 2)
        ),
        "target_remaining": (
            0.0
            if continuous_mode
            else round(sum(float(row.get("target_remaining") or 0) for row in bots), 2)
        ),
        "bot_live_open_count": sum(int(row.get("bot_live_open_count") or 0) for row in visible_bots),
        "campaign_open_count": sum(int(row.get("campaign_open_count") or 0) for row in visible_bots),
        "max_open_per_bot": max_open_per_bot,
        "max_open": configured_count * max_open_per_bot + disabled_open_count,
        "daily_loss_cap": round(sum(float(row.get("daily_loss_cap") or 0) for row in bots), 2),
        "daily_loss_remaining": round(sum(float(row.get("daily_loss_remaining") or 0) for row in bots), 2),
        "daily_loss_cap_hit": all_stopped and not all_complete,
        "unit_capacity_limited_bot_numbers": [
            int(row.get("bot_number") or 0)
            for row in bots
            if row.get("unit_capacity_limited")
        ],
        "bot_daily_realized_profit": round(sum(float(row.get("bot_daily_realized_profit") or 0) for row in bots), 2),
        "bot_daily_open_risk": round(sum(float(row.get("bot_daily_open_risk") or 0) for row in visible_bots), 2),
        "unit_staking_enabled": unit_staking_enabled,
        "sizing_mode": "probability_edge_kelly_units" if unit_staking_enabled else "profit_cycles",
        "progression_mode": (
            "continuous_opportunity_units" if continuous_mode else primary.get("progression_mode")
        ),
        "continuous_opportunity_mode": continuous_mode,
        "cycle_workflow_enabled": not continuous_mode,
        "cycle_tracking_only": bool(unit_staking_enabled and not continuous_mode),
        "cycle_completion_blocks": bool(not unit_staking_enabled and not continuous_mode),
        "outstanding_drawdown": (
            round(float(pooled_high_water_drawdown.get("outstanding_drawdown") or 0), 2)
            if pooled_recovery_enabled
            else per_bot_outstanding_drawdown
        ),
        "per_bot_outstanding_drawdown": per_bot_outstanding_drawdown,
        "pooled_recovery_enabled": pooled_recovery_enabled,
        "pooled_high_water_drawdown": pooled_high_water_drawdown,
        "recovery_reservations": recovery_reservations,
        "high_water_drawdowns": [
            dict(row.get("high_water_drawdown") or {}) for row in bots
        ] if continuous_mode else [],
        "unit_size_pct": unit_size_pct if unit_staking_enabled else 0.0,
        "unit_bankroll_snapshot": unit_snapshot,
        "unit_size": (
            round(float(unit_snapshot.get("balance") or 0) * unit_size_pct / 100.0, 2)
            if unit_staking_enabled
            else 0.0
        ),
        "unit_tiers": crypto_15m_unit_tiers(settings) if unit_staking_enabled else {},
        "bounded_unit_recovery": {
            "enabled": bool(
                unit_staking_enabled
                and setting_bool(settings, "CRYPTO_15M_UNIT_RECOVERY_ENABLED")
            ),
            "minimum_base_units": setting_float(
                settings,
                "CRYPTO_15M_UNIT_RECOVERY_MIN_BASE_UNITS",
            ),
            "minimum_probability_units": setting_float(
                settings,
                "CRYPTO_15M_UNIT_RECOVERY_MIN_PROBABILITY_UNITS",
            ),
            "target_drawdown_fraction": setting_float(
                settings,
                "CRYPTO_15M_UNIT_RECOVERY_TARGET_DRAWDOWN_FRACTION",
            ),
            "maximum_bonus_units": setting_float(
                settings,
                "CRYPTO_15M_UNIT_RECOVERY_MAX_BONUS_UNITS",
            ),
            "maximum_total_units": setting_float(
                settings,
                "CRYPTO_15M_UNIT_RECOVERY_MAX_TOTAL_UNITS",
            ),
            "pooled_recovery_enabled": pooled_recovery_enabled,
            "maximum_overlays_per_expiry": setting_int(
                settings,
                "CRYPTO_15M_RECOVERY_MAX_OVERLAYS_PER_EXPIRY",
            ),
            "open_overlay_count": int(
                recovery_reservations.get("open_overlay_count") or 0
            ),
            "reserved_recovery_profit": float(
                recovery_reservations.get("reserved_recovery_profit") or 0
            ),
            "legacy_full_recovery_used": False,
        },
    })
    return primary


def crypto_low_edge_pilot_rows(portfolio, status=None):
    rows = [
        row
        for row in portfolio.get("bets", [])
        if (row.get("low_edge_pilot") or {}).get("active")
        and row.get("strategy_owner") == CRYPTO_15M_CAMPAIGN_OWNER
    ]
    if status is not None:
        rows = [row for row in rows if row.get("status") == status]
    return rows


def crypto_low_edge_pilot_review(
    settings,
    portfolio,
    candidate,
    bot_number,
):
    edge = float(candidate.get("edge") or 0)
    confidence = float(candidate.get("confidence") or 0)
    price = float(candidate.get("entry_price") or 0)
    minimum_edge = setting_float(settings, "CRYPTO_15M_LOW_EDGE_PILOT_MIN_EDGE")
    maximum_edge = setting_float(settings, "CRYPTO_15M_LOW_EDGE_PILOT_MAX_EDGE")
    minimum_confidence = setting_float(
        settings,
        "CRYPTO_15M_LOW_EDGE_PILOT_MIN_CONFIDENCE",
    )
    minimum_price = setting_float(
        settings,
        "CRYPTO_15M_LOW_EDGE_PILOT_MIN_PRICE_CENTS",
    )
    maximum_price = setting_float(
        settings,
        "CRYPTO_15M_LOW_EDGE_PILOT_MAX_PRICE_CENTS",
    )
    official_rotation = setting_bool(
        settings,
        "CRYPTO_15M_LOW_EDGE_OFFICIAL_ROTATION",
    )
    candidate_match = bool(
        setting_bool(settings, "CRYPTO_15M_LOW_EDGE_PILOT_ENABLED")
        and minimum_edge <= edge < maximum_edge
        and minimum_price <= price <= maximum_price
        and confidence >= minimum_confidence
    )
    review = {
        "enabled": setting_bool(
            settings,
            "CRYPTO_15M_LOW_EDGE_PILOT_ENABLED",
        ),
        "official_rotation": official_rotation,
        "candidate_match": candidate_match,
        "active": False,
        "eligible": False,
        "affects_global_edge_floor": False,
        "base_cycle_only": False,
        "bot_number": bot_number,
        "edge": round(edge, 4),
        "confidence": round(confidence, 4),
        "entry_price": round(price, 4),
        "minimum_edge": minimum_edge,
        "maximum_edge_exclusive": maximum_edge,
        "minimum_confidence": minimum_confidence,
        "minimum_price": minimum_price,
        "maximum_price": maximum_price,
        "max_open": max(
            0,
            setting_int(settings, "CRYPTO_15M_LOW_EDGE_PILOT_MAX_OPEN"),
        ),
        "max_settled": (
            0
            if official_rotation
            else max(
                0,
                setting_int(settings, "CRYPTO_15M_LOW_EDGE_PILOT_MAX_SETTLED"),
            )
        ),
    }
    if not candidate_match:
        review["reason"] = "not_low_edge_pilot_candidate"
        return review
    open_count = len(crypto_low_edge_pilot_rows(portfolio, status="open"))
    settled_count = len(crypto_low_edge_pilot_rows(portfolio, status="settled"))
    review["open_count"] = open_count
    review["settled_count"] = settled_count
    if review["max_open"] > 0 and open_count >= review["max_open"]:
        review["reason"] = (
            "campaign_low_edge_official_open_limit"
            if official_rotation
            else "campaign_low_edge_pilot_open_limit"
        )
        return review
    if review["max_settled"] > 0 and settled_count >= review["max_settled"]:
        review["reason"] = "campaign_low_edge_pilot_sample_complete"
        return review
    review["eligible"] = True
    review["reason"] = (
        "low_edge_official_candidate"
        if official_rotation
        else "low_edge_pilot_candidate"
    )
    return review


def crypto_directional_recovery_breaker(settings, portfolio, side, now=None):
    enabled = setting_bool(
        settings,
        "CRYPTO_15M_DIRECTIONAL_RECOVERY_BREAKER_ENABLED",
    )
    selected_side = str(side or "").strip().lower()
    loss_threshold = max(
        1,
        setting_int(
            settings,
            "CRYPTO_15M_DIRECTIONAL_RECOVERY_BREAKER_LOSS_COUNT",
        ),
    )
    lookback_minutes = max(
        1.0,
        setting_float(
            settings,
            "CRYPTO_15M_DIRECTIONAL_RECOVERY_BREAKER_LOOKBACK_MINUTES",
        ),
    )
    minimum_bots = max(
        1,
        setting_int(
            settings,
            "CRYPTO_15M_DIRECTIONAL_RECOVERY_BREAKER_MIN_BOTS",
        ),
    )
    review = {
        "enabled": enabled,
        "active": False,
        "reason": "disabled" if not enabled else "below_loss_threshold",
        "side": selected_side,
        "loss_threshold": loss_threshold,
        "lookback_minutes": lookback_minutes,
        "minimum_distinct_bots": minimum_bots,
        "loss_count": 0,
        "distinct_bot_count": 0,
        "triggered_at": None,
        "losses": [],
    }
    if not enabled or selected_side not in {"yes", "no"}:
        return review

    reference_time = now or utc_now()
    if reference_time.tzinfo is None:
        reference_time = reference_time.replace(tzinfo=timezone.utc)
    cutoff = reference_time - timedelta(minutes=lookback_minutes)
    losses = []
    for row in portfolio.get("bets") or []:
        if (
            row.get("strategy_owner") != CRYPTO_15M_CAMPAIGN_OWNER
            or row.get("status") != "settled"
            or str(row.get("result") or "").upper() != "LOSS"
            or str(row.get("side") or "").lower() != selected_side
        ):
            continue
        campaign = row.get("crypto_live_campaign") or {}
        if campaign.get("role") not in (None, "primary"):
            continue
        settled_at = parse_time(row.get("settled_at"))
        if not settled_at:
            continue
        if settled_at.tzinfo is None:
            settled_at = settled_at.replace(tzinfo=timezone.utc)
        if settled_at < cutoff or settled_at > reference_time:
            continue
        losses.append({
            "ticker": row.get("ticker"),
            "asset": row.get("asset"),
            "bot_number": crypto_campaign_bot_number(row),
            "settled_at": settled_at.isoformat(),
            "profit": row.get("profit"),
        })

    losses.sort(key=lambda row: row["settled_at"])
    distinct_bots = {row.get("bot_number") for row in losses if row.get("bot_number")}
    review["loss_count"] = len(losses)
    review["distinct_bot_count"] = len(distinct_bots)
    review["losses"] = sorted(losses, key=lambda row: row["settled_at"])[-loss_threshold:]
    if len(losses) >= loss_threshold and len(distinct_bots) >= minimum_bots:
        review["active"] = True
        review["reason"] = "same_direction_cross_bot_loss_cluster"
        for index in range(loss_threshold - 1, len(losses)):
            prefix = losses[: index + 1]
            prefix_bots = {
                row.get("bot_number")
                for row in prefix
                if row.get("bot_number")
            }
            if len(prefix_bots) >= minimum_bots:
                review["triggered_at"] = prefix[-1]["settled_at"]
                break
    elif len(losses) >= loss_threshold:
        review["reason"] = "loss_threshold_without_cross_bot_cluster"
    return review


def crypto_directional_recovery_cooldown(
    settings,
    portfolio,
    bot_number,
    now=None,
):
    """Temporarily cap recovery sizing after a cross-bot directional cluster."""
    attempt_limit = max(
        0,
        setting_int(settings, "CRYPTO_15M_DIRECTIONAL_RECOVERY_COOLDOWN_BETS"),
    )
    review = {
        "enabled": bool(
            setting_bool(
                settings,
                "CRYPTO_15M_DIRECTIONAL_RECOVERY_BREAKER_ENABLED",
            )
            and attempt_limit > 0
        ),
        "active": False,
        "reason": "disabled",
        "bot_number": crypto_campaign_bot_number({"bot_number": bot_number}),
        "attempt_limit": attempt_limit,
        "attempts_used": 0,
        "attempts_remaining": attempt_limit,
        "triggered_at": None,
        "trigger_side": None,
    }
    if not review["enabled"]:
        return review

    clusters = [
        crypto_directional_recovery_breaker(
            settings,
            portfolio,
            side,
            now=now,
        )
        for side in ("yes", "no")
    ]
    active_clusters = [
        row for row in clusters
        if row.get("active") and row.get("triggered_at")
    ]
    if not active_clusters:
        review["reason"] = "no_active_directional_cluster"
        return review
    cluster = max(active_clusters, key=lambda row: row["triggered_at"])
    triggered_at = parse_time(cluster.get("triggered_at"))
    if not triggered_at:
        review["reason"] = "cluster_time_unavailable"
        return review
    if triggered_at.tzinfo is None:
        triggered_at = triggered_at.replace(tzinfo=timezone.utc)

    attempts = []
    for row in portfolio.get("bets") or []:
        campaign = row.get("crypto_live_campaign") or {}
        cooldown = campaign.get("directional_recovery_cooldown") or {}
        if (
            row.get("strategy_owner") != CRYPTO_15M_CAMPAIGN_OWNER
            or row.get("status") != "settled"
            or crypto_campaign_bot_number(row) != review["bot_number"]
            or not cooldown.get("active")
        ):
            continue
        settled_at = parse_time(row.get("settled_at"))
        if not settled_at:
            continue
        if settled_at.tzinfo is None:
            settled_at = settled_at.replace(tzinfo=timezone.utc)
        if settled_at > triggered_at:
            attempts.append({
                "ticker": row.get("ticker"),
                "result": row.get("result"),
                "settled_at": settled_at.isoformat(),
            })

    review.update({
        "active": len(attempts) < attempt_limit,
        "reason": (
            "directional_cluster_recovery_sizing_paused"
            if len(attempts) < attempt_limit
            else "cooldown_attempts_complete"
        ),
        "attempts_used": len(attempts),
        "attempts_remaining": max(0, attempt_limit - len(attempts)),
        "triggered_at": triggered_at.isoformat(),
        "trigger_side": cluster.get("side"),
        "cluster": cluster,
        "attempts": attempts,
    })
    return review


def crypto_15m_unit_tiers(settings):
    tiers = {
        0.5: {
            "minimum_win_probability": setting_float(
                settings,
                "CRYPTO_15M_UNIT_HALF_MIN_WIN_PROB",
            ),
            "minimum_win_probability_low": setting_float(
                settings,
                "CRYPTO_15M_UNIT_HALF_MIN_WIN_PROB_LOW",
            ),
            "minimum_confidence": setting_float(
                settings,
                "CRYPTO_15M_UNIT_HALF_MIN_CONFIDENCE",
            ),
            "minimum_edge": setting_float(
                settings,
                "CRYPTO_15M_UNIT_HALF_MIN_EDGE",
            ),
            "minimum_edge_low": setting_float(
                settings,
                "CRYPTO_15M_UNIT_HALF_MIN_EDGE_LOW",
            ),
        },
    }
    maximum = max(
        1,
        min(5, setting_int(settings, "CRYPTO_15M_UNIT_MAX_PER_MARKET")),
    )
    for units in range(1, maximum + 1):
        tiers[units] = {
            "minimum_win_probability": setting_float(
                settings,
                f"CRYPTO_15M_UNIT_{units}_MIN_WIN_PROB",
            ),
            "minimum_win_probability_low": setting_float(
                settings,
                f"CRYPTO_15M_UNIT_{units}_MIN_WIN_PROB_LOW",
            ),
            "minimum_confidence": setting_float(
                settings,
                f"CRYPTO_15M_UNIT_{units}_MIN_CONFIDENCE",
            ),
            "minimum_edge": setting_float(
                settings,
                f"CRYPTO_15M_UNIT_{units}_MIN_EDGE",
            ),
            "minimum_edge_low": setting_float(
                settings,
                f"CRYPTO_15M_UNIT_{units}_MIN_EDGE_LOW",
            ),
        }
    return tiers


def crypto_15m_unit_bankroll_base(portfolio):
    """Lock one crypto unit to the first observed equity for the local day."""
    day = local_date_key()
    snapshot = dict(portfolio.get("crypto_15m_unit_bankroll") or {})
    # A midnight reconciliation can temporarily expose only a few cents while
    # Kalshi is moving settlement cash.  Do not permanently lock that transient
    # value as the next day's bankroll base.
    if snapshot.get("date") == day and float(snapshot.get("balance") or 0) >= 1.0:
        return snapshot
    open_risk = sum(
        float(row.get("stake") or 0) + float(row.get("fee") or 0)
        for row in portfolio.get("bets") or []
        if row.get("status") == "open"
        and row.get("strategy_owner") == CRYPTO_15M_CAMPAIGN_OWNER
    )
    balance = max(0.0, float(portfolio.get("balance") or 0) + open_risk)
    snapshot = {
        "date": day,
        "balance": round(balance, 2),
        "source": "daily_crypto_equity_snapshot",
        "locked": True,
        "captured_at": iso_now(),
    }
    portfolio["crypto_15m_unit_bankroll"] = snapshot
    return snapshot


def crypto_execution_unit_cap(candidate):
    """Return the whole-unit execution cap, when live depth imposed one."""
    raw_cap = candidate.get("execution_unit_cap")
    if isinstance(raw_cap, dict):
        raw_cap = raw_cap.get("maximum_units")
    try:
        cap = int(math.floor(float(raw_cap)))
    except (TypeError, ValueError):
        return None
    return cap if cap >= 1 else None


def crypto_15m_sizing_probability(settings, candidate):
    """Return calibrated probability and a stricter lower bound for sizing.

    Candidate construction has already applied the evidence-weighted residual
    correction to the market probability.  Re-blending here would hide that
    probability's meaning and double-count market anchoring.  Instead, preserve
    the displayed calibrated interval and subtract a separately reported
    calibration-error reserve only from the sizing/Kelly lower bound.
    """
    probability = candidate.get("probability") or {}
    side = str(candidate.get("side") or "yes").lower()

    def selected(value):
        if value is None:
            return None
        parsed = float(value)
        return parsed if side == "yes" else 100.0 - parsed

    raw_probability = candidate.get("selected_side_probability")
    if raw_probability is None:
        raw_probability = selected(
            probability.get("p_yes")
            if probability.get("p_yes") is not None
            else probability.get("prob")
        )
    raw_low = candidate.get("selected_side_probability_low")
    if raw_low is None:
        raw_low = selected(
            probability.get("p_low")
            if side == "yes"
            else probability.get("p_high")
        )
    raw_high = candidate.get("selected_side_probability_high")
    if raw_high is None:
        raw_high = selected(
            probability.get("p_high")
            if side == "yes"
            else probability.get("p_low")
        )
    market_probability = selected(probability.get("market_implied_yes"))
    if market_probability is None:
        market_probability = float(candidate.get("entry_price") or 0)

    try:
        raw_probability = float(raw_probability)
        raw_low = float(raw_low)
        raw_high = float(raw_high)
        market_probability = float(market_probability)
        available = all(
            math.isfinite(value)
            for value in (raw_probability, raw_low, raw_high, market_probability)
        )
    except (TypeError, ValueError):
        raw_probability = raw_low = raw_high = market_probability = 0.0
        available = False

    already_adaptive = "adaptive_probability_source" in probability
    if already_adaptive:
        weight = clamp(
            float(probability.get("adaptive_model_weight") or 0),
            0.0,
            1.0,
        )
        residual_weight = clamp(
            float(
                probability.get("adaptive_residual_weight")
                if probability.get("adaptive_residual_weight") is not None
                else weight
            ),
            0.0,
            1.0,
        )
        win_probability = raw_probability
        win_probability_low = raw_low
        win_probability_high = raw_high
    else:
        # Backward-compatible protection for persisted/test candidates created
        # before adaptive residual anchoring moved into candidate construction.
        weight = clamp(
            setting_float(settings, "CRYPTO_15M_UNIT_WIN_PROB_MODEL_WEIGHT"),
            0.0,
            1.0,
        )
        residual_weight = weight
        win_probability = market_probability + weight * (raw_probability - market_probability)
        win_probability_low = market_probability + weight * (raw_low - market_probability)
        win_probability_high = market_probability + weight * (raw_high - market_probability)
    win_probability = max(0.01, min(99.99, win_probability))
    win_probability_low = max(0.01, min(win_probability, win_probability_low))
    win_probability_high = min(99.99, max(win_probability, win_probability_high))
    learned = candidate.get("learned_15m_model") or {}
    learned_probability = selected(learned.get("prob_yes"))
    residual_source_probability = selected(
        probability.get("adaptive_source_probability_yes")
    )
    configured_reserve = max(
        0.0,
        setting_float(settings, "CRYPTO_15M_UNIT_MIN_CALIBRATION_RESERVE_PP"),
    )
    learned_reserve = max(0.0, float(learned.get("calibration_error_reserve_pp") or 0))
    calibration_reserve = max(configured_reserve, learned_reserve)
    sizing_probability_low = max(
        0.01,
        min(win_probability, win_probability_low - calibration_reserve),
    )
    empirical_calibrator_active = bool(
        probability.get("adaptive_probability_source")
        not in (None, "guardrailed_heuristic_residual")
        and learned.get("prob_yes") is not None
        and learned.get("calibration_scope")
        and (learned.get("empirical_interval") or {}).get("available")
    )
    interval_level = float(probability.get("interval_level") or 0.90)
    calibration_status = (
        "empirical_market_residual_calibration"
        if empirical_calibrator_active and learned.get("interval_qualified")
        else "adaptive_market_guardrail_model_not_qualified"
    )
    return {
        "available": available,
        "win_probability": round(win_probability, 4),
        "win_probability_low": round(win_probability_low, 4),
        "win_probability_high": round(win_probability_high, 4),
        "calibrated_win_probability": round(win_probability, 4),
        "calibrated_win_probability_low": round(win_probability_low, 4),
        "calibrated_win_probability_high": round(win_probability_high, 4),
        "sizing_probability_low": round(sizing_probability_low, 4),
        "calibration_error_reserve_pp": round(calibration_reserve, 4),
        "raw_model_win_probability": (
            round(learned_probability, 4)
            if learned_probability is not None
            else round(raw_probability, 4)
        ),
        "residual_source_win_probability": (
            round(residual_source_probability, 4)
            if residual_source_probability is not None
            else None
        ),
        "market_implied_win_probability": round(market_probability, 4),
        "model_weight": round(weight, 4),
        "residual_correction_weight": round(residual_weight, 4),
        "method": (
            "adaptive_market_residual_probability_v2"
            if already_adaptive
            else "legacy_candidate_market_shrink_guardrail"
        ),
        "calibration_status": calibration_status,
        "empirical_calibrator_active": empirical_calibrator_active,
        "calibration_scope": learned.get("calibration_scope"),
        "interval_level": interval_level,
        "interval_status": (
            probability.get("interval_status")
            or (
                "empirical_coverage_qualified"
                if empirical_calibrator_active and learned.get("interval_qualified")
                else "estimated_model_interval_not_coverage_qualified"
            )
        ),
        "win_probability_interval": {
            "low": round(win_probability_low, 4),
            "high": round(win_probability_high, 4),
            "level": interval_level,
        },
    }


def crypto_15m_fractional_kelly_unit_cap(
    settings,
    candidate,
    probability,
    unit_size_pct,
    execution_pricing=None,
):
    """Cap units using the lower win-probability bound and exact execution cost."""
    price = max(0.0, float(candidate.get("entry_price") or 0))
    fee = max(0.0, float(candidate.get("exact_fee_cents") or 0))
    slippage = max(0.0, float(candidate.get("expected_slippage_cents") or 0))
    effective_cost = min(0.9999, (price + fee + slippage) / 100.0)
    probability_low = max(
        0.0001,
        min(
            0.9999,
            float(
                probability.get("sizing_probability_low")
                if probability.get("sizing_probability_low") is not None
                else probability.get("win_probability_low") or 0
            ) / 100.0,
        ),
    )
    full_kelly = (
        max(0.0, (probability_low - effective_cost) / (1.0 - effective_cost))
        if effective_cost < 1.0
        else 0.0
    )
    fraction = max(
        0.0,
        min(1.0, setting_float(settings, "CRYPTO_15M_UNIT_KELLY_FRACTION")),
    )
    fractional_kelly = full_kelly * fraction
    unit_fraction = max(0.0, float(unit_size_pct) / 100.0)
    unit_cap = fractional_kelly / unit_fraction if unit_fraction > 0 else 0.0
    result = {
        "full_kelly_fraction": round(full_kelly, 6),
        "kelly_fraction": round(fraction, 6),
        "fractional_kelly_fraction": round(fractional_kelly, 6),
        "effective_cost_probability": round(effective_cost * 100.0, 4),
        "conservative_probability": round(probability_low * 100.0, 4),
        "maximum_units": round(max(0.0, unit_cap), 4),
    }
    execution_pricing = execution_pricing or {}
    tier_reviews = {}
    accepted = []
    for key, tier in (execution_pricing.get("tiers") or {}).items():
        if not tier.get("complete_depth"):
            tier_reviews[key] = {
                "passes": False,
                "reason": "incomplete_executable_depth",
            }
            continue
        tier_cost = max(
            0.0,
            float(tier.get("break_even_probability") or 0) / 100.0,
        )
        tier_full = (
            max(0.0, (probability_low - tier_cost) / (1.0 - tier_cost))
            if tier_cost < 1.0
            else 0.0
        )
        tier_fractional = tier_full * fraction
        tier_cap = tier_fractional / unit_fraction if unit_fraction > 0 else 0.0
        requested_units = float(tier.get("units") or key)
        passes = requested_units <= tier_cap + 1e-9
        if passes:
            accepted.append(requested_units)
        tier_reviews[key] = {
            "passes": passes,
            "requested_units": requested_units,
            "break_even_probability": round(tier_cost * 100.0, 4),
            "full_kelly_fraction": round(tier_full, 6),
            "fractional_kelly_fraction": round(tier_fractional, 6),
            "maximum_units": round(max(0.0, tier_cap), 4),
        }
    if execution_pricing.get("available"):
        result["maximum_units"] = round(max(accepted, default=0.0), 4)
        result["method"] = "tier_specific_marginal_cost_fractional_kelly"
        result["tier_reviews"] = tier_reviews
    else:
        result["method"] = "top_quote_fractional_kelly_fallback"
    return result


def crypto_15m_portfolio_unit_capacity(settings, portfolio, unit_size):
    """Global daily worst-case capacity, expressed in ordinary crypto units."""
    maximum_units = max(
        0.0,
        setting_float(settings, "CRYPTO_15M_GLOBAL_DAILY_LOSS_UNITS"),
    )
    cap_dollars = max(0.0, maximum_units * max(0.0, unit_size))
    seen = set()
    settled_profit = 0.0
    open_risk = 0.0
    rows = list(portfolio.get("history") or []) + list(portfolio.get("bets") or [])
    for row in rows:
        if row.get("strategy_owner") != CRYPTO_15M_CAMPAIGN_OWNER:
            continue
        identity = row.get("id") or (
            row.get("ticker"),
            row.get("side"),
            row.get("placed_at"),
            row.get("status"),
        )
        if identity in seen:
            continue
        seen.add(identity)
        if row.get("status") == "open":
            open_risk += float(row.get("stake") or 0) + float(row.get("fee") or 0)
            continue
        if row.get("status") != "settled":
            continue
        stamp = row.get("settled_at") or row.get("closed_at") or row.get("placed_at")
        if local_date_key(stamp) != local_date_key() or not is_after_daily_reset(stamp):
            continue
        settled_profit += float(row.get("profit") or 0)
    realized_loss = max(0.0, -settled_profit)
    used = realized_loss + open_risk
    remaining = max(0.0, cap_dollars - used) if cap_dollars > 0 else None
    return {
        "enabled": cap_dollars > 0 and unit_size > 0,
        "maximum_daily_units": round(maximum_units, 4),
        "cap_dollars": round(cap_dollars, 2),
        "realized_profit": round(settled_profit, 2),
        "realized_loss_used": round(realized_loss, 2),
        "open_risk_used": round(open_risk, 2),
        "risk_used": round(used, 2),
        "remaining_dollars": round(remaining, 2) if remaining is not None else None,
        "maximum_units": (
            round(remaining / unit_size, 4)
            if remaining is not None and unit_size > 0
            else None
        ),
    }


def _crypto_unit_ladder_floor(value, tiers):
    try:
        limit = float(value)
    except (TypeError, ValueError):
        return 0.0
    return max((float(units) for units in tiers if float(units) <= limit + 1e-9), default=0.0)


def crypto_15m_model_maturity_review(settings, candidate, tiers):
    """Unlock stake tiers only after independent-market walk-forward evidence."""
    configured_maximum = max(tiers, default=0.0)
    if not setting_bool(settings, "CRYPTO_15M_MODEL_MATURITY_CAP_ENABLED"):
        return {
            "enabled": False,
            "maximum_units": configured_maximum,
            "reason": "model_maturity_cap_disabled",
            "checks": {},
        }
    learned = candidate.get("learned_15m_model") or {}
    evaluation = learned.get("evaluation") or {}

    def finite(section, key, fallback=None):
        value = (evaluation.get(section) or {}).get(key)
        try:
            parsed = float(value)
            return parsed if math.isfinite(parsed) else fallback
        except (TypeError, ValueError):
            return fallback

    market_brier = finite("market_weighted_market_baseline", "brier")
    model_brier = finite("market_weighted_calibrated_ensemble", "brier")
    policy_roi = finite("after_fee_policy", "roi")
    base_qualified = bool(
        learned.get("active")
        and learned.get("qualified_for_activation", learned.get("active"))
        and learned.get("interval_qualified")
        and market_brier is not None
        and model_brier is not None
        and model_brier < market_brier
        and policy_roi is not None
        and policy_roi > 0
    )
    unqualified_cap = _crypto_unit_ladder_floor(
        max(
            0.0,
            setting_float(settings, "CRYPTO_15M_MODEL_UNQUALIFIED_MAX_UNITS"),
        ),
        tiers,
    )
    checks = {
        "base": {
            "qualified": base_qualified,
            "active": bool(learned.get("active")),
            "interval_qualified": bool(learned.get("interval_qualified")),
            "market_weighted_brier_improvement": (
                round(market_brier - model_brier, 6)
                if market_brier is not None and model_brier is not None
                else None
            ),
            "after_fee_policy_roi": policy_roi,
        }
    }
    if not base_qualified:
        return {
            "enabled": True,
            "maximum_units": unqualified_cap,
            "reason": "model_not_walk_forward_qualified",
            "checks": checks,
            "unique_markets": learned.get("unique_markets"),
        }

    maximum_gap = max(
        0.0,
        setting_float(settings, "CRYPTO_15M_MODEL_TIER_MAX_CALIBRATION_GAP"),
    )
    tier_policy = evaluation.get("probability_tier_policy") or {}
    maximum_units = max(1.0, unqualified_cap)
    for units in sorted(float(value) for value in tiers if float(value) >= 2.0):
        tier_number = int(units)
        policy = tier_policy.get(str(tier_number)) or {}
        required_markets = max(
            1,
            setting_int(settings, f"CRYPTO_15M_MODEL_TIER_{tier_number}_MIN_MARKETS"),
        )
        try:
            markets = int(policy.get("markets") or 0)
            profit_low = float(policy.get("profit_per_contract_low_90"))
            roi = float(policy.get("roi"))
            calibration_gap = float(policy.get("calibration_gap"))
            passed = bool(
                markets >= required_markets
                and profit_low > 0
                and roi > 0
                and calibration_gap <= maximum_gap
            )
        except (TypeError, ValueError):
            markets = int(policy.get("markets") or 0)
            profit_low = roi = calibration_gap = None
            passed = False
        checks[str(tier_number)] = {
            "passed": passed,
            "markets": markets,
            "required_markets": required_markets,
            "profit_per_contract_low_90": profit_low,
            "roi": roi,
            "calibration_gap": calibration_gap,
            "maximum_calibration_gap": maximum_gap,
        }
        if not passed:
            break
        maximum_units = units
    maximum_units = _crypto_unit_ladder_floor(
        min(maximum_units, configured_maximum),
        tiers,
    )
    return {
        "enabled": True,
        "maximum_units": maximum_units,
        "reason": (
            "all_configured_tiers_qualified"
            if maximum_units >= configured_maximum
            else "evidence_limited_tier_unlock"
        ),
        "checks": checks,
        "unique_markets": learned.get("unique_markets"),
    }


def crypto_15m_execution_tier_pricing(
    settings,
    candidate,
    unit_size,
    tiers,
):
    """Price each unit tier from its marginal executable book cost.

    The top ask is sufficient for a one-contract edge display, but it is not a
    truthful price for a larger stake. This ladder walks the opposite-side book,
    applies exact fee rounding to each price level, and recomputes the complete
    probability/edge distribution for the requested tier.
    """
    side = str(candidate.get("side") or "yes").lower()
    kalshi = candidate.get("kalshi_microstructure") or {}
    contra_key = "no_levels" if side == "yes" else "yes_levels"
    raw_levels = kalshi.get(contra_key) or []
    contra_levels = []
    for row in raw_levels:
        try:
            price = float(row[0])
            count = float(row[1])
        except (TypeError, ValueError, IndexError):
            continue
        # Both the WebSocket and REST microstructure adapters normalize these
        # ladders to cents. Fractional values are fractional cents, not dollar
        # prices (for example, 0.8 means 0.8c, not 80c).
        if 0 < price < 100 and count > 0:
            contra_levels.append((price, count))
    executable_levels = sorted(
        ((100.0 - price, count) for price, count in contra_levels),
        key=lambda row: row[0],
    )
    computed_best_entry = executable_levels[0][0] if executable_levels else None
    declared_best_entry = _execution_number(
        kalshi.get(
            "best_yes_entry_price_cents"
            if side == "yes"
            else "best_no_entry_price_cents"
        )
    )
    if declared_best_entry is not None and not (0 < declared_best_entry < 100):
        declared_best_entry = None
    book_consistent = bool(
        computed_best_entry is not None
        and (
            declared_best_entry is None
            or abs(computed_best_entry - declared_best_entry) <= 0.011
        )
    )
    pricing_error = None
    if executable_levels and not book_consistent:
        # Never size from a ladder that contradicts its own top-of-book quote.
        # The live quote refresh can obtain a new book on the next scan.
        pricing_error = "orderbook_best_price_mismatch"
        executable_levels = []
    best_entry = executable_levels[0][0] if executable_levels else None
    probability = candidate.get("probability") or {}
    interval = {
        key: probability.get(key)
        for key in ("p_yes", "p_low", "p_high", "probability_sigma_pp", "interval_level")
        if probability.get(key) is not None
    }
    fee_schedule = candidate.get("fee_schedule") or {}
    adverse_selection_cents = expected_execution_slippage_cents(
        settings,
        kalshi,
        side,
    )
    tier_rows = {}
    for units in sorted(float(value) for value in tiers):
        requested_dollars = max(0.0, units * max(0.0, float(unit_size or 0)))
        contracts = (
            max(1, int(math.floor(requested_dollars * 100.0 / best_entry + 1e-9)))
            if requested_dollars > 0 and best_entry
            else 0
        )
        remaining = float(contracts)
        fills = []
        book_cost = 0.0
        total_fee = 0.0
        for price, available in executable_levels:
            if remaining <= 1e-9:
                break
            fill_count = min(remaining, available)
            if fill_count <= 0:
                continue
            fill_fee = kalshi_order_fee(
                price,
                fill_count,
                schedule=fee_schedule,
                liquidity_role="taker",
                fallback_rate=setting_float(settings, "CRYPTO_SHADOW_FEE_RATE"),
            )
            fills.append({
                "price_cents": round(price, 4),
                "contracts": round(fill_count, 4),
                "fee_dollars": fill_fee.get("fee_dollars"),
            })
            book_cost += fill_count * price / 100.0
            total_fee += float(fill_fee.get("fee_dollars") or 0)
            remaining -= fill_count
        filled_contracts = max(0.0, float(contracts) - remaining)
        complete = bool(contracts > 0 and remaining <= 1e-9)
        vwap = book_cost * 100.0 / filled_contracts if filled_contracts > 0 else None
        marginal = fills[-1]["price_cents"] if fills else None
        fee_per_contract = total_fee / filled_contracts if filled_contracts > 0 else 0.0
        metrics = (
            conservative_edge_metrics(
                probability.get("p_yes", probability.get("prob")),
                side,
                vwap,
                fee_per_contract_dollars=fee_per_contract,
                expected_slippage_cents=adverse_selection_cents,
                interval=interval,
            )
            if complete and vwap is not None
            else {}
        )
        tier_rows[f"{units:g}"] = {
            "units": units,
            "requested_dollars": round(requested_dollars, 4),
            "contracts": contracts,
            "filled_contracts": round(filled_contracts, 4),
            "complete_depth": complete,
            "depth_shortfall_contracts": round(max(0.0, remaining), 4),
            "best_entry_price_cents": round(best_entry, 4) if best_entry is not None else None,
            "vwap_entry_price_cents": round(vwap, 4) if vwap is not None else None,
            "marginal_entry_price_cents": marginal,
            "book_walk_slippage_cents": round(max(0.0, vwap - best_entry), 4)
            if vwap is not None and best_entry is not None
            else None,
            "expected_adverse_selection_cents": adverse_selection_cents,
            "expected_adverse_selection_dollars": round(
                adverse_selection_cents * filled_contracts / 100.0,
                4,
            ),
            "book_cost_dollars": round(book_cost, 4),
            "fee_dollars": round(total_fee, 4),
            "fee_per_contract_cents": round(fee_per_contract * 100.0, 4),
            "fills": fills,
            **metrics,
        }
    result = {
        "version": "marginal-book-v2",
        "available": bool(executable_levels),
        "error": pricing_error,
        "side": side,
        "book_price_unit": "cents",
        "book_consistent": book_consistent,
        "declared_best_entry_price_cents": (
            round(declared_best_entry, 4)
            if declared_best_entry is not None
            else None
        ),
        "computed_best_entry_price_cents": (
            round(computed_best_entry, 4)
            if computed_best_entry is not None
            else None
        ),
        "best_entry_price_cents": round(best_entry, 4) if best_entry is not None else None,
        "level_count": len(executable_levels),
        "total_available_contracts": round(sum(count for _price, count in executable_levels), 4),
        "expected_adverse_selection_cents": adverse_selection_cents,
        "tiers": tier_rows,
        "affects_live_sizing": True,
    }
    candidate["execution_tier_pricing"] = result
    return result


def crypto_dynamic_policy_state(settings):
    """Read the evidence state fail-closed; a missing/mismatched state is shadow."""
    config = dynamic_policy_configuration(settings)
    try:
        mtime_ns = CRYPTO_SCAN_INTELLIGENCE_STATE_FILE.stat().st_mtime_ns
    except OSError:
        mtime_ns = None
    if DYNAMIC_POLICY_STATE_CACHE.get("mtime_ns") != mtime_ns:
        intelligence_state = read_json(CRYPTO_SCAN_INTELLIGENCE_STATE_FILE, {})
        DYNAMIC_POLICY_STATE_CACHE.update({
            "mtime_ns": mtime_ns,
            "state": dict((intelligence_state or {}).get("dynamic_policy") or {}),
        })
    state = dict(DYNAMIC_POLICY_STATE_CACHE.get("state") or {})
    if state.get("policy_hash") != config.get("policy_hash"):
        return {
            "version": config.get("version"),
            "policy_hash": config.get("policy_hash"),
            "status": "shadow",
            "qualified_for_activation": False,
            "activation_reason": "policy_identity_changed",
            "independent_markets": 0,
            "activation_checks": {},
        }
    return state


def crypto_15m_unit_candidate_review(
    settings,
    portfolio,
    candidate,
    dynamic_policy_state=None,
):
    enabled = setting_bool(settings, "CRYPTO_15M_UNIT_STAKING_ENABLED")
    tiers = crypto_15m_unit_tiers(settings)
    snapshot = crypto_15m_unit_bankroll_base(portfolio)
    unit_size_pct = max(0.0, setting_float(settings, "CRYPTO_15M_UNIT_SIZE_PCT"))
    unit_size = round(float(snapshot.get("balance") or 0) * unit_size_pct / 100.0, 2)
    execution_pricing = crypto_15m_execution_tier_pricing(
        settings,
        candidate,
        unit_size,
        tiers,
    )
    sizing_probability = crypto_15m_sizing_probability(settings, candidate)
    dynamic_policy = dynamic_qualification_review(
        settings,
        candidate,
        execution_pricing,
        sizing_probability,
        tiers,
        policy_state=(
            dynamic_policy_state
            if dynamic_policy_state is not None
            else crypto_dynamic_policy_state(settings)
        ),
    )
    candidate["dynamic_qualification"] = dynamic_policy
    edge_raw = (
        candidate.get("expected_edge")
        if candidate.get("expected_edge") is not None
        else candidate.get("edge")
    )
    edge_low_raw = candidate.get("edge_low")
    confidence_raw = (
        candidate.get("probability_net_edge_positive")
        if candidate.get("probability_net_edge_positive") is not None
        else candidate.get("confidence")
    )
    try:
        edge = float(edge_raw)
        edge_low = float(edge_low_raw)
        confidence = float(confidence_raw)
        metrics_available = all(math.isfinite(value) for value in (edge, edge_low, confidence))
    except (TypeError, ValueError):
        edge = edge_low = confidence = 0.0
        metrics_available = False
    metrics_available = bool(metrics_available and sizing_probability.get("available"))
    win_probability = float(sizing_probability.get("win_probability") or 0)
    win_probability_low = float(
        sizing_probability.get("sizing_probability_low")
        if sizing_probability.get("sizing_probability_low") is not None
        else sizing_probability.get("win_probability_low") or 0
    )
    data_quality = float((candidate.get("data_quality") or {}).get("score") or 0)
    minimum_data_quality = setting_float(settings, "CRYPTO_15M_UNIT_MIN_DATA_QUALITY")
    probability_passed_tiers = []
    edge_passed_tiers = []
    passed_tiers = []
    if metrics_available and data_quality >= minimum_data_quality:
        for units, tier in tiers.items():
            execution_tier = (execution_pricing.get("tiers") or {}).get(f"{float(units):g}") or {}
            use_execution_tier = bool(
                execution_pricing.get("available")
                and execution_tier.get("complete_depth")
            )
            tier_confidence = float(
                execution_tier.get("probability_net_edge_positive")
                if use_execution_tier
                else confidence
            )
            tier_edge = float(
                execution_tier.get("expected_edge")
                if use_execution_tier
                else edge
            )
            tier_edge_low = float(
                execution_tier.get("edge_low")
                if use_execution_tier
                else edge_low
            )
            probability_passed = (
                win_probability >= float(tier["minimum_win_probability"])
                and win_probability_low >= float(tier["minimum_win_probability_low"])
            )
            edge_passed = (
                tier_confidence >= float(tier["minimum_confidence"])
                and tier_edge >= float(tier["minimum_edge"])
                and tier_edge_low >= float(tier["minimum_edge_low"])
                and (
                    not execution_pricing.get("available")
                    or bool(execution_tier.get("complete_depth"))
                )
            )
            if probability_passed:
                probability_passed_tiers.append(units)
            if edge_passed:
                edge_passed_tiers.append(units)
            if probability_passed and edge_passed:
                passed_tiers.append(units)
    probability_unit_cap = max(probability_passed_tiers, default=0.0)
    edge_unit_cap = max(edge_passed_tiers, default=0.0)
    kelly = crypto_15m_fractional_kelly_unit_cap(
        settings,
        candidate,
        sizing_probability,
        unit_size_pct,
        execution_pricing=execution_pricing,
    )
    kelly_unit_cap = _crypto_unit_ladder_floor(kelly.get("maximum_units"), tiers)
    legacy_model_target_units = _crypto_unit_ladder_floor(
        min(probability_unit_cap, edge_unit_cap, kelly_unit_cap),
        tiers,
    )
    dynamic_model_target_units = _crypto_unit_ladder_floor(
        dynamic_policy.get("target_units"),
        tiers,
    )
    model_target_units = (
        dynamic_model_target_units
        if dynamic_policy.get("affects_execution")
        else legacy_model_target_units
    )
    execution_unit_cap = crypto_execution_unit_cap(candidate)
    portfolio_capacity = crypto_15m_portfolio_unit_capacity(
        settings,
        portfolio,
        unit_size,
    )
    portfolio_unit_cap = _crypto_unit_ladder_floor(
        portfolio_capacity.get("maximum_units"),
        tiers,
    ) if portfolio_capacity.get("enabled") else max(tiers, default=0.0)
    scan_book_liquidity_cap = max(
        (
            float(key)
            for key, row in (execution_pricing.get("tiers") or {}).items()
            if row.get("complete_depth")
        ),
        default=0.0,
    ) if execution_pricing.get("available") else max(tiers, default=0.0)
    liquidity_unit_cap = min(
        _crypto_unit_ladder_floor(execution_unit_cap, tiers)
        if execution_unit_cap is not None
        else max(tiers, default=0.0),
        _crypto_unit_ladder_floor(scan_book_liquidity_cap, tiers),
    )
    model_maturity = crypto_15m_model_maturity_review(settings, candidate, tiers)
    model_maturity_unit_cap = _crypto_unit_ladder_floor(
        model_maturity.get("maximum_units"),
        tiers,
    )
    target_units = _crypto_unit_ladder_floor(
        min(
            model_target_units,
            liquidity_unit_cap,
            portfolio_unit_cap,
            model_maturity_unit_cap,
        ),
        tiers,
    )
    requested_stake = round(target_units * unit_size, 2)
    if not enabled:
        reason = "unit_staking_disabled"
    elif not metrics_available:
        reason = "crypto_unit_metrics_unavailable"
    elif data_quality < minimum_data_quality:
        reason = "crypto_unit_data_quality"
    elif dynamic_policy.get("affects_execution") and dynamic_model_target_units <= 0:
        reason = "crypto_dynamic_qualification_filter"
    elif not dynamic_policy.get("affects_execution") and probability_unit_cap <= 0:
        reason = "crypto_unit_win_probability_filter"
    elif not dynamic_policy.get("affects_execution") and edge_unit_cap <= 0:
        reason = "crypto_unit_edge_filter"
    elif kelly_unit_cap <= 0:
        reason = "crypto_unit_kelly_filter"
    elif portfolio_unit_cap <= 0:
        reason = "crypto_unit_portfolio_risk_cap"
    elif model_maturity_unit_cap <= 0:
        reason = "crypto_unit_model_maturity_cap"
    elif target_units <= 0:
        reason = "crypto_unit_quality_filter"
    elif unit_size <= 0:
        reason = "crypto_unit_bankroll_unavailable"
    else:
        reason = "eligible"
    return {
        "enabled": enabled,
        "eligible": bool(enabled and target_units > 0 and unit_size > 0),
        "reason": reason,
        "sizing_mode": "probability_edge_kelly_units",
        "qualification_policy": (
            "dynamic_qualification_v1"
            if dynamic_policy.get("affects_execution")
            else "legacy_probability_edge_tiers"
        ),
        "unit_size_pct": unit_size_pct,
        "unit_bankroll_base": snapshot.get("balance"),
        "unit_bankroll_snapshot": snapshot,
        "unit_size": unit_size,
        "maximum_units": max(tiers, default=0),
        "model_target_units": model_target_units,
        "legacy_model_target_units": legacy_model_target_units,
        "dynamic_model_target_units": dynamic_model_target_units,
        "target_units": target_units,
        "win_probability_unit_cap": probability_unit_cap,
        "conservative_edge_unit_cap": edge_unit_cap,
        "kelly_unit_cap": kelly_unit_cap,
        "liquidity_unit_cap": liquidity_unit_cap,
        "portfolio_unit_cap": portfolio_unit_cap,
        "model_maturity_unit_cap": model_maturity_unit_cap,
        "model_maturity": model_maturity,
        "model_maturity_downshifted": bool(
            target_units > 0 and target_units < model_target_units
        ),
        "execution_unit_cap": execution_unit_cap,
        "execution_downshifted": bool(
            execution_unit_cap is not None
            and target_units > 0
            and target_units < model_target_units
        ),
        "passed_tiers": passed_tiers,
        "probability_passed_tiers": probability_passed_tiers,
        "edge_passed_tiers": edge_passed_tiers,
        "requested_stake": requested_stake,
        "quality_tier": f"{target_units:g}u" if target_units else "",
        "metrics": {
            "confidence": round(confidence, 4),
            "edge_certainty": round(confidence, 4),
            "win_probability": round(win_probability, 4),
            "win_probability_low": sizing_probability.get("win_probability_low"),
            "conservative_sizing_probability_low": round(win_probability_low, 4),
            "win_probability_high": sizing_probability.get("win_probability_high"),
            "calibrated_win_probability": sizing_probability.get(
                "calibrated_win_probability"
            ),
            "calibrated_win_probability_low": sizing_probability.get(
                "calibrated_win_probability_low"
            ),
            "calibrated_win_probability_high": sizing_probability.get(
                "calibrated_win_probability_high"
            ),
            "win_probability_interval": sizing_probability.get(
                "win_probability_interval"
            ),
            "probability_calibration_status": sizing_probability.get(
                "calibration_status"
            ),
            "probability_interval_status": sizing_probability.get(
                "interval_status"
            ),
            "calibration_error_reserve_pp": sizing_probability.get(
                "calibration_error_reserve_pp"
            ),
            "raw_model_win_probability": sizing_probability.get("raw_model_win_probability"),
            "market_implied_win_probability": sizing_probability.get("market_implied_win_probability"),
            "expected_edge": round(edge, 4),
            "edge_low": round(edge_low, 4),
            "data_quality": round(data_quality, 4),
        },
        "metrics_available": metrics_available,
        "minimum_data_quality": minimum_data_quality,
        "probability_calibration": sizing_probability,
        "fractional_kelly": kelly,
        "execution_tier_pricing": execution_pricing,
        "dynamic_qualification": dynamic_policy,
        "portfolio_risk": portfolio_capacity,
        "requirements": {str(units): dict(tier) for units, tier in tiers.items()},
    }


def crypto_15m_bounded_unit_recovery_review(
    settings,
    candidate,
    unit_review,
    campaign_context,
    recovery_cooldown=None,
):
    """Add a small drawdown-aware unit bonus without loss-chasing sizing."""
    recovery_cooldown = recovery_cooldown or {}
    enabled = setting_bool(settings, "CRYPTO_15M_UNIT_RECOVERY_ENABLED")
    base_units = max(0.0, float(unit_review.get("target_units") or 0))
    unit_size = max(0.0, float(unit_review.get("unit_size") or 0))
    base_stake = max(0.0, float(unit_review.get("requested_stake") or 0))
    minimum_base_units = max(
        1.0,
        float(setting_float(settings, "CRYPTO_15M_UNIT_RECOVERY_MIN_BASE_UNITS")),
    )
    minimum_probability_units = max(
        1.0,
        float(
            setting_float(
                settings,
                "CRYPTO_15M_UNIT_RECOVERY_MIN_PROBABILITY_UNITS",
            )
        ),
    )
    maximum_bonus_units = max(
        0.0,
        float(setting_float(settings, "CRYPTO_15M_UNIT_RECOVERY_MAX_BONUS_UNITS")),
    )
    normal_maximum_units = max(
        1.0,
        float(unit_review.get("maximum_units") or 5),
    )

    def review_cap(key):
        raw = unit_review.get(key)
        if raw is None:
            return normal_maximum_units
        try:
            return max(0.0, float(raw))
        except (TypeError, ValueError):
            return 0.0

    evidence_caps = {
        "win_probability": review_cap("win_probability_unit_cap"),
        "kelly": review_cap("kelly_unit_cap"),
        "liquidity": review_cap("liquidity_unit_cap"),
        "portfolio": review_cap("portfolio_unit_cap"),
        "execution": review_cap("execution_unit_cap"),
        "model_maturity": review_cap("model_maturity_unit_cap"),
    }
    maximum_total_units = max(
        base_units,
        min(
            normal_maximum_units,
            float(setting_float(settings, "CRYPTO_15M_UNIT_RECOVERY_MAX_TOTAL_UNITS")),
            *evidence_caps.values(),
        ),
    )
    target_fraction = max(
        0.0,
        min(
            1.0,
            float(
                setting_float(
                    settings,
                    "CRYPTO_15M_UNIT_RECOVERY_TARGET_DRAWDOWN_FRACTION",
                )
            ),
        ),
    )
    pooled_recovery_enabled = bool(
        setting_bool(settings, "CRYPTO_15M_POOLED_RECOVERY_ENABLED")
        and campaign_context.get("pooled_recovery_enabled") is True
    )
    high_water_ledger = (
        campaign_context.get("pooled_high_water_drawdown") or {}
        if pooled_recovery_enabled
        else campaign_context.get("high_water_drawdown") or {}
    )
    continuous_drawdown = (
        campaign_context.get("pooled_outstanding_drawdown")
        if pooled_recovery_enabled
        else campaign_context.get("outstanding_drawdown")
    )
    if continuous_drawdown is None:
        continuous_drawdown = high_water_ledger.get("outstanding_drawdown")
    if continuous_drawdown is None:
        cycle_profit = float(campaign_context.get("cycle_realized_profit") or 0)
        outstanding_drawdown = round(max(0.0, -cycle_profit), 2)
        drawdown_source = "legacy_cycle_profit"
    else:
        outstanding_drawdown = round(max(0.0, float(continuous_drawdown or 0)), 2)
        drawdown_source = (
            "pooled_continuous_high_water"
            if pooled_recovery_enabled
            else "continuous_high_water"
        )
    drawdown_active = outstanding_drawdown > 0.009

    price_cents = max(0.0, float(candidate.get("entry_price") or 0))
    price_fraction = price_cents / 100.0
    unit_contracts = (
        max(0, int(math.floor(unit_size / price_fraction + 1e-12)))
        if unit_size > 0 and price_fraction > 0
        else 0
    )
    fee_schedule = candidate.get("fee_schedule") or {}
    if unit_contracts > 0 and fee_schedule.get("authoritative"):
        unit_fee = float(kalshi_order_fee(
            price_cents,
            unit_contracts,
            schedule=fee_schedule,
            liquidity_role="taker",
            fallback_rate=setting_float(settings, "CRYPTO_SHADOW_FEE_RATE"),
        ).get("fee_dollars") or 0)
    else:
        unit_fee = (
            unit_contracts * max(0.0, float(candidate.get("exact_fee_cents") or 0)) / 100.0
        )
    profit_per_unit = round(
        max(0.0, unit_contracts * (1.0 - price_fraction) - unit_fee),
        4,
    )
    target_recovery_profit = round(outstanding_drawdown * target_fraction, 2)
    reservations = (
        campaign_context.get("recovery_reservations") or {}
        if pooled_recovery_enabled
        else {}
    )
    reserved_recovery_profit = max(
        0.0,
        float(reservations.get("reserved_recovery_profit") or 0),
    )
    available_target_recovery_profit = round(
        max(0.0, target_recovery_profit - reserved_recovery_profit),
        2,
    )
    expiry_key = crypto_15m_recovery_expiry_key(candidate)
    expiry_reservation = (reservations.get("by_expiry") or {}).get(expiry_key) or {}
    expiry_open_overlay_count = max(
        0,
        int(expiry_reservation.get("count") or 0),
    )
    maximum_overlays_per_expiry = max(
        1,
        setting_int(settings, "CRYPTO_15M_RECOVERY_MAX_OVERLAYS_PER_EXPIRY"),
    )

    bonus_units = 0.0
    reason = "no_drawdown"
    if not enabled:
        reason = "bounded_unit_recovery_disabled"
    elif not unit_review.get("eligible"):
        reason = "unit_candidate_ineligible"
    elif not drawdown_active:
        reason = "no_drawdown"
    elif (candidate.get("live_slippage_reconfirmation") or {}).get(
        "base_units_only"
    ):
        reason = "slippage_reconfirmation_base_units_only"
    elif recovery_cooldown.get("active"):
        reason = "directional_cooldown_base_units_only"
    elif base_units < minimum_base_units:
        reason = "quality_below_recovery_floor"
    elif evidence_caps["win_probability"] < minimum_probability_units:
        reason = "probability_below_recovery_floor"
    elif base_units >= maximum_total_units:
        reason = "base_at_recovery_cap"
    elif profit_per_unit <= 0 or unit_size <= 0:
        reason = "recovery_unit_profit_unavailable"
    elif (
        pooled_recovery_enabled
        and expiry_open_overlay_count >= maximum_overlays_per_expiry
    ):
        reason = "pooled_recovery_expiry_reserved"
    elif pooled_recovery_enabled and available_target_recovery_profit <= 0.009:
        reason = "pooled_recovery_target_reserved"
    else:
        bonus_units = min(
            maximum_bonus_units,
            max(0.0, maximum_total_units - base_units),
            available_target_recovery_profit / profit_per_unit,
        )
        bonus_units = round(max(0.0, bonus_units), 4)
        reason = "bounded_recovery_bonus" if bonus_units > 0 else "recovery_target_zero"

    total_units = round(min(maximum_total_units, base_units + bonus_units), 4)
    recovery_bonus_stake = round(max(0.0, (total_units - base_units) * unit_size), 2)
    allocated_recovery_profit = round(max(0.0, bonus_units * profit_per_unit), 2)
    requested_stake = round(base_stake + recovery_bonus_stake, 2)
    active = bool(drawdown_active and recovery_bonus_stake > 0)
    return {
        "enabled": enabled,
        "active": active,
        "drawdown_active": drawdown_active,
        "reason": reason,
        "mode": "bounded_unit_recovery",
        "legacy_full_recovery_disabled": True,
        "drawdown_source": drawdown_source,
        "pooled_recovery_enabled": pooled_recovery_enabled,
        "outstanding_drawdown": outstanding_drawdown,
        "target_drawdown_fraction": target_fraction,
        "target_recovery_profit": target_recovery_profit,
        "reserved_recovery_profit": round(reserved_recovery_profit, 2),
        "available_target_recovery_profit": available_target_recovery_profit,
        "allocated_recovery_profit": allocated_recovery_profit,
        "expiry_key": expiry_key,
        "expiry_open_overlay_count": expiry_open_overlay_count,
        "maximum_overlays_per_expiry": maximum_overlays_per_expiry,
        "minimum_base_units": minimum_base_units,
        "minimum_probability_units": minimum_probability_units,
        "probability_unit_cap": evidence_caps["win_probability"],
        "kelly_unit_cap": evidence_caps["kelly"],
        "liquidity_unit_cap": evidence_caps["liquidity"],
        "portfolio_unit_cap": evidence_caps["portfolio"],
        "execution_unit_cap": evidence_caps["execution"],
        "model_maturity_unit_cap": evidence_caps["model_maturity"],
        "combined_cap_applied": True,
        "maximum_bonus_units": maximum_bonus_units,
        "maximum_total_units": maximum_total_units,
        "base_units": base_units,
        "bonus_units": bonus_units,
        "total_units": total_units,
        "unit_size": unit_size,
        "base_stake": round(base_stake, 2),
        "recovery_bonus_stake": recovery_bonus_stake,
        "requested_stake": requested_stake,
        "unit_contracts": unit_contracts,
        "estimated_fee_per_unit": round(unit_fee, 4),
        "estimated_profit_per_unit_after_fee": profit_per_unit,
        "directional_cooldown_active": bool(recovery_cooldown.get("active")),
    }


def crypto_15m_action_gate_configuration(settings, market_lane_name=None):
    if (
        setting_bool(settings, "CRYPTO_15M_TIERED_ACTION_GATE_ENABLED")
        and market_lane_name in (None, "crypto_15m", "commodity_15m")
    ):
        unit_enabled = bool(
            setting_bool(settings, "CRYPTO_15M_UNIT_STAKING_ENABLED")
            and market_lane_name in (None, "crypto_15m")
        )
        unit_one = crypto_15m_unit_tiers(settings).get(1) or {}
        minimum_edge = (
            float(unit_one.get("minimum_edge") or 0)
            if unit_enabled
            else setting_float(settings, "CRYPTO_15M_TIERED_MIN_EDGE")
        )
        minimum_confidence = (
            float(unit_one.get("minimum_confidence") or 0)
            if unit_enabled
            else setting_float(settings, "CRYPTO_15M_TIERED_MIN_CONFIDENCE")
        )
        minimum_minutes = setting_float(
            settings,
            "CRYPTO_15M_TIERED_MIN_MINUTES_REMAINING",
        )
        maximum_minutes = setting_float(
            settings,
            "CRYPTO_15M_TIERED_MAX_MINUTES_REMAINING",
        )
        low_price_max = setting_float(
            settings,
            "CRYPTO_15M_TIERED_LOW_PRICE_MAX_CENTS",
        )
        high_price_min = setting_float(
            settings,
            "CRYPTO_15M_TIERED_HIGH_PRICE_MIN_CENTS",
        )
        return {
            "enabled": True,
            "tiered": True,
            "mode": "confidence_unit_gate" if unit_enabled else "evidence_tiered_gate",
            "market_lanes": ["crypto_15m", "commodity_15m"],
            "minimum_edge": minimum_edge,
            "minimum_confidence": minimum_confidence,
            "minimum_price_cents": setting_float(
                settings,
                "CRYPTO_15M_TIERED_MIN_PRICE_CENTS",
            ),
            "maximum_price_cents": setting_float(
                settings,
                "CRYPTO_15M_TIERED_MAX_PRICE_CENTS",
            ),
            "minimum_minutes_remaining": minimum_minutes,
            "maximum_minutes_remaining": maximum_minutes,
            "maximum_same_expiry_open": max(
                1,
                setting_int(
                    settings,
                    "CRYPTO_15M_TIERED_MAX_SAME_EXPIRY_OPEN",
                ),
            ),
            "maximum_model_disagreement": setting_float(
                settings,
                "CRYPTO_15M_TIERED_MAX_MODEL_DISAGREEMENT",
            ),
            "price_tiers": [
                {
                    "name": "low_price_35_44",
                    "minimum_price_cents": setting_float(
                        settings,
                        "CRYPTO_15M_TIERED_MIN_PRICE_CENTS",
                    ),
                    "maximum_price_cents": low_price_max + 0.9999,
                    "minimum_edge": minimum_edge,
                    "minimum_confidence": minimum_confidence,
                    "minimum_minutes_remaining": minimum_minutes,
                    "maximum_minutes_remaining": setting_float(
                        settings,
                        "CRYPTO_15M_TIERED_LOW_MAX_MINUTES_REMAINING",
                    ),
                },
                {
                    "name": "mid_price_45_62",
                    "minimum_price_cents": low_price_max + 1.0,
                    "maximum_price_cents": high_price_min - 0.0001,
                    "minimum_edge": minimum_edge,
                    "minimum_confidence": minimum_confidence,
                    "minimum_minutes_remaining": minimum_minutes,
                    "maximum_minutes_remaining": maximum_minutes,
                },
                {
                    "name": "high_price_63_70",
                    "minimum_price_cents": high_price_min,
                    "maximum_price_cents": setting_float(
                        settings,
                        "CRYPTO_15M_TIERED_MAX_PRICE_CENTS",
                    ),
                    "minimum_edge": minimum_edge,
                    "minimum_confidence": max(
                        minimum_confidence,
                        setting_float(
                            settings,
                            "CRYPTO_15M_TIERED_HIGH_MIN_CONFIDENCE",
                        ),
                    ),
                    "minimum_minutes_remaining": minimum_minutes,
                    "maximum_minutes_remaining": maximum_minutes,
                },
            ],
            "directional_confirmation_required": setting_bool(
                settings,
                "CRYPTO_15M_DIRECTIONAL_CONFIRMATION_REQUIRED",
            ),
            "directional_confirmation_minimum_sources": setting_int(
                settings,
                "CRYPTO_15M_DIRECTIONAL_CONFIRMATION_MIN_SOURCES",
            ),
            "directional_confirmation_minimum_strength": setting_float(
                settings,
                "CRYPTO_15M_DIRECTIONAL_CONFIRMATION_MIN_STRENGTH",
            ),
            "directional_confirmation_requires_matching_flow": True,
            "unit_staking_enabled": unit_enabled,
            "unit_size_pct": setting_float(settings, "CRYPTO_15M_UNIT_SIZE_PCT"),
            "unit_tiers": crypto_15m_unit_tiers(settings) if unit_enabled else {},
            "bounded_unit_recovery": {
                "enabled": bool(
                    unit_enabled
                    and setting_bool(settings, "CRYPTO_15M_UNIT_RECOVERY_ENABLED")
                ),
                "minimum_base_units": setting_float(
                    settings,
                    "CRYPTO_15M_UNIT_RECOVERY_MIN_BASE_UNITS",
                ),
                "minimum_probability_units": setting_float(
                    settings,
                    "CRYPTO_15M_UNIT_RECOVERY_MIN_PROBABILITY_UNITS",
                ),
                "target_drawdown_fraction": setting_float(
                    settings,
                    "CRYPTO_15M_UNIT_RECOVERY_TARGET_DRAWDOWN_FRACTION",
                ),
                "maximum_bonus_units": setting_float(
                    settings,
                    "CRYPTO_15M_UNIT_RECOVERY_MAX_BONUS_UNITS",
                ),
                "maximum_total_units": setting_float(
                    settings,
                    "CRYPTO_15M_UNIT_RECOVERY_MAX_TOTAL_UNITS",
                ),
                "pooled_recovery_enabled": setting_bool(
                    settings,
                    "CRYPTO_15M_POOLED_RECOVERY_ENABLED",
                ),
                "maximum_overlays_per_expiry": setting_int(
                    settings,
                    "CRYPTO_15M_RECOVERY_MAX_OVERLAYS_PER_EXPIRY",
                ),
                "legacy_full_recovery_used": False,
            },
        }
    enabled = setting_bool(settings, "CRYPTO_15M_SIMPLE_ACTION_GATE_ENABLED")
    if enabled:
        return {
            "enabled": True,
            "mode": "simple_action_gate",
            "market_lanes": ["crypto_15m", "commodity_15m"],
            "minimum_edge": setting_float(settings, "CRYPTO_15M_SIMPLE_MIN_EDGE"),
            "minimum_confidence": setting_float(
                settings,
                "CRYPTO_15M_SIMPLE_MIN_CONFIDENCE",
            ),
            "minimum_price_cents": setting_float(
                settings,
                "CRYPTO_15M_SIMPLE_MIN_PRICE_CENTS",
            ),
            "maximum_price_cents": setting_float(
                settings,
                "CRYPTO_15M_SIMPLE_MAX_PRICE_CENTS",
            ),
            "minimum_minutes_remaining": setting_float(
                settings,
                "CRYPTO_15M_SIMPLE_MIN_MINUTES_REMAINING",
            ),
            "maximum_minutes_remaining": setting_float(
                settings,
                "CRYPTO_15M_SIMPLE_MAX_MINUTES_REMAINING",
            ),
            "maximum_same_expiry_open": max(
                1,
                setting_int(
                    settings,
                    "CRYPTO_15M_SIMPLE_MAX_SAME_EXPIRY_OPEN",
                ),
            ),
            "directional_confirmation_required": setting_bool(
                settings,
                "CRYPTO_15M_DIRECTIONAL_CONFIRMATION_REQUIRED",
            ),
            "directional_confirmation_minimum_sources": setting_int(
                settings,
                "CRYPTO_15M_DIRECTIONAL_CONFIRMATION_MIN_SOURCES",
            ),
            "directional_confirmation_minimum_strength": setting_float(
                settings,
                "CRYPTO_15M_DIRECTIONAL_CONFIRMATION_MIN_STRENGTH",
            ),
            "directional_confirmation_requires_matching_flow": True,
        }
    return {
        "enabled": False,
        "mode": "legacy_tiered_gate",
        "market_lanes": ["crypto_15m"],
        "minimum_edge": setting_float(settings, "CRYPTO_15M_MIN_EDGE"),
        "minimum_confidence": setting_float(settings, "CRYPTO_15M_MIN_CONFIDENCE"),
        "minimum_price_cents": setting_float(
            settings,
            "CRYPTO_15M_MIN_ENTRY_PRICE_CENTS",
        ),
        "maximum_price_cents": setting_float(
            settings,
            "CRYPTO_15M_MAX_ENTRY_PRICE_CENTS",
        ),
        "minimum_minutes_remaining": setting_float(
            settings,
            "CRYPTO_15M_MIN_MINUTES_REMAINING",
        ),
        "maximum_minutes_remaining": setting_float(
            settings,
            "CRYPTO_15M_MAX_MINUTES_REMAINING",
        ),
        "maximum_same_expiry_open": setting_int(
            settings,
            "CRYPTO_15M_ABSOLUTE_MAX_SAME_EXPIRY_OPEN",
        ),
        "directional_confirmation_required": setting_bool(
            settings,
            "CRYPTO_15M_DIRECTIONAL_CONFIRMATION_REQUIRED",
        ),
        "directional_confirmation_minimum_sources": setting_int(
            settings,
            "CRYPTO_15M_DIRECTIONAL_CONFIRMATION_MIN_SOURCES",
        ),
        "directional_confirmation_minimum_strength": setting_float(
            settings,
            "CRYPTO_15M_DIRECTIONAL_CONFIRMATION_MIN_STRENGTH",
        ),
        "directional_confirmation_requires_matching_flow": True,
    }


def crypto_15m_campaign_lane_review(settings, portfolio, candidate, bot_number):
    candidate_lane = str(candidate.get("market_lane") or market_lane(candidate))
    unit_mode = bool(
        candidate_lane == "crypto_15m"
        and setting_bool(settings, "CRYPTO_15M_UNIT_STAKING_ENABLED")
    )
    continuous_mode = bool(
        unit_mode and crypto_15m_continuous_opportunity_enabled(settings)
    )
    strategy = (
        {
            "goals": [],
            "goal_schedule_source": "continuous_opportunity_mode",
            "goal_schedule_override_date": "",
            "goal_schedule_key": "",
            "goal_schedule_locked": False,
            "configured_cycle_profit": 0.0,
            "configured_cycle_profit_key": "",
            "configured_cycle_count": 0,
            "configured_cycle_count_key": "",
            "effective_cycle_count": 0,
            "hybrid_active": False,
            "effective_date": "",
            "campaign_id": "",
            "partial_recovery_enabled": False,
            "full_recovery_losses": 0,
            "partial_recovery_fraction": 0.0,
        }
        if continuous_mode
        else crypto_15m_campaign_strategy(
            settings,
            bot_number=bot_number,
            portfolio=portfolio,
        )
    )
    support = setting_float_list(settings, "CRYPTO_15M_SUPPORT_STAKES") or [1.25, 2.5, 3.75]
    while len(support) < 3:
        support.append(support[-1] if support else 1.25)
    action_gate = crypto_15m_action_gate_configuration(
        settings,
        market_lane_name=candidate_lane,
    )
    unit_review = (
        crypto_15m_unit_candidate_review(settings, portfolio, candidate)
        if unit_mode
        else {
            "enabled": False,
            "eligible": False,
            "reason": "unit_staking_disabled",
        }
    )
    unit_context = (
        crypto_15m_campaign_lane_context(settings, portfolio, bot_number)
        if unit_mode
        else {}
    )
    recovery_cooldown = crypto_directional_recovery_cooldown(
        settings,
        portfolio,
        bot_number,
    )
    bounded_unit_recovery = (
        crypto_15m_bounded_unit_recovery_review(
            settings,
            candidate,
            unit_review,
            unit_context,
            recovery_cooldown,
        )
        if unit_mode
        else {
            "enabled": False,
            "active": False,
            "drawdown_active": False,
            "reason": "unit_staking_disabled",
            "requested_stake": 0.0,
        }
    )
    unit_recovery_overlay = bool(
        bounded_unit_recovery.get("enabled")
        and bounded_unit_recovery.get("drawdown_active")
    )
    cooldown_cycle_goal = (
        crypto_15m_campaign_lane_context(
            settings,
            portfolio,
            bot_number,
        ).get("cycle_goal")
        if recovery_cooldown.get("active") and not unit_mode
        else None
    )
    pilot = (
        {
            "enabled": False,
            "official_rotation": False,
            "candidate_match": False,
            "active": False,
            "eligible": False,
            "reason": (
                "disabled_by_evidence_tiered_gate"
                if action_gate.get("tiered")
                else "disabled_by_simple_action_gate"
            ),
            "affects_global_edge_floor": False,
            "base_cycle_only": False,
            "bot_number": bot_number,
        }
        if action_gate["enabled"]
        else crypto_low_edge_pilot_review(
            settings,
            portfolio,
            candidate,
            bot_number,
        )
    )
    candidate["low_edge_pilot"] = pilot
    if pilot.get("candidate_match") and not pilot.get("eligible"):
        context = crypto_15m_campaign_lane_context(
            settings,
            portfolio,
            bot_number,
        )
        review = {
            **context,
            "eligible": False,
            "reason": pilot.get("reason") or "campaign_low_edge_pilot_filter",
            "low_edge_pilot": pilot,
        }
        candidate["crypto_live_campaign"] = review
        candidate["strategy_owner"] = CRYPTO_15M_CAMPAIGN_OWNER
        candidate["bot_number"] = bot_number
        return review
    pilot_active = bool(pilot.get("eligible"))
    selected_price_tier = None
    if action_gate.get("tiered"):
        price = float(candidate.get("entry_price") or 0)
        selected_price_tier = next(
            (
                row
                for row in action_gate.get("price_tiers") or []
                if float(row["minimum_price_cents"])
                <= price
                <= float(row["maximum_price_cents"])
            ),
            None,
        )
    minimum_edge = (
        float(selected_price_tier["minimum_edge"])
        if selected_price_tier
        else action_gate["minimum_edge"]
    ) if action_gate["enabled"] else (
        float(pilot["minimum_edge"])
        if pilot_active
        else setting_float(settings, "CRYPTO_15M_MIN_EDGE")
    )
    minimum_confidence = (
        float(selected_price_tier["minimum_confidence"])
        if selected_price_tier
        else action_gate["minimum_confidence"]
    ) if action_gate["enabled"] else (
        float(pilot["minimum_confidence"])
        if pilot_active
        else setting_float(settings, "CRYPTO_15M_MIN_CONFIDENCE")
    )
    minimum_price = action_gate["minimum_price_cents"]
    maximum_price = action_gate["maximum_price_cents"]
    minimum_minutes = (
        float(selected_price_tier["minimum_minutes_remaining"])
        if selected_price_tier
        else action_gate["minimum_minutes_remaining"]
    )
    maximum_minutes = (
        float(selected_price_tier["maximum_minutes_remaining"])
        if selected_price_tier
        else action_gate["maximum_minutes_remaining"]
    )
    same_expiry_limit = action_gate["maximum_same_expiry_open"]
    dynamic_economic_gate_active = bool(
        unit_mode
        and (unit_review.get("dynamic_qualification") or {}).get(
            "affects_execution"
        )
    )
    economic_edge_floor = -1_000_000.0 if dynamic_economic_gate_active else minimum_edge
    economic_confidence_floor = (
        -1_000_000.0 if dynamic_economic_gate_active else minimum_confidence
    )
    review = review_crypto_15m_campaign_candidate(
        portfolio,
        candidate,
        local_date_key(),
        local_date_key,
        cycle_goals=(
            ()
            if continuous_mode
            else crypto_15m_campaign_internal_goals(settings, strategy)
        ),
        support_stakes=tuple(support[:3]),
        min_edge=economic_edge_floor,
        min_confidence=economic_confidence_floor,
        longshot_max_price=(
            minimum_price - 1.0
            if action_gate["enabled"]
            else setting_float(settings, "CRYPTO_15M_LONGSHOT_MAX_PRICE_CENTS")
        ),
        longshot_min_edge=(
            economic_edge_floor
            if dynamic_economic_gate_active
            else minimum_edge
            if action_gate["enabled"]
            else setting_float(settings, "CRYPTO_15M_LONGSHOT_MIN_EDGE")
        ),
        longshot_min_confidence=(
            economic_confidence_floor
            if dynamic_economic_gate_active
            else minimum_confidence
            if action_gate["enabled"]
            else setting_float(settings, "CRYPTO_15M_LONGSHOT_MIN_CONFIDENCE")
        ),
        strong_edge=setting_float(settings, "CRYPTO_15M_STRONG_MIN_EDGE"),
        strong_confidence=setting_float(settings, "CRYPTO_15M_STRONG_MIN_CONFIDENCE"),
        elite_edge=setting_float(settings, "CRYPTO_15M_ELITE_MIN_EDGE"),
        elite_confidence=setting_float(settings, "CRYPTO_15M_ELITE_MIN_CONFIDENCE"),
        min_price=minimum_price,
        max_price=maximum_price,
        min_minutes_remaining=minimum_minutes,
        max_minutes_remaining=maximum_minutes,
        mid_price_min=(
            minimum_price
            if action_gate["enabled"]
            else setting_float(settings, "CRYPTO_15M_MID_PRICE_MIN_CENTS")
        ),
        mid_price_max=(
            maximum_price
            if action_gate["enabled"]
            else setting_float(settings, "CRYPTO_15M_MID_PRICE_MAX_CENTS")
        ),
        mid_price_min_edge=(
            economic_edge_floor
            if dynamic_economic_gate_active
            else minimum_edge
            if action_gate["enabled"]
            else setting_float(settings, "CRYPTO_15M_MID_PRICE_MIN_EDGE")
        ),
        mid_price_min_confidence=(
            economic_confidence_floor
            if dynamic_economic_gate_active
            else minimum_confidence
            if action_gate["enabled"]
            else setting_float(settings, "CRYPTO_15M_MID_PRICE_MIN_CONFIDENCE")
        ),
        early_entry_min_minutes=(
            maximum_minutes
            if action_gate["enabled"]
            else setting_float(settings, "CRYPTO_15M_EARLY_ENTRY_MIN_MINUTES")
        ),
        early_entry_min_edge=(
            economic_edge_floor
            if dynamic_economic_gate_active
            else minimum_edge
            if pilot_active
            else (
                minimum_edge
                if action_gate["enabled"]
                else setting_float(settings, "CRYPTO_15M_EARLY_ENTRY_MIN_EDGE")
            )
        ),
        early_entry_min_confidence=(
            economic_confidence_floor
            if dynamic_economic_gate_active
            else max(
                minimum_confidence,
                setting_float(
                    settings,
                    "CRYPTO_15M_EARLY_ENTRY_MIN_CONFIDENCE",
                ),
            )
            if pilot_active
            else (
                minimum_confidence
                if action_gate["enabled"]
                else setting_float(
                    settings,
                    "CRYPTO_15M_EARLY_ENTRY_MIN_CONFIDENCE",
                )
            )
        ),
        normal_max_same_expiry_open=(
            same_expiry_limit
            if action_gate["enabled"]
            else setting_int(settings, "CRYPTO_15M_NORMAL_MAX_SAME_EXPIRY_OPEN")
        ),
        absolute_max_same_expiry_open=same_expiry_limit,
        same_expiry_elite_min_edge=setting_float(settings, "CRYPTO_15M_SAME_EXPIRY_ELITE_MIN_EDGE"),
        same_expiry_elite_min_confidence=setting_float(settings, "CRYPTO_15M_SAME_EXPIRY_ELITE_MIN_CONFIDENCE"),
        max_open=setting_int(settings, "CRYPTO_15M_MAX_OPEN") or 1,
        daily_loss_cap=setting_float(settings, "CRYPTO_15M_DAILY_LOSS_CAP"),
        daily_loss_cap_pct=setting_float(settings, "CRYPTO_15M_DAILY_LOSS_PCT"),
        fee_rate=setting_float(settings, "CRYPTO_SHADOW_FEE_RATE"),
        goal_tolerance=setting_float(settings, "CRYPTO_15M_GOAL_TOLERANCE"),
        partial_recovery_enabled=strategy["partial_recovery_enabled"],
        full_recovery_losses=strategy["full_recovery_losses"],
        partial_recovery_fraction=strategy["partial_recovery_fraction"],
        campaign_id=strategy["campaign_id"],
        bot_number=bot_number,
        primary_target_profit_cap=(
            cooldown_cycle_goal
            if recovery_cooldown.get("active")
            else None
        ),
        primary_recovery_mode_override="directional_cooldown",
        include_daily_settled=lambda value: crypto_15m_daily_capacity_includes(
            portfolio,
            bot_number,
            value,
        ),
        fixed_stake=(
            float(bounded_unit_recovery.get("requested_stake") or 0)
            if unit_mode
            else None
        ),
        fixed_stake_metadata=(
            {
                **unit_review,
                "bounded_recovery": bounded_unit_recovery,
            }
            if unit_mode
            else None
        ),
        daily_loss_remaining_override=(
            float(unit_context.get("daily_loss_remaining") or 0)
            if unit_mode
            else None
        ),
        cycle_completion_blocks=not unit_mode,
    )
    review["hybrid_strategy_active"] = strategy["hybrid_active"]
    review["hybrid_effective_date"] = strategy["effective_date"]
    review["goal_schedule_source"] = strategy["goal_schedule_source"]
    review["goal_schedule_override_date"] = strategy["goal_schedule_override_date"]
    review["goal_schedule_key"] = strategy["goal_schedule_key"]
    review["goal_schedule_locked"] = strategy["goal_schedule_locked"]
    review["configured_cycle_profit"] = strategy["configured_cycle_profit"]
    review["configured_cycle_profit_key"] = strategy["configured_cycle_profit_key"]
    review["configured_cycle_count"] = strategy["configured_cycle_count"]
    review["configured_cycle_count_key"] = strategy["configured_cycle_count_key"]
    review["effective_cycle_count"] = strategy["effective_cycle_count"]
    review["qualification_mode"] = action_gate["mode"]
    if dynamic_economic_gate_active:
        review["qualification_mode"] = "dynamic_qualification_v1"
    review["dynamic_qualification"] = unit_review.get("dynamic_qualification") or {}
    review["action_gate"] = action_gate
    review["selected_price_tier"] = selected_price_tier
    if unit_mode:
        unit_review = {
            **unit_review,
            "recovery_overlay_active": unit_recovery_overlay,
            "base_units": bounded_unit_recovery.get("base_units"),
            "recovery_bonus_units": bounded_unit_recovery.get("bonus_units"),
            "applied_total_units": bounded_unit_recovery.get("total_units"),
            "bounded_recovery": bounded_unit_recovery,
            "applied_stake": review.get("applied_stake"),
            "applied_contracts": review.get("applied_contracts"),
        }
        candidate["crypto_units"] = unit_review
        review["crypto_units"] = unit_review
        review["unit_staking_enabled"] = True
        review["cycle_completion_blocks"] = False
        review["bounded_unit_recovery"] = bounded_unit_recovery
        if continuous_mode:
            review.update({
                "active": not unit_context.get("daily_loss_cap_hit"),
                "status": (
                    "daily_loss_cap"
                    if unit_context.get("daily_loss_cap_hit")
                    else "active"
                ),
                "complete": False,
                "cycle_goals": [],
                "cycle_targets": [],
                "cycle_index": 0,
                "cycle_number": 0,
                "cycle_goal": 0.0,
                "cycle_target": 0.0,
                "cycle_start_profit": 0.0,
                "cycle_realized_profit": 0.0,
                "cycle_loss_count": 0,
                "cycle_win_count": 0,
                "target_remaining": 0.0,
                "progression_mode": "continuous_opportunity_units",
                "continuous_opportunity_mode": True,
                "cycle_workflow_enabled": False,
                "cycle_tracking_only": False,
                "continuous_recovery_ledger": True,
                "high_water_drawdown": dict(
                    unit_context.get("high_water_drawdown") or {}
                ),
                "pooled_recovery_enabled": bool(
                    unit_context.get("pooled_recovery_enabled")
                ),
                "pooled_high_water_drawdown": dict(
                    unit_context.get("pooled_high_water_drawdown") or {}
                ),
                "pooled_outstanding_drawdown": float(
                    unit_context.get("pooled_outstanding_drawdown") or 0
                ),
                "recovery_reservations": dict(
                    unit_context.get("recovery_reservations") or {}
                ),
                "outstanding_drawdown": float(
                    unit_context.get("outstanding_drawdown") or 0
                ),
                "realized_drawdown": float(
                    unit_context.get("outstanding_drawdown") or 0
                ),
                "partial_recovery_enabled": False,
                "partial_recovery_active": False,
                "full_recovery_target_profit": 0.0,
            })
        review["legacy_recovery_mode"] = review.get("recovery_mode")
        if unit_recovery_overlay:
            review["sizing_mode"] = "bounded_unit_recovery"
            review["recovery_mode"] = (
                "bounded_unit_recovery"
                if bounded_unit_recovery.get("active")
                else "bounded_unit_recovery_base_only"
            )
        else:
            review["sizing_mode"] = "probability_edge_kelly_units"
            review["recovery_mode"] = "unit_flat"
        # Preserve an earlier hard campaign failure (price, time, capacity,
        # market kind, and so on).  Unit diagnostics are still attached above,
        # but they must not overwrite the condition that actually rejected the
        # candidate.
        if not unit_review.get("eligible") and review.get("eligible"):
            review.update({
                "eligible": False,
                "reason": unit_review.get("reason") or "crypto_unit_quality_filter",
                "applied_stake": 0.0,
                "applied_contracts": 0,
                "required_contracts": 0,
                "failed_checks": [{
                    "metric": "crypto_unit_tier",
                    "actual": unit_review.get("metrics"),
                    "requirements": unit_review.get("requirements"),
                }],
            })
    maximum_model_disagreement = float(
        action_gate.get("maximum_model_disagreement") or 0
    )
    model_disagreement = float(
        (candidate.get("probability") or {}).get("model_disagreement") or 0
    )
    if (
        action_gate.get("tiered")
        and maximum_model_disagreement > 0
        and model_disagreement > maximum_model_disagreement
    ):
        review.update({
            "eligible": False,
            "reason": "campaign_model_disagreement_limit",
            "applied_stake": 0.0,
            "applied_contracts": 0,
            "required_contracts": 0,
            "failed_checks": [{
                "metric": "model_disagreement",
                "actual": round(model_disagreement, 4),
                "maximum": maximum_model_disagreement,
                "scope": "evidence_tiered_gate",
            }],
        })
    review["directional_recovery_cooldown"] = recovery_cooldown
    breaker = crypto_directional_recovery_breaker(
        settings,
        portfolio,
        candidate.get("side"),
    )
    review["directional_recovery_breaker"] = breaker
    if pilot_active:
        pilot = {
            **pilot,
            "active": bool(review.get("eligible")),
            "eligible": bool(review.get("eligible")),
            "reason": (
                "eligible"
                if review.get("eligible")
                else review.get("reason")
            ),
            "target_profit": review.get("target_profit"),
            "applied_stake": review.get("applied_stake"),
            "required_contracts": review.get("required_contracts"),
        }
        candidate["low_edge_pilot"] = pilot
        review["low_edge_pilot"] = pilot
    candidate["crypto_live_campaign"] = review
    candidate["strategy_owner"] = CRYPTO_15M_CAMPAIGN_OWNER
    candidate["bot_number"] = review.get("bot_number")
    return review


def crypto_15m_campaign_review(settings, portfolio, candidate, bot_number=None):
    configured_count = configured_crypto_15m_campaign_bot_count(settings)
    if bot_number is not None:
        number = crypto_campaign_bot_number({"bot_number": bot_number})
        if number > configured_count:
            context = crypto_15m_campaign_lane_context(settings, portfolio, number)
            review = {
                **context,
                "eligible": False,
                "reason": "campaign_bot_disabled",
            }
            candidate["crypto_live_campaign"] = review
            candidate["strategy_owner"] = CRYPTO_15M_CAMPAIGN_OWNER
            candidate["bot_number"] = number
            return review
        review = crypto_15m_campaign_lane_review(settings, portfolio, candidate, number)
        review["configured_bot_count"] = configured_count
        candidate["crypto_live_campaign"] = review
        return review

    reviews = []
    for number in crypto_15m_campaign_bot_order(settings, portfolio):
        review = crypto_15m_campaign_lane_review(settings, portfolio, candidate, number)
        review["configured_bot_count"] = configured_count
        candidate["crypto_live_campaign"] = review
        reviews.append(review)
        if review.get("eligible"):
            return review
    if not reviews:
        return {"active": True, "eligible": False, "reason": "campaign_no_bots_configured"}
    availability_reasons = {
        "campaign_complete",
        "campaign_daily_loss_cap",
        "campaign_open_slots_full",
        "campaign_asset_window_duplicate",
        "campaign_exact_contract_conflict",
        "campaign_expiry_window_concentration",
        "campaign_expiry_window_requires_elite",
        "campaign_low_edge_pilot_open_limit",
        "campaign_low_edge_pilot_sample_complete",
        "campaign_directional_recovery_breaker",
        "campaign_unit_capacity",
    }
    for review in reviews:
        if review.get("reason") not in availability_reasons:
            candidate["crypto_live_campaign"] = review
            candidate["bot_number"] = review.get("bot_number")
            return review
    if all(review.get("reason") == "campaign_complete" for review in reviews):
        selected = reviews[0]
    elif all(review.get("reason") in {"campaign_complete", "campaign_daily_loss_cap"} for review in reviews):
        selected = next((row for row in reviews if row.get("reason") == "campaign_daily_loss_cap"), reviews[0])
    else:
        selected = next(
            (
                row for row in reviews
                if row.get("reason") == "campaign_exact_contract_conflict"
            ),
            next(
                (
                    row for row in reviews
                    if row.get("reason") in {
                        "campaign_open_slots_full",
                        "campaign_asset_window_duplicate",
                    }
                ),
                reviews[0],
            ),
        )
    candidate["crypto_live_campaign"] = selected
    candidate["bot_number"] = selected.get("bot_number")
    return selected


def commodity_15m_campaign_readiness_reasons(settings, candidate):
    """Keep settlement-feed safeguards while sharing the campaign action gate."""
    if str(candidate.get("market_lane") or market_lane(candidate)) != "commodity_15m":
        return []
    reasons = []
    if not setting_bool(settings, "MULTI_MARKET_ENABLED"):
        reasons.append("multi_market_disabled")
    if execution_mode(settings) == "live" and not setting_bool(
        settings,
        "MULTI_MARKET_LIVE_ENABLED",
    ):
        reasons.append("multi_market_live_disabled")
    if execution_mode(settings) == "live" and not setting_bool(
        settings,
        "MULTI_MARKET_COMMODITY_LIVE_ENABLED",
    ):
        reasons.append("commodity_live_shadow")
    if candidate.get("market_kind") not in {"above", "below", "range"}:
        reasons.append("multi_market_unsupported_contract")
    model = candidate.get("model") or {}
    valid_source = model.get("data_source") == "pyth" or (
        model.get("data_source") == "kalshi_anchored_pyth_core"
        and model.get("proxy_ready")
    )
    if not valid_source or model.get("settlement_source") != "Pyth":
        reasons.append("commodity_pyth_readiness")
    if setting_bool(settings, "MULTI_MARKET_REQUIRE_PYTH_HISTORY") and int(
        model.get("history_points") or 0
    ) < 60:
        reasons.append("commodity_pyth_history_required")
    return reasons


def candidate_passes(settings, portfolio, candidate):
    if is_spot_flow_live_pilot_candidate(candidate):
        review = candidate.get("spot_flow_live_pilot") or {}
        candidate["skip_reasons"] = list(review.get("reasons") or [])
        candidate["decision"] = "eligible" if review.get("eligible") else "skipped"
        return bool(review.get("eligible"))
    lane = str(candidate.get("market_lane") or market_lane(candidate))
    campaign_lanes = {"crypto_15m", "commodity_15m"}
    if lane not in campaign_lanes and lane != "unsupported":
        return multi_market_candidate_passes(settings, portfolio, candidate)
    if (
        setting_bool(settings, "CRYPTO_15M_CAMPAIGN_ENABLED")
        and lane in campaign_lanes
    ):
        reasons = commodity_15m_campaign_readiness_reasons(settings, candidate)
        if (
            setting_bool(settings, "CRYPTO_15M_CONSERVATIVE_EDGE_REQUIRED")
            and not (
                lane == "crypto_15m"
                and setting_bool(settings, "CRYPTO_15M_UNIT_STAKING_ENABLED")
            )
            and "edge_low" in candidate
            and float(candidate.get("edge_low") or -999)
            <= setting_float(settings, "CRYPTO_15M_MIN_EDGE_LOW")
        ):
            reasons.append("conservative_edge_not_positive")
        if (
            setting_bool(settings, "CRYPTO_FEE_UNKNOWN_FAIL_CLOSED")
            and "fee_schedule_exact" in candidate
            and not candidate.get("fee_schedule_exact")
        ):
            reasons.append("fee_schedule_unverified")
        review = crypto_15m_campaign_review(settings, portfolio, candidate)
        slippage_reconfirmation = live_slippage_reconfirmation_review(
            settings,
            candidate,
        )
        if (
            slippage_reconfirmation.get("active")
            and not slippage_reconfirmation.get("ready")
        ):
            reasons.append("live_quote_slippage_reconfirm_wait")
        if live_depth_retry_cooldown_remaining(settings, candidate) > 0:
            reasons.append("live_depth_retry_cooldown")
        if duplicate_open(portfolio, candidate["ticker"], candidate["side"]):
            reasons.append("duplicate_open")
        max_open_bets = setting_int(settings, "CRYPTO_MAX_OPEN_BETS")
        if max_open_bets > 0 and len(bot_open_bets(portfolio)) >= max_open_bets:
            reasons.append("max_open_bets")
        max_asset = setting_int(settings, "CRYPTO_MAX_OPEN_PER_ASSET")
        if max_asset > 0 and open_count_for(portfolio, "asset", candidate.get("asset")) >= max_asset:
            reasons.append("asset_cap")
        disagreement_guard = candidate.get("disagreement_guard") or {}
        if disagreement_guard.get("enabled") and not disagreement_guard.get("ok"):
            reasons.append(disagreement_guard.get("reason") or "model_market_disagreement_unconfirmed")
        if not review.get("eligible"):
            reasons.append(review.get("reason") or "crypto_15m_campaign_filter")
        # Directional confirmation is the final campaign veto. Evaluating it
        # only after every other gate passes keeps skip analytics focused on
        # the reason that actually prevented an otherwise-valid live bet.
        # A commodity live pause is observation-only. Still evaluate the
        # directional veto so shadow analytics contain only candidates that
        # would otherwise have qualified for a live order.
        execution_reasons = [
            reason for reason in reasons if reason != "commodity_live_shadow"
        ]
        if not execution_reasons:
            directional_confirmation = crypto_15m_directional_confirmation_review(
                settings,
                candidate,
            )
            candidate["directional_confirmation"] = directional_confirmation
            if (
                directional_confirmation.get("enabled")
                and not directional_confirmation.get("ok")
            ):
                reasons.append(
                    directional_confirmation.get("reason")
                    or "campaign_directional_confirmation"
                )
        adaptive_control = adaptive_candidate_control(settings, candidate)
        candidate["adaptive_control"] = adaptive_control
        if adaptive_control.get("shadow"):
            reasons.append("adaptive_lane_shadow")
        candidate["skip_reasons"] = reasons
        candidate["decision"] = "skipped" if reasons else "eligible"
        return not reasons
    reasons = []
    entry_price = float(candidate.get("entry_price") or 0)
    edge = float(candidate.get("edge") or 0)
    confidence = float(candidate.get("confidence") or 0)
    if setting_float(settings, "CRYPTO_MIN_VOLUME") > candidate.get("volume", 0):
        reasons.append("low_volume")
    if setting_float(settings, "CRYPTO_MIN_LIQUIDITY") > candidate.get("liquidity", 0):
        reasons.append("low_liquidity")
    if edge < setting_float(settings, "CRYPTO_MIN_EDGE"):
        reasons.append("edge_too_low")
    if confidence < setting_float(settings, "CRYPTO_MIN_CONFIDENCE"):
        reasons.append("confidence_too_low")
    if entry_price < setting_float(settings, "CRYPTO_MIN_ENTRY_PRICE_CENTS"):
        reasons.append("entry_price_too_low")
    if entry_price > setting_float(settings, "CRYPTO_MAX_ENTRY_PRICE_CENTS"):
        reasons.append("entry_price_too_high")
    if setting_bool(settings, "CRYPTO_PRICE_DISCIPLINE_ENABLED"):
        favorite_min = setting_float(settings, "CRYPTO_FAVORITE_PRICE_MIN_CENTS")
        favorite_max = setting_float(settings, "CRYPTO_FAVORITE_PRICE_MAX_CENTS")
        heavy_max = setting_float(settings, "CRYPTO_HEAVY_FAVORITE_PRICE_MAX_CENTS")
        if entry_price > heavy_max:
            reasons.append("crypto_heavy_favorite_price_blocked")
        elif entry_price > favorite_max:
            if edge < setting_float(settings, "CRYPTO_HEAVY_FAVORITE_MIN_EDGE") or confidence < setting_float(settings, "CRYPTO_HEAVY_FAVORITE_MIN_CONFIDENCE"):
                reasons.append("crypto_heavy_favorite_needs_elite_quality")
        elif entry_price > favorite_min:
            if edge < setting_float(settings, "CRYPTO_FAVORITE_MIN_EDGE") or confidence < setting_float(settings, "CRYPTO_FAVORITE_MIN_CONFIDENCE"):
                reasons.append("crypto_favorite_needs_stronger_quality")
    if duplicate_open(portfolio, candidate["ticker"], candidate["side"]):
        reasons.append("duplicate_open")
    max_open_bets = setting_int(settings, "CRYPTO_MAX_OPEN_BETS")
    if max_open_bets > 0 and len(open_bets(portfolio)) >= max_open_bets:
        reasons.append("max_open_bets")
    if setting_int(settings, "CRYPTO_MAX_OPEN_PER_EVENT") > 0 and open_count_for(portfolio, "event_ticker", candidate.get("event_ticker")) >= setting_int(settings, "CRYPTO_MAX_OPEN_PER_EVENT"):
        reasons.append("same_event_cap")
    if setting_int(settings, "CRYPTO_MAX_OPEN_PER_ASSET") > 0 and open_count_for(portfolio, "asset", candidate.get("asset")) >= setting_int(settings, "CRYPTO_MAX_OPEN_PER_ASSET"):
        reasons.append("asset_cap")
    if setting_bool(settings, "CRYPTO_LIVE_CORE_ENABLED"):
        core = crypto_live_core_review(settings, candidate, float(portfolio.get("balance") or 0))
        candidate["live_core"] = core
        if not core.get("eligible"):
            reasons.append("live_core_quality_filter")
    adaptive_control = adaptive_candidate_control(settings, candidate)
    candidate["adaptive_control"] = adaptive_control
    if adaptive_control.get("shadow"):
        reasons.append("adaptive_lane_shadow")
    candidate["skip_reasons"] = reasons
    candidate["decision"] = "skipped" if reasons else "eligible"
    return not reasons


def multi_market_quality_thresholds(settings, price):
    minimum_edge = setting_float(settings, "MULTI_MARKET_LIVE_MIN_EDGE")
    minimum_confidence = setting_float(
        settings,
        "MULTI_MARKET_LIVE_MIN_CONFIDENCE",
    )
    tier = "standard_price"
    if setting_bool(settings, "MULTI_MARKET_TIERED_PRICE_QUALITY_ENABLED"):
        if price <= setting_float(settings, "MULTI_MARKET_LOW_PRICE_MAX_CENTS"):
            tier = "low_price"
            minimum_edge = max(
                minimum_edge,
                setting_float(settings, "MULTI_MARKET_LOW_PRICE_MIN_EDGE"),
            )
            minimum_confidence = max(
                minimum_confidence,
                setting_float(settings, "MULTI_MARKET_LOW_PRICE_MIN_CONFIDENCE"),
            )
        elif price >= setting_float(settings, "MULTI_MARKET_HIGH_PRICE_MIN_CENTS"):
            tier = "high_price"
            minimum_edge = max(
                minimum_edge,
                setting_float(settings, "MULTI_MARKET_HIGH_PRICE_MIN_EDGE"),
            )
            minimum_confidence = max(
                minimum_confidence,
                setting_float(settings, "MULTI_MARKET_HIGH_PRICE_MIN_CONFIDENCE"),
            )
    return {
        "tier": tier,
        "minimum_edge": minimum_edge,
        "minimum_confidence": minimum_confidence,
    }


def multi_market_candidate_passes(settings, portfolio, candidate):
    lane = str(candidate.get("market_lane") or market_lane(candidate))
    reasons = []
    if not setting_bool(settings, "MULTI_MARKET_ENABLED"):
        reasons.append("multi_market_disabled")
    if execution_mode(settings) == "live" and not setting_bool(
        settings,
        "MULTI_MARKET_LIVE_ENABLED",
    ):
        reasons.append("multi_market_live_disabled")
    minutes = float(candidate.get("minutes_to_close") or 0)
    if lane.endswith("15m"):
        minimum_minutes = setting_float(settings, "MULTI_MARKET_15M_MIN_MINUTES_REMAINING")
        maximum_minutes = setting_float(settings, "MULTI_MARKET_15M_MAX_MINUTES_REMAINING")
    else:
        minimum_minutes = setting_float(settings, "MULTI_MARKET_HOURLY_MIN_MINUTES_REMAINING")
        maximum_minutes = setting_float(settings, "MULTI_MARKET_HOURLY_MAX_MINUTES_REMAINING")
    if minutes < minimum_minutes or minutes > maximum_minutes:
        reasons.append("multi_market_entry_window")
    edge = float(candidate.get("edge") or 0)
    confidence = float(candidate.get("confidence") or 0)
    price = float(candidate.get("entry_price") or 0)
    quality = multi_market_quality_thresholds(settings, price)
    if edge < quality["minimum_edge"]:
        reasons.append(
            f"multi_market_{quality['tier']}_edge_too_low"
            if quality["tier"] != "standard_price"
            else "multi_market_edge_too_low"
        )
    if confidence < quality["minimum_confidence"]:
        reasons.append(
            f"multi_market_{quality['tier']}_confidence_too_low"
            if quality["tier"] != "standard_price"
            else "multi_market_confidence_too_low"
        )
    if not (
        setting_float(settings, "MULTI_MARKET_LIVE_MIN_PRICE_CENTS")
        <= price
        <= setting_float(settings, "MULTI_MARKET_LIVE_MAX_PRICE_CENTS")
    ):
        reasons.append("multi_market_price_range")
    if candidate.get("market_kind") not in {"above", "below", "range"}:
        reasons.append("multi_market_unsupported_contract")
    model = candidate.get("model") or {}
    if lane.startswith("commodity"):
        valid_source = model.get("data_source") == "pyth" or (
            model.get("data_source") == "kalshi_anchored_pyth_core"
            and model.get("proxy_ready")
        )
        if (
            not valid_source
            or model.get("settlement_source") != "Pyth"
        ):
            reasons.append("commodity_pyth_readiness")
        if setting_bool(settings, "MULTI_MARKET_REQUIRE_PYTH_HISTORY") and int(
            model.get("history_points") or 0
        ) < 60:
            reasons.append("commodity_pyth_history_required")
    if live_depth_retry_cooldown_remaining(settings, candidate) > 0:
        reasons.append("live_depth_retry_cooldown")
    if duplicate_open(portfolio, candidate.get("ticker"), candidate.get("side")):
        reasons.append("duplicate_open")
    max_open = setting_int(settings, "CRYPTO_MAX_OPEN_BETS")
    if max_open > 0 and len(bot_open_bets(portfolio)) >= max_open:
        reasons.append("max_open_bets")
    if setting_int(settings, "CRYPTO_MAX_OPEN_PER_EVENT") > 0 and open_count_for(
        portfolio,
        "event_ticker",
        candidate.get("event_ticker"),
    ) >= setting_int(settings, "CRYPTO_MAX_OPEN_PER_EVENT"):
        reasons.append("same_event_cap")
    if setting_int(settings, "CRYPTO_MAX_OPEN_PER_ASSET") > 0 and open_count_for(
        portfolio,
        "asset",
        candidate.get("asset"),
    ) >= setting_int(settings, "CRYPTO_MAX_OPEN_PER_ASSET"):
        reasons.append("asset_cap")
    lane_open = sum(
        1 for row in bot_open_bets(portfolio)
        if str((row.get("multi_market") or {}).get("lane") or row.get("market_lane") or "") == lane
    )
    if setting_int(settings, "MULTI_MARKET_MAX_OPEN_PER_LANE") > 0 and lane_open >= setting_int(
        settings,
        "MULTI_MARKET_MAX_OPEN_PER_LANE",
    ):
        reasons.append("multi_market_lane_cap")
    cluster = candidate.get("position_cluster") or position_cluster_key(candidate)
    cluster_open = sum(
        1 for row in bot_open_bets(portfolio)
        if (row.get("position_cluster") or position_cluster_key(row)) == cluster
    )
    if setting_int(settings, "MULTI_MARKET_MAX_OPEN_PER_CLUSTER") > 0 and cluster_open >= setting_int(
        settings,
        "MULTI_MARKET_MAX_OPEN_PER_CLUSTER",
    ):
        reasons.append("multi_market_cluster_cap")
    group = candidate.get("exposure_group") or exposure_group(candidate.get("asset"))
    group_open = sum(
        1 for row in bot_open_bets(portfolio)
        if (row.get("exposure_group") or exposure_group(row.get("asset"))) == group
    )
    if setting_int(settings, "MULTI_MARKET_MAX_OPEN_PER_EXPOSURE_GROUP") > 0 and group_open >= setting_int(
        settings,
        "MULTI_MARKET_MAX_OPEN_PER_EXPOSURE_GROUP",
    ):
        reasons.append("multi_market_exposure_group_cap")
    review = {
        "active": True,
        "enabled": setting_bool(settings, "MULTI_MARKET_ENABLED"),
        "live_enabled": setting_bool(settings, "MULTI_MARKET_LIVE_ENABLED"),
        "eligible": not reasons,
        "reason": reasons[0] if reasons else "eligible",
        "lane": lane,
        "owner": f"{lane}_pilot",
        "fixed_stake_cap": setting_float(settings, "MULTI_MARKET_LIVE_MAX_STAKE"),
        "quality_tier": quality["tier"],
        "minimum_edge": quality["minimum_edge"],
        "minimum_confidence": quality["minimum_confidence"],
        "recovery_enabled": False,
        "position_cluster": cluster,
        "exposure_group": group,
    }
    candidate["multi_market"] = review
    candidate["strategy_owner"] = review["owner"]
    candidate["position_cluster"] = cluster
    candidate["exposure_group"] = group
    candidate["skip_reasons"] = list(dict.fromkeys(reasons))
    candidate["decision"] = "skipped" if reasons else "eligible"
    return not reasons


def candidate_stake(settings, candidate, balance, portfolio=None, phase_two=None):
    if is_spot_flow_live_pilot_candidate(candidate):
        review = candidate.get("spot_flow_live_pilot") or {}
        if not review.get("eligible"):
            return 0.0
        # Exact whole-contract principal; fees are retained separately in the
        # pilot review and never create an extra contract.
        return round(
            min(
                float((review.get("sizing") or {}).get("principal_stake") or 0),
                max(0.0, float(balance or 0)),
            ),
            2,
        )
    lane = str(candidate.get("market_lane") or market_lane(candidate))
    if lane not in {"crypto_15m", "commodity_15m"} and lane != "unsupported":
        side_prob = candidate_side_probability(candidate)
        stake = kelly_stake(
            side_prob,
            candidate["entry_price"],
            balance,
            settings,
            probability_low_pct=candidate.get("selected_side_probability_low"),
            fee_cents=candidate.get("exact_fee_cents") or 0,
            slippage_cents=candidate.get("expected_slippage_cents") or 0,
        )
        stake = max(setting_float(settings, "CRYPTO_MIN_STAKE"), stake)
        return round(
            min(
                stake,
                setting_float(settings, "MULTI_MARKET_LIVE_MAX_STAKE"),
                balance,
            ),
            2,
        )
    if setting_bool(settings, "CRYPTO_15M_CAMPAIGN_ENABLED"):
        if portfolio is None:
            return 0.0
        assigned_bot = (candidate.get("crypto_live_campaign") or {}).get("bot_number") or candidate.get("bot_number")
        review = crypto_15m_campaign_review(settings, portfolio, candidate, bot_number=assigned_bot)
        stake = min(float(review.get("applied_stake") or 0), balance)
        return apply_candidate_stake_multiplier(candidate, stake)
    if setting_bool(settings, "CRYPTO_LIVE_CORE_ENABLED"):
        core = crypto_live_core_review(settings, candidate, balance)
        candidate["live_core"] = core
        stake = float(core.get("applied_stake") or 0)
        if portfolio is not None and stake > 0:
            stake = apply_crypto_event_diminishing(settings, portfolio, candidate, stake)
        return apply_candidate_stake_multiplier(candidate, min(stake, balance))
    side_prob = candidate_side_probability(candidate)
    stake = kelly_stake(
        side_prob,
        candidate["entry_price"],
        balance,
        settings,
        probability_low_pct=candidate.get("selected_side_probability_low"),
        fee_cents=candidate.get("exact_fee_cents") or 0,
        slippage_cents=candidate.get("expected_slippage_cents") or 0,
    )
    stake = max(stake, setting_float(settings, "CRYPTO_MIN_STAKE"))
    stake = min(stake, setting_float(settings, "CRYPTO_MAX_STAKE"), balance)
    if portfolio is not None and phase_two is not None:
        stake = apply_crypto_phase_two_staking(settings, portfolio, candidate, stake, balance, phase_two)
    if not (candidate.get("phase_two") or {}).get("active"):
        stake = apply_crypto_selective_edge_scaling(settings, candidate, stake, balance)
        if portfolio is not None and phase_two is not None:
            stake = apply_crypto_small_edge_staking(settings, portfolio, candidate, stake, balance, phase_two)
        if stake > 0:
            stake = apply_crypto_shared_recovery_staking(settings, candidate, stake, balance)
    if portfolio is not None and stake > 0:
        stake = apply_crypto_event_diminishing(settings, portfolio, candidate, stake)
        cluster = candidate.get("position_cluster") or position_cluster_key(candidate)
        cluster_exposure = sum(
            float(row.get("stake") or 0)
            for row in bot_open_bets(portfolio)
            if (row.get("position_cluster") or position_cluster_key(row)) == cluster
        )
        cluster_cap = max(0.0, balance * setting_float(settings, "CRYPTO_KELLY_CLUSTER_EXPOSURE_PCT"))
        if cluster_cap > 0:
            stake = min(stake, max(0.0, cluster_cap - cluster_exposure))
    return apply_candidate_stake_multiplier(candidate, min(stake, balance))


def place_paper_bet(settings, portfolio, candidate, stake=None, phase_two=None):
    balance = float(portfolio.get("balance") or 0)
    stake = candidate_stake(settings, candidate, balance, portfolio, phase_two) if stake is None else stake
    if stake <= 0:
        candidate["skip_reasons"].append("stake_unavailable")
        candidate["decision"] = "skipped"
        return None
    unit_price = float(candidate["entry_price"]) / 100.0
    fee_per_contract = max(0.0, float(candidate.get("exact_fee_cents") or 0)) / 100.0
    if unit_price <= 0:
        return None
    contracts = float(stake) / unit_price
    def paper_order_fee(contract_count):
        if candidate.get("fee_schedule"):
            return float(kalshi_order_fee(
                candidate["entry_price"],
                contract_count,
                schedule=candidate.get("fee_schedule"),
                liquidity_role="taker",
                fallback_rate=setting_float(settings, "CRYPTO_SHADOW_FEE_RATE"),
            ).get("fee_dollars") or 0)
        return contract_count * fee_per_contract

    fee = paper_order_fee(contracts)
    if float(stake) + fee > balance + 1e-9:
        contracts *= balance / max(1e-9, float(stake) + fee)
        fee = paper_order_fee(contracts)
        stake = round(contracts * unit_price, 2)
        if stake + fee > balance + 1e-9:
            stake = max(0.0, round(balance - fee, 2))
            contracts = stake / unit_price
            fee = paper_order_fee(contracts)
    owner = crypto_strategy_owner(candidate)
    bet = {
        "id": str(uuid.uuid4()),
        "status": "open",
        "mode": "paper",
        "placed_at": iso_now(),
        "ticker": candidate["ticker"],
        "event_ticker": candidate.get("event_ticker"),
        "series_ticker": candidate.get("series_ticker"),
        "asset": candidate["asset"],
        "title": candidate.get("title"),
        "market_kind": candidate["market_kind"],
        "market_lane": candidate.get("market_lane"),
        "position_cluster": candidate.get("position_cluster"),
        "exposure_group": candidate.get("exposure_group"),
        "side": candidate["side"],
        "entry_price": candidate["entry_price"],
        "stake": stake,
        "contracts": round(contracts, 4),
        "fee": round(fee, 4),
        "fee_per_contract": round(fee / contracts, 6) if contracts > 0 else 0.0,
        "fee_schedule": candidate.get("fee_schedule"),
        "model_prob_yes": candidate["model_prob_yes"],
        "edge": candidate["edge"],
        "confidence": candidate["confidence"],
        "expected_edge": candidate.get("expected_edge"),
        "edge_low": candidate.get("edge_low"),
        "probability_net_edge_positive": candidate.get("probability_net_edge_positive"),
        "expected_slippage_cents": candidate.get("expected_slippage_cents"),
        "data_quality": candidate.get("data_quality"),
        "close_time": candidate.get("close_time"),
        "floor_strike": candidate.get("floor_strike"),
        "cap_strike": candidate.get("cap_strike"),
        "model": candidate.get("model"),
        "probability": candidate.get("probability"),
        "microstructure": candidate.get("microstructure"),
        "kalshi_microstructure": candidate.get("kalshi_microstructure"),
        "live_underlying_refresh": candidate.get("live_underlying_refresh"),
        "flow_review": candidate.get("flow_review"),
        "disagreement_guard": candidate.get("disagreement_guard"),
        "directional_confirmation": candidate.get("directional_confirmation"),
        "learned_15m_model": candidate.get("learned_15m_model"),
        "market_regime_shadow": candidate.get("market_regime_shadow"),
        "market_regime_live": candidate.get("market_regime_live"),
        "ai_review": candidate.get("ai_review"),
        "grok_review": candidate.get("grok_review"),
        "selective_edge": candidate.get("selective_edge"),
        "shared_recovery": candidate.get("shared_recovery"),
        "phase_two": candidate.get("phase_two"),
        "phase_two_attempt_id": candidate.get("phase_two_attempt_id"),
        "phase_two_cycle": candidate.get("phase_two_cycle"),
        "shadow": candidate.get("shadow"),
        "small_edge": candidate.get("small_edge"),
        "low_edge_pilot": candidate.get("low_edge_pilot"),
        "adaptive_control": candidate.get("adaptive_control"),
        "strategy_identity": candidate.get("strategy_identity"),
        "strategy_version": candidate.get("strategy_version"),
        "strategy_config_hash": candidate.get("strategy_config_hash"),
        "feature_schema_version": candidate.get("feature_schema_version"),
        "crypto_units": candidate.get("crypto_units"),
        "crypto_live_campaign": candidate.get("crypto_live_campaign"),
        "live_core": candidate.get("live_core"),
        "event_diversification": candidate.get("event_diversification"),
        "multi_market": candidate.get("multi_market"),
        "strategy_owner": owner,
        "bot_number": crypto_campaign_bot_number(candidate) if owner == CRYPTO_15M_CAMPAIGN_OWNER else None,
    }
    portfolio["balance"] = round(
        float(portfolio.get("balance") or 0) - float(stake) - fee,
        2,
    )
    portfolio.setdefault("bets", []).append(bet)
    if owner == CRYPTO_15M_CAMPAIGN_OWNER:
        campaign = bet.get("crypto_live_campaign") or {}
        advance_crypto_15m_campaign_bot_order(
            portfolio,
            bet.get("bot_number"),
            campaign.get("configured_bot_count"),
        )
        mark_correlated_campaign_window(portfolio, bet)
    candidate["decision"] = "placed"
    log_line(
        f"PAPER CRYPTO BET: {bet['side'].upper()} {bet['asset']} {bet['ticker']} "
        f"stake=${stake:.2f} owner={owner} price={bet['entry_price']:.1f}c edge={bet['edge']:.2f}% "
        f"conf={bet['confidence']} selective={selective_tier(bet)} recovery={recovery_tier(bet)}"
    )
    event_line({"type": "paper_bet", "bet": bet})
    record_crypto_phase_two_placement(bet)
    return bet


def crypto_live_order_metadata(candidate, requested_stake):
    owner = crypto_strategy_owner(candidate)
    sizing_context = (
        candidate.get(PATIENT_FIELD)
        or candidate.get("spot_flow_live_pilot")
        or candidate.get("crypto_live_campaign")
        or candidate.get("live_core")
        or candidate.get("phase_two")
        or candidate.get("shared_recovery")
        or candidate.get("small_edge")
        or candidate.get("selective_edge")
        or {}
    )
    base_stake = money(sizing_context.get("base_stake") or requested_stake)
    recovery_context = candidate.get("shared_recovery") or {}
    return {
        "ticker": candidate.get("ticker"),
        "order_side": candidate.get("side"),
        "exchange_index": candidate.get("exchange_index"),
        "asset": candidate.get("asset"),
        "event_ticker": candidate.get("event_ticker"),
        "edge": candidate.get("edge"),
        "expected_edge": candidate.get("expected_edge"),
        "edge_low": candidate.get("edge_low"),
        "confidence": candidate.get("confidence"),
        "probability_net_edge_positive": candidate.get("probability_net_edge_positive"),
        "exact_fee_cents": candidate.get("exact_fee_cents"),
        "expected_slippage_cents": candidate.get("expected_slippage_cents"),
        "data_quality": candidate.get("data_quality"),
        "strategy_owner": owner,
        "spot_flow_live_pilot": candidate.get("spot_flow_live_pilot"),
        PATIENT_FIELD: candidate.get(PATIENT_FIELD),
        "bot_number": crypto_campaign_bot_number(candidate) if owner == CRYPTO_15M_CAMPAIGN_OWNER else None,
        "crypto_live_campaign": bool((candidate.get("crypto_live_campaign") or {}).get("enabled")),
        "campaign_role": (candidate.get("crypto_live_campaign") or {}).get("role"),
        "campaign_cycle": (candidate.get("crypto_live_campaign") or {}).get("cycle_number"),
        "campaign_bot_number": (candidate.get("crypto_live_campaign") or {}).get("bot_number"),
        "crypto_units": candidate.get("crypto_units"),
        "crypto_unit_count": (candidate.get("crypto_units") or {}).get("target_units"),
        "crypto_unit_size": (candidate.get("crypto_units") or {}).get("unit_size"),
        "live_unit_depth_downshift": candidate.get("live_unit_depth_downshift"),
        "crypto_sizing_mode": (candidate.get("crypto_live_campaign") or {}).get("sizing_mode"),
        "bounded_unit_recovery": (
            (candidate.get("crypto_live_campaign") or {}).get(
                "bounded_unit_recovery"
            )
            or (candidate.get("crypto_units") or {}).get("bounded_recovery")
        ),
        "phase_two": bool((candidate.get("phase_two") or {}).get("active")),
        "phase_two_attempt_id": candidate.get("phase_two_attempt_id"),
        "phase_two_cycle": candidate.get("phase_two_cycle"),
        "small_edge": bool((candidate.get("small_edge") or {}).get("active")),
        "low_edge_pilot": bool(
            (candidate.get("low_edge_pilot") or {}).get("active")
        ),
        "recovery": bool(recovery_context.get("active")),
        "base_stake": base_stake,
        "enhanced_sizing": requested_stake > base_stake + 0.009,
        "support_tier": (candidate.get("live_core") or {}).get("tier") or (candidate.get("small_edge") or {}).get("support_tier") or (candidate.get("selective_edge") or {}).get("tier"),
        "recovery_expected_profit": recovery_context.get("expected_profit") or recovery_context.get("slice_target_profit"),
    }


def preflight_live_kalshi_order(settings, candidate, stake):
    requested_stake = float(stake or 0)
    sprint_freeze = crypto_15m_sprint_execution_freeze(settings)
    if sprint_freeze.get("active") and not is_spot_flow_live_pilot_candidate(
        candidate
    ):
        return {
            "ok": False,
            "enabled": True,
            "error": "crypto_15m_sprint_live_freeze",
            "approved_stake": 0.0,
            "requested_stake": requested_stake,
            "execution_freeze": sprint_freeze,
        }
    if not setting_bool(settings, "CRYPTO_LIVE_REQUIRE_SHARED_BANKROLL"):
        return {"ok": True, "enabled": False, "approved_stake": requested_stake}
    if not live_order_review:
        return {"ok": False, "error": "shared_bankroll_unavailable", "approved_stake": 0.0}
    price = int(round(float(candidate.get("entry_price") or 0)))
    return live_order_review(
        "crypto",
        requested_stake,
        price_cents=price,
        metadata=crypto_live_order_metadata(candidate, requested_stake),
    )


def parse_kalshi_orderbook_levels(payload, side):
    """Return (price_cents, contracts) from fixed-point or legacy order books."""
    orderbook = (payload or {}).get("orderbook_fp") or (payload or {}).get("orderbook") or {}
    levels = orderbook.get(f"{side}_dollars") or orderbook.get(side) or []
    parsed = []
    for level in levels:
        if isinstance(level, dict):
            raw_price = (
                level.get("price_dollars")
                or level.get("price")
                or level.get(f"{side}_price_dollars")
                or level.get(f"{side}_price")
            )
            raw_count = level.get("count_fp") or level.get("count") or level.get("quantity") or level.get("size")
        elif isinstance(level, (list, tuple)) and len(level) >= 2:
            raw_price, raw_count = level[0], level[1]
        else:
            continue
        try:
            numeric_price = float(raw_price)
            price_cents = numeric_price * 100.0 if numeric_price <= 1.0 else numeric_price
            count = float(raw_count)
        except (TypeError, ValueError):
            continue
        if 0 < price_cents < 100 and count > 0:
            parsed.append((round(price_cents, 4), count))
    return parsed


def kalshi_orderbook_depth_summary(payload, order_side, required_contracts=0, limit_price_cents=None):
    """Describe the live contra book, including nearby prices outside the limit."""
    selected_side = str(order_side or "yes").strip().lower()
    contra_side = "no" if selected_side in {"yes", "y", "bid"} else "yes"
    contra_levels = sorted(
        parse_kalshi_orderbook_levels(payload, contra_side),
        key=lambda row: row[0],
        reverse=True,
    )
    required = max(0, int(required_contracts or 0))
    best_contra_bid = contra_levels[0][0] if contra_levels else None
    best_entry_price = 100.0 - best_contra_bid if best_contra_bid is not None else None

    cumulative = 0.0
    marginal_contra_bid = None
    for level_price, level_count in contra_levels:
        cumulative += level_count
        if required > 0 and cumulative + 1e-9 >= required:
            marginal_contra_bid = level_price
            break
    full_size_entry_price = (
        100.0 - marginal_contra_bid
        if marginal_contra_bid is not None
        else None
    )

    minimum_contra_bid = (
        100.0 - float(limit_price_cents)
        if limit_price_cents is not None
        else None
    )
    executable_levels = [
        (price, count)
        for price, count in contra_levels
        if minimum_contra_bid is None or price + 1e-9 >= minimum_contra_bid
    ]
    available_contracts = sum(count for _price, count in executable_levels)
    price_move_beyond_limit = (
        max(0.0, float(best_entry_price) - float(limit_price_cents))
        if best_entry_price is not None and limit_price_cents is not None
        else None
    )
    return {
        "selected_side": selected_side,
        "contra_side": contra_side,
        "required_contracts": required,
        "limit_price_cents": (
            int(round(float(limit_price_cents)))
            if limit_price_cents is not None
            else None
        ),
        "minimum_contra_bid_cents": (
            round(minimum_contra_bid, 4)
            if minimum_contra_bid is not None
            else None
        ),
        "available_contracts": round(available_contracts, 4),
        "total_contra_contracts": round(sum(count for _price, count in contra_levels), 4),
        "contra_level_count": len(contra_levels),
        "executable_level_count": len(executable_levels),
        "best_contra_bid_cents": (
            round(best_contra_bid, 4)
            if best_contra_bid is not None
            else None
        ),
        "best_entry_price_cents": (
            round(best_entry_price, 4)
            if best_entry_price is not None
            else None
        ),
        "full_size_entry_price_cents": (
            round(full_size_entry_price, 4)
            if full_size_entry_price is not None
            else None
        ),
        "marginal_contra_bid_cents": (
            round(marginal_contra_bid, 4)
            if marginal_contra_bid is not None
            else None
        ),
        "best_executable_contra_bid_cents": (
            max((price for price, _count in executable_levels), default=None)
        ),
        "price_move_beyond_limit_cents": (
            round(price_move_beyond_limit, 4)
            if price_move_beyond_limit is not None
            else None
        ),
        "depth_shortfall_contracts": round(
            max(0.0, required - available_contracts),
            4,
        ),
    }


def fetch_fresh_kalshi_orderbook(settings, ticker, *, force_rest=False):
    stream = KALSHI_CRYPTO_STREAM
    if not force_rest and stream and setting_bool(settings, "CRYPTO_KALSHI_WS_ENABLED"):
        max_age = max(0.25, setting_float(settings, "CRYPTO_KALSHI_WS_MAX_AGE_SECONDS"))
        payload = stream.orderbook_payload(ticker, max_age_seconds=max_age)
        if payload:
            return payload, payload.get("book_received_at") or payload.get("received_at") or iso_now()
    timeout = max(1.0, setting_float(settings, "CRYPTO_LIVE_DEPTH_PREFLIGHT_TIMEOUT_SECONDS"))
    url = f"{KALSHI_BASE}/markets/{quote(str(ticker or ''), safe='')}/orderbook"
    payload = http_json(url, timeout=timeout, retries=1)
    return payload, iso_now()


def fresh_kalshi_executable_depth(settings, ticker, order_side, limit_price_cents, required_contracts):
    """Check immediately executable opposite-side depth without changing price."""
    try:
        payload, fetched_at = fetch_fresh_kalshi_orderbook(settings, ticker)
    except Exception as exc:
        return {
            "ok": False,
            "error": "live_order_depth_unavailable",
            "message": safe_error_message(exc),
            "fetched_at": iso_now(),
        }

    summary = kalshi_orderbook_depth_summary(
        payload,
        order_side,
        required_contracts=required_contracts,
        limit_price_cents=limit_price_cents,
    )
    available_contracts = float(summary.get("available_contracts") or 0)
    required = int(summary.get("required_contracts") or 0)
    return {
        **summary,
        "ok": available_contracts + 1e-9 >= required,
        "error": None if available_contracts + 1e-9 >= required else "live_order_insufficient_fresh_depth",
        "fetched_at": fetched_at,
    }


def refresh_live_spot_flow_pilot_quote(settings, portfolio, candidate):
    """Reconfirm the pilot signal and exact FOK depth immediately before order."""
    original_price = float(candidate.get("entry_price") or 0)
    original_review = candidate.get("spot_flow_live_pilot") or {}
    refresh_started_at = utc_now()
    signal_matched_at = parse_time(original_review.get("signal_matched_at"))
    signal_to_refresh_seconds = (
        round(max(0.0, (refresh_started_at - signal_matched_at).total_seconds()), 4)
        if signal_matched_at
        else None
    )
    original_size = original_review.get("sizing") or {}
    required_contracts = max(1, int(original_size.get("contracts") or 1))
    try:
        payload, fetched_at = fetch_fresh_kalshi_orderbook(
            settings, candidate.get("ticker")
        )
    except Exception as exc:
        return {
            "ok": False,
            "enabled": True,
            "error": "pilot_live_quote_refresh_unavailable",
            "message": safe_error_message(exc),
            "original_price_cents": original_price,
            "signal_to_refresh_seconds": signal_to_refresh_seconds,
            "fetched_at": iso_now(),
        }

    asset = candidate.get("asset")
    try:
        coinbase = (
            COINBASE_MICROSTRUCTURE_STREAM.snapshot(asset)
            if COINBASE_MICROSTRUCTURE_STREAM
            else {}
        )
        kraken = (
            KRAKEN_MICROSTRUCTURE_STREAM.snapshot(asset)
            if KRAKEN_MICROSTRUCTURE_STREAM
            else {}
        )
    except Exception as exc:
        return {
            "ok": False,
            "enabled": True,
            "error": "pilot_live_source_refresh_unavailable",
            "message": safe_error_message(exc),
            "original_price_cents": original_price,
            "signal_to_refresh_seconds": signal_to_refresh_seconds,
            "fetched_at": fetched_at,
        }
    candidate["microstructure"] = {
        **(candidate.get("microstructure") or {}),
        "coinbase": coinbase,
        "kraken": kraken,
        "live_refreshed_at": iso_now(),
    }
    close_time = parse_time(candidate.get("close_time"))
    if close_time:
        candidate["minutes_to_close"] = round(
            max(0.0, (close_time - utc_now()).total_seconds() / 60.0), 4
        )

    yes_depth = kalshi_orderbook_depth_summary(payload, "yes", required_contracts=1)
    no_depth = kalshi_orderbook_depth_summary(payload, "no", required_contracts=1)
    yes_entry = yes_depth.get("best_entry_price_cents")
    no_entry = no_depth.get("best_entry_price_cents")
    spread = (
        float(yes_entry) + float(no_entry) - 100.0
        if yes_entry is not None and no_entry is not None
        else 999.0
    )
    candidate["kalshi_microstructure"] = {
        **(candidate.get("kalshi_microstructure") or {}),
        "source": "live_pre_submit_orderbook",
        "sequence_valid": True,
        "fresh": True,
        "book_consistent": bool(
            yes_entry is not None
            and no_entry is not None
            and float(yes_entry) + float(no_entry) >= 100.0 - 1e-9
        ),
        "age_seconds": 0.0,
        "spread_yes_cents": round(spread, 4),
        "best_yes_entry_price_cents": yes_entry,
        "best_no_entry_price_cents": no_entry,
        "orderbook_fetched_at": fetched_at,
    }
    signal = spot_flow_exact_signal_review(candidate, settings)
    original_signal = original_review.get("signal") or {}
    original_contract_cap = int(
        original_signal.get("maximum_contracts")
        or original_size.get("maximum_contracts")
        or setting_int(settings, "CRYPTO_SPOT_FLOW_LIVE_PILOT_MAX_CONTRACTS")
    )
    refreshed_contract_cap = int(
        signal.get("maximum_contracts") or original_contract_cap
    )
    # Revalidation may downgrade a confirmed signal to the approved spot-only
    # tier, but it may never increase the size chosen by the original scan.
    effective_contract_cap = min(original_contract_cap, refreshed_contract_cap)

    summary = {}
    refreshed_price = original_price
    size = original_size
    for _attempt in range(2):
        summary = kalshi_orderbook_depth_summary(
            payload,
            candidate.get("side"),
            required_contracts=required_contracts,
        )
        full_size_price = summary.get("full_size_entry_price_cents")
        if full_size_price is None:
            return {
                **summary,
                "ok": False,
                "enabled": True,
                "error": "pilot_live_quote_no_full_size_depth",
                "original_price_cents": original_price,
                "signal_to_refresh_seconds": signal_to_refresh_seconds,
                "fetched_at": fetched_at,
            }
        refreshed_price = float(int(math.ceil(float(full_size_price) - 1e-9)))
        candidate["entry_price"] = refreshed_price
        if str(candidate.get("side") or "").lower() == "yes":
            candidate["yes_ask"] = refreshed_price
        else:
            candidate["no_ask"] = refreshed_price
        sizing_bankroll = float(
            ((original_review.get("risk") or {}).get("bankroll") or {}).get(
                "sizing_bankroll"
            )
            or 0
        )
        size = spot_flow_live_pilot_size(
            candidate,
            sizing_bankroll,
            settings,
            available_cash=(
                ((original_review.get("risk") or {}).get("bankroll") or {}).get(
                    "cash_balance"
                )
            ),
            maximum_contracts=effective_contract_cap,
        )
        new_required = max(1, int(size.get("contracts") or 0))
        if new_required == required_contracts:
            break
        required_contracts = new_required

    validation = original_review.get("validation") or {}
    current_reconciliation = read_json(LIVE_RECONCILIATION_FILE, {})
    risk = spot_flow_live_pilot_risk_review(
        portfolio,
        current_reconciliation,
        validation,
        settings=settings,
    )
    reasons = list(risk.get("reasons") or [])
    candidate_shard_cash = shard_cash(current_reconciliation.get("account") or {}, candidate.get("exchange_index"))
    if candidate_shard_cash is None:
        reasons.append("pilot_exchange_shard_balance_unavailable")
    elif float(size.get("expected_total_cost") or 0) > candidate_shard_cash:
        reasons.append("pilot_exchange_shard_cash_insufficient")
    if not signal.get("ok"):
        reasons.extend(signal.get("reasons") or [])
    if signal.get("side") != original_review.get("signal", {}).get("side"):
        reasons.append("pilot_signal_direction_changed")
    maximum_move = float(
        original_review.get("maximum_adverse_move_cents")
        or setting_float(
            settings, "CRYPTO_SPOT_FLOW_LIVE_PILOT_MAX_ADVERSE_MOVE_CENTS"
        )
    )
    adverse_move = refreshed_price - original_price
    if adverse_move > maximum_move + 1e-9:
        reasons.append("pilot_live_quote_adverse_move")
    if int(size.get("contracts") or 0) < 1:
        reasons.append("pilot_stake_below_one_contract")
    if float(size.get("principal_stake") or 0) > max(
        0.0,
        float(risk.get("open_exposure_cap") or 0)
        - float(risk.get("open_exposure") or 0),
    ) + 0.005:
        reasons.append("pilot_open_exposure_room_insufficient")
    immediate_depth = kalshi_orderbook_depth_summary(
        payload,
        candidate.get("side"),
        required_contracts=int(size.get("contracts") or 0),
        limit_price_cents=refreshed_price,
    )
    if float(immediate_depth.get("available_contracts") or 0) + 1e-9 < int(
        size.get("contracts") or 0
    ):
        reasons.append("pilot_live_order_insufficient_fresh_depth")
    fee = kalshi_order_fee(
        refreshed_price,
        1,
        schedule=candidate.get("fee_schedule") or {},
        liquidity_role="taker",
    )
    if not fee.get("exact") or not fee.get("authoritative"):
        reasons.append("pilot_fee_schedule_not_exact")
    candidate["exact_fee_cents"] = round(
        float(fee.get("fee_dollars") or 0) * 100.0, 4
    )
    review = {
        **original_review,
        "tier": original_review.get("tier") or original_signal.get("tier"),
        "revalidated_tier": signal.get("tier"),
        "eligible": not reasons,
        "reason": reasons[0] if reasons else "eligible",
        "reasons": list(dict.fromkeys(reasons)),
        "signal": signal,
        "risk": risk,
        "sizing": size,
        "refreshed_at": fetched_at,
    }
    candidate["spot_flow_live_pilot"] = review
    candidate["skip_reasons"] = list(review["reasons"])
    candidate["decision"] = "eligible" if review["eligible"] else "skipped"
    return {
        **immediate_depth,
        "ok": review["eligible"],
        "enabled": True,
        "error": review["reason"] if not review["eligible"] else None,
        "original_price_cents": original_price,
        "refreshed_price_cents": refreshed_price,
        "adverse_move_cents": round(adverse_move, 4),
        "max_adverse_move_cents": maximum_move,
        "signal_to_refresh_seconds": signal_to_refresh_seconds,
        "required_contracts": int(size.get("contracts") or 0),
        "fetched_at": fetched_at,
        "pilot_review": review,
    }


def refresh_live_underlying_probability(settings, candidate, orderbook_payload):
    """Recompute a crypto 15m decision from the latest Coinbase WS midpoint.

    The initial scan may spend several seconds fetching other assets and Kalshi
    data.  Reusing that old underlying price with a new Kalshi quote creates a
    mismatched snapshot, so live execution refreshes both sides of the edge.
    """
    enabled = (
        str(candidate.get("market_lane") or market_lane(candidate)) == "crypto_15m"
        and setting_bool(settings, "CRYPTO_LIVE_UNDERLYING_REFRESH_ENABLED")
    )
    if not enabled:
        return {"ok": True, "enabled": False}

    require_fresh = setting_bool(settings, "CRYPTO_LIVE_UNDERLYING_REQUIRE_FRESH")
    stream = COINBASE_MICROSTRUCTURE_STREAM
    try:
        snapshot = stream.snapshot(candidate.get("asset")) if stream else {}
    except Exception as exc:
        snapshot = {"error": f"{type(exc).__name__}:{safe_error_message(exc)}"}
    fresh_mid = float(snapshot.get("mid") or 0)
    raw_age = snapshot.get("book_age_seconds")
    try:
        book_age_seconds = float(raw_age) if raw_age is not None else None
    except (TypeError, ValueError):
        book_age_seconds = None
    max_age_seconds = max(
        0.1,
        setting_float(settings, "CRYPTO_LIVE_UNDERLYING_MAX_AGE_SECONDS"),
    )
    fresh_enough = bool(
        fresh_mid > 0
        and book_age_seconds is not None
        and book_age_seconds <= max_age_seconds
    )
    if not fresh_enough:
        review = {
            "ok": not require_fresh,
            "enabled": True,
            "error": "live_underlying_refresh_unavailable",
            "required": require_fresh,
            "source": snapshot.get("source"),
            "book_age_seconds": book_age_seconds,
            "max_age_seconds": max_age_seconds,
            "message": snapshot.get("error"),
            "captured_at": iso_now(),
        }
        candidate["live_underlying_refresh"] = review
        return review

    original_model = dict(candidate.get("model") or {})
    original_probability = dict(candidate.get("probability") or {})
    original_microstructure = dict(candidate.get("microstructure") or {})
    old_proxy_spot = float(original_model.get("spot") or 0)
    old_coinbase_mid = float(
        original_model.get("coinbase_spot")
        or (original_microstructure.get("coinbase") or {}).get("mid")
        or old_proxy_spot
        or 0
    )
    if old_proxy_spot <= 0 or old_coinbase_mid <= 0:
        review = {
            "ok": not require_fresh,
            "enabled": True,
            "error": "live_underlying_original_snapshot_missing",
            "required": require_fresh,
            "source": snapshot.get("source"),
            "book_age_seconds": book_age_seconds,
            "max_age_seconds": max_age_seconds,
            "captured_at": iso_now(),
        }
        candidate["live_underlying_refresh"] = review
        return review

    # Preserve the scan-time Coinbase-to-settlement-proxy basis while carrying
    # forward the newest liquid-exchange price move.
    basis_dollars = old_proxy_spot - old_coinbase_mid
    fresh_proxy_spot = fresh_mid + basis_dollars
    fresh_model = dict(original_model)
    fresh_model["spot"] = fresh_proxy_spot
    fresh_model["coinbase_spot"] = fresh_mid

    yes_levels = parse_kalshi_orderbook_levels(orderbook_payload, "yes")
    no_levels = parse_kalshi_orderbook_levels(orderbook_payload, "no")
    best_yes_bid = max((price for price, _count in yes_levels), default=None)
    best_no_bid = max((price for price, _count in no_levels), default=None)
    market = {
        "ticker": candidate.get("ticker"),
        "series_ticker": candidate.get("series_ticker"),
        "close_time": candidate.get("close_time"),
        "floor_strike": candidate.get("floor_strike"),
        "cap_strike": candidate.get("cap_strike"),
        "volume": candidate.get("volume") or 0,
        "yes_bid": best_yes_bid,
        "yes_ask": 100.0 - best_no_bid if best_no_bid is not None else None,
        "no_bid": best_no_bid,
        "no_ask": 100.0 - best_yes_bid if best_yes_bid is not None else None,
    }
    fresh_probability = probability_for_15m_market(
        market,
        fresh_model,
        settings=settings,
        now=utc_now(),
    )
    if not fresh_probability:
        review = {
            "ok": not require_fresh,
            "enabled": True,
            "error": "live_underlying_probability_unavailable",
            "required": require_fresh,
            "source": snapshot.get("source"),
            "book_age_seconds": book_age_seconds,
            "max_age_seconds": max_age_seconds,
            "captured_at": iso_now(),
        }
        candidate["live_underlying_refresh"] = review
        return review

    learned = candidate.get("learned_15m_model") or {}
    market_yes = fresh_probability.get("market_implied_yes")
    old_market_yes = original_probability.get("market_implied_yes")
    if market_yes is not None:
        market_yes = float(market_yes)
        weight = clamp(
            float(
                original_probability.get("adaptive_residual_weight")
                if original_probability.get("adaptive_residual_weight") is not None
                else original_probability.get("adaptive_model_weight")
                if original_probability.get("adaptive_model_weight") is not None
                else setting_float(
                    settings,
                    "CRYPTO_15M_UNIT_WIN_PROB_SHADOW_MAX_WEIGHT",
                )
            ),
            0.0,
            1.0,
        )
        source_kind = str(
            original_probability.get("adaptive_probability_source")
            or "guardrailed_heuristic_residual"
        )
        fresh_heuristic = float(fresh_probability.get("prob") or market_yes)
        source_probability = fresh_heuristic
        source_low = source_high = None
        if (
            source_kind != "guardrailed_heuristic_residual"
            and old_market_yes is not None
            and original_probability.get("adaptive_source_probability_yes") is not None
        ):
            market_move = market_yes - float(old_market_yes)
            source_probability = (
                float(original_probability["adaptive_source_probability_yes"])
                + market_move
            )
            if original_probability.get("adaptive_source_probability_low") is not None:
                source_low = (
                    float(original_probability["adaptive_source_probability_low"])
                    + market_move
                )
            if original_probability.get("adaptive_source_probability_high") is not None:
                source_high = (
                    float(original_probability["adaptive_source_probability_high"])
                    + market_move
                )
        final_probability = market_yes + weight * (source_probability - market_yes)
        fresh_probability.update({
            "heuristic_prob_before_ml": round(fresh_heuristic, 2),
            "heuristic_raw_market_gap": fresh_probability.get("raw_market_gap"),
            "learned_pre_anchor_prob": learned.get("prob_yes"),
            "learned_blend_weight": round(weight, 6),
            "adaptive_model_weight": original_probability.get(
                "adaptive_model_weight", 0.0
            ),
            "adaptive_residual_weight": round(weight, 6),
            "adaptive_probability_source": source_kind,
            "adaptive_probability_status": original_probability.get(
                "adaptive_probability_status"
            ),
            "adaptive_source_probability_yes": round(source_probability, 4),
            "adaptive_source_probability_low": source_low,
            "adaptive_source_probability_high": source_high,
            "raw_market_gap": round(abs(source_probability - market_yes), 2),
            "prob": round(clamp(final_probability, 0.01, 99.99), 2),
        })
        fresh_probability["market_gap"] = round(
            abs(float(fresh_probability["prob"]) - market_yes),
            2,
        )
        if source_low is not None and source_high is not None:
            adaptive_low = market_yes + weight * (source_low - market_yes)
            adaptive_high = market_yes + weight * (source_high - market_yes)
            original_interval = original_probability.get("adaptive_probability_interval") or {}
            fresh_probability["adaptive_probability_interval"] = {
                **original_interval,
                "available": True,
                "p_yes": round(fresh_probability["prob"], 4),
                "p_low": round(
                    clamp(min(adaptive_low, fresh_probability["prob"]), 0.01, 99.99),
                    4,
                ),
                "p_high": round(
                    clamp(max(adaptive_high, fresh_probability["prob"]), 0.01, 99.99),
                    4,
                ),
            }

    old_probability = float(candidate.get("model_prob_yes") or 0)
    new_probability = float(fresh_probability["prob"])
    candidate["model"] = fresh_model
    candidate["probability"] = fresh_probability
    candidate["model_prob_yes"] = new_probability
    candidate["minutes_to_close"] = fresh_probability.get("minutes_to_close")
    candidate["microstructure"] = {
        **original_microstructure,
        "live_coinbase": snapshot,
        "settlement_proxy_spot": fresh_proxy_spot,
        "live_refreshed_at": iso_now(),
    }
    review = {
        "ok": True,
        "enabled": True,
        "error": None,
        "required": require_fresh,
        "source": snapshot.get("source"),
        "book_age_seconds": round(book_age_seconds, 3),
        "max_age_seconds": max_age_seconds,
        "old_coinbase_mid": round(old_coinbase_mid, 8),
        "fresh_coinbase_mid": round(fresh_mid, 8),
        "basis_dollars": round(basis_dollars, 8),
        "old_proxy_spot": round(old_proxy_spot, 8),
        "fresh_proxy_spot": round(fresh_proxy_spot, 8),
        "underlying_move_bps": round(
            (fresh_proxy_spot - old_proxy_spot) / old_proxy_spot * 10000.0,
            4,
        ),
        "old_model_prob_yes": round(old_probability, 2),
        "fresh_model_prob_yes": round(new_probability, 2),
        "fresh_confidence": candidate.get("confidence"),
        "captured_at": iso_now(),
    }
    candidate["live_underlying_refresh"] = review
    return review


def crypto_candidate_applied_units(candidate):
    """Best available unit count for the candidate's currently applied stake."""
    unit_review = candidate.get("crypto_units") or {}
    campaign = candidate.get("crypto_live_campaign") or {}
    campaign_units = campaign.get("crypto_units") or {}
    values = (
        unit_review.get("applied_total_units"),
        (unit_review.get("bounded_recovery") or {}).get("total_units"),
        campaign_units.get("applied_total_units"),
        (campaign.get("bounded_unit_recovery") or {}).get("total_units"),
        unit_review.get("target_units"),
        campaign_units.get("target_units"),
    )
    for value in values:
        try:
            units = float(value)
        except (TypeError, ValueError):
            continue
        if math.isfinite(units) and units > 0:
            return units
    unit_size = float(unit_review.get("unit_size") or campaign_units.get("unit_size") or 0)
    applied_stake = float(campaign.get("applied_stake") or unit_review.get("applied_stake") or 0)
    return applied_stake / unit_size if unit_size > 0 and applied_stake > 0 else 0.0


def reconcile_live_unit_accounting(candidate, live_order):
    """Replace pre-cap unit labels with the units and recovery actually filled."""
    unit_review = candidate.get("crypto_units") or {}
    campaign = candidate.get("crypto_live_campaign") or {}
    campaign_units = campaign.get("crypto_units") or {}
    unit_size = float(
        unit_review.get("unit_size")
        or campaign_units.get("unit_size")
        or 0
    )
    actual_stake = max(0.0, float(live_order.get("actual_stake") or 0))
    actual_contracts = max(0, int(float(live_order.get("contracts") or 0)))
    reported_executed_price = float(
        live_order.get("executed_price")
        or live_order.get("price")
        or candidate.get("entry_price")
        or 0
    )
    if unit_size <= 0 or actual_stake <= 0 or actual_contracts <= 0:
        return {}
    accounting_fill_price = actual_stake * 100.0 / actual_contracts
    if accounting_fill_price <= 0:
        return {}
    if abs(reported_executed_price - accounting_fill_price) > 0.0001:
        live_order["reported_executed_price"] = reported_executed_price
    live_order["executed_price"] = round(accounting_fill_price, 6)
    live_order["accounting_fill_price_cents"] = round(accounting_fill_price, 6)

    bounded = (
        unit_review.get("bounded_recovery")
        or campaign.get("bounded_unit_recovery")
        or {}
    )
    bounded = dict(bounded) if isinstance(bounded, dict) else {}
    model_base_units = max(
        0.0,
        float(
            bounded.get("model_base_units")
            or bounded.get("base_units")
            or unit_review.get("base_units")
            or unit_review.get("target_units")
            or 0
        ),
    )
    model_bonus_units = max(
        0.0,
        float(
            bounded.get("model_bonus_units")
            or bounded.get("bonus_units")
            or unit_review.get("recovery_bonus_units")
            or 0
        ),
    )
    model_total_units = max(
        model_base_units + model_bonus_units,
        float(
            bounded.get("model_total_units")
            or bounded.get("total_units")
            or unit_review.get("applied_total_units")
            or 0
        ),
    )

    model_base_stake = model_base_units * unit_size
    model_base_contracts = max(
        0,
        int(math.floor((model_base_stake * 100.0 / accounting_fill_price) + 1e-9)),
    )
    applied_base_contracts = min(actual_contracts, model_base_contracts)
    applied_bonus_contracts = max(0, actual_contracts - applied_base_contracts)
    applied_base_stake = applied_base_contracts * accounting_fill_price / 100.0
    applied_bonus_stake = applied_bonus_contracts * accounting_fill_price / 100.0
    applied_base_units = applied_base_stake / unit_size
    applied_bonus_units = applied_bonus_stake / unit_size
    applied_total_units = actual_stake / unit_size
    recovery_active = applied_bonus_contracts > 0 and applied_bonus_units > 0.0001

    previous_reason = str(bounded.get("reason") or "")
    if model_bonus_units > 0.0001 and not recovery_active:
        accounting_reason = "post_fill_recovery_not_executed"
    elif recovery_active and applied_bonus_units + 0.0001 < model_bonus_units:
        accounting_reason = "post_fill_recovery_partially_executed"
    else:
        accounting_reason = previous_reason
    profit_per_unit = max(
        0.0,
        float(bounded.get("estimated_profit_per_unit_after_fee") or 0),
    )
    reconciled_bounded = {
        **bounded,
        "model_base_units": round(model_base_units, 4),
        "model_bonus_units": round(model_bonus_units, 4),
        "model_total_units": round(model_total_units, 4),
        "model_requested_stake": round(
            float(bounded.get("model_requested_stake") or bounded.get("requested_stake") or model_total_units * unit_size),
            2,
        ),
        "active": recovery_active,
        "reason": accounting_reason,
        "base_units": round(applied_base_units, 4),
        "bonus_units": round(applied_bonus_units, 4),
        "total_units": round(applied_total_units, 4),
        "base_stake": round(applied_base_stake, 4),
        "recovery_bonus_stake": round(applied_bonus_stake, 4),
        "applied_stake": round(actual_stake, 4),
        "applied_base_contracts": applied_base_contracts,
        "applied_bonus_contracts": applied_bonus_contracts,
        "applied_total_contracts": actual_contracts,
        "allocated_recovery_profit": round(applied_bonus_units * profit_per_unit, 2),
        "accounting_reconciled": True,
        "accounting_schema_version": 2,
    }
    reconciled_units = {
        **unit_review,
        "model_selected_units": round(model_total_units, 4),
        "requested_total_units": round(model_total_units, 4),
        "base_units": round(applied_base_units, 4),
        "recovery_bonus_units": round(applied_bonus_units, 4),
        "applied_total_units": round(applied_total_units, 4),
        "applied_stake": round(actual_stake, 4),
        "applied_contracts": actual_contracts,
        "bounded_recovery": reconciled_bounded,
        "recovery_overlay_active": recovery_active,
        "accounting_reconciled": True,
        "accounting_schema_version": 2,
    }
    reconciled_campaign = {
        **campaign,
        "crypto_units": reconciled_units,
        "bounded_unit_recovery": reconciled_bounded,
        "recovery_overlay_active": recovery_active,
        "applied_stake": round(actual_stake, 4),
        "applied_contracts": actual_contracts,
        "accounting_reconciled": True,
        "accounting_schema_version": 2,
    }
    accounting = {
        "reconciled": True,
        "model_selected_units": round(model_total_units, 4),
        "executed_units": round(applied_total_units, 4),
        "model_base_units": round(model_base_units, 4),
        "executed_base_units": round(applied_base_units, 4),
        "model_recovery_bonus_units": round(model_bonus_units, 4),
        "executed_recovery_bonus_units": round(applied_bonus_units, 4),
        "executed_base_contracts": applied_base_contracts,
        "executed_recovery_bonus_contracts": applied_bonus_contracts,
        "executed_contracts": actual_contracts,
        "unit_size": round(unit_size, 4),
        "actual_stake": round(actual_stake, 4),
        "accounting_fill_price_cents": round(accounting_fill_price, 6),
        "reported_fill_price_cents": round(reported_executed_price, 6),
        "downshifted_after_sizing": applied_total_units + 0.0001 < model_total_units,
        "reason": accounting_reason,
    }
    candidate["crypto_units"] = reconciled_units
    candidate["crypto_live_campaign"] = reconciled_campaign
    candidate["live_unit_accounting"] = accounting
    live_order["unit_accounting"] = accounting
    return accounting


def reconcile_portfolio_live_unit_accounting(portfolio):
    """One-time repair for live unit bets saved before post-fill reconciliation."""
    repaired = []
    for row in portfolio.get("bets") or []:
        if str(row.get("mode") or "").lower() != "live":
            continue
        if row.get("strategy_owner") != CRYPTO_15M_CAMPAIGN_OWNER:
            continue
        if (row.get("crypto_units") or {}).get("accounting_schema_version") == 2:
            continue
        if not (row.get("crypto_units") or {}).get("unit_size"):
            continue
        live_order = dict(row.get("live_order") or {})
        live_order.update({
            "actual_stake": row.get("stake"),
            "contracts": row.get("contracts"),
            "executed_price": row.get("entry_price"),
            "price": live_order.get("price") or row.get("entry_price"),
        })
        accounting = reconcile_live_unit_accounting(row, live_order)
        if not accounting:
            continue
        reported_entry_price = float(row.get("entry_price") or 0)
        accounting_entry_price = float(
            accounting.get("accounting_fill_price_cents") or 0
        )
        if abs(reported_entry_price - accounting_entry_price) > 0.0001:
            row["reported_entry_price"] = reported_entry_price
            row["entry_price"] = round(accounting_entry_price, 6)
        row["live_order"] = live_order
        repaired.append(row)
    return repaired


def try_live_unit_depth_downshift_refresh(
    settings,
    portfolio,
    candidate,
    trigger,
    reference_price_cents=None,
    original_applied_units=None,
):
    """Try successively smaller whole-unit tiers with a newly fetched live book."""
    lane = str(candidate.get("market_lane") or market_lane(candidate))
    observed_units = crypto_candidate_applied_units(candidate)
    try:
        current_units = float(original_applied_units)
    except (TypeError, ValueError):
        current_units = observed_units
    if not math.isfinite(current_units) or current_units <= 0:
        current_units = observed_units
    minimum_units = max(
        1,
        setting_int(settings, "CRYPTO_LIVE_UNIT_DEPTH_DOWNSHIFT_MIN_UNITS"),
    )
    enabled = bool(
        setting_bool(settings, "CRYPTO_LIVE_UNIT_DEPTH_DOWNSHIFT_ENABLED")
        and lane == "crypto_15m"
        and setting_bool(settings, "CRYPTO_15M_UNIT_STAKING_ENABLED")
        and (candidate.get("crypto_live_campaign") or {}).get("enabled")
        and (candidate.get("crypto_units") or {}).get("eligible")
    )
    result = {
        "enabled": enabled,
        "attempted": False,
        "active": False,
        "trigger": str(trigger or "fresh_depth_unavailable"),
        "original_units": round(current_units, 4),
        "minimum_units": minimum_units,
        "attempts": [],
    }
    if not enabled:
        result["reason"] = "unit_depth_downshift_disabled_or_inapplicable"
        return result

    highest_lower_whole_unit = int(math.ceil(current_units - 1e-9)) - 1
    if highest_lower_whole_unit < minimum_units:
        result["reason"] = "no_lower_whole_unit_tier"
        return result

    result["attempted"] = True
    root_candidate = deepcopy(candidate)
    origin = root_candidate.get("execution_quote_origin") or {}
    reference_price = float(
        reference_price_cents
        if reference_price_cents is not None
        else origin.get("price_cents") or root_candidate.get("entry_price") or 0
    )
    assigned_bot = (
        (root_candidate.get("crypto_live_campaign") or {}).get("bot_number")
        or root_candidate.get("bot_number")
    )
    prior_downshift = root_candidate.get("live_unit_depth_downshift") or {}
    original_units = float(prior_downshift.get("original_units") or current_units)

    for maximum_units in range(highest_lower_whole_unit, minimum_units - 1, -1):
        trial = deepcopy(root_candidate)
        cap = {
            "maximum_units": maximum_units,
            "reason": "fresh_executable_depth",
            "trigger": result["trigger"],
            "original_units": round(original_units, 4),
            "prior_applied_units": round(current_units, 4),
            "set_at": iso_now(),
        }
        trial["execution_unit_cap"] = cap
        trial["entry_price"] = reference_price
        if str(trial.get("side") or "").lower() == "yes":
            trial["yes_ask"] = reference_price
        else:
            trial["no_ask"] = reference_price
        apply_candidate_pricing(settings, trial)
        campaign_review = crypto_15m_campaign_review(
            settings,
            portfolio,
            trial,
            bot_number=assigned_bot,
        )
        directional = crypto_15m_directional_confirmation_review(settings, trial)
        trial["directional_confirmation"] = directional
        if (
            campaign_review.get("eligible")
            and directional.get("enabled")
            and not directional.get("ok")
        ):
            campaign_review = {
                **campaign_review,
                "eligible": False,
                "reason": directional.get("reason"),
            }
        attempt = {
            "maximum_units": maximum_units,
            "campaign_eligible": bool(campaign_review.get("eligible")),
            "campaign_reason": campaign_review.get("reason"),
        }
        if not campaign_review.get("eligible"):
            result["attempts"].append(attempt)
            continue

        refreshed = refresh_live_campaign_candidate_quote(
            settings,
            portfolio,
            trial,
            allow_unit_downshift=False,
        )
        attempt.update({
            "quote_ok": bool(refreshed.get("ok")),
            "quote_error": refreshed.get("error"),
            "applied_units": round(crypto_candidate_applied_units(trial), 4),
            "required_contracts": refreshed.get("required_contracts"),
            "available_contracts": refreshed.get("available_contracts"),
        })
        result["attempts"].append(attempt)
        applied_units = crypto_candidate_applied_units(trial)
        if not (
            refreshed.get("ok")
            and applied_units >= minimum_units
            and applied_units <= maximum_units + 1e-9
            and applied_units < current_units - 1e-9
        ):
            continue

        result.update({
            "active": True,
            "reason": "largest_fresh_whole_unit_tier",
            "original_units": round(original_units, 4),
            "prior_applied_units": round(current_units, 4),
            "applied_units": round(applied_units, 4),
            "maximum_units": maximum_units,
            "reference_price_cents": reference_price,
            "refreshed_price_cents": refreshed.get("refreshed_price_cents"),
            "selected_at": iso_now(),
        })
        trial["live_unit_depth_downshift"] = result
        candidate.clear()
        candidate.update(trial)
        return {**refreshed, "unit_depth_downshift": result}

    result["reason"] = "no_smaller_whole_unit_tier_qualified"
    return result


def live_depth_failure_or_downshift(
    settings,
    portfolio,
    candidate,
    failure,
    allow_unit_downshift,
    reference_price_cents,
    original_applied_units,
):
    if not allow_unit_downshift:
        return failure
    downshift = try_live_unit_depth_downshift_refresh(
        settings,
        portfolio,
        candidate,
        failure.get("error"),
        reference_price_cents=reference_price_cents,
        original_applied_units=original_applied_units,
    )
    if downshift.get("ok"):
        return downshift
    if downshift.get("attempted"):
        failure["unit_depth_downshift"] = downshift
    return failure


def refresh_live_campaign_candidate_quote(
    settings,
    portfolio,
    candidate,
    allow_unit_downshift=True,
):
    """Reprice and revalidate a short-horizon candidate from one fresh book."""
    original_price = float(candidate.get("entry_price") or 0)
    original_applied_units = crypto_candidate_applied_units(candidate)
    fee_schedule_supplied = "fee_schedule" in candidate
    candidate.setdefault("execution_quote_origin", {
        "captured_at": iso_now(),
        "price_cents": original_price,
        "raw_edge": candidate.get("raw_edge"),
        "net_edge": candidate.get("edge"),
        "confidence": candidate.get("confidence"),
        "quote_fetched_at": candidate.get("market_quote_fetched_at"),
    })
    lane = str(candidate.get("market_lane") or market_lane(candidate))
    campaign_candidate = lane in {"crypto_15m", "commodity_15m"}
    if not setting_bool(settings, "CRYPTO_LIVE_QUOTE_REFRESH_ENABLED"):
        return {
            "ok": True,
            "enabled": False,
            "original_price_cents": original_price,
            "refreshed_price_cents": original_price,
        }
    if not campaign_candidate and not setting_bool(settings, "MULTI_MARKET_LIVE_ENABLED"):
        return {
            "ok": True,
            "enabled": False,
            "original_price_cents": original_price,
            "refreshed_price_cents": original_price,
        }

    slippage_reconfirmation = live_slippage_reconfirmation_review(
        settings,
        candidate,
    )
    if (
        slippage_reconfirmation.get("active")
        and not slippage_reconfirmation.get("ready")
    ):
        return {
            "ok": False,
            "enabled": True,
            "error": "live_quote_slippage_reconfirm_wait",
            "original_price_cents": original_price,
            "reconfirmation": slippage_reconfirmation,
            "fetched_at": iso_now(),
        }

    assigned_bot = (
        (candidate.get("crypto_live_campaign") or {}).get("bot_number")
        or candidate.get("bot_number")
    ) if campaign_candidate else None
    required_contracts = max(
        1,
        int(
            (candidate.get("crypto_live_campaign") or {}).get("applied_contracts")
            or (candidate.get("crypto_live_campaign") or {}).get("required_contracts")
            or (
                setting_float(settings, "MULTI_MARKET_LIVE_MAX_STAKE")
                * 100.0
                / max(1.0, original_price)
            )
            or 1
        ),
    )
    try:
        payload, fetched_at = fetch_fresh_kalshi_orderbook(settings, candidate.get("ticker"))
    except Exception as exc:
        return {
            "ok": False,
            "enabled": True,
            "error": "live_quote_refresh_unavailable",
            "message": safe_error_message(exc),
            "original_price_cents": original_price,
            "fetched_at": iso_now(),
        }

    underlying_refresh = refresh_live_underlying_probability(
        settings,
        candidate,
        payload,
    )
    if not underlying_refresh.get("ok"):
        return {
            "ok": False,
            "enabled": True,
            "error": underlying_refresh.get("error"),
            "original_price_cents": original_price,
            "underlying_refresh": underlying_refresh,
            "fetched_at": fetched_at,
        }

    priority_asset = str(settings.get("CRYPTO_15M_PRIORITY_ASSET") or "").strip().upper()
    is_priority = str(candidate.get("asset") or "").strip().upper() == priority_asset
    max_adverse_move = setting_float(
        settings,
        (
            "CRYPTO_LIVE_QUOTE_REFRESH_PRIORITY_MAX_ADVERSE_CENTS"
            if is_priority
            else "CRYPTO_LIVE_QUOTE_REFRESH_MAX_ADVERSE_CENTS"
        ),
    )
    quote_age_seconds = None
    quote_fetched_at = parse_time(candidate.get("market_quote_fetched_at"))
    if quote_fetched_at:
        quote_age_seconds = max(0.0, (utc_now() - quote_fetched_at).total_seconds())

    last_summary = {}
    refreshed_price = original_price
    review = candidate.get("crypto_live_campaign") or {}
    slippage_reconfirmed = False
    for _attempt in range(3):
        summary = kalshi_orderbook_depth_summary(
            payload,
            candidate.get("side"),
            required_contracts=required_contracts,
        )
        last_summary = summary
        full_size_price = summary.get("full_size_entry_price_cents")
        if full_size_price is None:
            failure = {
                **summary,
                "ok": False,
                "enabled": True,
                "error": "live_quote_no_full_size_depth",
                "original_price_cents": original_price,
                "refreshed_price_cents": None,
                "adverse_move_cents": None,
                "max_adverse_move_cents": max_adverse_move,
                "quote_age_seconds": (
                    round(quote_age_seconds, 3)
                    if quote_age_seconds is not None
                    else None
                ),
                "fetched_at": fetched_at,
            }
            return live_depth_failure_or_downshift(
                settings,
                portfolio,
                candidate,
                failure,
                allow_unit_downshift,
                original_price,
                original_applied_units,
            )

        # A buy limit must round upward so the marginal fixed-point level remains executable.
        refreshed_price = float(int(math.ceil(float(full_size_price) - 1e-9)))
        adverse_move = refreshed_price - original_price
        candidate["entry_price"] = refreshed_price
        candidate["kalshi_microstructure"] = {
            **(candidate.get("kalshi_microstructure") or {}),
            "age_seconds": 0.0,
            "orderbook_fetched_at": fetched_at,
        }
        if str(candidate.get("side") or "").lower() == "yes":
            candidate["yes_ask"] = refreshed_price
        else:
            candidate["no_ask"] = refreshed_price
        pricing_result = apply_candidate_pricing(settings, candidate)
        raw_edge = pricing_result["raw_edge"]
        net_edge = pricing_result["expected_edge"]
        underlying_refresh["fresh_confidence"] = candidate.get("confidence")
        candidate["disagreement_guard"] = (
            crypto_15m_disagreement_review(settings, candidate)
            if campaign_candidate
            else {"enabled": False, "ok": True, "reason": "lane_specific_model"}
        )

        reconfirmation_move = None
        if slippage_reconfirmation.get("active"):
            reference_price = float(
                slippage_reconfirmation.get("reference_price_cents") or 0
            )
            reconfirmation_move = abs(refreshed_price - reference_price)
            maximum_confirmation_move = float(
                slippage_reconfirmation.get("maximum_confirmation_move_cents")
                or setting_float(
                    settings,
                    "CRYPTO_LIVE_SLIPPAGE_RECONFIRM_MAX_MOVE_CENTS",
                )
            )
            if reconfirmation_move > maximum_confirmation_move + 1e-9:
                failure = {
                    **summary,
                    "ok": False,
                    "enabled": True,
                    "error": "live_quote_slippage_reconfirm_unstable",
                    "original_price_cents": original_price,
                    "refreshed_price_cents": refreshed_price,
                    "adverse_move_cents": round(adverse_move, 4),
                    "max_adverse_move_cents": max_adverse_move,
                    "reconfirmation_reference_price_cents": reference_price,
                    "reconfirmation_move_cents": round(reconfirmation_move, 4),
                    "reconfirmation_max_move_cents": maximum_confirmation_move,
                    "reconfirmation": slippage_reconfirmation,
                    "refreshed_raw_edge": raw_edge,
                    "refreshed_net_edge": net_edge,
                    "refreshed_edge_low": candidate.get("edge_low"),
                    "refreshed_confidence": candidate.get("confidence"),
                    "refreshed_probability": {
                        key: (candidate.get("probability") or {}).get(key)
                        for key in ("p_yes", "p_low", "p_high")
                    },
                    "quote_age_seconds": (
                        round(quote_age_seconds, 3)
                        if quote_age_seconds is not None
                        else None
                    ),
                    "underlying_refresh": underlying_refresh,
                    "fetched_at": fetched_at,
                }
                return live_depth_failure_or_downshift(
                    settings,
                    portfolio,
                    candidate,
                    failure,
                    allow_unit_downshift,
                    original_price,
                    original_applied_units,
                )
            slippage_reconfirmed = True
            candidate["live_slippage_reconfirmation"] = {
                **slippage_reconfirmation,
                "active": False,
                "ready": True,
                "status": "confirmed",
                "confirmed": True,
                "confirmation_price_cents": refreshed_price,
                "confirmation_move_cents": round(reconfirmation_move, 4),
                "confirmed_at": iso_now(),
                "base_units_only": True,
            }

        if adverse_move > max_adverse_move + 1e-9 and not slippage_reconfirmed:
            failure = {
                **summary,
                "ok": False,
                "enabled": True,
                "error": "live_quote_slippage_limit",
                "original_price_cents": original_price,
                "refreshed_price_cents": refreshed_price,
                "adverse_move_cents": round(adverse_move, 4),
                "max_adverse_move_cents": max_adverse_move,
                "refreshed_raw_edge": raw_edge,
                "refreshed_net_edge": net_edge,
                "refreshed_edge_low": candidate.get("edge_low"),
                "refreshed_confidence": candidate.get("confidence"),
                "refreshed_probability": {
                    key: (candidate.get("probability") or {}).get(key)
                    for key in ("p_yes", "p_low", "p_high")
                },
                "quote_age_seconds": (
                    round(quote_age_seconds, 3)
                    if quote_age_seconds is not None
                    else None
                ),
                "underlying_refresh": underlying_refresh,
                "fetched_at": fetched_at,
            }
            return live_depth_failure_or_downshift(
                settings,
                portfolio,
                candidate,
                failure,
                allow_unit_downshift,
                original_price,
                original_applied_units,
            )

        conservative_failure = (
            campaign_candidate
            and setting_bool(settings, "CRYPTO_15M_CONSERVATIVE_EDGE_REQUIRED")
            and not (
                str(candidate.get("market_lane") or "") == "crypto_15m"
                and setting_bool(settings, "CRYPTO_15M_UNIT_STAKING_ENABLED")
            )
            and float(candidate.get("edge_low") or -999)
            <= setting_float(settings, "CRYPTO_15M_MIN_EDGE_LOW")
        )
        fee_failure = (
            campaign_candidate
            and setting_bool(settings, "CRYPTO_FEE_UNKNOWN_FAIL_CLOSED")
            and fee_schedule_supplied
            and not candidate.get("fee_schedule_exact")
        )
        if conservative_failure or fee_failure:
            if slippage_reconfirmed:
                clear_live_slippage_reconfirmation(candidate)
            return {
                **summary,
                "ok": False,
                "enabled": True,
                "error": (
                    "fee_schedule_unverified"
                    if fee_failure
                    else "conservative_edge_not_positive"
                ),
                "original_price_cents": original_price,
                "refreshed_price_cents": refreshed_price,
                "refreshed_raw_edge": raw_edge,
                "refreshed_net_edge": net_edge,
                "refreshed_edge_low": candidate.get("edge_low"),
                "refreshed_confidence": candidate.get("confidence"),
                "refreshed_probability": {
                    key: (candidate.get("probability") or {}).get(key)
                    for key in ("p_yes", "p_low", "p_high")
                },
                "reconfirmation": candidate.get("live_slippage_reconfirmation"),
                "fetched_at": fetched_at,
            }

        if campaign_candidate:
            review = crypto_15m_campaign_review(
                settings,
                portfolio,
                candidate,
                bot_number=assigned_bot,
            )
            disagreement = candidate.get("disagreement_guard") or {}
            if (
                review.get("eligible")
                and disagreement.get("enabled")
                and not disagreement.get("ok")
            ):
                review = {
                    **review,
                    "eligible": False,
                    "reason": disagreement.get("reason")
                    or "model_market_disagreement_unconfirmed",
                }
            directional = crypto_15m_directional_confirmation_review(settings, candidate)
            candidate["directional_confirmation"] = directional
            if review.get("eligible") and directional.get("enabled") and not directional.get("ok"):
                review = {**review, "eligible": False, "reason": directional.get("reason")}
        else:
            multi_market_candidate_passes(settings, portfolio, candidate)
            review = candidate.get("multi_market") or {}
        if not review.get("eligible"):
            if slippage_reconfirmed:
                clear_live_slippage_reconfirmation(candidate)
            return {
                **summary,
                "ok": False,
                "enabled": True,
                "error": "live_quote_revalidation_failed",
                "revalidation_reason": review.get("reason"),
                "original_price_cents": original_price,
                "refreshed_price_cents": refreshed_price,
                "adverse_move_cents": round(adverse_move, 4),
                "max_adverse_move_cents": max_adverse_move,
                "refreshed_raw_edge": round(raw_edge, 2),
                "refreshed_net_edge": round(net_edge, 2),
                "refreshed_edge_low": candidate.get("edge_low"),
                "refreshed_confidence": candidate.get("confidence"),
                "refreshed_probability": {
                    key: (candidate.get("probability") or {}).get(key)
                    for key in ("p_yes", "p_low", "p_high")
                },
                "refreshed_disagreement_guard": candidate.get("disagreement_guard"),
                "reconfirmation": candidate.get("live_slippage_reconfirmation"),
                "quote_age_seconds": (
                    round(quote_age_seconds, 3)
                    if quote_age_seconds is not None
                    else None
                ),
                "fetched_at": fetched_at,
            }

        refreshed_required = max(
            1,
            int(
                review.get("applied_contracts")
                or (
                    setting_float(settings, "MULTI_MARKET_LIVE_MAX_STAKE")
                    * 100.0
                    / max(1.0, refreshed_price)
                )
                or 1
            ),
        )
        limit_summary = kalshi_orderbook_depth_summary(
            payload,
            candidate.get("side"),
            required_contracts=refreshed_required,
            limit_price_cents=refreshed_price,
        )
        last_summary = limit_summary
        if (
            refreshed_required == required_contracts
            and float(limit_summary.get("available_contracts") or 0) + 1e-9
            >= refreshed_required
        ):
            required_contracts = refreshed_required
            break
        required_contracts = refreshed_required
    else:
        if slippage_reconfirmed:
            clear_live_slippage_reconfirmation(candidate)
        failure = {
            **last_summary,
            "ok": False,
            "enabled": True,
            "error": "live_quote_reprice_not_converged",
            "original_price_cents": original_price,
            "refreshed_price_cents": refreshed_price,
            "fetched_at": fetched_at,
        }
        return live_depth_failure_or_downshift(
            settings,
            portfolio,
            candidate,
            failure,
            allow_unit_downshift,
            original_price,
            original_applied_units,
        )

    if slippage_reconfirmed:
        clear_live_slippage_reconfirmation(candidate)
    return {
        **last_summary,
        "ok": True,
        "enabled": True,
        "error": None,
        "priority_asset": is_priority,
        "original_price_cents": original_price,
        "refreshed_price_cents": refreshed_price,
        "adverse_move_cents": round(refreshed_price - original_price, 4),
        "max_adverse_move_cents": max_adverse_move,
        "refreshed_raw_edge": candidate.get("raw_edge"),
        "refreshed_net_edge": candidate.get("edge"),
        "refreshed_edge_low": candidate.get("edge_low"),
        "refreshed_confidence": candidate.get("confidence"),
        "refreshed_probability": {
            key: (candidate.get("probability") or {}).get(key)
            for key in ("p_yes", "p_low", "p_high")
        },
        "refreshed_disagreement_guard": candidate.get("disagreement_guard"),
        "reconfirmation": candidate.get("live_slippage_reconfirmation"),
        "underlying_refresh": underlying_refresh,
        "required_contracts": required_contracts,
        "available_contracts": last_summary.get("available_contracts"),
        "quote_age_seconds": (
            round(quote_age_seconds, 3)
            if quote_age_seconds is not None
            else None
        ),
        "fetched_at": fetched_at,
        "campaign_review": {
            key: review.get(key)
            for key in (
                "eligible",
                "reason",
                "bot_number",
                "quality_tier",
                "applied_contracts",
                "applied_stake",
                "estimated_fee",
                "target_profit",
                "lane",
                "owner",
            )
        },
    }


def live_quote_refresh_age_seconds(refresh):
    fetched_at = parse_time((refresh or {}).get("fetched_at"))
    if not fetched_at:
        return None
    if fetched_at.tzinfo is None:
        fetched_at = fetched_at.replace(tzinfo=timezone.utc)
    return max(0.0, (utc_now() - fetched_at).total_seconds())


def reusable_live_quote_refresh(settings, candidate, bot_number=None):
    refresh = candidate.get("live_quote_refresh") or {}
    if not refresh.get("ok") or not refresh.get("enabled"):
        return False
    age = live_quote_refresh_age_seconds(refresh)
    if age is None or age > setting_float(settings, "CRYPTO_LIVE_QUOTE_REUSE_SECONDS"):
        return False
    if str(candidate.get("market_lane") or market_lane(candidate)) not in {
        "crypto_15m",
        "commodity_15m",
    }:
        return bool(
            int(round(float(candidate.get("entry_price") or 0)))
            == int(round(float(refresh.get("refreshed_price_cents") or 0)))
        )
    campaign = candidate.get("crypto_live_campaign") or {}
    refreshed_campaign = refresh.get("campaign_review") or {}
    expected_bot = int(bot_number or campaign.get("bot_number") or 0)
    refreshed_bot = int(refreshed_campaign.get("bot_number") or 0)
    expected_contracts = max(
        1,
        int(campaign.get("applied_contracts") or campaign.get("required_contracts") or 1),
    )
    return bool(
        expected_bot == refreshed_bot
        and expected_contracts == int(refresh.get("required_contracts") or 0)
        and int(round(float(candidate.get("entry_price") or 0)))
        == int(round(float(refresh.get("refreshed_price_cents") or 0)))
    )


def refresh_and_rerank_live_candidates(settings, portfolio, candidates):
    """Refresh the best executable quotes concurrently, then rank on fresh edge."""
    eligible = sorted(
        (
            candidate
            for candidate in candidates
            if not candidate.get("skip_reasons")
        ),
        key=lambda row: crypto_candidate_sort_key(settings, row),
        reverse=True,
    )
    limit = max(1, setting_int(settings, "CRYPTO_LIVE_RERANK_MAX_CANDIDATES"))
    selected = eligible[:limit]
    if not selected:
        return {"enabled": True, "requested": 0, "refreshed": 0, "failed": 0}

    workers = max(
        1,
        min(
            len(selected),
            setting_int(settings, "CRYPTO_FETCH_MAX_WORKERS") or 1,
        ),
    )
    refreshed = 0
    failed = 0
    started = time.monotonic()
    with ThreadPoolExecutor(max_workers=workers, thread_name_prefix="crypto-rerank") as pool:
        futures = {
            pool.submit(
                refresh_live_campaign_candidate_quote,
                settings,
                portfolio,
                candidate,
            ): candidate
            for candidate in selected
        }
        for future in as_completed(futures):
            candidate = futures[future]
            try:
                review = future.result()
            except Exception as exc:
                review = {
                    "ok": False,
                    "enabled": True,
                    "error": "live_quote_refresh_unavailable",
                    "message": safe_error_message(exc),
                    "fetched_at": iso_now(),
                }
            candidate["live_quote_refresh"] = review
            if review.get("ok"):
                refreshed += 1
            else:
                failed += 1
                reason = review.get("error") or "live_quote_refresh_failed"
                failure_control = handle_live_quote_refresh_failure(
                    settings,
                    candidate,
                    review,
                )
                if failure_control.get("status") in {"waiting", "ready"}:
                    review["reconfirmation"] = failure_control
                candidate["skip_reasons"] = list(
                    dict.fromkeys([*(candidate.get("skip_reasons") or []), reason])
                )
                candidate["decision"] = "skipped"

    candidates.sort(
        key=lambda row: crypto_candidate_sort_key(settings, row),
        reverse=True,
    )
    return {
        "enabled": True,
        "requested": len(selected),
        "refreshed": refreshed,
        "failed": failed,
        "seconds": round(time.monotonic() - started, 3),
        "workers": workers,
    }


def fok_insufficient_resting_volume(value):
    if isinstance(value, (dict, list)):
        message = json.dumps(value, sort_keys=True)
    else:
        message = str(value or "")
    normalized = message.lower().replace("-", "_").replace(" ", "_")
    return bool(
        "fill_or_kill" in normalized
        and (
            "insufficient_resting_volume" in normalized
            or "insufficient_volume" in normalized
        )
    )


def place_live_kalshi_order(
    settings,
    portfolio,
    candidate,
    stake,
    allow_unit_downshift=True,
):
    patient_active = is_patient_candidate(candidate)
    if setting_bool(settings, "CRYPTO_ETH_PATIENT_ONLY_LIVE") and not patient_active:
        return {"ok": False, "error": "patient_only_live_selection", "contracts": 0}
    pilot_active = is_spot_flow_live_pilot_candidate(candidate) or patient_active
    if patient_active:
        reasons = patient_order_reasons(settings, portfolio, candidate, utc_now())
        readiness = crypto_patient_readiness(settings)
        if reasons or not readiness["ok"]:
            return {"ok": False, "error": "patient_not_ready", "reasons": reasons,
                    "readiness": readiness, "contracts": 0}
        if abs(float(stake or 0) - float(candidate[PATIENT_FIELD]["principal_stake"])) > 1e-9:
            return {"ok": False, "error": "patient_stake_changed", "contracts": 0}
    sprint_freeze = crypto_15m_sprint_execution_freeze(settings)
    if sprint_freeze.get("active") and not pilot_active:
        return {
            "ok": False,
            "dry_run": True,
            "error": "crypto_15m_sprint_live_freeze",
            "contracts": 0,
            "requested_stake": round(float(stake or 0), 2),
            "execution_freeze": sprint_freeze,
        }
    price = int(round(float(candidate.get("entry_price") or 0)))
    if price <= 0 or price >= 100:
        return {"ok": False, "error": "invalid_price", "price": price}
    if (
        not pilot_active
        and
        setting_bool(settings, "CRYPTO_15M_CAMPAIGN_ENABLED")
        and str(candidate.get("market_lane") or market_lane(candidate))
        in {"crypto_15m", "commodity_15m"}
    ):
        action_gate = crypto_15m_action_gate_configuration(
            settings,
            market_lane_name=str(
                candidate.get("market_lane") or market_lane(candidate)
            ),
        )
        minimum = int(math.ceil(action_gate["minimum_price_cents"]))
        maximum = int(math.floor(action_gate["maximum_price_cents"]))
        if price < minimum or price > maximum:
            return {
                "ok": False,
                "error": "crypto_15m_order_price_range",
                "price": price,
                "minimum_price": minimum,
                "maximum_price": maximum,
            }

    owner = crypto_strategy_owner(candidate)
    campaign_active = bool((candidate.get("crypto_live_campaign") or {}).get("enabled"))
    live_max_stake = (
        float(stake or 0)
        if campaign_active or pilot_active
        else setting_float(settings, "CRYPTO_LIVE_MAX_STAKE")
    )
    if live_max_stake <= 0:
        live_max_stake = setting_float(settings, "CRYPTO_MAX_STAKE")
    requested_stake = min(float(stake or 0), live_max_stake)
    shared_review = None
    funding_issue = shared_cash_pool.capacity_review(
        "crypto", candidate.get("ticker"), candidate[PATIENT_FIELD]["cost"] if patient_active else requested_stake)
    if funding_issue:
        return funding_issue
    if setting_bool(settings, "CRYPTO_LIVE_REQUIRE_SHARED_BANKROLL"):
        if not reserve_live_order:
            return {"ok": False, "error": "shared_bankroll_unavailable", "requested_stake": round(requested_stake, 2)}
        reservation_stake = candidate[PATIENT_FIELD]["cost"] if patient_active else requested_stake
        shared_review = reserve_live_order(
            "crypto",
            reservation_stake,
            price_cents=price,
            metadata=crypto_live_order_metadata(candidate, requested_stake),
        )
        if not shared_review.get("ok"):
            return {
                "ok": False,
                "error": "shared_bankroll_guard",
                "shared_bankroll": {
                    key: shared_review.get(key)
                    for key in ("error", "approved_stake", "requested_stake", "min_contract_stake", "loss_room")
                },
                "price": price,
                "requested_stake": round(requested_stake, 2),
                "live_max_stake": live_max_stake,
            }
        if patient_active and float(shared_review.get("approved_stake") or 0) + 1e-9 < reservation_stake:
            if finalize_reservation:
                finalize_reservation(shared_review.get("reservation_id"), "released_patient_size_changed", 0.0)
            return {"ok": False, "error": "patient_shared_size_changed", "contracts": 0}
        requested_stake = min(requested_stake, float(shared_review.get("approved_stake") or requested_stake))

    # Campaign sizing is expressed as an exact whole-contract stake. The small
    # tolerance prevents binary floating-point representation from dropping a
    # contract (for example, $0.88 at 22 cents).
    count = int(math.floor(((requested_stake * 100) / price) + 1e-9))
    if patient_active and count != candidate[PATIENT_FIELD]["contracts"]:
        if shared_review and finalize_reservation:
            finalize_reservation(shared_review.get("reservation_id"), "released_patient_size_changed", 0.0)
        return {"ok": False, "error": "patient_shared_size_changed", "contracts": 0}
    if count < 1:
        if shared_review and finalize_reservation:
            finalize_reservation(shared_review.get("reservation_id"), "released_below_contract", 0.0)
        return {
            "ok": False,
            "error": "stake_too_small_for_one_contract",
            "price": price,
            "requested_stake": round(requested_stake, 2),
            "live_max_stake": live_max_stake,
        }

    if not kalshi_event_order_body:
        if shared_review and finalize_reservation:
            finalize_reservation(shared_review.get("reservation_id"), "released_client_unavailable", 0.0)
        return {"ok": False, "error": "kalshi_client_unavailable", "requested_stake": round(requested_stake, 2)}

    actual_reserved_stake = round(count * price / 100.0, 2)
    # A campaign stake is payout-targeted. Accepting an IOC partial fill turns a
    # recovery bet into an arbitrary smaller bet that cannot reach its target.
    # FOK keeps the one-open-bet strategy honest: get the complete recovery
    # position at the qualified price, or leave the slot empty and keep scanning.
    time_in_force = (
        "fill_or_kill"
        if campaign_active or pilot_active
        else settings.get("CRYPTO_LIVE_TIME_IN_FORCE", "immediate_or_cancel")
    )
    body = kalshi_event_order_body(
        ticker=candidate["ticker"],
        order_side=candidate["side"],
        price_cents=price,
        count=count,
        client_order_id=(candidate[PATIENT_FIELD]["client_order_id"] if patient_active else f"crypto-{uuid.uuid4()}"),
        time_in_force=time_in_force,
    )

    if setting_bool(settings, "CRYPTO_LIVE_DRY_RUN"):
        if shared_review and finalize_reservation:
            finalize_reservation(shared_review.get("reservation_id"), "dry_run_released", 0.0)
        return {
            "ok": False,
            "dry_run": True,
            "error": "live_dry_run",
            "request": {**body, "client_order_id": body["client_order_id"]},
            "contracts": count,
            "price": price,
            "requested_stake": round(requested_stake, 2),
            "actual_stake": actual_reserved_stake,
            "live_max_stake": live_max_stake,
            "shared_bankroll": {
                "reservation_id": (shared_review or {}).get("reservation_id"),
                "approved_stake": (shared_review or {}).get("approved_stake", actual_reserved_stake),
                "target_hit": (shared_review or {}).get("target_hit"),
            },
        }

    readiness = (
        crypto_patient_readiness(settings)
        if patient_active
        else crypto_spot_flow_live_pilot_readiness(settings, candidate)
        if pilot_active
        else crypto_live_readiness(settings)
    )
    if not readiness.get("ok"):
        if shared_review and finalize_reservation:
            finalize_reservation(shared_review.get("reservation_id"), "released_not_ready", 0.0)
        return {"ok": False, "error": "live_not_ready", "readiness": readiness, "requested_stake": round(requested_stake, 2)}

    liquidity_preflight = None
    if (campaign_active or pilot_active) and setting_bool(
        settings, "CRYPTO_LIVE_DEPTH_PREFLIGHT_ENABLED"
    ):
        # Never reuse the earlier ranking snapshot here. This check occurs
        # immediately before submission and must reflect executable depth now.
        liquidity_preflight = fresh_kalshi_executable_depth(
            settings,
            candidate.get("ticker"),
            candidate.get("side"),
            price,
            count,
        )
        liquidity_preflight["source"] = "immediate_pre_submit_depth"
        if not liquidity_preflight.get("ok"):
            if shared_review and finalize_reservation:
                finalize_reservation(shared_review.get("reservation_id"), "released_liquidity_preflight", 0.0)
            if (
                not pilot_active
                and allow_unit_downshift
                and setting_bool(
                    settings, "CRYPTO_LIVE_UNIT_DEPTH_DOWNSHIFT_ENABLED"
                )
                and liquidity_preflight.get("error")
                == "live_order_insufficient_fresh_depth"
            ):
                downshift_refresh = try_live_unit_depth_downshift_refresh(
                    settings,
                    portfolio,
                    candidate,
                    "immediate_pre_submit_depth",
                    reference_price_cents=(
                        (candidate.get("execution_quote_origin") or {}).get(
                            "price_cents"
                        )
                        or price
                    ),
                )
                if downshift_refresh.get("ok"):
                    reduced_stake = float(
                        (candidate.get("crypto_live_campaign") or {}).get(
                            "applied_stake"
                        )
                        or (candidate.get("crypto_units") or {}).get(
                            "applied_stake"
                        )
                        or 0
                    )
                    if reduced_stake > 0:
                        reduced_order = place_live_kalshi_order(
                            settings,
                            portfolio,
                            candidate,
                            reduced_stake,
                            allow_unit_downshift=False,
                        )
                        reduced_order["unit_depth_downshift"] = (
                            downshift_refresh.get("unit_depth_downshift")
                            or candidate.get("live_unit_depth_downshift")
                        )
                        reduced_order["initial_liquidity_preflight"] = (
                            liquidity_preflight
                        )
                        return reduced_order
            return {
                "ok": False,
                "error": liquidity_preflight.get("error") or "live_order_liquidity_preflight",
                "message": liquidity_preflight.get("message"),
                "request": {**body, "client_order_id": body["client_order_id"]},
                "contracts": 0,
                "price": price,
                "requested_stake": round(requested_stake, 2),
                "actual_stake": 0.0,
                "live_max_stake": live_max_stake,
                "liquidity_preflight": liquidity_preflight,
                "unit_depth_downshift": candidate.get(
                    "live_unit_depth_downshift"
                ),
            }

    if patient_active:
        reasons = patient_order_reasons(settings, portfolio, candidate, utc_now())
        if reasons:
            if shared_review and finalize_reservation:
                finalize_reservation(shared_review.get("reservation_id"), "released_patient_confirmation_expired", 0.0)
            return {"ok": False, "error": "patient_confirmation_expired", "reasons": reasons, "contracts": 0}
    creds = kalshi_credentials(settings)
    fok_retry = {
        "enabled": bool(
            campaign_active
            and time_in_force == "fill_or_kill"
            and setting_bool(settings, "CRYPTO_LIVE_FOK_SAFE_RETRY_ENABLED")
        ),
        "attempted": False,
    }
    try:
        data, _headers = kalshi_private_request(KALSHI_ORDER_PATH, method="POST", body=body, **creds)
    except Exception as exc:
        first_exception_details = exception_diagnostics(exc)
        if fok_retry["enabled"] and fok_insufficient_resting_volume(exc):
            fok_retry["attempted"] = True
            fok_retry["first_error"] = safe_error_message(exc)
            fok_retry["first_error_details"] = first_exception_details
            original_retry_price = price
            retry_refresh = refresh_live_campaign_candidate_quote(
                settings,
                portfolio,
                candidate,
            )
            candidate["live_quote_refresh"] = retry_refresh
            fok_retry["revalidation"] = retry_refresh
            if retry_refresh.get("ok"):
                retry_review = candidate.get("crypto_live_campaign") or {}
                retry_price = int(round(float(candidate.get("entry_price") or 0)))
                retry_count = max(
                    1,
                    int(
                        retry_review.get("applied_contracts")
                        or retry_refresh.get("required_contracts")
                        or 1
                    ),
                )
                retry_actual_stake = round(
                    retry_count * retry_price / 100.0,
                    2,
                )
                max_retry_move = float(
                    retry_refresh.get("max_adverse_move_cents")
                    if retry_refresh.get("max_adverse_move_cents") is not None
                    else setting_float(
                        settings,
                        "CRYPTO_LIVE_QUOTE_REFRESH_MAX_ADVERSE_CENTS",
                    )
                )
                retry_move = retry_price - original_retry_price
                fully_revalidated = bool(
                    retry_review.get("eligible")
                    and retry_move <= max_retry_move + 1e-9
                    and int(retry_refresh.get("required_contracts") or 0)
                    == retry_count
                    and float(retry_refresh.get("available_contracts") or 0)
                    + 1e-9
                    >= retry_count
                )
                fok_retry.update({
                    "fully_revalidated": fully_revalidated,
                    "original_price_cents": original_retry_price,
                    "retry_price_cents": retry_price,
                    "adverse_move_cents": round(retry_move, 4),
                    "retry_contracts": retry_count,
                    "retry_stake": retry_actual_stake,
                })
            else:
                fully_revalidated = False

            if fully_revalidated:
                if shared_review and finalize_reservation:
                    finalize_reservation(
                        shared_review.get("reservation_id"),
                        "released_fok_reprice",
                        0.0,
                    )
                    shared_review = None
                if setting_bool(settings, "CRYPTO_LIVE_REQUIRE_SHARED_BANKROLL"):
                    shared_review = reserve_live_order(
                        "crypto",
                        retry_actual_stake,
                        price_cents=retry_price,
                        metadata=crypto_live_order_metadata(
                            candidate,
                            retry_actual_stake,
                        ),
                    )
                    approved_retry_stake = float(
                        (shared_review or {}).get("approved_stake") or 0
                    )
                    if (
                        not (shared_review or {}).get("ok")
                        or approved_retry_stake + 0.005 < retry_actual_stake
                    ):
                        if (
                            (shared_review or {}).get("ok")
                            and finalize_reservation
                        ):
                            finalize_reservation(
                                shared_review.get("reservation_id"),
                                "released_fok_reprice_guard",
                                0.0,
                            )
                        return {
                            "ok": False,
                            "error": "shared_bankroll_fok_reprice_guard",
                            "message": "Repriced full-size recovery stake was not fully approved",
                            "request": {
                                **body,
                                "client_order_id": body["client_order_id"],
                            },
                            "liquidity_preflight": retry_refresh,
                            "shared_bankroll": {
                                key: (shared_review or {}).get(key)
                                for key in (
                                    "error",
                                    "approved_stake",
                                    "requested_stake",
                                    "loss_room",
                                )
                            },
                            "fok_retry": fok_retry,
                        }
                price = retry_price
                count = retry_count
                requested_stake = retry_actual_stake
                actual_reserved_stake = retry_actual_stake
                live_max_stake = max(live_max_stake, retry_actual_stake)
                liquidity_preflight = {
                    **retry_refresh,
                    "source": "fok_reprice_revalidation",
                }
                retry_body = kalshi_event_order_body(
                    ticker=candidate["ticker"],
                    order_side=candidate["side"],
                    price_cents=retry_price,
                    count=retry_count,
                    client_order_id=f"crypto-{uuid.uuid4()}",
                    time_in_force=time_in_force,
                )
                try:
                    data, _headers = kalshi_private_request(
                        KALSHI_ORDER_PATH,
                        method="POST",
                        body=retry_body,
                        **creds,
                    )
                    body = retry_body
                    fok_retry["submitted"] = True
                except Exception as retry_exc:
                    retry_exception_details = exception_diagnostics(retry_exc)
                    fok_retry["submitted"] = True
                    fok_retry["retry_error"] = safe_error_message(retry_exc)
                    fok_retry["retry_error_details"] = retry_exception_details
                    if shared_review and finalize_reservation:
                        finalize_reservation(
                            shared_review.get("reservation_id"),
                            "exception",
                            0.0,
                        )
                    return {
                        "ok": False,
                        "error": (
                            "live_order_insufficient_fresh_depth"
                            if fok_insufficient_resting_volume(retry_exc)
                            else "live_order_exception"
                        ),
                        "message": safe_error_message(retry_exc),
                        "exception_details": retry_exception_details,
                        "request": {
                            **retry_body,
                            "client_order_id": retry_body["client_order_id"],
                        },
                        "liquidity_preflight": retry_refresh,
                        "fok_retry": fok_retry,
                    }
            else:
                if shared_review and finalize_reservation:
                    finalize_reservation(
                        shared_review.get("reservation_id"),
                        "released_fok_retry_depth",
                        0.0,
                    )
                return {
                    "ok": False,
                    "error": (
                        retry_refresh.get("error")
                        or "live_order_insufficient_fresh_depth"
                    ),
                    "message": (
                        retry_refresh.get("message")
                        or safe_error_message(exc)
                    ),
                    "request": {**body, "client_order_id": body["client_order_id"]},
                    "liquidity_preflight": retry_refresh,
                    "fok_retry": fok_retry,
                }
        else:
            if shared_review and finalize_reservation and not patient_active:
                finalize_reservation(shared_review.get("reservation_id"), "exception", 0.0)
            return {
                "ok": False,
                "error": "live_order_exception",
                "message": safe_error_message(exc),
                "exception_details": first_exception_details,
                "request": {**body, "client_order_id": body["client_order_id"]},
                "liquidity_preflight": liquidity_preflight,
                "fok_retry": fok_retry,
            }

    order_response = data.get("order") if isinstance(data, dict) and isinstance(data.get("order"), dict) else data
    fill_count = order_fill_count(order_response or {})
    if fill_count <= 0:
        if patient_active and (
            not isinstance(order_response, dict)
            or str(order_response.get("status") or "").lower() not in {"canceled", "cancelled"}
        ):
            return {"ok": False, "error": "live_order_exception", "message": "patient_order_outcome_unconfirmed",
                    "request": body, "response": order_response, "contracts": 0}
        if shared_review and finalize_reservation:
            finalize_reservation(shared_review.get("reservation_id"), "not_filled", 0.0)
        return {
            "ok": False,
            "error": "live_order_not_filled",
            "request": {**body, "client_order_id": body["client_order_id"]},
            "response": order_response,
            "contracts": 0,
            "price": price,
            "requested_stake": round(requested_stake, 2),
            "actual_stake": 0.0,
            "live_max_stake": live_max_stake,
            "liquidity_preflight": liquidity_preflight,
            "fok_retry": fok_retry,
        }

    executed_price = order_entry_price_cents(order_response or {}, outcome_side=candidate.get("side"))
    if executed_price <= 0:
        executed_price = float(price)
    actual_stake = round(fill_count * executed_price / 100.0, 4)
    if shared_review and finalize_reservation:
        finalize_reservation(
            shared_review.get("reservation_id"),
            "filled_pending_persist" if patient_active else "filled",
            actual_stake + order_fill_fee(order_response or {}) if patient_active else actual_stake,
        )
    result = {
        "ok": True,
        "request": {**body, "client_order_id": body["client_order_id"]},
        "response": order_response,
        "contracts": fill_count,
        "price": price,
        "executed_price": executed_price,
        "requested_stake": round(requested_stake, 2),
        "actual_stake": actual_stake,
        "live_max_stake": live_max_stake,
        "liquidity_preflight": liquidity_preflight,
        "fok_retry": fok_retry,
        "unit_depth_downshift": candidate.get("live_unit_depth_downshift"),
        "shared_bankroll": {
            "reservation_id": (shared_review or {}).get("reservation_id"),
            "approved_stake": (shared_review or {}).get("approved_stake", actual_stake),
            "target_hit": (shared_review or {}).get("target_hit"),
        },
    }
    if not pilot_active:
        reconcile_live_unit_accounting(candidate, result)
    return result


def record_live_bet(portfolio, candidate, live_order, persist=True):
    stake = round(float(live_order.get("actual_stake") or 0), 4)
    owner = crypto_strategy_owner(candidate)
    bet = {
        "id": str(uuid.uuid4()),
        "status": "open",
        "mode": "live",
        "placed_at": iso_now(),
        "ticker": candidate["ticker"],
        "kalshi_ticker": candidate["ticker"],
        "event_ticker": candidate.get("event_ticker"),
        "series_ticker": candidate.get("series_ticker"),
        "asset": candidate["asset"],
        "title": candidate.get("title"),
        "market_kind": candidate["market_kind"],
        "market_lane": candidate.get("market_lane"),
        "position_cluster": candidate.get("position_cluster"),
        "exposure_group": candidate.get("exposure_group"),
        "side": candidate["side"],
        "order_side": candidate["side"],
        "entry_price": live_order.get(
            "accounting_fill_price_cents",
            live_order.get("executed_price", live_order.get("price", candidate["entry_price"])),
        ),
        "stake": stake,
        "contracts": float(live_order.get("contracts") or 0),
        "fee_schedule": candidate.get("fee_schedule"),
        "model_prob_yes": candidate["model_prob_yes"],
        "edge": candidate["edge"],
        "confidence": candidate["confidence"],
        "close_time": candidate.get("close_time"),
        "floor_strike": candidate.get("floor_strike"),
        "cap_strike": candidate.get("cap_strike"),
        "model": candidate.get("model"),
        "probability": candidate.get("probability"),
        "microstructure": candidate.get("microstructure"),
        "kalshi_microstructure": candidate.get("kalshi_microstructure"),
        "live_underlying_refresh": candidate.get("live_underlying_refresh"),
        "live_unit_depth_downshift": candidate.get("live_unit_depth_downshift"),
        "flow_review": candidate.get("flow_review"),
        "disagreement_guard": candidate.get("disagreement_guard"),
        "directional_confirmation": candidate.get("directional_confirmation"),
        "learned_15m_model": candidate.get("learned_15m_model"),
        "market_regime_shadow": candidate.get("market_regime_shadow"),
        "market_regime_live": candidate.get("market_regime_live"),
        "ai_review": candidate.get("ai_review"),
        "grok_review": candidate.get("grok_review"),
        "selective_edge": candidate.get("selective_edge"),
        "shared_recovery": candidate.get("shared_recovery"),
        "phase_two": candidate.get("phase_two"),
        "phase_two_attempt_id": candidate.get("phase_two_attempt_id"),
        "phase_two_cycle": candidate.get("phase_two_cycle"),
        "shadow": candidate.get("shadow"),
        "small_edge": candidate.get("small_edge"),
        "low_edge_pilot": candidate.get("low_edge_pilot"),
        "adaptive_control": candidate.get("adaptive_control"),
        "strategy_identity": candidate.get("strategy_identity"),
        "strategy_version": candidate.get("strategy_version"),
        "strategy_config_hash": candidate.get("strategy_config_hash"),
        "feature_schema_version": candidate.get("feature_schema_version"),
        "crypto_units": candidate.get("crypto_units"),
        "crypto_live_campaign": candidate.get("crypto_live_campaign"),
        "live_core": candidate.get("live_core"),
        "event_diversification": candidate.get("event_diversification"),
        "execution_quality": candidate.get("execution_quality"),
        "multi_market": candidate.get("multi_market"),
        "spot_flow_live_pilot": candidate.get("spot_flow_live_pilot"),
        "strategy_owner": owner,
        "bot_number": crypto_campaign_bot_number(candidate) if owner == CRYPTO_15M_CAMPAIGN_OWNER else None,
        "live_order": live_order,
    }
    if is_patient_candidate(candidate):
        bet[PATIENT_FIELD] = deepcopy(candidate[PATIENT_FIELD])
        # Recovery accounting follows actual fill quantity, including any
        # unexpected partial response from a nominally FOK order.
        if float(live_order.get("contracts") or 0) < candidate[PATIENT_FIELD]["contracts"]:
            bet[PATIENT_FIELD].update(recovery_extra_cost=0.0, recovery_extra_contracts=0)
    quoted_entry_price = live_order.get("price", candidate.get("entry_price"))
    if quoted_entry_price != bet["entry_price"]:
        bet["quoted_entry_price"] = quoted_entry_price
    fee = order_fill_fee(live_order.get("response") or {})
    if fee:
        bet["fee"] = fee
    portfolio.setdefault("bets", []).append(bet)
    if owner == CRYPTO_15M_CAMPAIGN_OWNER:
        campaign = bet.get("crypto_live_campaign") or {}
        advance_crypto_15m_campaign_bot_order(
            portfolio,
            bet.get("bot_number"),
            campaign.get("configured_bot_count"),
        )
        mark_correlated_campaign_window(portfolio, bet)
    candidate["decision"] = "placed_live"
    log_line(
        f"LIVE MARKET BET: {bet['side'].upper()} {bet['asset']} {bet['ticker']} "
        f"lane={bet.get('market_lane', 'unknown')} "
        f"stake=${stake:.2f} owner={owner} price={bet['entry_price']}c contracts={bet['contracts']:.4f} "
        f"edge={bet['edge']:.2f}% conf={bet['confidence']} "
        f"low_edge_pilot={bool((bet.get('low_edge_pilot') or {}).get('active'))} "
        f"event_tier={(bet.get('event_diversification') or {}).get('tier', 'first_full')}"
    )
    event_line({"type": "live_bet", "bet": bet})
    if persist:
        update_live_bot_ledger([bet])
        # A remote fill must be durable before the rest of the scan continues.
        # If a later model/API call fails, startup ledger recovery can still
        # reconstruct the exact position.
        save_portfolio(portfolio)
        if is_patient_candidate(candidate) and finalize_reservation:
            finalize_reservation((live_order.get("shared_bankroll") or {}).get("reservation_id"), "filled", stake)
    record_crypto_phase_two_placement(bet)
    return bet


def settle_open_bets(settings, portfolio, asset_data):
    grace = timedelta(minutes=setting_float(settings, "CRYPTO_SETTLE_GRACE_MINUTES"))
    now = utc_now()
    settled = 0
    official_markets = {}
    for bet in portfolio.get("bets", []):
        if bet.get("status") != "open":
            continue
        if bet.get("mode") == "live":
            continue
        close_time = parse_time(bet.get("close_time"))
        if not close_time or now < close_time + grace:
            continue
        ticker = str(bet.get("ticker") or "")
        if not ticker:
            continue
        if ticker not in official_markets:
            try:
                payload = http_json(
                    f"{KALSHI_BASE}/markets/{quote(ticker, safe='')}",
                    timeout=5,
                    retries=1,
                )
                official_markets[ticker] = (payload or {}).get("market") or {}
            except Exception as exc:
                official_markets[ticker] = {"_error": safe_error_message(exc)}
        official = official_markets[ticker]
        official_result = str(official.get("result") or "").strip().lower()
        if (
            str(official.get("status") or "").strip().lower() != "finalized"
            or official_result not in {"yes", "no"}
        ):
            # Never use a post-close spot proxy as settlement. Leave the paper
            # position open until Kalshi publishes the official result.
            continue
        yes_win = official_result == "yes"
        side_win = yes_win if bet.get("side") == "yes" else not yes_win
        payout = float(bet.get("contracts") or 0) if side_win else 0.0
        profit = round(
            payout
            - float(bet.get("stake") or 0)
            - float(bet.get("fee") or 0),
            2,
        )
        settlement_value, settlement_value_field = parse_settlement_value(official)
        bet.update({
            "status": "settled",
            "settled_at": official.get("settlement_ts") or official.get("settled_time") or iso_now(),
            "settlement_spot": settlement_value,
            "official_settlement_value": settlement_value,
            "settlement_value_field": settlement_value_field,
            "settlement_source": "kalshi_finalized_market",
            "market_result": official_result,
            "result": "WIN" if side_win else "LOSS",
            "payout": round(payout, 2),
            "profit": profit,
        })
        portfolio["balance"] = round(float(portfolio.get("balance") or 0) + payout, 2)
        settled += 1
        log_line(
            f"SETTLED CRYPTO BET: {bet['result']} {bet['asset']} {bet['ticker']} "
            f"side={bet['side']} official_result={official_result} "
            f"settlement_value={settlement_value} profit=${profit:.2f}"
        )
        event_line({"type": "settled_bet", "bet": bet})
    return settled


def summarize_low_edge_live_pilot(portfolio, settings):
    rows = crypto_low_edge_pilot_rows(portfolio)
    open_rows = [row for row in rows if row.get("status") == "open"]
    settled = sorted(
        [row for row in rows if row.get("status") == "settled"],
        key=lambda row: str(row.get("settled_at") or row.get("placed_at") or ""),
    )
    wins = sum(1 for row in settled if row.get("result") == "WIN")
    losses = sum(1 for row in settled if row.get("result") == "LOSS")
    stake = sum(float(row.get("stake") or 0) for row in settled)
    profit = sum(float(row.get("profit") or 0) for row in settled)
    current_streak = 0
    maximum_loss_streak = 0
    for row in settled:
        if row.get("result") == "LOSS":
            current_streak += 1
            maximum_loss_streak = max(maximum_loss_streak, current_streak)
        else:
            current_streak = 0
    official_rotation = setting_bool(
        settings,
        "CRYPTO_15M_LOW_EDGE_OFFICIAL_ROTATION",
    )
    maximum_settled = (
        0
        if official_rotation
        else max(
            0,
            setting_int(settings, "CRYPTO_15M_LOW_EDGE_PILOT_MAX_SETTLED"),
        )
    )
    return {
        "enabled": setting_bool(settings, "CRYPTO_15M_LOW_EDGE_PILOT_ENABLED"),
        "mode": "official_rotation" if official_rotation else "live_controlled_pilot",
        "official_rotation": official_rotation,
        "affects_global_edge_floor": False,
        "base_cycle_only": False,
        "open": len(open_rows),
        "settled": len(settled),
        "wins": wins,
        "losses": losses,
        "win_rate": round(wins / len(settled) * 100.0, 2) if settled else 0.0,
        "stake": round(stake, 2),
        "profit": round(profit, 2),
        "roi": round(profit / stake * 100.0, 2) if stake else 0.0,
        "maximum_loss_streak": maximum_loss_streak,
        "maximum_settled": maximum_settled,
        "remaining_until_review": (
            max(0, maximum_settled - len(settled))
            if maximum_settled > 0
            else None
        ),
        "sample_complete": bool(
            maximum_settled > 0 and len(settled) >= maximum_settled
        ),
        "configuration": {
            "minimum_edge": setting_float(
                settings,
                "CRYPTO_15M_LOW_EDGE_PILOT_MIN_EDGE",
            ),
            "maximum_edge_exclusive": setting_float(
                settings,
                "CRYPTO_15M_LOW_EDGE_PILOT_MAX_EDGE",
            ),
            "minimum_confidence": setting_float(
                settings,
                "CRYPTO_15M_LOW_EDGE_PILOT_MIN_CONFIDENCE",
            ),
            "minimum_price_cents": setting_float(
                settings,
                "CRYPTO_15M_LOW_EDGE_PILOT_MIN_PRICE_CENTS",
            ),
            "maximum_price_cents": setting_float(
                settings,
                "CRYPTO_15M_LOW_EDGE_PILOT_MAX_PRICE_CENTS",
            ),
            "maximum_open": setting_int(
                settings,
                "CRYPTO_15M_LOW_EDGE_PILOT_MAX_OPEN",
            ),
        },
        "recent_records": list(reversed(settled[-50:])),
        "open_records": sorted(
            open_rows,
            key=lambda row: str(row.get("placed_at") or ""),
            reverse=True,
        ),
    }


def current_strategy_performance(portfolio, identity, settings=None):
    """Version-scoped live campaign results for the strategy running now."""
    fingerprint = str((identity or {}).get("fingerprint") or "")
    matched = []
    open_rows = []
    for bet in (portfolio or {}).get("bets") or []:
        row_identity = bet.get("strategy_identity") or {}
        if not fingerprint or str(row_identity.get("fingerprint") or "") != fingerprint:
            continue
        if bet.get("strategy_owner") != CRYPTO_15M_CAMPAIGN_OWNER:
            continue
        if str(bet.get("mode") or "").lower() != "live" or is_user_crypto_bet(bet):
            continue
        if str(bet.get("market_lane") or market_lane(bet)) != "crypto_15m":
            continue
        if bet.get("status") == "settled":
            matched.append(bet)
        elif bet.get("status") == "open":
            open_rows.append(bet)

    wins = sum(1 for bet in matched if str(bet.get("result") or "").upper() == "WIN")
    losses = sum(1 for bet in matched if str(bet.get("result") or "").upper() == "LOSS")
    stake = sum(float(bet.get("stake") or 0) for bet in matched)
    profit = sum(float(bet.get("profit") or 0) for bet in matched)
    entry_prices = [float(bet.get("entry_price") or 0) for bet in matched if float(bet.get("entry_price") or 0) > 0]
    confidences = [float(bet.get("confidence") or 0) for bet in matched if bet.get("confidence") is not None]
    settled_times = sorted(
        str(bet.get("settled_at") or bet.get("close_time") or "")
        for bet in matched
        if bet.get("settled_at") or bet.get("close_time")
    )
    return {
        "fingerprint": fingerprint,
        "status": "active" if matched else "collecting",
        "settled_count": len(matched),
        "independent_markets": len({str(bet.get("ticker") or bet.get("id") or "") for bet in matched}),
        "open_count": len(open_rows),
        "wins": wins,
        "losses": losses,
        "win_rate": round(wins / max(1, wins + losses), 4),
        "stake": round(stake, 2),
        "profit": round(profit, 2),
        "roi_pct": round(100.0 * profit / stake, 4) if stake > 0 else 0.0,
        "average_entry_price_cents": round(sum(entry_prices) / len(entry_prices), 4) if entry_prices else None,
        "average_confidence": round(sum(confidences) / len(confidences), 4) if confidences else None,
        "first_settled_at": settled_times[0] if settled_times else None,
        "last_settled_at": settled_times[-1] if settled_times else None,
        "version_scoped": True,
    }


def summarize(portfolio, candidates, placed, settings):
    actual_settled = [
        bet for bet in portfolio.get("bets", [])
        if bet.get("status") == "settled"
    ]
    settled = [
        bet for bet in actual_settled
        if bet.get("status") == "settled" and crypto_analytics_included(bet, settings)
    ]
    analytics_excluded = [
        bet for bet in actual_settled
        if not crypto_analytics_included(bet, settings)
    ]
    user_settled = [bet for bet in actual_settled if is_user_crypto_bet(bet)]
    user_open = [bet for bet in open_bets(portfolio) if is_user_crypto_bet(bet)]
    wins = sum(1 for bet in settled if bet.get("result") == "WIN")
    losses = sum(1 for bet in settled if bet.get("result") == "LOSS")
    profit = round(sum(float(bet.get("profit") or 0) for bet in settled), 2)
    shared_bankroll = build_shared_bankroll_state(save=True) if build_shared_bankroll_state else {}
    analytics = scan_analytics(portfolio, candidates, placed, settings)
    campaign = (
        crypto_15m_campaign_context(settings, portfolio)
        if setting_bool(settings, "CRYPTO_15M_CAMPAIGN_ENABLED")
        else {}
    )
    phase_two = {} if campaign else crypto_phase_two_context(settings, portfolio)
    mode = execution_mode(settings)
    live_reconciliation = read_json(LIVE_RECONCILIATION_FILE, {})
    live_cash = (live_reconciliation.get("account") or {}).get("cash_balance") or portfolio.get("live_cash_balance")
    grok_state = load_grok_usage_state(settings)
    report = {
        "generated_at": iso_now(),
        "mode": mode,
        "balance": round(float(live_cash if mode == "live" and live_cash is not None else portfolio.get("balance") or 0), 2),
        "portfolio_balance": round(float(portfolio.get("balance") or 0), 2),
        "live_cash_balance": live_cash,
        "starting_balance": portfolio.get("starting_balance"),
        "open_exposure": open_exposure(portfolio),
        "open_bets_count": len(open_bets(portfolio)),
        "live_open_bets_count": len([bet for bet in open_bets(portfolio) if bet.get("mode") == "live"]),
        "settled_count": len(settled),
        "actual_settled_count": len(actual_settled),
        "analytics_excluded_settled_count": len(analytics_excluded),
        "wins": wins,
        "losses": losses,
        "win_rate": round(wins / max(1, wins + losses), 3),
        "realized_profit": profit,
        "actual_realized_profit": round(sum(float(bet.get("profit") or 0) for bet in actual_settled), 2),
        "analytics_excluded_realized_profit": round(sum(float(bet.get("profit") or 0) for bet in analytics_excluded), 2),
        "account_realized_profit": round(sum(float(bet.get("profit") or 0) for bet in actual_settled), 2),
        "user_bet_summary": {
            "open_count": len(user_open),
            "open_exposure": round(sum(float(bet.get("stake") or 0) for bet in user_open), 2),
            "settled_count": len(user_settled),
            "wins": sum(1 for bet in user_settled if bet.get("result") == "WIN"),
            "losses": sum(1 for bet in user_settled if bet.get("result") == "LOSS"),
            "profit": round(sum(float(bet.get("profit") or 0) for bet in user_settled), 2),
        },
        "placed_count": len(placed),
        "top_candidates": sorted(candidates, key=lambda row: row.get("edge", -999), reverse=True)[:25],
        "open_bets": open_bets(portfolio),
        "recent_bets": sorted(
            [
                bet for bet in portfolio.get("bets", [])
                if (
                    bet.get("status") == "open"
                    or crypto_analytics_included(bet, settings)
                    or is_user_crypto_bet(bet)
                )
            ],
            key=lambda bet: str(
                bet.get("settled_at")
                or bet.get("placed_at")
                or bet.get("created_at")
                or ""
            ),
            reverse=True,
        )[:25],
        "shared_bankroll": shared_bankroll,
        "crypto_15m_campaign": campaign,
        "crypto_15m_action_gate": crypto_15m_action_gate_configuration(settings),
        "multi_market": {
            "enabled": setting_bool(settings, "MULTI_MARKET_ENABLED"),
            "live_enabled": setting_bool(settings, "MULTI_MARKET_LIVE_ENABLED"),
            "configured_series_by_lane": count_rows(
                [{"series_ticker": series} for series in setting_list(settings, "CRYPTO_SERIES")],
                market_lane_label,
            ),
            "candidate_by_lane": analytics.get("candidate_by_lane") or [],
            "placed_by_lane": count_rows(placed, market_lane_label),
            "open_by_lane": analytics.get("open_by_lane") or [],
            "settled_by_lane": analytics.get("settled_by_lane") or [],
            "commodity_data": {
                "provider": "pyth",
                "history_key_saved": bool(pyth_api_key(settings)),
                "channel": settings.get("MULTI_MARKET_PYTH_CHANNEL", "fixed_rate@1000ms"),
                "ready": bool(
                    pyth_api_key(settings)
                    and all(
                        (COMMODITY_DATA_HEALTH.get(asset) or {}).get("ok")
                        for asset in COMMODITY_ASSETS
                    )
                ),
                "feed_health": {
                    asset: dict(COMMODITY_DATA_HEALTH.get(asset) or {})
                    for asset in sorted(COMMODITY_ASSETS)
                },
            },
            "entry_requirements": {
                "minimum_edge": setting_float(settings, "MULTI_MARKET_LIVE_MIN_EDGE"),
                "minimum_confidence": setting_float(settings, "MULTI_MARKET_LIVE_MIN_CONFIDENCE"),
                "price_cents": [
                    setting_float(settings, "MULTI_MARKET_LIVE_MIN_PRICE_CENTS"),
                    setting_float(settings, "MULTI_MARKET_LIVE_MAX_PRICE_CENTS"),
                ],
                "maximum_stake": setting_float(settings, "MULTI_MARKET_LIVE_MAX_STAKE"),
            },
        },
        "low_edge_live_pilot": summarize_low_edge_live_pilot(
            portfolio,
            settings,
        ),
        "phase_two": phase_two,
        "live_readiness": crypto_live_readiness(settings),
        "live_reconciliation": live_reconciliation,
        "analytics": analytics,
        "grok_usage": {
            "date": grok_state.get("date"),
            "daily_calls": grok_state.get("daily_calls", 0),
            "daily_cost_usd": grok_state.get("daily_cost_usd", 0.0),
            "daily_unpriced_reserve_usd": grok_state.get("daily_unpriced_reserve_usd", 0.0),
            "daily_accounted_cost_usd": grok_accounted_cost(grok_state),
            "daily_budget_usd": setting_float(settings, "CRYPTO_GROK_DAILY_BUDGET_USD"),
            "cache_entries": len(grok_state.get("cache") or {}),
        },
        "shadow_algorithm": summarize_shadow_candidates(candidates),
        "settings": {
            k: v
            for k, v in settings.items()
            if not (k.endswith("_KEY") or "SECRET" in k or "PRIVATE" in k or "TOKEN" in k)
        },
    }
    if mode == "paper":
        report["paper_balance"] = report["portfolio_balance"]
    write_json(REPORT_FILE, report)
    return report


def compact_15m_learning_state(state):
    state = state or {}
    return {
        "status": state.get("status", "disabled"),
        "active": bool(state.get("active")),
        "training_in_background": bool(state.get("training_in_background")),
        "evaluation_revision": state.get("evaluation_revision"),
        "activation_reason": state.get("activation_reason"),
        "generated_at": state.get("generated_at"),
        "model_architecture": state.get("model_architecture"),
        "sample_weighting": state.get("sample_weighting"),
        "rows": state.get("rows", 0),
        "unique_markets": state.get("unique_markets", 0),
        "activation_checks": state.get("activation_checks") or {},
        "evaluation": state.get("evaluation") or {},
        "research_feature_readiness": (
            state.get("research_feature_readiness")
            or (state.get("evaluation") or {}).get("research_feature_readiness")
            or {}
        ),
        "research_shadow_ablation": (
            state.get("research_shadow_ablation")
            or (state.get("evaluation") or {}).get("research_shadow_ablation")
            or {}
        ),
        "subgroup_calibrators": len(state.get("subgroup_calibrators") or {}),
    }


def settlement_proxy_window(settings, asset, close_time):
    rows = []
    window_seconds = setting_float(settings, "CRYPTO_15M_SETTLEMENT_WINDOW_SECONDS")
    for stream in (COINBASE_MICROSTRUCTURE_STREAM, KRAKEN_MICROSTRUCTURE_STREAM):
        if not stream:
            continue
        try:
            row = stream.settlement_window(asset, close_time, window_seconds=window_seconds) or {}
        except Exception:
            row = {}
        if number := float(row.get("average") or 0):
            if number > 0 and int(row.get("observations") or 0) > 0:
                rows.append(row)
    total_observations = sum(int(row.get("observations") or 0) for row in rows)
    average = (
        sum(float(row["average"]) * int(row.get("observations") or 0) for row in rows)
        / total_observations
        if total_observations > 0
        else None
    )
    return {
        "source": "coinbase_kraken_one_second_mid_average",
        "asset": asset,
        "close_time": str(close_time or ""),
        "window_seconds": window_seconds,
        "observations": total_observations,
        "source_count": len(rows),
        "average": average,
        "sources": rows,
    }


def background_learning_state(previous_state, train_kwargs):
    """Do not stall quote capture/reconciliation while a CPU-heavy model trains."""
    global LEARNING_TRAINING_EXECUTOR, LEARNING_TRAINING_FUTURE
    if LEARNING_TRAINING_EXECUTOR is None:
        LEARNING_TRAINING_EXECUTOR = ThreadPoolExecutor(max_workers=1, thread_name_prefix="crypto-model-training")
    if LEARNING_TRAINING_FUTURE is None:
        LEARNING_TRAINING_FUTURE = LEARNING_TRAINING_EXECUTOR.submit(
            load_or_train_15m_model, CRYPTO_15M_TRAINING_DATASET_FILE,
            CRYPTO_15M_MODEL_STATE_FILE, **train_kwargs)
    if LEARNING_TRAINING_FUTURE.done():
        completed = LEARNING_TRAINING_FUTURE
        LEARNING_TRAINING_FUTURE = None
        return completed.result()
    if previous_state.get("evaluation_revision") == EVALUATION_REVISION:
        state = dict(previous_state)
    else:
        state = {"status": "collecting", "activation_reason": "corrected_evaluation_training",
                 "rows": previous_state.get("rows", 0), "unique_markets": previous_state.get("unique_markets", 0)}
    return {**state, "active": False, "training_in_background": True}


def run_15m_learning_cycle(settings):
    if not setting_bool(settings, "CRYPTO_15M_LEARNING_ENABLED"):
        return (
            {"status": "disabled", "active": False, "activation_reason": "disabled"},
            {"resolved_markets": 0, "resolved_snapshots": 0, "pending": 0},
        )
    try:
        resolution = resolve_15m_training_snapshots(
            KALSHI_BASE,
            CRYPTO_15M_TRAINING_PENDING_FILE,
            CRYPTO_15M_TRAINING_DATASET_FILE,
            settlement_grace_minutes=setting_float(
                settings,
                "CRYPTO_15M_TRAINING_SETTLEMENT_GRACE_MINUTES",
            ),
            max_markets_per_run=setting_int(
                settings,
                "CRYPTO_15M_TRAINING_MAX_RESOLVES_PER_SCAN",
            ),
            proxy_window_provider=lambda asset, close_time: settlement_proxy_window(
                settings,
                asset,
                close_time,
            ),
        )
    except Exception as exc:
        resolution = {
            "resolved_markets": 0,
            "resolved_snapshots": 0,
            "pending": 0,
            "error": safe_error_message(exc),
        }
        log_line(f"Crypto 15m training resolution WARNING: {type(exc).__name__}: {safe_error_message(exc)}")
    try:
        previous_state = read_json(CRYPTO_15M_MODEL_STATE_FILE, {})
        force_collection_refresh = (
            int(resolution.get("resolved_snapshots") or 0) > 0
            and str(previous_state.get("status") or "collecting") in {
                "collecting",
                "error",
            }
        )
        train_kwargs = dict(
            retrain_minutes=setting_float(settings, "CRYPTO_15M_ML_RETRAIN_MINUTES"),
            minimum_shadow_markets=setting_int(settings, "CRYPTO_15M_ML_MIN_SHADOW_MARKETS"),
            minimum_active_markets=setting_int(settings, "CRYPTO_15M_ML_MIN_ACTIVE_MARKETS"),
            minimum_brier_improvement=setting_float(
                settings,
                "CRYPTO_15M_ML_MIN_BRIER_IMPROVEMENT",
            ),
            midrange_max_calibration_gap=setting_float(
                settings,
                "CRYPTO_15M_ML_MIDRANGE_MAX_CALIBRATION_GAP",
            ),
            minimum_interval_markets=setting_int(
                settings,
                "CRYPTO_15M_ML_MIN_INTERVAL_MARKETS",
            ),
            minimum_interval_coverage=setting_float(
                settings,
                "CRYPTO_15M_ML_MIN_INTERVAL_COVERAGE",
            ),
            force=force_collection_refresh,
        )
        if setting_bool(settings, "CRYPTO_15M_ML_BACKGROUND_TRAINING"):
            state = background_learning_state(previous_state, train_kwargs)
        else:
            state = load_or_train_15m_model(CRYPTO_15M_TRAINING_DATASET_FILE,
                CRYPTO_15M_MODEL_STATE_FILE, **train_kwargs)
    except Exception as exc:
        state = {
            "status": "error",
            "active": False,
            "activation_reason": "training_error",
            "error": safe_error_message(exc),
        }
        log_line(f"Crypto 15m model training WARNING: {type(exc).__name__}: {safe_error_message(exc)}")
    if not state.get("training_in_background") and setting_bool(settings, "CRYPTO_15M_ML_FORCE_SHADOW") and state.get("status") not in {
        "collecting",
        "error",
    }:
        state = dict(state)
        state["qualified_for_activation"] = bool(
            state.get("active")
            or state.get("qualified_for_activation")
            or previous_state.get("qualified_for_activation")
        )
        state["force_shadow"] = True
        state["active"] = False
        state["status"] = "shadow"
        if state["qualified_for_activation"]:
            state["activation_reason"] = "forced_shadow_for_live_calibration"
        write_json(CRYPTO_15M_MODEL_STATE_FILE, state)
    return state, resolution


def run_scan():
    settings = load_settings()
    configure_runtime_files(settings)
    mode = execution_mode(settings)
    portfolio = load_portfolio(settings)
    portfolio["mode"] = mode
    repaired_unit_rows = (
        reconcile_portfolio_live_unit_accounting(portfolio)
        if mode == "live"
        else []
    )
    if repaired_unit_rows:
        update_live_bot_ledger(repaired_unit_rows)
        save_portfolio(portfolio)
        log_line(
            "CRYPTO LIVE UNIT ACCOUNTING REPAIR: "
            f"reconciled={len(repaired_unit_rows)}"
        )
    migrated_campaign_rows = ensure_crypto_15m_campaign_bot_numbers(portfolio)
    if migrated_campaign_rows:
        log_line("Crypto campaign migration: assigned legacy campaign rows to Bot 1")
    configured_assets = setting_list(settings, "CRYPTO_ASSETS")
    coinbase_stream = get_coinbase_microstructure_stream(settings, configured_assets)
    kraken_stream = get_kraken_microstructure_stream(settings, configured_assets)
    learned_15m_state, training_resolution = run_15m_learning_cycle(settings)
    live_reconciliation = reconcile_live_account(portfolio, settings) if mode == "live" else {}
    campaign_enabled = setting_bool(settings, "CRYPTO_15M_CAMPAIGN_ENABLED")
    campaign = crypto_15m_campaign_context(settings, portfolio) if campaign_enabled else {}
    phase_two = {} if campaign_enabled else crypto_phase_two_context(settings, portfolio)
    if campaign_enabled:
        log_line(
            f"Crypto {mode} 15m campaign scan status={campaign.get('status')} "
            f"bots={campaign.get('configured_bot_count', 1)} available={campaign.get('available_bot_numbers', [])} "
            f"realized=${campaign.get('realized_profit')} "
            f"open={campaign.get('bot_live_open_count')}/{campaign.get('max_open')}"
        )
        for lane in campaign.get("bots") or [campaign]:
            log_line(
                f"Crypto {mode} 15m Bot {lane.get('bot_number', 1)} "
                f"status={lane.get('status')} cycle={lane.get('cycle_number')}/{len(lane.get('cycle_goals') or [])} "
                f"goal=${lane.get('cycle_goal')} configured_cycle_profit=${lane.get('configured_cycle_profit')} "
                f"configured_cycle_count={lane.get('configured_cycle_count')} "
                f"goal_locked={lane.get('goal_schedule_locked')} realized=${lane.get('realized_profit')} "
                f"open={lane.get('bot_live_open_count')}/{lane.get('max_open')}"
            )
    else:
        log_line(
            f"Crypto {mode} scan started phase_two={phase_two.get('status')} "
            f"cycle={phase_two.get('current_cycle')}/{phase_two.get('max_cycles')} "
            f"target_remaining=${phase_two.get('target_remaining')}"
        )
    event_line({
        "type": "scan_started",
        "mode": mode,
        "balance": portfolio.get("balance"),
        "live_cash_balance": portfolio.get("live_cash_balance"),
        "open_exposure": open_exposure(portfolio),
        "crypto_15m_campaign": campaign,
        "phase_two": phase_two,
        "live_readiness": crypto_live_readiness(settings) if mode == "live" else {},
        "spot_flow_live_pilot_readiness": (
            crypto_spot_flow_live_pilot_readiness(settings)
            if mode == "live"
            else {}
        ),
    })
    fear_greed = (
        {"value": 50, "classification": "neutral", "source": "disabled_for_15m"}
        if campaign_enabled
        else fetch_fear_greed()
    )
    markets = fetch_kalshi_markets(settings)
    market_fetch_health = dict(LAST_KALSHI_MARKET_FETCH_HEALTH)
    needed_assets = {
        asset for asset in (infer_asset(market) for market in markets) if asset
    } | {
        str(bet.get("asset") or "").upper()
        for bet in open_bets(portfolio)
        if bet.get("asset")
    }
    selected_assets = sorted(needed_assets)
    stream_assets = sorted(set(configured_assets) | set(selected_assets))
    coinbase_stream = get_coinbase_microstructure_stream(settings, stream_assets)
    kraken_stream = get_kraken_microstructure_stream(settings, stream_assets)
    fetch_started = time.monotonic()
    with ThreadPoolExecutor(max_workers=2, thread_name_prefix="crypto-scan-inputs") as pool:
        asset_future = pool.submit(
            fetch_asset_data,
            settings,
            selected_assets,
            coinbase_stream,
            kraken_stream,
        )
        kalshi_micro_future = pool.submit(
            fetch_kalshi_microstructure,
            settings,
            markets,
        )
        asset_data = asset_future.result()
        kalshi_microstructure_by_ticker = kalshi_micro_future.result()
    input_fetch_seconds = round(time.monotonic() - fetch_started, 3)
    log_line(
        f"Crypto parallel inputs ready seconds={input_fetch_seconds} "
        f"assets={len(asset_data)} market_micro={len(kalshi_microstructure_by_ticker)}"
    )
    settlement_lag_shadow = configure_settlement_lag_shadow(settings, markets)
    settled = settle_open_bets(settings, portfolio, asset_data)
    if settled and not campaign_enabled:
        phase_two = crypto_phase_two_context(settings, portfolio)
    candidates = build_candidates(
        settings,
        markets,
        asset_data,
        fear_greed,
        kalshi_microstructure_by_ticker=kalshi_microstructure_by_ticker,
        learned_state=learned_15m_state,
    )
    candidates.sort(
        key=lambda row: crypto_candidate_sort_key(settings, row),
        reverse=True,
    )
    isolated_live_pilot_fast_path = bool(
        mode == "live"
        and setting_bool(settings, "CRYPTO_SPOT_FLOW_LIVE_PILOT_ENABLED")
        and crypto_15m_sprint_execution_freeze(settings).get("active")
    )

    def prepare_research_context():
        # None of this work is required to qualify the isolated spot-flow live
        # pilot.  In that mode it runs only after the order decision so disk I/O,
        # shadow settlement, and regime analytics cannot age an executable quote.
        prepared_perps = (
            run_perps_shadow(settings)
            if run_perps_shadow
            else {"mode": "unavailable", "error": "module_import_failed"}
        )
        prepared_regime = build_market_regime_scan_context(
            settings,
            asset_data,
            prepared_perps,
            candidates,
        )
        for raw_candidate in candidates:
            candidate_passes(settings, portfolio, raw_candidate)
        prepared_training = {
            "added": 0,
            "pending": training_resolution.get("pending", 0),
        }
        if setting_bool(settings, "CRYPTO_15M_LEARNING_ENABLED"):
            try:
                # Record after the complete raw-candidate review so the training
                # row retains decision thresholds and explicit data presence.
                prepared_training = record_15m_training_snapshots(
                    [
                        raw_candidate
                        for raw_candidate in candidates
                        if raw_candidate.get("market_lane") == "crypto_15m"
                    ],
                    CRYPTO_15M_TRAINING_PENDING_FILE,
                    max_pending=setting_int(
                        settings,
                        "CRYPTO_15M_TRAINING_MAX_PENDING",
                    ),
                )
            except Exception as exc:
                prepared_training = {
                    "added": 0,
                    "pending": training_resolution.get("pending", 0),
                    "error": safe_error_message(exc),
                }
                log_line(
                    "Crypto 15m snapshot recording WARNING: "
                    f"{type(exc).__name__}: {safe_error_message(exc)}"
                )
        return prepared_perps, prepared_regime, prepared_training

    perps_shadow = {"mode": "deferred_until_after_live_decision"}
    market_regime = {"status": "deferred_until_after_live_decision"}
    training_record = {
        "added": 0,
        "pending": training_resolution.get("pending", 0),
    }
    if not isolated_live_pilot_fast_path:
        perps_shadow, market_regime, training_record = prepare_research_context()
    live_rerank = {
        "enabled": False,
        "reason": "not_live_campaign",
        "requested": 0,
        "refreshed": 0,
        "failed": 0,
    }
    if (
        mode == "live"
        and (campaign_enabled or setting_bool(settings, "MULTI_MARKET_LIVE_ENABLED"))
        and setting_bool(settings, "CRYPTO_LIVE_QUOTE_REFRESH_ENABLED")
        and not (
            crypto_15m_sprint_execution_freeze(settings).get("active")
            and setting_bool(settings, "CRYPTO_SPOT_FLOW_LIVE_PILOT_ENABLED")
        )
    ):
        live_rerank = refresh_and_rerank_live_candidates(
            settings,
            portfolio,
            candidates,
        )
        log_line(
            f"Crypto live fresh rerank requested={live_rerank.get('requested')} "
            f"refreshed={live_rerank.get('refreshed')} failed={live_rerank.get('failed')} "
            f"seconds={live_rerank.get('seconds', 0)} workers={live_rerank.get('workers', 0)}"
        )
        event_line({"type": "live_candidate_rerank", **live_rerank})
    # Live qualification consumes the already-registered evidence summary.  The
    # current scan is captured into research ledgers only after execution, so a
    # profitable-looking shadow calculation can never delay its own live check.
    signal_reference = empty_signal_tournament_ledger(settings)
    current_signal_policy_hash = (
        signal_reference.get("configuration") or {}
    ).get("policy_hash")
    validation_cache = (
        read_json(CRYPTO_SPOT_FLOW_VALIDATION_CACHE_FILE, {})
        if isolated_live_pilot_fast_path
        else {}
    )
    cached_validation = validation_cache.get("validation") or {}
    cache_valid = bool(
        validation_cache.get("signal_policy_hash") == current_signal_policy_hash
        and cached_validation.get("gates")
    )
    if cache_valid:
        signal_tournament_ledger = {}
        signal_tournament_shadow = {
            "configuration": signal_reference.get("configuration") or {},
        }
        log_line(
            "Crypto live priority path loaded compact validation cache "
            f"generated_at={validation_cache.get('generated_at')}"
        )
    else:
        signal_tournament_ledger = normalize_signal_tournament_ledger(
            read_json(CRYPTO_SIGNAL_TOURNAMENT_FILE, signal_reference),
            settings,
        )
        signal_tournament_shadow = summarize_signal_tournament(
            signal_tournament_ledger,
            settings,
        )
    spot_flow_live_pilot_candidates, spot_flow_live_pilot = (
        build_spot_flow_live_pilot_candidates(
            [
                candidate
                for candidate in candidates
                if candidate.get("market_lane") == "crypto_15m"
            ],
            portfolio,
            live_reconciliation,
            signal_tournament_shadow,
            signal_tournament_ledger,
            settings=settings,
            precomputed_validation=cached_validation if cache_valid else None,
        )
        if mode == "live"
        else (
            [],
            {
                "mode": "inactive_outside_live_execution",
                "affects_execution": True,
                "matched_candidates": 0,
                "eligible_candidates": 0,
            },
        )
    )
    placed, patient_promotion_report = run_patient_scan(
        sys.modules[__name__], settings, portfolio, candidates,
    )
    scan_bet_limit = effective_scan_bet_limit(settings, campaign_enabled)
    ai_scan_context = {"local_calls": 0, "openai_calls": 0, "grok_context": {"api_calls": 0}}
    execution_candidates = (
        spot_flow_live_pilot_candidates
        if mode == "live"
        and crypto_15m_sprint_execution_freeze(settings).get("active")
        else [*candidates, *spot_flow_live_pilot_candidates]
    )
    for candidate in execution_candidates:
        if mode == "live" and setting_bool(settings, "CRYPTO_ETH_PATIENT_ONLY_LIVE"):
            # The patient runtime above is the only selected live entry path.
            continue
        if patient_enabled(settings) and candidate.get("asset") == "ETH" and candidate.get("market_lane") == "crypto_15m":
            # The promoted lane owns ETH decisions when selected, including its
            # missed entries. Do not let another route chase its patient target.
            candidate["skip_reasons"] = ["eth_patient_lane_owns_execution"]
            candidate["decision"] = "skipped"
            continue
        prior_refresh = candidate.get("live_quote_refresh") or {}
        prior_refresh_age = live_quote_refresh_age_seconds(prior_refresh)
        if (
            mode == "live"
            and prior_refresh.get("enabled")
            and not prior_refresh.get("ok")
            and prior_refresh_age is not None
            and prior_refresh_age
            <= setting_float(settings, "CRYPTO_LIVE_QUOTE_REUSE_SECONDS")
        ):
            refresh_error = (
                prior_refresh.get("error") or "live_quote_refresh_failed"
            )
            candidate["skip_reasons"] = list(
                dict.fromkeys(
                    [*(candidate.get("skip_reasons") or []), refresh_error]
                )
            )
            candidate["decision"] = "skipped"
            handle_live_quote_refresh_failure(settings, candidate, prior_refresh)
            quality = build_execution_quality_record(
                candidate,
                "quote_rejected",
                reason=refresh_error,
                settings=settings,
            )
            candidate["execution_quality"] = quality
            persist_execution_quality_record(settings, quality)
            persist_signal_live_pipeline_parity(
                settings,
                candidate,
                prior_refresh,
            )
            continue
        if not candidate_passes(settings, portfolio, candidate):
            continue
        if len(placed) >= scan_bet_limit:
            candidate["skip_reasons"].append("scan_bet_limit_reached")
            candidate["decision"] = "skipped"
            continue
        if mode == "live":
            assigned_bot = (
                (candidate.get("crypto_live_campaign") or {}).get("bot_number")
                or candidate.get("bot_number")
            )
            if reusable_live_quote_refresh(
                settings,
                candidate,
                bot_number=assigned_bot,
            ):
                quote_refresh = candidate.get("live_quote_refresh") or {}
                quote_refresh["reused_for_order"] = True
            else:
                quote_refresh = (
                    refresh_live_spot_flow_pilot_quote(
                        settings,
                        portfolio,
                        candidate,
                    )
                    if is_spot_flow_live_pilot_candidate(candidate)
                    else refresh_live_campaign_candidate_quote(
                        settings,
                        portfolio,
                        candidate,
                    )
                )
                candidate["live_quote_refresh"] = quote_refresh
            if not quote_refresh.get("ok"):
                refresh_error = quote_refresh.get("error") or "live_quote_refresh_failed"
                candidate["skip_reasons"].append(refresh_error)
                candidate["decision"] = "skipped"
                failure_control = handle_live_quote_refresh_failure(
                    settings,
                    candidate,
                    quote_refresh,
                )
                if failure_control.get("status") in {"waiting", "ready"}:
                    quote_refresh["reconfirmation"] = failure_control
                log_line(
                    f"CRYPTO LIVE QUOTE SKIP: {candidate.get('ticker')} reason={refresh_error} "
                    f"old={quote_refresh.get('original_price_cents')}c "
                    f"fresh={quote_refresh.get('refreshed_price_cents')}c "
                    f"move={quote_refresh.get('adverse_move_cents')}c "
                    f"best={quote_refresh.get('best_entry_price_cents')}c "
                    f"full_size={quote_refresh.get('full_size_entry_price_cents')}c "
                    f"available={quote_refresh.get('available_contracts')} "
                    f"required={quote_refresh.get('required_contracts')} "
                    f"quote_age={quote_refresh.get('quote_age_seconds')}s "
                    f"signal_to_refresh={quote_refresh.get('signal_to_refresh_seconds')}s "
                    f"revalidation={quote_refresh.get('revalidation_reason')}"
                )
                event_line({
                    "type": "live_quote_refresh_failed",
                    "candidate": candidate,
                    "quote_refresh": quote_refresh,
                })
                quality = build_execution_quality_record(
                    candidate,
                    "quote_rejected",
                    reason=refresh_error,
                    settings=settings,
                )
                candidate["execution_quality"] = quality
                persist_execution_quality_record(settings, quality)
                persist_signal_live_pipeline_parity(
                    settings,
                    candidate,
                    quote_refresh,
                )
                continue
            log_line(
                f"CRYPTO LIVE QUOTE REFRESH: {candidate.get('ticker')} "
                f"priority={quote_refresh.get('priority_asset')} "
                f"old={quote_refresh.get('original_price_cents')}c "
                f"fresh={quote_refresh.get('refreshed_price_cents')}c "
                f"move={quote_refresh.get('adverse_move_cents')}c "
                f"edge={quote_refresh.get('refreshed_net_edge')}% "
                f"available={quote_refresh.get('available_contracts')} "
                f"required={quote_refresh.get('required_contracts')} "
                f"quote_age={quote_refresh.get('quote_age_seconds')}s "
                f"signal_to_refresh={quote_refresh.get('signal_to_refresh_seconds')}s"
            )
            event_line({
                "type": "live_quote_refreshed",
                "candidate": candidate,
                "quote_refresh": quote_refresh,
            })
            persist_signal_live_pipeline_parity(
                settings,
                candidate,
                quote_refresh,
            )
        balance = live_bankroll_for_sizing(settings, portfolio) if mode == "live" else float(portfolio.get("balance") or 0)
        stake = candidate_stake(settings, candidate, balance, portfolio, phase_two)
        if stake <= 0:
            candidate["skip_reasons"].append("stake_unavailable")
            candidate["decision"] = "skipped"
            continue
        if mode == "live":
            preflight = preflight_live_kalshi_order(settings, candidate, stake)
            candidate["shared_bankroll_preflight"] = {
                key: preflight.get(key)
                for key in ("ok", "enabled", "error", "requested_stake", "approved_stake", "min_contract_stake")
                if key in preflight
            }
            if preflight.get("loss_room"):
                candidate["shared_bankroll_preflight"]["loss_room"] = (
                    preflight.get("loss_room")
                )
            if not preflight.get("ok"):
                candidate["skip_reasons"].append(preflight.get("error") or "shared_bankroll_guard")
                candidate["decision"] = "skipped"
                log_line(
                    f"CRYPTO LIVE PREFLIGHT SKIP: {candidate.get('ticker')} "
                    f"reason={preflight.get('error') or 'shared_bankroll_guard'} "
                    f"risk_scope={(preflight.get('loss_room') or {}).get('scope') or 'unknown'} "
                    f"loss_cap=${float((preflight.get('loss_room') or {}).get('cap') or 0):.2f} "
                    f"realized_loss=${float((preflight.get('loss_room') or {}).get('realized_daily_loss') or 0):.2f} "
                    f"open_exposure=${float((preflight.get('loss_room') or {}).get('open_exposure') or 0):.2f} "
                    f"sports_open=${float((preflight.get('loss_room') or {}).get('sports_open_exposure') or 0):.2f} "
                    f"crypto_open=${float((preflight.get('loss_room') or {}).get('crypto_open_exposure') or 0):.2f} "
                    f"other_strategy_ignored={bool((preflight.get('loss_room') or {}).get('other_strategy_exposure_ignored'))} "
                    f"remaining=${float((preflight.get('loss_room') or {}).get('remaining') or 0):.2f}"
                )
                event_line({
                    "type": "live_order_preflight_failed",
                    "candidate": candidate,
                    "preflight": candidate["shared_bankroll_preflight"],
                })
                continue
            stake = min(stake, float(preflight.get("approved_stake") or stake))
        candidate["ai_review"] = (
            {
                "enabled": False,
                "effective_veto": False,
                "effective_provider": "disabled_for_15m",
                "reason": "short_horizon_deterministic_model",
            }
            if str(candidate.get("market_lane") or "").endswith("15m")
            else maybe_ai_review(settings, candidate, ai_scan_context)
        )
        candidate["grok_review"] = candidate["ai_review"].get("grok_vote") or {"enabled": False}
        if candidate["ai_review"].get("effective_veto"):
            effective_vote = next(
                (
                    vote for vote in (
                        candidate["ai_review"].get("grok_vote") or {},
                        candidate["ai_review"].get("openai_vote") or {},
                        candidate["ai_review"].get("local_vote") or {},
                    )
                    if vote.get("veto")
                ),
                {},
            )
            candidate["ai_veto_reason"] = ",".join(effective_vote.get("reasons") or []) or effective_vote.get("risk_level") or "ai_veto"
            log_line(
                f"CRYPTO AI VETO: {candidate.get('side')} {candidate.get('asset')} {candidate.get('ticker')} "
                f"edge={candidate.get('edge')} conf={candidate.get('confidence')} provider={candidate['ai_review'].get('effective_provider')} "
                f"reason={candidate.get('ai_veto_reason')}"
            )
            event_line({"type": "crypto_ai_veto", "candidate": candidate})
            candidate["skip_reasons"].append("ai_veto")
            candidate["decision"] = "skipped"
            continue
        if mode == "live":
            live_order = place_live_kalshi_order(settings, portfolio, candidate, stake)
            persist_signal_live_pipeline_parity(
                settings,
                candidate,
                candidate.get("live_quote_refresh") or {},
                live_order=live_order,
            )
            unit_downshift = (
                live_order.get("unit_depth_downshift")
                or candidate.get("live_unit_depth_downshift")
                or {}
            )
            if unit_downshift.get("active"):
                log_line(
                    f"CRYPTO LIVE UNIT DOWNSHIFT: {candidate.get('ticker')} "
                    f"original={unit_downshift.get('original_units')}u "
                    f"applied={unit_downshift.get('applied_units')}u "
                    f"trigger={unit_downshift.get('trigger')} "
                    f"fresh={unit_downshift.get('refreshed_price_cents')}c"
                )
                event_line({
                    "type": "live_unit_depth_downshift",
                    "candidate": candidate,
                    "unit_depth_downshift": unit_downshift,
                    "order_ok": bool(live_order.get("ok")),
                })
            if live_order.get("dry_run"):
                candidate["decision"] = "live_dry_run"
                candidate["live_order"] = live_order
                log_line(
                    f"CRYPTO LIVE DRY RUN: {candidate.get('side')} {candidate.get('asset')} {candidate.get('ticker')} "
                    f"stake=${live_order.get('actual_stake', 0):.2f} owner={crypto_strategy_owner(candidate)} price={live_order.get('price')}c "
                    f"edge={candidate.get('edge')}% conf={candidate.get('confidence')}"
                )
                event_line({"type": "live_dry_run", "candidate": candidate, "live_order": live_order})
                continue
            execution_outcome = "filled" if live_order.get("ok") else "order_failed"
            quality = build_execution_quality_record(
                candidate,
                execution_outcome,
                live_order=live_order,
                reason=live_order.get("error") or "",
                settings=settings,
            )
            candidate["execution_quality"] = quality
            live_order["execution_quality"] = quality
            persist_execution_quality_record(settings, quality)
            if live_order.get("ok"):
                bet = record_live_bet(portfolio, candidate, live_order)
            else:
                live_error = live_order.get("error", "live_order_failed")
                candidate["skip_reasons"].append(live_error)
                if live_error == "live_order_insufficient_fresh_depth":
                    start_live_depth_retry_cooldown(settings, candidate)
                candidate["decision"] = "skipped"
                candidate["live_order"] = live_order
                depth = live_order.get("liquidity_preflight") or {}
                exception_details = live_order.get("exception_details") or {}
                exception_type = exception_details.get("exception_type")
                exchange_error = (
                    exception_details.get("exchange_error")
                    or live_order.get("message")
                )
                log_line(
                    f"CRYPTO LIVE ORDER FAILED: {candidate.get('ticker')} reason={live_error} "
                    f"limit={depth.get('limit_price_cents')}c "
                    f"best={depth.get('best_entry_price_cents')}c "
                    f"full_size={depth.get('full_size_entry_price_cents')}c "
                    f"move={depth.get('price_move_beyond_limit_cents')}c "
                    f"available={depth.get('available_contracts')} "
                    f"required={depth.get('required_contracts')} "
                    f"retry_cooldown_seconds={float((candidate.get('live_depth_retry_cooldown') or {}).get('seconds_remaining') or 0):.0f} "
                    f"exception_type={compact_log_value(exception_type)} "
                    f"exchange_error={compact_log_value(exchange_error)}"
                )
                event_line({"type": "live_order_failed", "candidate": candidate, "live_order": live_order})
                if setting_bool(settings, "CRYPTO_LIVE_FALLBACK_TO_PAPER"):
                    bet = place_paper_bet(settings, portfolio, candidate)
                else:
                    bet = None
        else:
            bet = place_paper_bet(settings, portfolio, candidate, stake=stake, phase_two=phase_two)
        if bet:
            candidate["placed_bet_id"] = bet.get("id")
            candidate["placed_stake"] = bet.get("stake")
            placed.append(bet)
            if campaign_enabled:
                campaign = crypto_15m_campaign_context(settings, portfolio)
            elif crypto_strategy_owner(bet) == "phase_two_cycle":
                phase_two = crypto_phase_two_context(settings, portfolio)
    # Live candidates have now completed fresh-book validation and any FOK order
    # attempt.  All research-only work starts below this boundary.
    if isolated_live_pilot_fast_path:
        perps_shadow, market_regime, training_record = prepare_research_context()
    crypto_15m_candidates = [
        candidate
        for candidate in candidates
        if candidate.get("market_lane") == "crypto_15m"
    ]
    prospective_shadow = run_prospective_research(settings, crypto_15m_candidates)
    legacy_candidates = crypto_15m_candidates if setting_bool(settings, "CRYPTO_LEGACY_SHADOW_COLLECTION_ENABLED") else []
    cycle_shadow = run_crypto_cycle_shadow(settings, legacy_candidates)
    low_edge_shadow = run_low_edge_shadow(settings, legacy_candidates)
    rejection_shadow = run_rejection_shadow(
        settings,
        [
            candidate
            for candidate in candidates
            if candidate.get("market_lane") in {"crypto_15m", "commodity_15m"}
        ],
    )
    directional_opposition_v2 = run_directional_opposition_v2(
        settings,
        legacy_candidates,
    )
    signal_tournament_shadow = run_signal_tournament_shadow(
        settings,
        legacy_candidates,
    )
    execution_shadow_runtime = build_execution_shadow_runtime(settings)
    execution_lab_shadow = run_execution_lab_shadow(
        settings,
        legacy_candidates,
        runtime=execution_shadow_runtime,
    )
    asset_specialist_shadow = run_asset_specialist_shadow(
        settings,
        legacy_candidates,
        runtime=execution_shadow_runtime,
    )
    complement_arb_shadow = run_complement_arb_shadow(
        settings,
        legacy_candidates,
    )
    btc_15m_sprint = run_btc_15m_sprint(
        settings,
        legacy_candidates,
    )
    maker_taker_shadow = run_maker_taker_shadow(
        settings,
        crypto_15m_candidates,
    )
    shadow_algorithm = apply_crypto_shadow_analysis(settings, portfolio, candidates)
    apply_final_quality_filters(candidates)
    scan_intelligence = {
        "status": "disabled",
        "candidate_records": 0,
        "recent_candidates": [],
    }
    if setting_bool(settings, "CRYPTO_SCAN_INTELLIGENCE_ENABLED"):
        try:
            scan_intelligence = record_scan_intelligence(
                [
                    candidate for candidate in candidates
                    if candidate.get("market_lane") == "crypto_15m"
                ],
                CRYPTO_SCAN_INTELLIGENCE_FILE,
                CRYPTO_SCAN_INTELLIGENCE_STATE_FILE,
                settlements=training_resolution.get("settled_markets") or [],
                btc_context=(
                    ((asset_data.get("BTC") or {}).get("microstructure") or {}).get("coinbase")
                    or {}
                ),
                settings=settings,
                max_active=setting_int(
                    settings,
                    "CRYPTO_SCAN_INTELLIGENCE_MAX_ACTIVE",
                ),
            )
        except Exception as exc:
            scan_intelligence = {
                "status": "error",
                "candidate_records": 0,
                "recent_candidates": [],
                "error": safe_error_message(exc),
            }
            log_line(
                f"Crypto scan intelligence WARNING: {type(exc).__name__}: "
                f"{safe_error_message(exc)}"
            )
    shadow_algorithm.update(summarize_shadow_candidates(candidates))
    shadow_algorithm["outcomes"] = summarize_shadow_outcomes(portfolio.get("bets", []))
    event_line({"type": "shadow_algorithm", "summary": shadow_algorithm})
    save_portfolio(portfolio)
    if mode == "live":
        live_reconciliation = reconcile_live_account(portfolio, settings)
        save_portfolio(portfolio)
    # A promoted spot candidate may have replaced its generic book simulation
    # with the exact live refresh/order result during the execution loop.  Read
    # the ledger again so the dashboard never lags that parity result by one
    # scan.
    parity_counts = {
        key: signal_tournament_shadow.get(key, 0)
        for key in (
            "captured_this_scan",
            "execution_parity_this_scan",
            "settled_this_scan",
        )
    }
    signal_tournament_shadow = summarize_signal_tournament(
        normalize_signal_tournament_ledger(
            read_json(
                CRYPTO_SIGNAL_TOURNAMENT_FILE,
                empty_signal_tournament_ledger(settings),
            ),
            settings,
        ),
        settings,
    )
    signal_tournament_shadow.update(parity_counts)
    report = summarize(portfolio, candidates, placed, settings)
    report["shadow_algorithm"] = shadow_algorithm
    report["cycle_shadow"] = cycle_shadow
    settlement_lag_payload = read_json(CRYPTO_SETTLEMENT_LAG_SHADOW_FILE, {})
    report["settlement_lag_shadow"] = (
        settlement_lag_payload.get("summary") or settlement_lag_shadow
    )
    report["low_edge_shadow"] = low_edge_shadow
    report["rejection_shadow"] = rejection_shadow
    report["directional_opposition_v2"] = directional_opposition_v2
    report["signal_tournament_shadow"] = signal_tournament_shadow
    report["execution_lab_shadow"] = execution_lab_shadow
    report["asset_specialist_shadow"] = asset_specialist_shadow
    report["prospective_shadow"] = prospective_shadow
    if not setting_bool(settings, "CRYPTO_LEGACY_SHADOW_COLLECTION_ENABLED"):
        for key in ("cycle_shadow", "low_edge_shadow", "directional_opposition_v2",
                    "signal_tournament_shadow", "execution_lab_shadow", "asset_specialist_shadow"):
            section = report[key]
            section.update(collection_status="retired_settlement_only", automatic_promotion=False,
                           review_status="historical_diagnostic_only")
            for lane in section.get("lanes") or []:
                for gate in ("review", "interim_review"):
                    if isinstance(lane.get(gate), dict):
                        lane[gate] = {**lane[gate], "eligible": False, "status": "historical_diagnostic_only"}
    report["spot_flow_live_pilot"] = spot_flow_live_pilot
    report["eth_patient_promotion"] = patient_promotion_report
    report["complement_arb_shadow"] = complement_arb_shadow
    report["btc_15m_sprint"] = btc_15m_sprint
    if not setting_bool(settings, "CRYPTO_LEGACY_SHADOW_COLLECTION_ENABLED"):
        for key in ("complement_arb_shadow", "btc_15m_sprint"):
            report[key]["collection_status"] = "retired_settlement_only"
    report["maker_taker_shadow"] = maker_taker_shadow
    report["perps_shadow"] = perps_shadow
    report["market_regime"] = market_regime
    report["crypto_15m_learning"] = compact_15m_learning_state(learned_15m_state)
    if not setting_bool(settings, "CRYPTO_15M_LEARNING_ACTIVE_ENABLED"):
        report["crypto_15m_learning"].update(active=False, activation_reason="operator_shadow_freeze")
    report["crypto_15m_training"] = {
        **training_resolution,
        **training_record,
    }
    report["scan_intelligence"] = scan_intelligence
    active_strategy_identity = build_strategy_identity(settings, learned_15m_state)
    report["strategy_identity"] = active_strategy_identity
    report["current_strategy_performance"] = current_strategy_performance(
        portfolio,
        active_strategy_identity,
        settings,
    )
    report["adaptive_governor"] = load_governor_state()
    report["crypto_15m_microstructure"] = {
        "enabled": setting_bool(settings, "CRYPTO_15M_MICROSTRUCTURE_ENABLED"),
        "assets_requested": len(selected_assets),
        "assets_loaded": sum(
            1 for row in asset_data.values()
            if (row.get("microstructure") or {}).get("settlement_proxy_source_count")
        ),
        "kalshi_markets_loaded": sum(
            1 for row in kalshi_microstructure_by_ticker.values()
            if not row.get("error")
        ),
        "coinbase_stream_connected": bool(coinbase_stream and coinbase_stream.connected),
        "coinbase_stream_error": coinbase_stream.last_error if coinbase_stream else "",
        "coinbase_trade_gap_count": coinbase_stream.trade_gap_count if coinbase_stream else 0,
        "coinbase_trade_backfill_count": coinbase_stream.trade_backfill_count if coinbase_stream else 0,
        "kraken_stream_connected": bool(kraken_stream and kraken_stream.connected),
        "kraken_stream_error": kraken_stream.last_error if kraken_stream else "",
        "kalshi_stream": (
            KALSHI_CRYPTO_STREAM.status()
            if KALSHI_CRYPTO_STREAM
            else {"enabled": False}
        ),
        "parallel_input_fetch_seconds": input_fetch_seconds,
    }
    report["live_candidate_rerank"] = live_rerank
    report["kalshi_market_fetch"] = market_fetch_health
    write_json(REPORT_FILE, report)
    analytics = report.get("analytics") or {}
    top_log_count = max(0, setting_int(settings, "CRYPTO_LOG_TOP_CANDIDATES"))
    for candidate in candidates[:top_log_count]:
        log_line(
            "Top crypto candidate: "
            f"edge={candidate.get('edge')}c edge_low={candidate.get('edge_low')}c "
            f"pr_edge_positive={candidate.get('confidence')}% "
            f"{candidate.get('side')} {candidate.get('asset')} {candidate.get('ticker')} "
            f"prob_yes={candidate.get('model_prob_yes')} price={candidate.get('entry_price')}c "
            f"data_quality={float((candidate.get('data_quality') or {}).get('score') or 0):.3f} "
            f"flow={float((candidate.get('flow_review') or {}).get('score') or 0):+.3f} "
            f"gap={float((candidate.get('probability') or {}).get('raw_market_gap') or 0):.2f} "
            f"band={price_band(candidate.get('entry_price'))} kind={candidate.get('market_kind')} "
            f"time={hours_to_close_band(candidate)} news={news_source_label(candidate)} "
            f"regime={((candidate.get('market_regime_shadow') or {}).get('alignment') or 'n/a')} "
            f"regime_live={float((candidate.get('market_regime_live') or {}).get('selected_side_adjustment_pp') or 0):+.3f}pp "
            f"units={int((candidate.get('crypto_units') or {}).get('target_units') or 0)} "
            f"decision={candidate.get('decision')} skips={candidate.get('skip_reasons')}"
        )
    log_line(
        "Crypto shadow algorithm: "
        f"candidates={shadow_algorithm.get('candidate_count', 0)} "
        f"fee_positive={shadow_algorithm.get('fee_positive_ev_count', 0)} "
        f"net_threshold={shadow_algorithm.get('net_threshold_pass_count', 0)} "
        f"correlation_approved={shadow_algorithm.get('correlation_approved_count', 0)} "
        f"recommended=${float(shadow_algorithm.get('shadow_recommended_stake') or 0):.2f} "
        "execution_impact=false"
    )
    event_top_count = max(0, setting_int(settings, "CRYPTO_EVENT_TOP_CANDIDATES"))
    event_line({
        "type": "scan_analytics",
        "summary": analytics.get("candidate_summary", {}),
        "skip_reasons": (analytics.get("candidate_by_skip_reason") or [])[:12],
        "price_bands": analytics.get("candidate_by_price_band", []),
        "asset_bands": analytics.get("candidate_by_asset", []),
        "top_candidates": [
            {
                "asset": row.get("asset"),
                "ticker": row.get("ticker"),
                "side": row.get("side"),
                "kind": row.get("market_kind"),
                "entry_price": row.get("entry_price"),
                "edge": row.get("edge"),
                "confidence": row.get("confidence"),
                "expected_edge": row.get("expected_edge"),
                "edge_low": row.get("edge_low"),
                "probability_net_edge_positive": row.get("probability_net_edge_positive"),
                "probability": {
                    key: (row.get("probability") or {}).get(key)
                    for key in (
                        "p_yes",
                        "p_low",
                        "p_high",
                        "interval_status",
                        "adaptive_model_weight",
                        "adaptive_residual_weight",
                        "adaptive_probability_source",
                        "adaptive_probability_status",
                    )
                },
                "data_quality": row.get("data_quality"),
                "flow_review": row.get("flow_review"),
                "disagreement_guard": row.get("disagreement_guard"),
                "directional_confirmation": row.get("directional_confirmation"),
                "crypto_units": row.get("crypto_units"),
                "campaign_review": row.get("crypto_live_campaign"),
                "live_quote_refresh": {
                    key: (row.get("live_quote_refresh") or {}).get(key)
                    for key in (
                        "ok",
                        "error",
                        "original_price_cents",
                        "refreshed_price_cents",
                        "adverse_move_cents",
                        "max_adverse_move_cents",
                        "refreshed_net_edge",
                        "refreshed_edge_low",
                        "refreshed_confidence",
                        "refreshed_probability",
                        "reconfirmation",
                        "fetched_at",
                    )
                    if key in (row.get("live_quote_refresh") or {})
                },
                "live_slippage_reconfirmation": row.get(
                    "live_slippage_reconfirmation"
                ),
                "market_regime_shadow": row.get("market_regime_shadow"),
                "market_regime_live": row.get("market_regime_live"),
                "learned_15m_model": {
                    key: (row.get("learned_15m_model") or {}).get(key)
                    for key in (
                        "active",
                        "available",
                        "calibration_scope",
                        "logistic_prob_yes",
                        "prob_yes",
                        "prob_yes_low",
                        "prob_yes_high",
                        "interval_qualified",
                        "calibration_error_reserve_pp",
                        "model_architecture",
                        "sample_weighting",
                        "influence",
                        "reason",
                        "status",
                        "unique_markets",
                    )
                    if key in (row.get("learned_15m_model") or {})
                },
                "decision": row.get("decision"),
                "skip_reasons": row.get("skip_reasons"),
                "shadow": row.get("shadow"),
            }
            for row in candidates[:event_top_count]
        ],
    })
    log_line(f"Crypto {mode} scan complete markets={len(markets)} candidates={len(candidates)} placed={len(placed)} settled={settled} balance=${portfolio.get('balance'):.2f}")
    event_line({
        "type": "scan_completed",
        "mode": mode,
        "markets": len(markets),
        "candidates": len(candidates),
        "placed": len(placed),
        "settled": settled,
        "balance": portfolio.get("balance"),
        "live_reconciliation": live_reconciliation,
        "summary": analytics.get("candidate_summary", {}),
    })
    return report


def crypto_loop_interval_seconds(settings, report=None):
    interval_minutes = setting_float(settings, "CRYPTO_SCAN_INTERVAL_MINUTES")
    campaign = (report or {}).get("crypto_15m_campaign") or {}
    if (
        setting_bool(settings, "CRYPTO_15M_CAMPAIGN_ENABLED")
        and campaign.get("complete")
    ):
        interval_minutes = max(
            interval_minutes,
            setting_float(
                settings,
                "CRYPTO_CAMPAIGN_COMPLETE_SCAN_INTERVAL_MINUTES",
            ),
        )
    return max(6.0, interval_minutes * 60.0)


def crypto_network_outage_backoff_seconds(settings, outage_streak):
    threshold = max(
        1,
        setting_int(settings, "CRYPTO_NETWORK_OUTAGE_FAILURE_THRESHOLD"),
    )
    outage_streak = max(0, int(outage_streak or 0))
    if outage_streak < threshold:
        return 0.0
    base_seconds = max(
        60.0,
        setting_float(settings, "CRYPTO_NETWORK_OUTAGE_BACKOFF_MINUTES")
        * 60.0,
    )
    maximum_seconds = max(
        base_seconds,
        setting_float(settings, "CRYPTO_NETWORK_OUTAGE_MAX_BACKOFF_MINUTES")
        * 60.0,
    )
    escalation_steps = max(0, (outage_streak - threshold) // 3)
    return min(maximum_seconds, base_seconds * (2 ** escalation_steps))


def main():
    settings = load_settings()
    configure_runtime_files(settings)
    try:
        acquire_single_instance(Path(".crypto_bot.pid"), "crypto bot")
    except AlreadyRunningError as exc:
        log_line(f"CRYPTO START SKIPPED: {exc}")
        return
    if setting_bool(settings, "CRYPTO_RUN_LOOP"):
        outage_streak = 0
        outage_started_at = None
        last_outage_alert_monotonic = None
        while True:
            scan_started = time.monotonic()
            report = None
            try:
                report = run_scan()
            except Exception as exc:
                log_line(f"CRYPTO LOOP ERROR {type(exc).__name__}: {exc}")
            settings = load_settings()
            health = (report or {}).get("kalshi_market_fetch") or {}
            outage = bool(health.get("outage"))
            threshold = max(
                1,
                setting_int(
                    settings,
                    "CRYPTO_NETWORK_OUTAGE_FAILURE_THRESHOLD",
                ),
            )
            now_monotonic = time.monotonic()
            if outage:
                outage_streak += 1
                outage_started_at = outage_started_at or iso_now()
                repeat_seconds = max(
                    60.0,
                    setting_float(
                        settings,
                        "CRYPTO_NETWORK_OUTAGE_ALERT_REPEAT_MINUTES",
                    )
                    * 60.0,
                )
                should_alert = bool(
                    outage_streak == threshold
                    or (
                        outage_streak > threshold
                        and (
                            last_outage_alert_monotonic is None
                            or now_monotonic - last_outage_alert_monotonic
                            >= repeat_seconds
                        )
                    )
                )
                if should_alert:
                    last_outage_alert_monotonic = now_monotonic
                    backoff_seconds = crypto_network_outage_backoff_seconds(
                        settings,
                        outage_streak,
                    )
                    log_line(
                        "CRYPTO NETWORK OUTAGE ALERT: "
                        f"consecutive_failed_scans={outage_streak} "
                        f"failed_series={health.get('failed_series')} "
                        f"backoff_seconds={backoff_seconds:.0f}"
                    )
                    event_line({
                        "type": "crypto_network_outage_alert",
                        "outage_started_at": outage_started_at,
                        "consecutive_failed_scans": outage_streak,
                        "backoff_seconds": backoff_seconds,
                        "market_fetch": health,
                    })
            else:
                if outage_streak >= threshold:
                    log_line(
                        "CRYPTO NETWORK OUTAGE RECOVERED: "
                        f"outage_started_at={outage_started_at} "
                        f"failed_scans={outage_streak}"
                    )
                    event_line({
                        "type": "crypto_network_outage_recovered",
                        "outage_started_at": outage_started_at,
                        "recovered_at": iso_now(),
                        "failed_scans": outage_streak,
                        "market_fetch": health,
                    })
                outage_streak = 0
                outage_started_at = None
                last_outage_alert_monotonic = None
            outage_backoff_seconds = crypto_network_outage_backoff_seconds(
                settings,
                outage_streak,
            )
            if report is not None:
                report["network_outage"] = {
                    "active": bool(outage_streak >= threshold),
                    "outage_started_at": outage_started_at,
                    "consecutive_failed_scans": outage_streak,
                    "next_scan_delay_seconds": outage_backoff_seconds,
                    "market_fetch": health,
                }
                write_json(REPORT_FILE, report)
            target_seconds = max(
                crypto_loop_interval_seconds(settings, report),
                outage_backoff_seconds,
            )
            elapsed_seconds = time.monotonic() - scan_started
            time.sleep(max(0.1, target_seconds - elapsed_seconds))
    else:
        run_scan()


if __name__ == "__main__":
    main()
